Here's a **SwiftUI-based native iOS habit tracking app** written in **Swift**. This example includes core functionality: adding habits, tracking completion, and persistence via `UserDefaults`.

---

### ✅ Key Features
- Add and manage habits
- Toggle daily completion
- Persistent data storage
- Simple, clean UI

---

### 📱 Code Implementation

```swift
import SwiftUI

// MARK: - Data Model
struct Habit: Identifiable, Codable {
    let id = UUID()
    var name: String
    var goal: String
    var completed: Bool
}

// MARK: - View Model
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    init() {
        loadHabits()
    }

    func addHabit(name: String, goal: String) {
        let newHabit = Habit(name: name, goal: goal, completed: false)
        habits.append(newHabit)
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].completed.toggle()
        }
    }

    private func saveHabits() {
        let encoder = JSONEncoder()
        if let encoded = try? encoder.encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    private func loadHabits() {
        if let savedData = UserDefaults.standard.data(forKey: "habits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: savedData) {
            habits = decoded
        }
    }
}

// MARK: - Main App UI
@main
struct HabitTrackerApp: App {
    @StateObject private var viewModel = HabitViewModel()

    var body: some Scene {
        WindowGroup {
            TabView {
                HabitListView(viewModel: viewModel)
                    .tabItem {
                        Label("Habits", systemImage: "list.dash")
                    }

                AddHabitView(viewModel: viewModel)
                    .tabItem {
                        Label("Add", systemImage: "plus")
                    }
            }
        }
    }
}

// MARK: - Habit List View
struct HabitListView: View {
    @ObservedObject var viewModel: HabitViewModel

    var body: some View {
        NavigationView {
            List {
                ForEach(viewModel.habits) { habit in
                    HStack {
                        Text(habit.name)
                            .font(.headline)
                        Spacer()
                        Toggle(isOn: Binding<Bool>(
                            get: { habit.completed },
                            set: { viewModel.toggleCompletion(for: habit) }
                        )) {
                            Text(habit.goal)
                        }
                        .toggleStyle(.switch)
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("My Habits")
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        viewModel.habits.remove(atOffsets: offsets)
    }
}

// MARK: - Add Habit View
struct AddHabitView: View {
    @ObservedObject var viewModel: HabitViewModel
    @State private var name: String = ""
    @State private var goal: String = ""

    var body: some View {
        Form {
            TextField("Habit Name", text: $name)
            TextField("Goal (e.g., 5 times a week)", text: $goal)
            Button("Add Habit") {
                if !name.isEmpty && !goal.isEmpty {
                    viewModel.addHabit(name: name, goal: goal)
                    name = ""
                    goal = ""
                }
            }
            .disabled(name.isEmpty || goal.isEmpty)
        }
        .navigationTitle("New Habit")
    }
}
```

---

### 🧪 How It Works
1. **Data Persistence**: Uses `UserDefaults` to save and load habits automatically.
2. **UI Components**:
   - `TabView` for switching between habit list and add-screen.
   - `List` for displaying habits with a toggle for completion.
   - `TextField` and `Button` for adding new habits.
3. **State Management**: `@Published` and `@ObservedObject` ensure UI updates when data changes.

---

### 🛠️ Enhancements to Consider
- Add a calendar view for historical tracking.
- Use `CoreData` or `CloudKit` for advanced persistence.
- Add notifications for habit reminders.
- Support dark mode and localization.

