Here's a minimal working example of a native iOS habit tracker app using **Swift** and **SwiftUI**, with core functionality:

```swift
import SwiftUI

// MARK: - Data Model
struct Habit: Identifiable {
    let id = UUID()
    var name: String
    var isCompleted: Bool = false
}

// MARK: - Main App
@main
struct HabitTrackerApp: App {
    @StateObject private var habitStore = HabitStore()

    var body: some Scene {
        WindowGroup {
            ContentView(habits: habitStore.habits)
                .environmentObject(habitStore)
        }
    }
}

// MARK: - Habit Store (State Management)
class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [
        Habit(name: "Drink Water"),
        Habit(name: "Exercise"),
        Habit(name: "Read Book")
    ]

    func addHabit(_ habit: Habit) {
        habits.append(habit)
    }
}

// MARK: - Views
struct ContentView: View {
    @EnvironmentObject var habitStore: HabitStore
    @State private var showingAddHabit = false

    var body: some View {
        NavigationView {
            List {
                ForEach($habitStore.habits) { $habit in
                    HStack {
                        Text(habit.name)
                        Spacer()
                        Toggle(isOn: $habit.isCompleted) {
                            Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                        }
                        .toggleStyle(SwitchToggleStyle(tint: Color.green))
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("Habit Tracker")
            .toolbar {
                Button(action: { showingAddHabit = true }) {
                    Image(systemName: "plus")
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView()
            }
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habitStore.habits.remove(atOffsets: offsets)
    }
}

struct AddHabitView: View {
    @EnvironmentObject var habitStore: HabitStore
    @Environment(\.presentationMode) var presentationMode
    @State private var habitName = ""

    var body: some View {
        NavigationView {
            Form {
                TextField("New Habit", text: $habitName)
            }
            .navigationTitle("Add Habit")
            .toolbar {
                Button("Save") {
                    if !habitName.isEmpty {
                        habitStore.addHabit(Habit(name: habitName))
                        presentationMode.wrappedValue.dismiss()
                    }
                }
            }
        }
    }
}

// MARK: - Preview
struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView(habits: [])
            .environmentObject(HabitStore())
    }
}
```

