Here's a **basic implementation** of a native iOS habit tracking app using **Swift** and **SwiftUI**, with **Core Data** for persistence. This example includes core features like habit creation, tracking, and storage.

---

### 📦 Project Structure
1. **Core Data Model** (`HabitModel.xcdatamodeld`)
2. **SwiftUI Views** for habit list, detail, and tracking
3. **ViewModels** for business logic
4. **Core Data Persistence** setup

---

### ✅ Step 1: Core Data Model
Create a Core Data entity named `Habit` with the following attributes:
- `name` (String)
- `frequency` (Int16, e.g., 1 = daily, 7 = weekly)
- `trackedDates` (Transformable Array of Dates)

---

### 📱 Code Implementation

#### 1. **App Entry Point and Core Data Setup**
```swift
import SwiftUI
import CoreData

@main
struct HabitTrackerApp: App {
    let persistenceController = PersistenceController.shared

    var body: some Scene {
        WindowGroup {
            HabitListView()
                .environment(\.managedObjectContext, persistenceController.container.viewContext)
        }
    }
}

// Core Data Stack
class PersistenceController {
    static let shared = PersistenceController()

    let container: NSPersistentCloudKitContainer

    init(inMemory: Bool = false) {
        container = NSPersistentCloudKitContainer(name: "HabitModel")
        if inMemory {
            container.persistentStoreDescriptions.first?.url = URL(fileURLWithPath: "/dev/null")
        }
        container.loadPersistentStores { (storeDescription, error) in
            if let error = error as NSError? {
                fatalError("Unresolved error $error), $error.userInfo)")
            }
        }
    }
}
```

---

#### 2. **Habit List View**
```swift
import SwiftUI

struct HabitListView: View {
    @Environment(\.managedObjectContext) private var viewContext
    @FetchRequest(
        sortDescriptors: [NSSortDescriptor(keyPath: \Habit.name, ascending: true)],
        animation: .default)
    private var habits: FetchedResults<Habit>

    var body: some View {
        NavigationView {
            List {
                ForEach(habits) { habit in
                    NavigationLink(destination: HabitTrackingView(habit: habit)) {
                        VStack(alignment: .leading) {
                            Text(habit.name ?? "Unnamed Habit")
                            Text("Frequency: $habit.frequency) $habit.frequency == 1 ? "day" : "days")")
                        }
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("Habits")
            .toolbar {
                Button("Add") {
                    addHabit()
                }
            }
        }
    }

    private func addHabit() {
        withAnimation {
            let newHabit = Habit(context: viewContext)
            newHabit.name = "New Habit"
            newHabit.frequency = 1
            newHabit.trackedDates = [Date]()

            do {
                try viewContext.save()
            } catch {
                let nsError = error as NSError
                fatalError("Unresolved error $nsError), $nsError.userInfo)")
            }
        }
    }

    private func deleteHabit(at offsets: IndexSet) {
        for index in offsets {
            let habit = habits[index]
            viewContext.delete(habit)
        }
        do {
            try viewContext.save()
        } catch {
            let nsError = error as NSError
            fatalError("Unresolved error $nsError), $nsError.userInfo)")
        }
    }
}
```

---

#### 3. **Habit Detail View**
```swift
import SwiftUI

struct HabitDetailView: View {
    @Environment(\.managedObjectContext) private var viewContext
    @ObservedObject var habit: Habit
    @State private var name: String = ""
    @State private var frequency: Int16 = 1

    var body: some View {
        Form {
            TextField("Habit Name", text: $name)
                .onAppear { name = habit.name ?? "" }
            Stepper("Frequency: $frequency) $frequency == 1 ? "day" : "days")", value: $frequency, in: 1...30)
            Button("Save") {
                habit.name = name
                habit.frequency = frequency
                do {
                    try viewContext.save()
                } catch {
                    let nsError = error as NSError
                    fatalError("Unresolved error $nsError), $nsError.userInfo)")
                }
            }
        }
        .navigationTitle("Edit Habit")
    }
}
```

---

#### 4. **Habit Tracking View**
```swift
import SwiftUI

struct HabitTrackingView: View {
    @Environment(\.managedObjectContext) private var viewContext
    @ObservedObject var habit: Habit

    var body: some View {
        VStack {
            Text("Track $habit.name ?? "Habit")")
                .font(.title)
            Button("Mark Complete") {
                if let dates = habit.trackedDates as? [Date] {
                    var updatedDates = dates
                    updatedDates.append(Date())
                    habit.trackedDates = updatedDates as NSObject
                    do {
                        try viewContext.save()
                    } catch {
                        let nsError = error as NSError
                        fatalError("Unresolved error $nsError), $nsError.userInfo)")
                    }
                }
            }
            .padding()
            .background(Color.blue)
            .foregroundColor(.white)
            .cornerRadius(8)
        }
        .padding()
    }
}
```

---

### 🛠️ Notes for Implementation
1. **Core Data Model**: Create a `Habit` entity in `HabitModel.xcdatamodeld` with the required attributes.
2. **Date Transformation**: Ensure the `trackedDates` attribute is set to **Transformable** type and uses `NSDateTransformer` for date arrays.
3. **CloudKit Sync**: Enable CloudKit in the Core Data container for cross-device syncing.
4. **UI Enhancements**: Add a calendar view (e.g., using `DatePicker` or a third-party library) for detailed tracking.

---

