Here's a basic implementation of a native iOS habit tracking app using **Swift** and **UIKit**. This example includes core features: habit creation, daily tracking, and a calendar view.

---

### **1. Data Model**
```swift
import Foundation

struct Habit: Codable {
    let name: String
    let creationDate: Date
    var completedDates: [Date]

    var currentStreak: Int {
        guard !completedDates.isEmpty else { return 0 }
        let sortedDates = completedDates.sorted()
        let lastDate = sortedDates.last!
        let today = Date()

        // Check if last completed date is yesterday
        let calendar = Calendar.current
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!
        if calendar.isDate(lastDate, inSameDayAs: yesterday) {
            return sortedDates.filter { calendar.isDate($0, inSameDayAs: calendar.date(byAdding: .day, value: -1, to: today)!) }.count
        }
        return 1
    }
}
```

---

### **2. Habit List View Controller**
```swift
import UIKit

class HabitListViewController: UITableViewController {
    var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        loadHabits()
        navigationItem.rightBarButtonItem = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabit))
    }

    @objc func addHabit() {
        let alert = UIAlertController(title: "New Habit", message: nil, preferredStyle: .alert)
        alert.addTextField { textField in
            textField.placeholder = "Enter habit name"
        }
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        alert.addAction(UIAlertAction(title: "Save", style: .default, handler: { [weak self] _ in
            guard let name = alert.textFields?.first?.text, !name.isEmpty else { return }
            let newHabit = Habit(name: name, creationDate: Date(), completedDates: [])
            self?.habits.append(newHabit)
            self?.tableView.reloadData()
        }))
        present(alert, animated: true)
    }

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]
        cell.textLabel?.text = habit.name
        cell.detailTextLabel?.text = "Streak: $habit.currentStreak) days"
        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let habit = habits[indexPath.row]
        let detailVC = HabitDetailViewController(habit: habit)
        detailVC.onUpdate = { [weak self] updatedHabit in
            self?.habits[indexPath.row] = updatedHabit
            self?.tableView.reloadRows(at: [indexPath], with: .automatic)
        }
        navigationController?.pushViewController(detailVC, animated: true)
    }

    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits"), 
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    func saveHabits() {
        if let data = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(data, forKey: "habits")
        }
    }
}
```

