### **3. Habit Detail View Controller**
```swift
import UIKit

class HabitDetailViewController: UIViewController {
    var habit: Habit
    var onUpdate: ((Habit) -> Void)?

    private let calendarView = UICollectionView(frame: .zero, collectionViewLayout: UICollectionViewFlowLayout())

    init(habit: Habit) {
        self.habit = habit
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .systemBackground
        title = habit.name

        setupViews()
    }

    private func setupViews() {
        let todayButton = UIButton(type: .system)
        todayButton.setTitle("Mark Today", for: .normal)
        todayButton.addTarget(self, action: #selector(markToday), for: .touchUpInside)

        let calendarLayout = UICollectionViewFlowLayout()
        calendarLayout.itemSize = CGSize(width: 40, height: 40)
        calendarView.collectionViewLayout = calendarLayout
        calendarView.register(HabitCalendarCell.self, forCellWithReuseIdentifier: "CalendarCell")
        calendarView.dataSource = self
        calendarView.backgroundColor = .secondarySystemBackground

        let stackView = UIStackView(arrangedSubviews: [todayButton, calendarView])
        stackView.axis = .vertical
        stackView.spacing = 16
        stackView.translatesAutoresizingMaskIntoConstraints = false

        view.addSubview(stackView)

        NSLayoutConstraint.activate([
            stackView.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 16),
            stackView.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
            stackView.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16)
        ])
    }

    @objc private func markToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if !habit.completedDates.contains(where: { calendar.isDate($0, inSameDayAs: today) }) {
            var updatedHabit = habit
            updatedHabit.completedDates.append(today)
            habit = updatedHabit
            onUpdate?(updatedHabit)
            calendarView.reloadData()
        }
    }
}

extension HabitDetailViewController: UICollectionViewDataSource {
    func collectionView(_ collectionView: UICollectionView, numberOfItemsInSection section: Int) -> Int {
        return 7 // 7-day view
    }

    func collectionView(_ collectionView: UICollectionView, cellForItemAt indexPath: IndexPath) -> UICollectionViewCell {
        let cell = collectionView.dequeueReusableCell(withReuseIdentifier: "CalendarCell", for: indexPath) as! HabitCalendarCell
        let calendar = Calendar.current
        let today = Date()
        let targetDate = calendar.date(byAdding: .day, value: -3 + indexPath.item, to: today)! // Center current day
        cell.configure(date: targetDate, isCompleted: habit.completedDates.contains(where: { calendar.isDate($0, inSameDayAs: targetDate) }))
        return cell
    }
}

class HabitCalendarCell: UICollectionViewCell {
    private let label = UILabel()

    override init(frame: CGRect) {
        super.init(frame: frame)
        contentView.addSubview(label)
        label.translatesAutoresizingMaskIntoConstraints = false
        NSLayoutConstraint.activate([
            label.centerXAnchor.constraint(equalTo: contentView.centerXAnchor),
            label.centerYAnchor.constraint(equalTo: contentView.centerYAnchor)
        ])
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    func configure(date: Date, isCompleted: Bool) {
        let formatter = DateFormatter()
        formatter.dateFormat = "d"
        label.text = formatter.string(from: date)
        contentView.layer.borderColor = isCompleted ? UIColor.green.cgColor : UIColor.clear.cgColor
        contentView.layer.borderWidth = isCompleted ? 2 : 0
    }
}
```

