Here's a basic implementation of a native iOS habit tracking app using **Swift** and **SwiftUI**. This example includes core functionality: adding habits, marking them as completed, and displaying a list.

---

### 📱 Habit Tracking App (SwiftUI + Swift)
```swift
import SwiftUI

// MARK: - Data Model
struct Habit: Identifiable, Equatable {
    let id = UUID()
    var name: String
    var description: String
    var completed: Bool
}

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    func addHabit(name: String, description: String) {
        let newHabit = Habit(name: name, description: description, completed: false)
        habits.append(newHabit)
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].completed.toggle()
        }
    }
}

// MARK: - Main View
struct ContentView: View {
    @StateObject private var viewModel = HabitViewModel()

    var body: some View {
        NavigationView {
            List {
                ForEach(viewModel.habits) { habit in
                    HabitRow(habit: habit)
                        .onTap {
                            viewModel.toggleCompletion(for: habit)
                        }
                }
                .onDelete { indices in
                    viewModel.habits.remove(atOffsets: indices)
                }
            }
            .navigationTitle("Habits")
            .toolbar {
                NavigationLink(destination: AddHabitView(viewModel: viewModel)) {
                    Image(systemName: "plus")
                }
            }
        }
    }
}

// MARK: - Habit Row
struct HabitRow: View {
    let habit: Habit

    var body: some View {
        HStack {
            Image(systemName: habit.completed ? "checkmark.circle.fill" : "circle")
                .foregroundColor(habit.completed ? .green : .gray)
            VStack(alignment: .leading) {
                Text(habit.name)
                    .font(.headline)
                Text(habit.description)
                    .font(.subheadline)
                    .foregroundColor(.gray)
            }
        }
    }
}

// MARK: - Add Habit View
struct AddHabitView: View {
    @ObservedObject var viewModel: HabitViewModel
    @State private var name: String = ""
    @State private var description: String = ""
    @Environment(\.dismiss) var dismiss

    var body: some View {
        NavigationView {
            Form {
                TextField("Habit Name", text: $name)
                TextField("Description", text: $description)
            }
            .navigationTitle("New Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .primaryAction) {
                    Button("Save") {
                        viewModel.addHabit(name: name, description: description)
                        dismiss()
                    }
                }
            }
        }
    }
}

// MARK: - Preview
struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}
```

