Here's an initial implementation of a native iOS habit tracking app using **Swift** and **SwiftUI**, with CoreData for persistence:

---

### **1. Data Model (CoreData Entity)**
```swift
// Habit+CoreDataClass.swift (generated by Xcode)
@objc(Habit)
public class Habit: NSManagedObject {
    @NSManaged public var name: String
    @NSManaged public var target: Int16
    @NSManaged public var frequency: Int16
    @NSManaged public var completion: Int16
    @NSManaged public var uuid: UUID
}
```

---

### **2. View Model (MVVM Pattern)**
```swift
import SwiftUI
import CoreData

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    let container = NSPersistentContainer(name: "HabitTracker")

    init() {
        container.loadPersistentStores { description, error in
            if let error = error {
                fatalError("CoreData load error: $error)")
            }
        }
        fetchHabits()
    }

    func fetchHabits() {
        let request: NSFetchRequest<Habit> = Habit.fetchRequest()
        do {
            habits = try container.viewContext.fetch(request)
        } catch {
            print("Fetch error: $error)")
        }
    }

    func addHabit(name: String, target: Int16, frequency: Int16) {
        let habit = Habit(context: container.viewContext)
        habit.name = name
        habit.target = target
        habit.frequency = frequency
        habit.completion = 0
        habit.uuid = UUID()

        do {
            try container.viewContext.save()
            fetchHabits()
        } catch {
            print("Save error: $error)")
        }
    }

    func deleteHabit(at index: Int) {
        let habit = habits[index]
        container.viewContext.delete(habit)
        do {
            try container.viewContext.save()
            fetchHabits()
        } catch {
            print("Delete error: $error)")
        }
    }

    func markAsCompleted(habit: Habit) {
        habit.completion += 1
        do {
            try container.viewContext.save()
            fetchHabits()
        } catch {
            print("Update error: $error)")
        }
    }
}
```

