### **2. ViewModel for Data Management**
```swift
import Foundation
import SwiftUI

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let habitsKey = "savedHabits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, description: String, frequency: Habit.Frequency) {
        let newHabit = Habit(name: name, description: description, frequency: frequency)
        habits.append(newHabit)
    }

    func toggleCompletion(for habit: Habit, date: Date) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]
            updatedHabit.completion[date] = !(updatedHabit.completion[date] ?? false)
            habits[index] = updatedHabit
        }
    }

    private func saveHabits() {
        if let encodedData = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encodedData, forKey: habitsKey)
        }
    }

    private func loadHabits() {
        if let savedData = UserDefaults.standard.data(forKey: habitsKey),
           let decodedHabits = try? JSONDecoder().decode([Habit].self, from: savedData) {
            habits = decodedHabits
        }
    }
}
```

