#### 3. **Core Data Stack**
```swift
// ViewModels/CoreDataService.swift
import Foundation
import CoreData

class CoreDataService {
    static let shared = CoreDataService()

    lazy var container: NSPersistentContainer = {
        let container = NSPersistentContainer(name: "HabitTracker")
        container.loadPersistentStores { (storeDescription, error) in
            if let error = error as NSError? {
                fatalError("Unresolved error $error), $error.userInfo)")
            }
        }
        return container
    }()

    var context: NSManagedObjectContext { return container.viewContext }

    func saveContext() {
        if context.hasChanges {
            do {
                try context.save()
            } catch {
                let nserror = error as NSError
                fatalError("Unresolved error $nserror), $nserror.userInfo)")
            }
        }
    }
}
```

#### 4. **HabitViewModel**
```swift
// ViewModels/HabitViewModel.swift
import SwiftUI
import CoreData

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    private let coreData = CoreDataService.shared

    init() {
        fetchHabits()
    }

    func fetchHabits() {
        do {
            let request: NSFetchRequest<Habit> = Habit.fetchRequest()
            habits = try coreData.context.fetch(request)
        } catch {
            print("Failed to fetch habits: $error)")
        }
    }

    func addHabit(name: String, goal: Int16, frequency: String) {
        let habit = Habit(context: coreData.context)
        habit.name = name
        habit.goal = goal
        habit.frequency = frequency
        habit.dailyRecords = []

        do {
            try coreData.context.save()
            habits.append(habit)
        } catch {
            print("Failed to save habit: $error)")
        }
    }

    func markComplete(habit: Habit, date: Date) {
        let record = DailyRecord(context: coreData.context)
        record.date = date
        record.completed = true
        habit.addToDailyRecords(record)

        do {
            try coreData.context.save()
        } catch {
            print("Failed to mark habit complete: $error)")
        }
    }
}
```

