```swift
import SwiftUI

// MARK: - Data Models
struct Habit: Identifiable, Codable {
    let id = UUID()
    let name: String
    var completions: [Bool] // true = completed, false = not completed
}

// MARK: - View Models
class HabitsViewModel: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    init() {
        loadHabits()
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits") {
            do {
                habits = try JSONDecoder().decode([Habit].self, from: data)
            } catch {
                print("Failed to load habits: $error)")
            }
        }
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: "habits")
        } catch {
            print("Failed to save habits: $error)")
        }
    }

    func addHabit(name: String) {
        let newHabit = Habit(name: name, completions: [])
        habits.append(newHabit)
    }
}

// MARK: - Views
struct HabitRow: View {
    @Binding var habit: Habit
    @State private var currentDay = 0

    var body: some View {
        HStack {
            Text(habit.name)
                .font(.headline)
            Spacer()
            ForEach(0..<30, id: \.self) { day in
                Toggle(isOn: Binding(
                    get: { habit.completions[safe: day] ?? false },
                    set: { newValue in
                        if day >= habit.completions.count {
                            habit.completions += Array(repeating: false, count: day - habit.completions.count + 1)
                        }
                        habit.completions[day] = newValue
                    }
                )) {
                    Circle()
                        .frame(width: 12, height: 12)
                        .foregroundColor(habit.completions[safe: day] ?? false ? .green : .gray)
                }
                .toggleStyle(.switch)
                .frame(width: 24, height: 24)
            }
            Text("Streak: $calculateStreak())")
                .foregroundColor(.blue)
        }
        .padding()
    }

    private func calculateStreak() -> Int {
        var streak = 0
        for i in (0..<habit.completions.count).reversed() {
            if habit.completions[i] {
                streak += 1
            } else {
                break
            }
        }
        return streak
    }
}

extension Array where Element == Bool {
    subscript(safe index: Int) -> Bool? {
        guard index >= 0, index < count else { return nil }
        return self[index]
    }
}

struct ContentView: View {
    @StateObject private var viewModel = HabitsViewModel()

    var body: some View {
        NavigationView {
            List {
                ForEach($viewModel.habits) { $habit in
                    HabitRow(habit: $habit)
                }
                .onDelete { indices in
                    viewModel.habits.remove(atOffsets: indices)
                }
            }
            .navigationTitle("Habit Tracker")
            .toolbar {
                NavigationLink {
                    AddHabitView(viewModel: viewModel)
                } label: {
                    Image(systemName: "plus")
                }
            }
        }
    }
}

struct AddHabitView: View {
