                TextField("Habit name", text: $habitName)
                    .textFieldStyle(.roundedBorder)
                    .padding()
                Spacer()
                Button("Add Habit") {
                    viewModel.addHabit(name: habitName)
                    dismiss()
                }
                .padding()
            }
            .navigationTitle("New Habit")
        }
    }
}

