class DashboardRepository {
    private val apiService = RetrofitClient.apiService

    suspend fun fetchAccountSummary(): Resource<AccountSummary> {
        return try {
            val response = apiService.getAccountSummary("Bearer $token")
            if (response.isSuccessful) {
                Resource.Success(response.body()!!)
            } else {
                Resource.Error("Failed to fetch data")
            }
        } catch (e: Exception) {
            Resource.Error(e.message ?: "Unknown error")
        }
    }

    companion object {
        private val token = "YOUR_SECURE_TOKEN" // Use secure storage in production
    }
}
