### **5. Secure Data Handling**
#### **`SecureStorage.kt`** (Using Android Keystore)
```kotlin
object SecureStorage {
    private const val KEY_ALIAS = "banking_app_key"

    fun encryptData(data: String): String {
        val keyStore = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        val keyGenerator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
        val keySpec = KeyGenParameterSpec.Builder(
            KEY_ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_CBC)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_PKCS7)
            .build()
        keyGenerator.init(keySpec)
        val cipher = keyGenerator.generateKey().let { keyStore.getKey(KEY_ALIAS, null) } as SecretKey
        val encryptedBytes = cipher.let { cipher ->
            cipher.init(Cipher.ENCRYPT_MODE, it)
            cipher.doFinal(data.toByteArray(Charsets.UTF_8))
        }
        return Base64.encodeToString(encryptedBytes, Base64.DEFAULT)
    }

    fun decryptData(encryptedData: String): String {
        val keyStore = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        val cipher = keyStore.getKey(KEY_ALIAS, null) as SecretKey
        val decryptedBytes = cipher.let { cipher ->
            cipher.init(Cipher.DECRYPT_MODE, it)
            cipher.doFinal(Base64.decode(encryptedData, Base64.DEFAULT))
        }
        return String(decryptedBytes, Charsets.UTF_8)
    }
}
