#### `SecureDataStore.kt` (Example for secure storage)
```kotlin
package com.example.bankingapp

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.dataStore
import androidx.datastore.preferences.core.*
import androidx.datastore.preferences.preferencesDataStore
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

class SecureDataStore(context: Context) {
    private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "secure_prefs")

    val sessionToken: Flow<String?> = context.dataStore.data.map { preferences ->
        preferences[stringPreferencesKey("session_token")]
    }

    suspend fun saveSessionToken(token: String) {
        context.dataStore.edit { preferences ->
            preferences[stringPreferencesKey("session_token")] = token
        }
    }

    suspend fun clearSessionToken() {
        context.dataStore.edit { preferences ->
            preferences.remove(stringPreferencesKey("session_token"))
        }
    }
}
