package com.example.banking

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.launch

class BankingViewModel : ViewModel() {
    private val fakeAPI = FakeBankingAPI()
    val balance = MutableStateFlow("$$1000.00")

    fun login(email: String, password: String): Boolean {
        return fakeAPI.login(email, password)
    }

    fun transferFunds(amount: String, recipient: String): Boolean {
        val amountFloat = amount.toFloatOrNull() ?: return false
        val currentBalance = balance.value.replace("$", "").toFloatOrNull() ?: 1000f
        if (currentBalance - amountFloat < 0) return false
        balance.value = "\$${currentBalance - amountFloat}"
        return true
    }
}
