```javascript
import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase({ name: 'survey.db', location: 'default' });

export const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, location TEXT, notes TEXT, synced BOOLEAN)'
    );
  });
};

export const saveSurvey = (name, location, notes) => {
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (name, location, notes, synced) VALUES (?, ?, ?, ?)',
      [name, location, notes, false]
    );
  });
};

export const getUnsyncedSurveys = callback => {
  db.transaction(tx => {
    tx.executeSql('SELECT * FROM surveys WHERE synced = ?', [false], (tx, results) => {
      callback(results.rows.raw());
    });
  });
};

export const markAsSynced = (id) => {
  db.transaction(tx => {
    tx.executeSql('UPDATE surveys SET synced = ? WHERE id = ?', [true, id]);
  });
};
```

