import { useNetInfo } from '@react-native-async-storage/async-storage';

const SurveyForm = () => {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const netInfo = useNetInfo();

  const handleSubmit = () => {
    saveSurvey(name, location, notes);
    Alert.alert('Survey saved locally!');
    if (netInfo.isConnected) {
      syncData();
    }
  };

  const syncData = () => {
    getUnsyncedSurveys((surveys) => {
      surveys.forEach(survey => {
        // Replace with your backend sync endpoint
        fetch('https://your-backend.com/api/sync', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(survey),
        })
          .then(() => markAsSynced(survey.id))
          .catch(err => console.error('Sync failed:', err));
      });
    });
  };

  return (
