import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import { database } from '../db'
import { NetInfo } from '@react-native-community/netinfo'

interface SyncState {
  pendingResponses: number
  lastSync: Date | null
}

export const syncResponses = createAsyncThunk(
  'sync/syncResponses',
  async () => {
    const hasConnection = await NetInfo.fetch().then(status => status.isConnected)
    if (!hasConnection) return

    const responses = await database.get('responses').query(q => q.eq('status', 'unsynced')).fetch()
    for (const response of responses) {
      try {
