import { openDatabase } from 'react-native-sqlite-storage';

const db = openDatabase({ name: 'surveys.db', location: 'default' });

const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT, latitude REAL, longitude REAL, notes TEXT, synced BOOLEAN)'
    );
  });
};

const addSurvey = (latitude, longitude, notes) => {
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (timestamp, latitude, longitude, notes, synced) VALUES (?, ?, ?, ?, ?)',
      [new Date().toISOString(), latitude, longitude, notes, false]
    );
  });
};

const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0',
        [],
        (tx, results) => {
          const rows = results.rows.raw();
          resolve(rows);
        },
        (tx, error) => reject(error)
      );
    });
  });
};

const markAsSynced = (id) => {
  db.transaction(tx => {
    tx.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [id]);
  });
};

export { initDB, addSurvey, getUnsyncedSurveys, markAsSynced };
