import React, { useState, useEffect } from 'react'
import { View, TextInput, Button, Alert } from 'react-native'
import { database } from './database'
import { NetInfo } from '@react-native-community/net-info'

const SurveyScreen = () => {
  const [location, setLocation] = useState('')
  const [notes, setNotes] = useState('')

  // Save survey locally (offline-first)
  const saveSurvey = async () => {
    const survey = database.write(() =>
      database.get('surveys').create((record) => {
        record.location = location
        record.notes = notes
        record.timestamp = Date.now()
        record.synced = false
      })
    )
    Alert.alert('Saved locally. Will sync when online.')
  }

  // Sync unsynced surveys
  const syncSurveys = async () => {
    const surveys = await database.get('surveys').query().fetch()
    const unsynced = surveys.filter((s) => !s.synced)

    for (const survey of unsynced) {
      try {
        // Replace with your API endpoint
        await fetch('https://your-api.com/sync', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: survey.id,
            location: survey.location,
            notes: survey.notes,
            timestamp: survey.timestamp,
          }),
        })

        // Mark as synced
        database.write(() =>
          survey.update((record) => {
            record.synced = true
          })
        )
      } catch (error) {
        console.error('Sync failed:', error)
      }
    }
  }

  // Check connectivity and auto-sync
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      if (state.isConnected) {
        syncSurveys()
      }
    })

    return () => unsubscribe()
  }, [])

  return (
    <View style={{ padding: 20 }}>
      <TextInput
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
        style={{ marginBottom: 10 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        multiline
        style={{ marginBottom: 10, height: 100 }}
      />
      <Button title="Save Survey" onPress={saveSurvey} />
      <Button title="Manual Sync" onPress={syncSurveys} />
    </View>
  )
}

export default SurveyScreen
