const db = SQLite.openDatabase('surveys.db');

// Create table if not exists
db.transaction(tx => {
  tx.executeSql(
    'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, location TEXT, notes TEXT, synced BOOLEAN)'
  );
});

export default function App() {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(false);

  // Check online status
  useEffect(() => {
    const checkOnlineStatus = async () => {
      const status = await Network.getNetworkStateAsync();
      setOnline(status.isInternetReachable);
    };
    checkOnlineStatus();
  }, []);

  // Load surveys from local DB
  useEffect(() => {
    loadSurveys();
  }, []);

  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql('SELECT * FROM surveys', [], (_, { rows }) => {
        setSurveys(rows._array);
      });
    });
  };

  // Save survey to local DB (offline-first)
  const saveSurvey = () => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (name, location, notes, synced) VALUES (?, ?, ?, ?)',
