    if (!online) return alert('No internet connection!');

    db.transaction(tx => {
      tx.executeSql('SELECT * FROM surveys WHERE synced = 0', [], (_, { rows }) => {
        const unsynced = rows._array;
        if (unsynced.length === 0) {
          alert('No data to sync!');
          return;
        }

        // Simulate sending to remote server
        console.log('Syncing:', unsynced);
        alert(`Synced ${unsynced.length} surveys!`);

        // Mark as synced in local DB
        unsynced.forEach(survey => {
          tx.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [survey.id]);
        });
      });
    });

    loadSurveys();
  };

  return (
