import { SQLiteDatabase, openDatabase } from 'react-native-sqlite-storage';

const DB_NAME = 'survey.db';

export const initDB = async (): Promise<SQLiteDatabase> => {
  const db = await openDatabase({ name: DB_NAME, location: 'default' });
  await db.executeSql(`
    CREATE TABLE IF NOT EXISTS surveys (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT,
      location TEXT,
      notes TEXT,
      synced BOOLEAN DEFAULT 0
    )
  `);
  return db;
};

export const saveSurveyLocally = async (
  db: SQLiteDatabase,
  name: string,
  location: string,
  notes: string
) => {
  await db.executeSql(
    'INSERT INTO surveys (name, location, notes) VALUES (?, ?, ?)',
    [name, location, notes]
  );
};

export const getUnsyncedSurveys = async (db: SQLiteDatabase) => {
  const result = await db.executeSql('SELECT * FROM surveys WHERE synced = 0');
  return result[0].rows.raw();
};

export const markAsSynced = async (db: SQLiteDatabase, id: number) => {
  await db.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [id]);
};
```

