### 🔄 `syncService.ts` (Sync Logic)
```ts
import { getUnsyncedSurveys, markAsSynced } from './database';
import NetInfo from '@react-native-community/netinfo';

const API_URL = 'https://your-backend.com/api/surveys'; // Replace with real endpoint

export const syncData = async (db: SQLiteDatabase) => {
  const isOnline = await NetInfo.fetch().then(status => status.isConnected);
  if (!isOnline) return;

  const unsynced = await getUnsyncedSurveys(db);
  for (const survey of unsynced) {
    try {
      await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey),
      });
      await markAsSynced(db, survey.id);
    } catch (error) {
      console.error('Sync failed:', error);
      // Retry logic could be added here
    }
  }
};
```

