### **4. Sync Logic**
Create `src/utils/sync.ts`:
```ts
// src/utils/sync.ts
import { getUnsyncedSurveys, markAsSynced } from '../models/SurveyModel';
import { SQLiteDBConnection } from 'react-native-sqlite-storage';

// Mock backend API
const mockBackend = async (survey: any) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      console.log('Synced survey:', survey);
      resolve({ success: true });
    }, 1000);
  });
};

export const syncSurveys = async (db: SQLiteDBConnection) => {
  const unsynced = await getUnsyncedSurveys(db);
  if (unsynced.length === 0) return;

  const idsToSync = unsynced.map((s: any) => s.id);
  const syncPromises = unsynced.map((s: any) => mockBackend(s));

  try {
    await Promise.all(syncPromises);
    await markAsSynced(db, idsToSync);
    console.log('Sync completed for', idsToSync.length, 'surveys');
  } catch (error) {
    console.error('Sync failed:', error);
  }
};
```

