### **3. Local Database (SQLite)**
```dart
// lib/services/db_service.dart
import 'package:sqflite/sqflite.dart';
import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart';
import 'survey.dart';

class DatabaseService {
  Database? _database;

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    final documentsDirectory = await getApplicationDocumentsDirectory();
    final path = join(documentsDirectory.path, 'surveys.db');
    return await openDatabase(
      path,
      version: 1,
      onCreate: (db, version) {
        return db.execute(
          "CREATE TABLE surveys(id TEXT PRIMARY KEY, title TEXT, description TEXT, timestamp TEXT, synced INTEGER)",
        );
      },
    );
  }

  Future<void> insertSurvey(Survey survey) async {
    final db = await database;
    await db.insert('surveys', survey.toJson(), conflictAlgorithm: ConflictAlgorithm.replace);
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await database;
    final maps = await db.query('surveys', where: 'synced = ?', whereArgs: [0]);
    return List.generate(maps.length, (i) => Survey.fromJson(maps[i]));
  }

  Future<void> markSurveyAsSynced(String id) async {
    final db = await database;
    await db.update('surveys', {'synced': 1}, where: 'id = ?', whereArgs: [id]);
  }
}
```

