// lib/services/firebase_service.dart
import 'package:cloud_firestore/cloud_firestore.dart';
import 'survey.dart';
import 'db_service.dart';

class FirebaseService {
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;
  final DatabaseService _dbService = DatabaseService();

  Future<void> syncSurveys() async {
    final unsyncedSurveys = await _dbService.getUnsyncedSurveys();
    for (var survey in unsyncedSurveys) {
      try {
        await _firestore.collection('surveys').doc(survey.id).set(survey.toJson());
        await _dbService.markSurveyAsSynced(survey.id);
      } catch (e) {
        // Handle sync error (e.g., retry logic)
        print('Sync failed for survey $survey: $e');
      }
    }
  }
}
