    return Survey(
      id: map['id'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      notes: map['notes'],
      timestamp: DateTime.parse(map['timestamp']),
      synced: map['synced'] == 1, // SQLite stores bool as 0/1
    );
  }
}
