### 2. `database.dart`
```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import 'models/survey.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._();
  static Database? _database;

  DatabaseHelper._();

  factory DatabaseHelper() => _instance;

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    String path = join(await getDatabasesPath(), 'surveys.db');
    return await openDatabase(
      path,
      version: 1,
      onCreate: _onCreate,
    );
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        notes TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        synced INTEGER NOT NULL DEFAULT 0
      )
    ''');
  }

  Future<int> insertSurvey(Survey survey) async {
    final db = await database;
    return await db.insert('surveys', survey.toMap());
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query(
      'surveys',
      where: 'synced = ?',
      whereArgs: [0],
    );
    return List.generate(maps.length, (i) => Survey.fromMap(maps[i]));
  }

  Future<void> markAsSynced(int id) async {
    final db = await database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}
```

