import 'dart:convert';
import 'package:http/http.dart' as http;
import 'models/survey.dart';
import 'database.dart';

class SyncManager {
  static const String _baseUrl = 'https://your-api.com/api/surveys';

  Future<void> syncSurveys() async {
    final db = DatabaseHelper();
    final unsynced = await db.getUnsyncedSurveys();

    for (var survey in unsynced) {
      try {
        final response = await http.post(
          Uri.parse(_baseUrl),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode(survey.toMap()),
        );

        if (response.statusCode == 201) {
          await db.markAsSynced(survey.id!);
        } else {
          // Handle conflict or retry logic here
          print('Sync failed for survey ${survey.id}');
        }
      } catch (e) {
        print('Sync error: $e');
      }
    }
  }
}
