import 'package:flutter/material.dart';
import 'package:hive/hive.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'dart:convert';
import 'package:http/http.dart' as http;

// Survey data model
class Survey {
  final String id;
  final String location;
  final String notes;
  bool synced;

  Survey({required this.id, required this.location, required this.notes, this.synced = false});

  Map<String, dynamic> toJson() => {
        'id': id,
        'location': location,
        'notes': notes,
        'synced': synced,
      };
}

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();
  Hive.registerAdapter(SurveyAdapter());
  await Hive.openBox<Survey>('surveys');
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Field Survey',
      home: SurveyScreen(),
    );
  }
}

class SurveyScreen extends StatefulWidget {
  @override
  _SurveyScreenState createState() => _SurveyScreenState();
}

class _SurveyScreenState extends State<SurveyScreen> {
  final _box = Hive.box<Survey>('surveys');
  final _locationController = TextEditingController();
  final _notesController = TextEditingController();
  bool _isOnline = false;

  @override
  void initState() {
    super.initState();
    _checkConnectivity();
    Connectivity().onConnectivityChanged.listen((result) {
      setState(() {
        _isOnline = result != ConnectivityResult.none;
      });
      if (_isOnline) _syncData();
    });
  }

  Future<void> _checkConnectivity() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    setState(() {
      _isOnline = connectivityResult != ConnectivityResult.none;
    });
  }

  void _saveLocally() {
    final survey = Survey(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      location: _locationController.text,
      notes: _notesController.text,
    );
    _box.add(survey);
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Saved offline')));
  }

  Future<void> _syncData() async {
    final unsynced = _box.values.where((s) => !s.synced).toList();
    for (var survey in unsynced) {
      final response = await http.post(
        Uri.parse('http://your-backend-url/api/sync'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(survey.toJson()),
      );
      if (response.statusCode == 200) {
        survey.synced = true;
        await _box.put(survey.id, survey);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Field Survey')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            TextField(controller: _locationController, decoration: InputDecoration(labelText: 'Location')),
            TextField(controller: _notesController, decoration: InputDecoration(labelText: 'Notes')),
            SizedBox(height: 20),
            ElevatedButton(onPressed: _saveLocally, child: Text('Save Offline')),
            if (_isOnline)
              ElevatedButton(onPressed: _syncData, child: Text('Sync Data')),
          ],
        ),
      ),
    );
  }
}

// Hive adapter for Survey
class SurveyAdapter extends TypeAdapter<Survey> {
  @override
  final int typeId = 0;

  @override
  Survey read(BinaryReader reader) {
    return Survey(
      id: reader.readString(),
      location: reader.readString(),
      notes: reader.readString(),
      synced: reader.readBool(),
    );
  }

  @override
  void write(BinaryWriter writer, Survey obj) {
    writer.writeString(obj.id);
    writer.writeString(obj.location);
    writer.writeString(obj.notes);
    writer.writeBool(obj.synced);
  }
}
```

