from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

# Initialize SQLite DB
def init_db():
    with app.app_context():
        db = sqlite3.connect('surveys.db')
        db.execute('''
            CREATE TABLE IF NOT EXISTS surveys (
                id TEXT PRIMARY KEY,
                location TEXT,
                notes TEXT,
                synced BOOLEAN
            )
        ''')
        db.commit()

@app.route('/api/sync', methods=['POST'])
def sync_data():
    data = request.json
    conn = sqlite3.connect('surveys.db')
    cursor = conn.cursor()
    cursor.execute('''
        INSERT OR IGNORE INTO surveys (id, location, notes, synced)
        VALUES (?, ?, ?, ?)
    ''', (data['id'], data['location'], data['notes'], data['synced']))
    conn.commit()
    return jsonify({'status': 'success'})

if __name__ == '__main__':
    init_db()
    app.run(debug=True, host='0.0.0.0')
```

