import { View, Text, TextInput, Button, Alert } from 'react-native';
import SQLite from 'react-native-sqlite-storage';
import NetInfo from '@react-native-community/netinfo';

// Initialize SQLite DB
const db = SQLite.openDatabase(
  { name: 'survey.db', location: 'default' },
  () => {},
  error => console.error('DB Open Error:', error)
);

// Create surveys table
db.transaction(tx => {
  tx.executeSql(
    'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, location TEXT, notes TEXT, synced INTEGER DEFAULT 0);'
  );
});

const App = () => {
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [isOnline, setIsOnline] = useState(true);

  // Check network status
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected ?? false);
      if (state.isConnected) syncData();
    });
    return () => unsubscribe();
  }, []);

  // Save survey locally (offline-first)
  const saveSurvey = () => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (location, notes) VALUES (?, ?);',
        [location, notes],
        () => {
          Alert.alert('Saved locally!');
          setLocation('');
          setNotes('');
        }
      );
    });
  };

  // Sync unsynced data to server
  const syncData = () => {
    db.transaction(tx => {
      tx.executeSql('SELECT * FROM surveys WHERE synced = 0;', [], (_, { rows }) => {
        rows.forEach(row => {
          // Simulate API sync (replace with real backend)
          fetch('https://jsonplaceholder.typicode.com/posts', {
            method: 'POST',
            body: JSON.stringify({ location: row.location, notes: row.notes }),
            headers: { 'Content-Type': 'application/json' },
          })
            .then(response => response.json())
            .then(() => {
              // Mark as synced
              tx.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?;', [row.id]);
              console.log('Synced survey ID:', row.id);
            })
            .catch(error => console.error('Sync error:', error));
        });
      });
    });
  };

  return (
    <View style={{ padding: 20 }}>
      <Text>Offline-First Survey App</Text>
      <TextInput
        placeholder="Location"
