// App.tsx
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, Alert } from 'react-native';
import * as SQLite from 'expo-sqlite';
import * as Location from 'expo-location';
import * as Network from 'expo-network';

const db = SQLite.openDatabase('survey.db');

// Initialize database
const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, location TEXT, notes TEXT, synced BOOLEAN DEFAULT 0)'
    );
  });
};

// Save survey locally
const saveSurvey = async (name: string, notes: string) => {
  const { status } = await Location.requestForegroundPermissionsAsync();
  if (status !== 'granted') {
    Alert.alert('Permission denied');
    return;
  }

  const location = await Location.getCurrentPositionAsync({});
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (name, location, notes) VALUES (?, ?, ?)',
      [name, JSON.stringify(location), notes]
    );
  });
};

// Sync unsynced surveys
const syncSurveys = async () => {
  db.transaction(tx => {
    tx.executeSql('SELECT * FROM surveys WHERE synced = 0', [], (_, { rows }) => {
      rows.forEach(async (survey: any) => {
        try {
          const response = await fetch('http://localhost:3000/api/sync', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(survey),
          });

          if (response.ok) {
            db.transaction(tx => {
              tx.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [survey.id]);
            });
          }
        } catch (error) {
          console.error('Sync failed:', error);
        }
      });
    });
  });
};

// Check connectivity and sync
useEffect(() => {
  const checkConnectivity = async () => {
    const isOnline = await Network.getNetworkStateAsync();
    if (isOnline.isInternetReachable) syncSurveys();
  };
  checkConnectivity();
}, []);

initDB();

export default function App() {
  const [name, setName] = useState('');
  const [notes, setNotes] = useState('');

  const handleSubmit = () => {
    if (!name.trim()) return;
    saveSurvey(name, notes);
    setName('');
    setNotes('');
    Alert.alert('Survey saved offline!');
  };

  return (
    <View style={{ padding: 20 }}>
      <TextInput
        placeholder="Survey Name"
        value={name}
        onChangeText={setName}
        style={{ marginBottom: 10, borderBottomWidth: 1 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ marginBottom: 10, borderBottomWidth: 1 }}
        multiline
      />
      <Button title="Submit Survey" onPress={handleSubmit} />
    </View>
  );
}
```

