```dart
// main.dart
import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';

class Survey {
  int? id;
  String name;
  String location;
  String notes;
  bool synced;

  Survey({
    this.id,
    required this.name,
    required this.location,
    required this.notes,
    this.synced = false,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'name': name,
      'location': location,
      'notes': notes,
      'synced': synced ? 1 : 0,
    };
  }

  factory Survey.fromMap(Map<String, dynamic> map) {
    return Survey(
      id: map['id'],
      name: map['name'],
      location: map['location'],
      notes: map['notes'],
      synced: map['synced'] == 1,
    );
  }
}

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._internal();
  factory DatabaseHelper() => _instance;
  late Database _database;

  DatabaseHelper._internal();

  Future<Database> get database async {
    if (_database != null) return _database;
    _database = await _initDatabase();
    return _database;
  }

  Future<Database> _initDatabase() async {
    final path = await getDatabasesPath();
    return await openDatabase(
      '$path/surveys.db',
      onCreate: (db, version) {
        return db.execute(
          'CREATE TABLE surveys(id INTEGER PRIMARY KEY, name TEXT, location TEXT, notes TEXT, synced INTEGER)',
        );
      },
      version: 1,
    );
  }

  Future<int> insertSurvey(Survey survey) async {
    final db = await database;
    return await db.insert('surveys', survey.toMap());
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query(
      'surveys',
      where: 'synced = ?',
      whereArgs: [0],
    );
    return List.generate(maps.length, (i) {
      return Survey.fromMap(maps[i]);
    });
  }

  Future<void> markAsSynced(int id) async {
    final db = await database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

class SurveyApp extends StatefulWidget {
