from flask import Flask, request, jsonify
import sqlite3
import os

app = Flask(__name__)
DB_PATH = 'surveys.db'

# Initialize database
def init_db():
    if not os.path.exists(DB_PATH):
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('''CREATE TABLE surveys
                     (id INTEGER PRIMARY KEY AUTOINCREMENT,
                      name TEXT,
                      location TEXT,
                      notes TEXT)''')
        conn.commit()
        conn.close()

@app.route('/sync', methods=['POST'])
def sync_data():
    data = request.json
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('INSERT INTO surveys (name, location, notes) VALUES (?, ?, ?)',
              (data['name'], data['location'], data['notes']))
    conn.commit()
    conn.close()
    return jsonify({'status': 'success'}), 200

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000)
