```tsx
// App.tsx
import React, { useState } from 'react';
import { View, Text, TextInput, Button, Alert } from 'react-native';
import * as SQLite from 'expo-sqlite';
import * as NetInfo from '@react-native-community/netinfo';
import axios from 'axios';

const db = SQLite.openDatabase('survey.db');

// Initialize database
db.transaction(tx => {
  tx.executeSql(
    'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, location TEXT, notes TEXT, isSynced INTEGER DEFAULT 0);'
  );
});

const App = () => {
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');

  // Save survey locally
  const saveSurvey = () => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (location, notes) VALUES (?, ?);',
        [location, notes],
        () => {
          Alert.alert('Saved offline. Sync when connected.');
          setLocation('');
          setNotes('');
        }
      );
    });
  };

  // Sync unsynced surveys
  const syncData = async () => {
    db.transaction(tx => {
      tx.executeSql('SELECT * FROM surveys WHERE isSynced = 0;', [], async (_, { rows }) => {
        for (const row of rows._array) {
          try {
            await axios.post('http://your-server-ip:3000/sync', row);
            tx.executeSql('UPDATE surveys SET isSynced = 1 WHERE id = ?;', [row.id]);
          } catch (error) {
            console.error('Sync failed:', error);
          }
        }
      });
    });
  };

  // Check connectivity and sync
  React.useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        syncData();
      }
    });
    return () => unsubscribe();
  }, []);

  return (
    <View style={{ padding: 20 }}>
      <TextInput placeholder="Location" value={location} onChangeText={setLocation} />
      <TextInput placeholder="Notes" value={notes} onChangeText={setNotes} />
      <Button title="Save Survey" onPress={saveSurvey} />
    </View>
  );
};

export default App;
