// Connect to MongoDB
mongoose.connect(process.env.MONGO_URI, { useNewUrlParser: true });

// 1. Real-Time Messaging
io.on("connection", (socket) => {
  socket.on("sendMessage", async ({ sender, receiver, message }) => {
    // Example: Deduct 1 credit per message
    const user = await User.findOne({ username: sender });
    if (user.credits > 0) {
      user.credits -= 1;
      await user.save();
      io.to(receiver).emit("receiveMessage", { sender, message });
    } else {
      socket.emit("insufficientCredits");
    }
  });

  socket.on("joinRoom", (username) => {
    socket.join(username);
  });
});

// 2. In-App Monetization (Stripe)
app.post("/purchase-credits", async (req, res) => {
  const { username, amount } = req.body; // e.g., "amount" = 100 (cents)
  const user = await User.findOne({ username });

  try {
    const paymentIntent = await stripe.paymentIntents.create({
      amount,
      currency: "usd",
      payment_method_types: ["card"],
    });

    if (paymentIntent.status === "succeeded") {
      user.credits += amount / 100; // Convert cents to credits
      await user.save();
      res.json({ clientSecret: paymentIntent.client_secret });
    } else {
      res.status(400).json({ error: "Payment failed" });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Start server
server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
