      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ receiver: "user456", content: input }),
    });
    setInput("");
  };

  const purchaseCredits = async () => {
    const amount = 100; // $1.00
    const res = await fetch("/purchase", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ amount }),
    });
    const { clientSecret } = await res.json();
    const stripe = await stripePromise;
    const { error } = await stripe.confirmCardPayment(clientSecret, {
      payment_method: {
        card: document.getElementById("card-element"),
      },
    });

    if (!error) {
      // Add credits to balance
      fetch("/add-credits", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ amount }),
      }).then(() => setBalance((prev) => prev + amount));
    }
  };

  return (
    <div>
      <h1>Social Messaging App</h1>
      <p>Balance: ${balance / 100}</p>
      <div>
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
      <ul>
        {messages.map((msg, i) => (
          <li key={i}>{msg.content}</li>
        ))}
      </ul>
      <button onClick={purchaseCredits}>Buy $1.00 Credits</button>
    </div>
  );
};

export default App;
