### 1. **Backend (Node.js + WebSocket)**
```javascript
// server.js
const express = require('express');
const http = require('http');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve static files (HTML, JS, CSS)
app.use(express.static('public'));
app.use(express.json());

// In-memory data store
let chartData = { labels: [], values: [] };

// WebSocket handler
wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ type: 'init', data: chartData }));

  ws.on('message', (message) => {
    const { label, value } = JSON.parse(message);
    chartData.labels.push(label);
    chartData.values.push(value);
    // Broadcast update to all clients
    wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(JSON.stringify({ type: 'update', data: chartData }));
      }
    });
  });
});

// Handle form submission
app.post('/submit', (req, res) => {
  const { label, value } = req.body;
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify({ type: 'formUpdate', data: { label, value } }));
    }
  });
  res.sendStatus(200);
});

server.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

