### **Backend (Python + Flask + WebSocket)**
```python
# app.py
from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit
import datetime
import threading
import time

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'
socketio = SocketIO(app, cors_allowed_origins="*")

# Store data in memory
data_stream = []

@app.route('/submit', methods=['POST'])
def submit():
    value = request.json.get('value')
    timestamp = datetime.datetime.now().strftime('%H:%M:%S')
    data_stream.append({'timestamp': timestamp, 'value': float(value)})
    socketio.emit('update', {'timestamp': timestamp, 'value': float(value)})
    return jsonify({'status': 'success'})

# Simulate real-time data (optional)
def background_task():
    while True:
        timestamp = datetime.datetime.now().strftime('%H:%M:%S')
        value = float(100 + (10 * (datetime.datetime.now().second % 60)))
        data_stream.append({'timestamp': timestamp, 'value': value})
        socketio.emit('update', {'timestamp': timestamp, 'value': value})
        time.sleep(1)

# Start background task on server launch
threading.Thread(target=background_task, daemon=True).start()

if __name__ == '__main__':
    socketio.run(app, host='0.0.0.0', port=5000)
```

