  <h1>Interactive Dashboard</h1>
  <canvas id="dataChart"></canvas>
  <form id="dataForm">
    <label for="value">Add Data Point:</label>
    <input type="number" id="value" required />
    <button type="submit">Submit</button>
  </form>

  <script>
    // Initialize chart
    const ctx = document.getElementById('dataChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Real-Time Data',
          data: [],
          borderColor: 'rgba(75, 192, 192, 1)',
          fill: false,
        }]
      },
      options: {
        animation: false,
        scales: {
          x: { type: 'linear', position: 'bottom' }
        }
      }
    });

    // Simulate real-time data (every 2 seconds)
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      addDataPoint(randomValue, true);
    }, 2000);

    // Handle form submission
    document.getElementById('dataForm').addEventListener('submit', function (e) {
      e.preventDefault();
      const value = parseFloat(document.getElementById('value').value);
      if (!isNaN(value)) {
        addDataPoint(value, false);
        this.reset();
      }
    });

    // Function to add data to the chart
    function addDataPoint(value, isAuto) {
      const dataset = chart.data.datasets[0];
      const label = chart.data.labels.length + 1;

      chart.data.labels.push(label);
      dataset.data.push(value);

      // Keep only last 10 data points
      if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        dataset.data.shift();
      }

      chart.update();

      // Optional: Log source of data
      const source = isAuto ? 'Auto' : 'User';
      console.log(`Added ${value} (Source: ${source})`);
    }
  </script>
</body>
</html>
```

