```javascript
// server.js
const express = require('express');
const http = require('http');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

let data = [0]; // Simulated real-time data

// Serve static files (HTML + JS)
app.use(express.static(__dirname));
app.use(express.json());

// WebSocket handler
wss.on('connection', (ws) => {
  ws.send(JSON.stringify(data)); // Send initial data
  ws.on('message', (message) => {
    const value = parseInt(message.toString().trim()) || 0;
    data.push(data[data.length - 1] + value); // Update data
    broadcast(JSON.stringify(data)); // Broadcast to all clients
  });
});

// Broadcast helper
function broadcast(data) {
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

// Start server
server.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

