### 2. **`background.js`** (Core blocking logic)
```javascript
// List of known tracking domains (simplified example)
const trackingDomains = [
  "doubleclick.net",
  "adservice.org",
  "googleadservices.com",
  "facebook.com",
  "pixel.facebook.com"
];

// Block requests to tracking domains
chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    const url = new URL(details.url);
    const isTrackingDomain = trackingDomains.some(domain =>
      url.hostname.endsWith(domain)
    );
    if (isTrackingDomain) {
      console.log(`Blocked tracking request to ${url.hostname}`);
      return { cancel: true };
    }
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Optional: Load dynamic blocklist from storage
chrome.storage.local.get("blocklist", (result) => {
  if (result.blocklist) {
    trackingDomains.push(...result.blocklist);
  }
});
```

---

### 3. **`content.js`** (DOM manipulation to remove tracking scripts)
```javascript
// Remove existing tracking scripts from the page
function removeTrackingScripts() {
  const scripts = document.querySelectorAll("script");
  scripts.forEach(script => {
    const src = script.src || "";
    const url = new URL(src, document.location.href);
    if (trackingDomains.some(domain => url.hostname.endsWith(domain))) {
      script.remove();
      console.log(`Removed tracking script from ${url.hostname}`);
    }
  });
}

// Run on initial load and after dynamic content loads
removeTrackingScripts();
new MutationObserver(() => {
  removeTrackingScripts();
}).observe(document.body, { childList: true, subtree: true });
```

