### 4. **`content.js`**  
```javascript
import { TRACKING_DOMAINS } from "./tracking-domains.js";

// Block tracking scripts in the DOM
function blockTrackingScripts() {
  const scripts = document.querySelectorAll("script");
  scripts.forEach(script => {
    const src = script.src || "";
    const url = new URL(src, window.location.href);
    const isTracking = TRACKING_DOMAINS.some(domain => 
      url.hostname.endsWith(domain) || url.hostname === domain
    );
    if (isTracking) {
      console.log(`Removed tracking script: ${url.hostname}`);
      script.remove();
    }
  });
}

// Block tracking iframes
function blockTrackingIframes() {
  const iframes = document.querySelectorAll("iframe");
  iframes.forEach(iframe => {
    const src = iframe.src || "";
    const url = new URL(src, window.location.href);
    const isTracking = TRACKING_DOMAINS.some(domain => 
      url.hostname.endsWith(domain) || url.hostname === domain
    );
    if (isTracking) {
      console.log(`Removed tracking iframe: ${url.hostname}`);
      iframe.remove();
    }
  });
}

// Observe DOM changes to block dynamically added elements
const observer = new MutationObserver((mutations) => {
  mutations.forEach(mutation => {
    mutation.addedNodes.forEach(node => {
      if (node.tagName === "SCRIPT" || node.tagName === "IFRAME") {
        blockTrackingScripts();
        blockTrackingIframes();
      }
    });
  });
});

observer.observe(document.body, {
  childList: true,
  subtree: true
});

// Initial scan
blockTrackingScripts();
blockTrackingIframes();
```

