### 3. **Content Script (`content.ts`)**
```typescript
// content.ts
// Load blocklist from extension resources
const blocklistUrl = chrome.runtime.getURL("blocklist.json");
fetch(blocklistUrl)
  .then((response) => response.json())
  .then((data) => {
    const trackingDomains = data.trackingDomains;

    // Function to check if a script is tracking
    function isTrackingScript(script: HTMLScriptElement): boolean {
      const src = script.src.toLowerCase();
      return trackingDomains.some((domain: string) => src.includes(domain));
    }

    // Remove existing tracking scripts
    function removeExistingTrackingScripts() {
      document.querySelectorAll("script").forEach((script) => {
        if (isTrackingScript(script as HTMLScriptElement)) {
          script.remove();
        }
      });
    }

    // Block dynamically added scripts
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node instanceof HTMLScriptElement && isTrackingScript(node)) {
            node.remove();
          }
        });
      });
    });

    // Start observing the DOM
    observer.observe(document.body, { childList: true, subtree: true });

    // Remove existing scripts
    removeExistingTrackingScripts();
  })
  .catch((error) => {
    console.error("Failed to load blocklist:", error);
  });
```

