import { chrome } from 'webextension-polyfill-ts';
import * as fs from 'fs'; // For local file access (Node.js in background script)
import * as path from 'path';

// Load tracking domains from JSON
const trackerListPath = path.join(__dirname, 'tracking-domains.json');
const trackerData = JSON.parse(fs.readFileSync(trackerListPath, 'utf8'));
const trackers = new Set(trackerData.trackers);

// Block requests to tracking domains
chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    const url = new URL(details.url);
    if (trackers.has(url.hostname)) {
      console.log(`Blocked tracker: ${url.hostname}`);
      return { cancel: true };
    }
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Optional: Allow users to toggle blocking
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.command === "toggleBlocking") {
    trackers.clear(); // For demo purposes only
    sendResponse({ status: "disabled" });
  }
});
