### 🧹 **3. Content Script (`content.js`)**  
This script removes tracking elements (e.g., iframes, scripts) from the DOM.

```javascript
// Remove tracking scripts and iframes from the page
const TRACKING_ATTRIBUTES = ["src", "href", "data-src"];

function blockTrackingElements() {
  const elements = document.querySelectorAll(
    "script, iframe, img, link, embed, object"
  );

  elements.forEach(element => {
    for (const attr of TRACKING_ATTRIBUTES) {
      if (element.hasAttribute(attr)) {
        const url = new URL(element.getAttribute(attr), window.location.href);
        const isTrackingDomain = TRACKING_DOMAINS.some(domain => {
          const regex = new RegExp(`\\.${domain}$|^[^\.]+\.${domain}$`);
          return regex.test(url.hostname);
        });

        if (isTrackingDomain) {
          console.log(`Removed tracking element: ${element.outerHTML}`);
          element.remove();
        }
      }
    }
  });
}

// Run on initial load and after dynamic content updates
blockTrackingElements();

// Optional: Observe DOM changes for dynamically loaded content
const observer = new MutationObserver(blockTrackingElements);
observer.observe(document.body, { childList: true, subtree: true });
```

