    // === Data Initialization ===
    const stocks = Array.from({ length: gridSize.width * gridSize.height }, (_, i) => ({
      id: i,
      price: Math.random() * 100,
      x: i % gridSize.width,
      y: Math.floor(i / gridSize.width)
    }));

    // === Color Scale ===
