        .attr("fill", d => colorScale(d.price));
    }, refreshInterval);

    // === Optional: Add Axis Labels ===
    const xAxis = d3.axisBottom(d3.scaleLinear().domain([0, gridSize.width]).range([0, gridSize.width * cellSize]));
    const yAxis = d3.axisLeft(d3.scaleLinear().domain([0, gridSize.height]).range([0, gridSize.height * cellSize]));

    svg.append("g")
      .attr("transform", `translate(0,${gridSize.height * cellSize})`)
      .call(xAxis);

    svg.append("g")
      .attr("transform", `translate(0,0)`)
      .call(yAxis);
  </script>
