    const width = gridSize * cellSize;
    const height = gridSize * cellSize;
    const updateInterval = 1000; // Real-time update every 1s
    const stockSymbols = ["AAPL", "GOOGL", "MSFT", "AMZN", "TSLA", "NVDA", "FB", "TSM", "AVGO", "CSCO"];

