        data.flatMap((row, i) => row.map((cell, j) => ({ ...cell, row: i, col: j }))),
        v => d3.mean(v, d => d.price),
        d => d.row,
        d => d.col
      )).attr("fill", ([, , mean]) => colorScale(mean));
    }, updateInterval);
  </script>
