    // Generate initial mock stock price data (5 stocks × 50 time intervals)
    const generateData = () => {
      const rows = 5, cols = 50;
      return Array.from({length: rows}, () => 
        Array.from({length: cols}, () => 100 + Math.random() * 20) // $100-$120
      );
    };

    let zData = generateData();
    const stocks = ['Stock A', 'Stock B', 'Stock C', 'Stock D', 'Stock E'];
    const timeLabels = Array.from({length: 50}, (_, i) => `T${i+1}`);

    const trace = {
      z: zData,
      x: timeLabels,
      y: stocks,
      type: 'heatmap',
      colorscale: 'Hot',
      showscale: true,
      hoverongaps: false
    };

    const layout = {
      title: 'Real-Time Stock Price Heatmap',
      xaxis: { title: 'Time Intervals' },
      yaxis: { title: 'Stocks' },
      dragmode: 'zoom'
    };

    Plotly.newPlot('heatmap', [trace], layout);

    // Simulate real-time updates every second
    setInterval(() => {
      // Update prices with random fluctuations
      zData = zData.map(row => 
        row.map(price => price + (Math.random() - 0.5) * 5) // ±$2.50
      );

      // Shift time window to show latest data
      zData = zData.map(row => [...row.slice(1), 100 + Math.random() * 20]);
      timeLabels.push(`T${timeLabels.length + 1}`);
      timeLabels.shift();

      Plotly.restyle('heatmap', 'z', [zData]);
      Plotly.relayout('heatmap', {xaxis: {title: `Latest ${timeLabels.length} Intervals`}});
