### 📦 **Client-Side Code (HTML + JS)**

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Stock Heatmap</title>
  <script src="https://d3js.org/d3.v7.min.js"></script>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <canvas id="heatmap" width="800" height="600"></canvas>
  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");

    // Grid size and cell size
    const gridSize = 20;
    const cellSize = 20;
    let data = Array.from({ length: gridSize }, () =>
      Array.from({ length: gridSize }, () => Math.random() * 100)
    );

    // Color mapping (blue → red)
    function getColor(value) {
      const max = 100;
      const ratio = value / max;
      const r = Math.floor(255 * ratio);
      const g = 0;
      const b = Math.floor(255 * (1 - ratio));
      return `rgb(${r},${g},${b})`;
    }

    // Initial draw
    function draw(transform = d3.zoomIdentity) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (let y = 0; y < gridSize; y++) {
        for (let x = 0; x < gridSize; x++) {
          ctx.fillStyle = getColor(data[y][x]);
          ctx.fillRect(
            x * cellSize * transform.k + transform.x,
            y * cellSize * transform.k + transform.y,
            cellSize * transform.k,
            cellSize * transform.k
          );
        }
      }
    }

    // Zoom/pan behavior
    const zoom = d3.zoom().scaleExtent([0.5, 4]).on("zoom", (event) => {
      draw(event.transform);
    });
    d3.select(canvas).call(zoom);

    // Simulate real-time updates (mock WebSocket)
    setInterval(() => {
      const x = Math.floor(Math.random() * gridSize);
      const y = Math.floor(Math.random() * gridSize);
      data[y][x] = Math.random() * 100;
      draw(d3.zoomTransform(canvas)); // Redraw with current transform
    }, 1000);

    // Initial draw
    draw();
  </script>
</body>
