### 📄 Code (Self-contained HTML + TypeScript):

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Stock Price Heatmap</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; border: 1px solid #ccc; }
  </style>
</head>
<body>
  <canvas id="heatmap"></canvas>

  <script>
    // === CONFIG ===
    const width = 800, height = 600;
    const cols = 100, rows = 50;
    const cellWidth = width / cols, cellHeight = height / rows;
    const zoomSpeed = 0.1;
    const panSpeed = 1.5;

    // === STATE ===
    let scale = 1;
    let offsetX = 0, offsetY = 0;
    let prices = Array.from({ length: rows }, () => 
      Array.from({ length: cols }, () => Math.random() * 100)
    );

    // === CANVAS ===
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    canvas.width = width;
    canvas.height = height;

    // === UTILS ===
    function getColor(value) {
      // Map 0-100 to red/green gradient
      const mid = 50;
      const delta = Math.abs(value - mid);
      const intensity = 255 - Math.floor(delta * 5); // 0-255
      const r = value < mid ? 255 : 0;
      const g = value > mid ? 255 : 0;
      return `rgb(${r}, ${g}, 0, ${intensity / 255})`;
    }

    function drawHeatmap() {
      ctx.clearRect(0, 0, width, height);
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          const value = prices[y][x];
          const color = getColor(value);
          const x0 = (x * cellWidth + offsetX) * scale;
          const y0 = (y * cellHeight + offsetY) * scale;
          ctx.fillStyle = color;
          ctx.fillRect(x0, y0, cellWidth * scale, cellHeight * scale);
        }
      }
    }

    // === INTERACTIONS ===
    canvas.addEventListener('wheel', (e) => {
      const zoomFactor = e.deltaY > 0 ? 1 - zoomSpeed : 1 + zoomSpeed;
      scale = Math.max(0.2, Math.min(3, scale * zoomFactor));
      drawHeatmap();
    });

    canvas.addEventListener('mousedown', (e) => {
      const startX = e.offsetX, startY = e.offsetY;
      canvas.addEventListener('mousemove', onMouseMove);
      function onMouseMove(e) {
        offsetX += (e.offsetX - startX) / scale;
        offsetY += (e.offsetY - startY) / scale;
        drawHeatmap();
      }
      canvas.addEventListener('mouseup', () => {
        canvas.removeEventListener('mousemove', onMouseMove);
      }, { once: true });
    });

    // === REAL-TIME UPDATES ===
    setInterval(() => {
      // Simulate price changes
      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          prices[y][x] += (Math.random() - 0.5) * 5; // Random ±2.5
          prices[y][x] = Math.max(0, Math.min(100, prices[y][x])); // Clamp
        }
      }
      drawHeatmap();
    }, 1000);

    // === INITIAL DRAW ===
    drawHeatmap();
  </script>
</body>
</html>
```

