### ✅ **HTML + JavaScript (D3.js)**
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
    }
    svg {
      width: 100vw;
      height: 100vh;
    }
  </style>
</head>
<body>
  <svg></svg>

  <script src="https://d3js.org/d3.v7.min.js"></script>
  <script>
    const width = window.innerWidth;
    const height = window.innerHeight;
    const cols = 20;
    const rows = 15;
    const cellSize = 30;

    const svg = d3.select("svg");
    const g = svg.append("g");

    // Generate grid data
    const data = d3.range(rows).map(() => d3.range(cols).map(() => Math.random() * 100));

    // Color scale
    const colorScale = d3.scaleSequential(d3.interpolateViridis)
      .domain([0, 100]);

    // Draw heatmap
    const cells = g.selectAll("rect")
      .data(d3.flatRollup(d3.range(rows).flatMap((r, i) => d3.range(cols).map(c => [i, c, data[i][c]])), 
        ([[r, c, v]]) => v, d => d[0]), ([r, c, v]) => [r, c]);

    cells.enter()
      .append("rect")
      .attr("x", ([r, c]) => c * cellSize)
      .attr("y", ([r, c]) => r * cellSize)
      .attr("width", cellSize)
      .attr("height", cellSize)
      .attr("fill", ([r, c, v]) => colorScale(v));

    // Real-time updates
    setInterval(() => {
      data.forEach(row => {
        row.forEach((val, i) => {
          row[i] = val + (Math.random() - 0.5) * 10;
        });
      });
      g.selectAll("rect")
        .data(d3.flatRollup(d3.range(rows).flatMap((r, i) => d3.range(cols).map(c => [i, c, data[i][c]])), 
          ([[r, c, v]]) => v, d => d[0]), ([r, c, v]) => [r, c])
        .attr("fill", ([r, c, v]) => colorScale(v));
    }, 1000);

    // Zoom/pan
    const zoom = d3.zoom()
      .scaleExtent([0.5, 5])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);
  </script>
</body>
</html>
```

