```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { DragDropContext, Droppable, Draggable, DropResult } from 'react-beautiful-dnd';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

const App: React.FC = () => {
  const [board, setBoard] = useState<{
    columns: Record<string, { id: string; title: string; taskIds: string[] }>;
    tasks: Record<string, { id: string; content: string }>;
  }>({
    columns: {},
    tasks: {},
  });

  useEffect(() => {
    socket.on('sync-board', (updatedBoard) => {
      setBoard(updatedBoard);
    });

    // Initial sync
    socket.emit('sync-board');
  }, []);

  const onDragEnd = (result: DropResult) => {
    const { source, destination, draggableId } = result;

    if (!destination) return;

    const sourceColumn = board.columns[source.droppableId];
    const destinationColumn = board.columns[destination.droppableId];

    // Remove task from source
    const sourceTaskIds = [...sourceColumn.taskIds];
    const [movedTask] = sourceTaskIds.splice(source.index, 1);

    // Add task to destination
    const destinationTaskIds = [...destinationColumn.taskIds];
    destinationTaskIds.splice(destination.index, 0, movedTask);

    // Update board state
    const updatedColumns = {
      ...board.columns,
      [source.droppableId]: { ...sourceColumn, taskIds: sourceTaskIds },
      [destination.droppableId]: { ...destinationColumn, taskIds: destinationTaskIds },
    };

    const updatedBoard = {
      ...board,
      columns: updatedColumns,
    };

    setBoard(updatedBoard);
    socket.emit('update-task', updatedBoard); // Sync with backend
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
        {Object.values(board.columns).map((column) => (
          <Droppable key={column.id} droppableId={column.id}>
            {(provided) => (
              <div
                ref={provided.innerRef}
                style={{
                  border: '1px solid #ccc',
                  padding: '10px',
                  borderRadius: '8px',
                  width: '250px',
                }}
              >
                <h3>{column.title}</h3>
                {column.taskIds.map((taskId, index) => (
                  <Draggable key={taskId} draggableId={taskId} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        style={{
                          ...provided.draggableProps.style,
                          background: '#f0f0f0',
                          margin: '5px 0',
                          padding: '10px',
                          borderRadius: '4px',
                        }}
                      >
                        {board.tasks[taskId].content}
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
};

export default App;
```

