  useEffect(() => {
    const newSocket = io("http://localhost:3001"); // Connect to backend
    setSocket(newSocket);

    newSocket.on("connect", () => {
      console.log("Connected to backend");
    });

    newSocket.on("boardUpdate", (updatedBoard: Column[]) => {
      setColumns(updatedBoard);
    });

    return () => newSocket.disconnect();
  }, []);

  const initBoard = () => {
    if (socket) {
      const initialBoard: Column[] = [
        {
