File: `app.py`
```python
from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy
from flask_socketio import SocketIO, emit
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = os.getenv('DATABASE_URL', 'sqlite:///tasks.db')
db = SQLAlchemy(app)
socketio = SocketIO(app, cors_allowed_origins="*")

class Task(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.String(200), nullable=False)
    column = db.Column(db.String(50), default='todo')
    position = db.Column(db.Integer, default=0)
    board_id = db.Column(db.String(50), default='default_board')

@app.route('/board/<board_id>/tasks')
def get_tasks(board_id):
    tasks = Task.query.filter_by(board_id=board_id).order_by(Task.position).all()
    return jsonify([{'id': t.id, 'content': t.content, 'column': t.column, 'position': t.position} for t in tasks])

@app.route('/task', methods=['POST'])
def create_task():
    data = request.json
    task = Task(content=data['content'], board_id=data['board_id'])
    db.session.add(task)
    db.session.commit()
    return jsonify({'id': task.id})

@socketio.on('task_moved')
def handle_task_moved(data):
    task = Task.query.get(data['id'])
    if task:
        task.column = data['column']
        task.position = data['position']
        db.session.commit()
        emit('task_updated', data, broadcast=True)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    socketio.run(app, debug=True)
```

