```html
<!DOCTYPE html>
<html>
<head>
  <title>Task Board</title>
  <style>
    .board { display: flex; gap: 20px; }
    .column { border: 1px solid #ccc; padding: 10px; min-width: 200px; }
    .task { padding: 10px; margin: 5px 0; background: #f0f0f0; cursor: grab; }
  </style>
</head>
<body>
  <div class="board">
    <div class="column" id="todo" data-column="todo">TODO</div>
    <div class="column" id="in-progress" data-column="in-progress">In Progress</div>
    <div class="column" id="done" data-column="done">Done</div>
  </div>
  <button onclick="createTask()">Add Task</button>

  <script src="https://cdn.socket.io/4.5.4/socket.io.min.js"></script>
  <script>
    const socket = io();
    const boardId = 'default_board';
    const columns = ['todo', 'in-progress', 'done'];

    // Load tasks
    function loadTasks() {
      fetch(`/board/${boardId}/tasks`)
        .then(res => res.json())
        .then(tasks => {
          columns.forEach(col => {
            document.getElementById(col).innerHTML = `<h3>${col.toUpperCase()}</h3>`;
          });
          tasks.forEach(task => renderTask(task));
        });
    }

    // Render task
    function renderTask(task) {
      const col = document.getElementById(task.column);
      const taskDiv = document.createElement('div');
      taskDiv.className = 'task';
      taskDiv.draggable = true;
      taskDiv.textContent = task.content;
      taskDiv.dataset.id = task.id;
      taskDiv.dataset.column = task.column;
      taskDiv.dataset.position = task.position;

      // Drag events
      taskDiv.addEventListener('dragstart', e => e.dataTransfer.setData('text/plain', task.id));
      taskDiv.addEventListener('dragover', e => e.preventDefault());
      taskDiv.addEventListener('drop', e => {
        const taskId = e.dataTransfer.getData('text');
        const taskEl = document.querySelector(`[data-id='${taskId}']`);
        const targetCol = e.target.closest('.column');
        if (targetCol) {
          const newColumn = targetCol.dataset.column;
          const newPosition = Array.from(targetCol.children).indexOf(taskEl);
          socket.emit('task_moved', { id: taskId, column: newColumn, position: newPosition });
        }
      });

      col.appendChild(taskDiv);
    }

    // Create task
    function createTask() {
      const content = prompt('Task content:');
      if (content) {
        fetch('/task', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ content, board_id: boardId })
        }).then(res => res.json())
          .then(data => renderTask({ id: data.id, content, column: 'todo', position: 0 }));
      }
    }

    // Listen for updates
    socket.on('task_updated', data => {
      fetch(`/board/${boardId}/tasks`)
        .then(res => res.json())
        .then(tasks => {
          columns.forEach(col => document.getElementById(col).innerHTML = `<h3>${col.toUpperCase()}</h3>`));
          tasks.forEach(task => renderTask(task));
        });
    });

    // Initial load
    loadTasks();
  </script>
</body>
</html>
