const express = require('express');
const http = require('http');
const { app, server } = require('./frontend');
const { Server } = require('socket.io');

const PORT = 3000;

const app = express();
const httpServer = http.createServer(app);
const io = new Server(httpServer, {
  cors: { origin: '*' },
});

// In-memory storage for tasks
const projectTasks = {
  project1: [
    { id: '1', column: 'todo', content: 'Task 1' },
    { id: '2', column: 'inprogress', content: 'Task 2' },
    { id: '3', column: 'done', content: 'Task 3' },
  ],
};

io.on('connection', (socket) => {
  console.log('Client connected:', socket.id);

  socket.on('joinProject', (projectId) => {
    socket.join(projectId);
    socket.emit('taskUpdate', projectTasks[projectId] || []);
  });

  socket.on('updateTask', (projectId, updatedTask) => {
    const tasks = projectTasks[projectId];
    const index = tasks.findIndex((t) => t.id === updatedTask.id);
    if (index !== -1) {
      tasks[index] = updatedTask;
      io.to(projectId).emit('taskUpdate', tasks);
    }
  });
});

httpServer.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
