import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { io } from 'socket.io-client';

const socket = io('http://localhost:3000');

const App: React.FC = () => {
  const [tasks, setTasks] = useState<{ id: string; column: string; content: string }[]>([]);
  const [projectId] = useState('project1');

  useEffect(() => {
    socket.emit('joinProject', projectId);

    socket.on('taskUpdate', (updatedTasks) => {
      setTasks(updatedTasks);
    });

    return () => {
      socket.off('taskUpdate');
    };
  }, [projectId]);

  const onDragEnd = (result: any) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    const updatedTask = {
      id: draggableId,
      column: destination.droppableId,
      content: tasks.find((t) => t.id === draggableId)?.content || 'New Task',
    };

    setTasks((prev) =>
      prev.map((task) =>
        task.id === draggableId ? { ...task, column: destination.droppableId } : task
      )
    );

    socket.emit('updateTask', projectId, updatedTask);
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
        {['todo', 'inprogress', 'done'].map((column) => (
          <Droppable droppableId={column} key={column}>
            {(provided) => (
              <div
                {...provided.droppableProps}
                ref={provided.innerRef}
                style={{
                  border: '1px solid #ccc',
                  padding: '10px',
                  borderRadius: '8px',
                  width: '300px',
                }}
              >
                <h3>{column.toUpperCase()}</h3>
                {tasks
                  .filter((task) => task.column === column)
                  .map((task, index) => (
                    <Draggable key={task.id} draggableId={task.id} index={index}>
                      {(provided) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                          style={{
                            ...provided.draggableProps.style,
                            padding: '8px',
                            margin: '5px 0',
                            backgroundColor: '#f0f0f0',
                            borderRadius: '4px',
                          }}
                        >
                          {task.content}
                        </div>
                      )}
                    </Draggable>
                  ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
};

export default App;
```

