import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import mongoose from 'mongoose';
import cors from 'cors';

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "http://localhost:3000", methods: ["GET", "POST"] },
});

// MongoDB connection
mongoose.connect('mongodb://localhost:27017/taskboard', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Task schema
interface Task {
  title: string;
  description: string;
  status: string;
}
const taskSchema = new mongoose.Schema<Task>({
  title: String,
  description: String,
  status: String,
  createdAt: { type: Date, default: Date.now },
});
const TaskModel = mongoose.model<Task>('Task', taskSchema);

// API routes
app.use(cors());
app.use(express.json());

app.get('/api/tasks', async (req, res) => {
  const tasks = await TaskModel.find();
  res.json(tasks);
});

app.post('/api/tasks', async (req, res) => {
  const task = new TaskModel(req.body);
  await task.save();
  io.emit('taskUpdate', task);
  res.json(task);
});

// WebSocket for real-time updates
io.on('connection', (socket) => {
  console.log('Client connected:', socket.id);

  socket.on('updateTask', async (taskId: string, newStatus: string) => {
    await TaskModel.findByIdAndUpdate(taskId, { status: newStatus });
    io.emit('taskUpdate', { id: taskId, status: newStatus });
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

// Start server
server.listen(4000, () => {
