import React, { useEffect, useState } from 'react';
import { DndProvider, useDrag, useDrop } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import io from 'socket.io-client';

const socket = io('http://localhost:4000');

interface Task {
  _id: string;
  title: string;
  description: string;
  status: string;
  createdAt: Date;
}

const Task: React.FC<{ task: Task; moveTask: (taskId: string, newStatus: string) => void }> = ({ task, moveTask }) => {
  const [, ref] = useDrag({
    type: 'TASK',
    item: { id: task._id, status: task.status },
  });

  const [, drop] = useDrop({
    accept: 'TASK',
    drop: (item: { id: string, status: string }) => {
      moveTask(item.id, task.status);
    },
  });

  return (
    <div ref={(node) => ref(drop(node))} style={{ padding: '10px', border: '1px solid #ccc', marginBottom: '10px' }}>
      <strong>{task.title}</strong>
      <p>{task.description}</p>
    </div>
  );
};

const TaskBoard: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    // Fetch initial tasks
    fetch('http://localhost:4000/api/tasks')
      .then(res => res.json())
      .then(data => setTasks(data));

    // Listen for real-time updates
    socket.on('taskUpdate', (updatedTask: Partial<Task>) => {
      setTasks(prev => 
        prev.map(task => 
          task._id === updatedTask._id 
            ? { ...task, status: updatedTask.status || task.status } 
            : task
        )
      );
    });

    return () => socket.off('taskUpdate');
  }, []);

  const moveTask = (taskId: string, newStatus: string) => {
    socket.emit('updateTask', taskId, newStatus);
  };

  const addTask = () => {
    const newTask: Omit<Task, '_id' | 'createdAt'> = {
      title: 'New Task',
      description: 'Edit me',
      status: 'To Do',
    };
    fetch('http://localhost:4000/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newTask),
    });
  };

  const columns = ['To Do', 'In Progress', 'Done'];
  return (
    <DndProvider backend={HTML5Backend}>
      <div style={{ display: 'flex', gap: '20px' }}>
        {columns.map(column => (
          <div key={column} style={{ flex: 1, border: '1px solid #999', padding: '10px' }}>
            <h3>{column}</h3>
            {tasks
              .filter(task => task.status === column)
              .map(task => (
                <Task key={task._id} task={task} moveTask={moveTask} />
              ))}
          </div>
        ))}
      </div>
      <button onClick={addTask}>Add Task</button>
    </DndProvider>
  );
};

export default function App() {
  return <TaskBoard />;
}
