import React, { useEffect, useState } from "react";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import socket from "./socket";

const App: React.FC = () => {
  const [board, setBoard] = useState<TaskBoard | null>(null);

  // Fetch initial board
  useEffect(() => {
    fetch("/api/board")
      .then((res) => res.json())
      .then((data) => setBoard(data));
  }, []);

  // Sync updates from server
  useEffect(() => {
    socket.on("boardUpdated", (updatedBoard: TaskBoard) => {
      setBoard(updatedBoard);
    });
    return () => socket.off("boardUpdated");
  }, []);

  // Handle drag-and-drop
  const onDragEnd = (result: any) => {
    if (!board || !result.destination) return;

    const { source, destination } = result;
    const sourceColumn = board.columns[source.droppableId];
    const destColumn = board.columns[destination.droppableId];

    if (!sourceColumn || !destColumn) return;

    // Remove task from source
    const task = sourceColumn.taskIds.splice(source.index, 1)[0];
    // Add task to destination
    destColumn.taskIds.splice(destination.index, 0, task);

    // Update state
    const updatedBoard = { ...board };
    setBoard(updatedBoard);

    // Send update to server
    socket.emit("taskMoved", updatedBoard);
  };

  if (!board) return <div>Loading...</div>;

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: "flex", gap: "20px", padding: "20px" }}>
        {Object.values(board.columns).map((column) => (
          <Droppable key={column.id} droppableId={column.id}>
            {(provided) => (
              <div
                {...provided.droppableProps}
                ref={provided.innerRef}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "10px",
                  width: "250px",
                }}
              >
                <h3>{column.title}</h3>
                {column.taskIds.map((taskId, index) => {
                  const task = board.tasks[taskId];
                  return (
                    <Draggable key={taskId} draggableId={taskId} index={index}>
                      {(provided) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                          style={{
                            ...provided.draggableProps.style,
                            padding: "8px",
                            margin: "4px 0",
                            background: "#f0f0f0",
                            borderRadius: "4px",
                          }}
                        >
                          {task.content}
                        </div>
                      )}
                    </Draggable>
                  );
                })}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
};

export default App;
```

