### **1. Backend (Node.js + Express + Socket.IO)**
Create a file `server.js`:

```javascript
const express = require('express');
const http = require('http');
const { v4: uuidv4 } = require('uuid');
const cors = require('cors');
const socketIO = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIO(server, {
  cors: { origin: '*', methods: ['GET', 'POST'] },
});

// Initial task board data
let taskBoards = {};

// API to get task boards
app.get('/api/boards/:id', (req, res) => {
  const boardId = req.params.id;
  res.json(taskBoards[boardId] || { columns: [], tasks: [] });
});

// Socket.IO logic
io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  socket.on('createBoard', () => {
    const boardId = uuidv4();
    taskBoards[boardId] = { columns: ['To Do', 'In Progress', 'Done'], tasks: [] };
    socket.emit('boardCreated', { boardId });
  });

  socket.on('joinBoard', (boardId) => {
    if (!taskBoards[boardId]) {
      taskBoards[boardId] = { columns: ['To Do', 'In Progress', 'Done'], tasks: [] };
    }
    socket.join(boardId);
    socket.emit('boardState', taskBoards[boardId]);
  });

  socket.on('moveTask', ({ boardId, taskId, newColumnIndex }) => {
    const board = taskBoards[boardId];
    const task = board.tasks.find((t) => t.id === taskId);
    if (task) {
      task.columnIndex = newColumnIndex;
      io.to(boardId).emit('taskMoved', { taskId, newColumnIndex });
    }
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

const PORT = 3000;
server.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

