### **2. Frontend (React + React DnD + Socket.IO)**
Create an `index.html` file with embedded React and dependencies:

```html
<!DOCTYPE html>
<html>
<head>
  <title>Task Board</title>
  <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
  <script src="https://unpkg.com/@react-dnd/core@15.0.0/dist/index.umd.js"></script>
  <script src="https://unpkg.com/@react-dnd/html5-backend@15.0.0/dist/index.umd.js"></script>
  <script src="https://unpkg.com/socket.io-client@4.5.4/dist/socket.io.js"></script>
  <style>
    .column { border: 1px solid #ccc; padding: 10px; min-width: 200px; display: inline-block; vertical-align: top; margin: 10px; }
    .task { border: 1px solid #000; padding: 5px; margin: 5px; background: #f9f9f9; }
  </style>
</head>
<body>
  <div id="root"></div>
  <script type="text/javascript">
    const { useState, useEffect } = React;
    const { DndProvider, useDrag, useDrop } = ReactDnd;
    const { HTML5Backend } = ReactDndHtml5Backend;

    const Task = ({ id, text, columnIndex, moveTask }) => {
      const [{ isDragging }, drag] = useDrag({
        type: 'task',
        item: { id, columnIndex },
        collect: (monitor) => ({
          isDragging: monitor.isDragging(),
        }),
      });

      const [, drop] = useDrop({
        accept: 'task',
        drop: (item) => {
          if (item.columnIndex !== columnIndex) {
            moveTask(id, item.columnIndex);
          }
        },
      });

      return React.createElement('div', { ref: (node) => drag(drop(node)), style: { opacity: isDragging ? 0.5 : 1 } }, text);
    };

    const Column = ({ column, tasks, onMoveTask }) => {
      return React.createElement('div', { className: 'column' },
        React.createElement('h3', null, column),
        tasks.map((task) =>
          React.createElement(Task, {
            key: task.id,
            id: task.id,
            text: task.text,
            columnIndex: task.columnIndex,
            moveTask: onMoveTask,
          })
        )
      );
    };

    const TaskBoard = ({ boardId }) => {
      const [columns, setColumns] = useState([]);
      const [tasks, setTasks] = useState([]);
      const socket = io('http://localhost:3000');

      useEffect(() => {
        socket.emit('joinBoard', boardId);

        socket.on('boardState', ({ columns: cols, tasks: t }) => {
          setColumns(cols);
          setTasks(t.map((t) => ({ ...t, columnIndex: t.columnIndex })));
        });

        socket.on('taskMoved', ({ taskId, newColumnIndex }) => {
          setTasks((prev) =>
            prev.map((t) => (t.id === taskId ? { ...t, columnIndex: newColumnIndex } : t))
          );
        });
      }, [boardId]);

      const moveTask = (taskId, newColumnIndex) => {
        setTasks((prev) =>
          prev.map((t) => (t.id === taskId ? { ...t, columnIndex: newColumnIndex } : t))
        );
        socket.emit('moveTask', { boardId, taskId, newColumnIndex });
      };

      return React.createElement(DndProvider, { backend: HTML5Backend },
        columns.map((col, idx) =>
          React.createElement(Column, {
            key: idx,
            column: col,
            tasks: tasks.filter((t) => t.columnIndex === idx),
            onMoveTask: moveTask,
          })
        )
      );
    };

    const App = () => {
      const [boardId, setBoardId] = useState('');
      const [isCreating, setIsCreating] = useState(false);

      const createBoard = () => {
        const socket = io('http://localhost:3000');
        socket.emit('createBoard');
        socket.on('boardCreated', ({ boardId }) => {
          setBoardId(boardId);
          setIsCreating(false);
        });
      };

      return React.createElement('div', null,
        React.createElement('button', { onClick: () => setIsCreating(true) }, 'Create New Board'),
        isCreating && React.createElement('button', { onClick: createBoard }, 'Confirm'),
        boardId
          ? React.createElement(TaskBoard, { boardId })
          : React.createElement('p', null, 'Enter or create a board ID to start.')
      );
    };

    ReactDOM.createRoot(document.getElementById('root')).render(React.createElement(App));
  </script>
</body>
</html>
