import React, { useState, useEffect } from "react";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import socket from "./socket";
import "./App.css";

function App() {
  const [board, setBoard] = useState(null);

  // Receive initial board state
  useEffect(() => {
    socket.on("board:init", (initialBoard) => setBoard(initialBoard));
    socket.on("board:update", (updatedBoard) => setBoard(updatedBoard));
  }, []);

  const onDragEnd = (result) => {
    if (!board || !result.destination) return;

    const { source, destination } = result;
    const sourceColumn = board.columns[source.droppableId];
    const destColumn = board.columns[destination.droppableId];

    if (sourceColumn === destColumn) {
      // Same column
      const newTaskIds = Array.from(sourceColumn.taskIds);
      const [removed] = newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, removed);

      const newColumns = {
        ...board.columns,
        [source.droppableId]: {
          ...sourceColumn,
          taskIds: newTaskIds,
        },
      };

      setBoard({ ...board, columns: newColumns });
      socket.emit("board:update", { ...board, columns: newColumns });
    } else {
      // Different column
      const sourceTaskIds = Array.from(sourceColumn.taskIds);
      const [removed] = sourceTaskIds.splice(source.index, 1);

      const destTaskIds = Array.from(destColumn.taskIds);
      destTaskIds.splice(destination.index, 0, removed);

      const newColumns = {
        ...board.columns,
        [source.droppableId]: {
          ...sourceColumn,
          taskIds: sourceTaskIds,
        },
        [destination.droppableId]: {
          ...destColumn,
          taskIds: destTaskIds,
        },
      };

      setBoard({ ...board, columns: newColumns });
      socket.emit("board:update", { ...board, columns: newColumns });
    }
  };

  if (!board) return <div>Loading...</div>;

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: "flex", gap: "20px", padding: "20px" }}>
        {Object.values(board.columns).map((column) => (
          <Droppable droppableId={column.id} key={column.id}>
            {(provided) => (
              <div
                {...provided.droppableProps}
                ref={provided.innerRef}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "10px",
                  width: "250px",
                }}
              >
                <h3>{column.title}</h3>
                {column.taskIds.map((taskId, index) => {
                  const task = board.tasks[taskId];
                  return (
                    <Draggable key={task.id} draggableId={task.id} index={index}>
                      {(provided) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                          style={{
                            ...provided.draggableProps.style,
                            background: "#f0f0f0",
                            margin: "5px 0",
                            padding: "10px",
                            borderRadius: "4px",
                          }}
                        >
                          {task.content}
                        </div>
                      )}
                    </Draggable>
                  );
                })}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
}

export default App;
```

