const { useState, useEffect } = React;

function App() {
  const [board, setBoard] = useState(null);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const io = require('socket.io-client');
    const socket = io('http://localhost:3000');
    setSocket(socket);

    socket.on('init', (initialBoard) => setBoard(initialBoard));
    socket.on('updateBoard', (updatedBoard) => setBoard(updatedBoard));

    return () => socket.disconnect();
  }, []);

  if (!board) return <div>Loading...</div>;

  const onDragStart = (e, taskId, sourceColumn) => {
    e.dataTransfer.setData('taskId', taskId);
    e.dataTransfer.setData('sourceColumn', sourceColumn);
  };

  const onDragOver = (e) => e.preventDefault();

  const onDrop = (e, targetColumn) => {
    const taskId = e.dataTransfer.getData('taskId');
    const sourceColumn = e.dataTransfer.getData('sourceColumn');

    const newBoard = { ...board };
    const task = newBoard.columns[sourceColumn].tasks.find(t => t.id === taskId);
    const index = newBoard.columns[sourceColumn].tasks.indexOf(task);

    newBoard.columns[sourceColumn].tasks.splice(index, 1);
    newBoard.columns[targetColumn].tasks.push(task);

    setBoard(newBoard);
    socket.emit('updateBoard', newBoard);
  };

  return (
    <div className="board">
      {Object.values(board.columns).map((col) => (
        <div
          key={col.id}
          className="column"
          onDragOver={onDragOver}
          onDrop={(e) => onDrop(e, col.id)}
        >
          <h3>{col.title}</h3>
          {col.tasks.map((task) => (
            <div
              key={task.id}
              className="task"
              draggable
              onDragStart={(e) => onDragStart(e, task.id, col.id)}
            >
              {task.text || `Task ${task.id}`}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
