import React, { useEffect, useState } from "react";
import { DndProvider } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import socket from "./socket";

type Task = { id: string; text: string };
type Column = { id: string; tasks: Task[] };
type Board = { columns: Column[] };

const App: React.FC = () => {
  const [board, setBoard] = useState<Board>({ columns: [] });

  useEffect(() => {
    socket.on("sync-board", (newBoard: Board) => setBoard(newBoard));
    socket.emit("update-board", board); // Sync initial state
  }, []);

  const moveTask = (taskId: string, sourceColId: string, targetColId: string) => {
    const newBoard = { ...board };
    const sourceCol = newBoard.columns.find((col) => col.id === sourceColId)!;
    const task = sourceCol.tasks.find((t) => t.id === taskId)!;
    sourceCol.tasks = sourceCol.tasks.filter((t) => t.id !== taskId);
    const targetCol = newBoard.columns.find((col) => col.id === targetColId)!;
    targetCol.tasks.push(task);
    setBoard(newBoard);
    socket.emit("update-board", newBoard);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div style={{ display: "flex", gap: "20px", padding: "20px" }}>
        {board.columns.map((col) => (
          <Column key={col.id} column={col} onMoveTask={moveTask} />
        ))}
      </div>
    </DndProvider>
  );
};

type ColumnProps = {
  column: Column;
  onMoveTask: (taskId: string, sourceColId: string, targetColId: string) => void;
};

const Column: React.FC<ColumnProps> = ({ column, onMoveTask }) => {
  const [{ isOver, item }, drop] = useDrop(() => ({
    accept: "TASK",
    drop: (item: { id: string, sourceColId: string }) => onMoveTask(item.id, item.sourceColId, column.id),
    collect: (monitor) => ({
      isOver: monitor.isOver(),
      item: monitor.getItem(),
    }),
  }));

  const [{ isDragging }, drag] = useDrag(() => ({
    type: "TASK",
    item: { id: column.id, sourceColId: column.id },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drop}
      style={{
        border: "1px solid #ccc",
        padding: "10px",
        width: "200px",
        minHeight: "100px",
      }}
    >
      <h3>{column.id}</h3>
      {column.tasks.map((task) => (
        <Task key={task.id} task={task} columnId={column.id} />
      ))}
    </div>
  );
};

type TaskProps = {
  task: Task;
  columnId: string;
};

const Task: React.FC<TaskProps> = ({ task, columnId }) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: "TASK",
    item: { id: task.id, sourceColId: columnId },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drag}
      style={{
        opacity: isDragging ? 0.5 : 1,
        padding: "8px",
        margin: "5px 0",
        background: "#f0f0f0",
        cursor: "grab",
      }}
    >
      {task.text}
    </div>
  );
};

export default App;
```

