// 1. Order structure
struct Order {
    std::string symbol;
    bool is_buy; // true = buy, false = sell
    double price;
    int quantity;
};

// 2. Thread-safe message queue for incoming orders
class OrderQueue {
public:
    void push(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx_);
        queue_.push(order);
        cond_.notify_one();
    }

    Order pop() {
        std::unique_lock<std::mutex> lock(mtx_);
        cond_.wait(lock, [this] { return !queue_.empty(); });
        Order order = queue_.front();
        queue_.pop();
        return order;
    }

    bool empty() {
        std::lock_guard<std::mutex> lock(mtx_);
        return queue_.empty();
    }

private:
    std::queue<Order> queue_;
    std::mutex mtx_;
    std::condition_variable cond_;
};

// 3. High-performance order book (simplified)
class OrderBook {
public:
    void add_order(const Order& order) {
        if (order.is_buy) {
            bids[order.price] += order.quantity;
        } else {
            asks[order.price] += order.quantity;
        }

        // Match orders (simplified logic)
        match_orders();
    }

    void match_orders() {
        while (!bids.empty() && !asks.empty()) {
            auto best_bid = get_best_bid();
            auto best_ask = get_best_ask();

            if (best_bid.price >= best_ask.price) {
                int trade_quantity = std::min(bids[best_bid.price], asks[best_ask.price]);
                std::cout << "Match: " << trade_quantity << " @ " << best_bid.price << std::endl;

                bids[best_bid.price] -= trade_quantity;
                asks[best_ask.price] -= trade_quantity;

                if (bids[best_bid.price] == 0) bids.erase(best_bid.price);
                if (asks[best_ask.price] == 0) asks.erase(best_ask.price);
            } else {
                break;
            }
        }
    }

    std::pair<double, int> get_best_bid() {
        return { *bids.rbegin().first, bids.rbegin().second };
    }

    std::pair<double, int> get_best_ask() {
        return { *asks.begin().first, asks.begin().second };
    }

private:
    std::map<double, int, std::greater<>> bids; // descending order (highest bid first)
    std::map<double, int> asks; // ascending order (lowest ask first)
};

// 4. Asynchronous TCP server
class TradingServer {
public:
    TradingServer(boost::asio::io_context& io, short port)
        : acceptor_(io, tcp::endpoint(tcp::v4(), port)) {
        start_accept();
    }

    void start_accept() {
        auto socket = std::make_shared<tcp::socket>(acceptor_.get_executor());
        acceptor_.async_accept(*socket,
            boost::bind(&TradingServer::handle_accept, this, socket, _1));
    }

    void handle_accept(std::shared_ptr<tcp::socket> socket, const boost::system::error_code& error) {
        if (!error) {
            boost::asio::async_read_until(*socket, boost::asio::dynamic_buffer(order_buffer_), '\n',
                boost::bind(&TradingServer::handle_read, this, socket, _1, _2));
        }
        start_accept(); // Accept next connection
    }

    void handle_read(std::shared_ptr<tcp::socket> socket, const boost::system::error_code& error, size_t bytes_transferred) {
        if (!error) {
            std::string order_str = order_buffer_.substr(0, bytes_transferred);
            order_buffer_.erase(0, bytes_transferred);

            // Parse order: "SYMBOL,IS_BUY,PRICE,QUANTITY\n"
            std::istringstream iss(order_str);
            std::string symbol, is_buy_str;
            double price;
            int quantity;
            std::getline(iss, symbol, ',');
            std::getline(iss, is_buy_str, ',');
            iss >> price >> quantity;

            Order order{ symbol, (is_buy_str == "BUY"), price, quantity };
            order_queue_.push(order); // Send to order processing thread

            // Continue reading
            boost::asio::async_read_until(*socket, boost::asio::dynamic_buffer(order_buffer_), '\n',
                boost::bind(&TradingServer::handle_read, this, socket, _1, _2));
        }
    }

    OrderQueue order_queue_;
    std::string order_buffer_;
    tcp::acceptor acceptor_;
};

// 5. Main execution
int main() {
    boost::asio::io_context io;
    TradingServer server(io, 8080);
    OrderBook order_book;

    // Worker thread for order processing
    std::thread worker([&] {
        while (true) {
            Order order = server.order_queue_.pop();
            order_book.add_order(order);
        }
    });

    // Start network I/O
    io.run();

    worker.join();
    return 0;
}
```

