// ---------------------------- ORDER STRUCTURE ----------------------------
struct Order {
    uint64_t id;
    std::string symbol;
    double price;
    uint32_t quantity;
    bool is_buy;
    std::atomic<uint32_t> remaining_quantity;
    std::atomic<bool> is_filled;

    Order(uint64_t id, std::string symbol, double price, uint32_t quantity, bool is_buy)
        : id(id), symbol(symbol), price(price), quantity(quantity), is_buy(is_buy),
          remaining_quantity(quantity), is_filled(false) {}
};

// ---------------------------- ORDER BOOK ----------------------------
class OrderBook {
public:
    void add_order(std::shared_ptr<Order> order) {
        std::lock_guard<std::mutex> lock(book_mutex);
        if (order->is_buy) {
            buy_orders[order->price].push_back(order);
        } else {
            sell_orders[order->price].push_back(order);
        }
        match_orders();
    }

    void match_orders() {
        while (!buy_orders.empty() && !sell_orders.empty()) {
            auto best_buy = get_best_buy();
            auto best_sell = get_best_sell();

            if (best_buy.first > best_sell.first) break;

            auto buy_price = best_buy.first;
            auto sell_price = best_sell.first;
            auto buy_order = best_buy.second;
            auto sell_order = best_sell.second;

            uint32_t trade_quantity = std::min(buy_order->remaining_quantity, sell_order->remaining_quantity);

            // Execute trade at the seller's price
            double trade_price = sell_price;
            buy_order->remaining_quantity -= trade_quantity;
            sell_order->remaining_quantity -= trade_quantity;

            if (buy_order->remaining_quantity == 0) {
                buy_orders[buy_price].erase(std::remove(buy_orders[buy_price].begin(), buy_orders[buy_price].end(), buy_order));
                if (buy_orders[buy_price].empty()) buy_orders.erase(buy_price);
            }

            if (sell_order->remaining_quantity == 0) {
                sell_orders[sell_price].erase(std::remove(sell_orders[sell_price].begin(), sell_orders[sell_price].end(), sell_order));
                if (sell_orders[sell_price].empty()) sell_orders.erase(sell_price);
            }
        }
    }

private:
    std::map<double, std::vector<std::shared_ptr<Order>>, std::greater<>> buy_orders; // Max heap (descending)
    std::map<double, std::vector<std::shared_ptr<Order>>> sell_orders; // Min heap (ascending)
    std::mutex book_mutex;

    std::pair<double, std::shared_ptr<Order>> get_best_buy() {
        return {buy_orders.begin()->first, buy_orders.begin()->second.front()};
    }

    std::pair<double, std::shared_ptr<Order>> get_best_sell() {
        return {sell_orders.begin()->first, sell_orders.begin()->second.front()};
    }
};

