        uint64_t id = std::hash<std::string>{}(raw_message);
        std::string symbol = "AAPL";
        double price = 150.00;
        uint32_t quantity = 100;
        bool is_buy = true;

        auto order = std::make_shared<Order>(id, symbol, price, quantity, is_buy);
        order_book.add_order(order);
    }

private:
    OrderBook order_book;
};

// ---------------------------- THREAD POOL FOR SCALABILITY ----------------------------
class ThreadPool {
public:
    ThreadPool(size_t threads) {
        for (size_t i = 0; i < threads; ++i) {
            workers.emplace_back([this] {
                while (!stop.load()) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    template <class F>
    void enqueue(F f) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.push(f);
        }
        condition.notify_one();
    }

    ~ThreadPool() {
        stop = true;
        condition.notify_all();
        for (auto& worker : workers) worker.join();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    std::atomic<bool> stop{false};
};

// ---------------------------- MAIN TRADING ENGINE ----------------------------
int main() {
    ThreadPool pool(std::thread::hardware_concurrency());
    MessageHandler handler;

    // Simulate incoming orders
    for (int i = 0; i < 1000; ++i) {
        std::string raw_order = "BUY AAPL 150.00 100";
        pool.enqueue([&handler, raw_order] { handler.process_message(raw_order); });
    }

    // Wait for all tasks to complete (in a real system, this would run indefinitely)
    std::this_thread::sleep_for(std::chrono::seconds(1));

    return 0;
}
