    Price    float64 `json:"price"`
}

var orderChan = make(chan Order, 10000) // Buffered channel for scalability
var wg sync.WaitGroup

func handleOrder(w http.ResponseWriter, r *http.Request) {
    var order Order
    json.NewDecoder(r.Body).Decode(&order)
    orderChan <- order
    w.WriteHeader(http.StatusOK)
    fmt.Fprintf(w, "Order received: %v", order)
}

func orderProcessor() {
    for order := range orderChan {
        fmt.Printf("Forwarding Order ID: %d | Symbol: %s | Quantity: %d | Price: %.2f\n",
            order.ID, order.Symbol, order.Quantity, order.Price)
        // Forward to C++ core engine via IPC or TCP (not shown)
    }
    wg.Done()
}

func main() {
    http.HandleFunc("/order", handleOrder)
    wg.Add(1)
    go orderProcessor()

    fmt.Println("Starting message broker on :8080...")
    http.ListenAndServe(":8080", nil)
    wg.Wait()
}
```

**Why Go?**  
- Lightweight goroutines and channels handle thousands of concurrent connections.  
