use std::sync::Arc;
use tokio::sync::Mutex;

#[derive(Clone)]
struct RiskEngine {
    max_exposure: f64,
    current_exposure: Arc<Mutex<f64>>,
}

impl RiskEngine {
    fn new(max_exposure: f64) -> Self {
        RiskEngine {
            max_exposure,
            current_exposure: Arc::new(Mutex::new(0.0)),
        }
    }

    async fn validate_order(&self, order_value: f64) -> bool {
        let mut exposure = self.current_exposure.lock().await;
        if *exposure + order_value > self.max_exposure {
            false
        } else {
            *exposure += order_value;
            true
        }
    }
}
