import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
public class RiskService {
    private final AtomicLong totalExposure = new AtomicLong(0);
    private final long MAX_EXPOSURE = 1_000_000; // $1M limit

    @PostMapping("/check-risk")
    public boolean checkRisk(@RequestBody TradeRequest request) {
        long exposure = totalExposure.addAndGet(request.quantity * request.price);
        boolean allowed = exposure <= MAX_EXPOSURE;
        if (!allowed) totalExposure.addAndGet(-request.quantity * request.price); // Rollback
        return allowed;
    }

    public static void main(String[] args) {
        SpringApplication.run(RiskService.class, args);
    }
}

class TradeRequest {
    public String symbol;
    public long price;
    public long quantity;
}
