### Code (C++17+):
```cpp
#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <unordered_map>
#include <vector>
#include <memory>
#include <functional>

// Forward declaration for order book
class OrderBook;

// Order structure
struct Order {
    std::string symbol;
    std::string side;  // "BUY" or "SELL"
    double price;
    int quantity;
    std::string id;
};

// Thread-safe message queue
template <typename T>
class MessageQueue {
public:
    void push(T message) {
        std::lock_guard<std::mutex> lock(mtx_);
        queue_.push(std::move(message));
        cond_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mtx_);
        cond_.wait(lock, [this] { return !queue_.empty(); });
        T msg = std::move(queue_.front());
        queue_.pop();
        return msg;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return queue_.empty();
    }

private:
    std::queue<T> queue_;
    mutable std::mutex mtx_;
    std::condition_variable cond_;
};

// Order book with basic matching logic
class OrderBook {
public:
    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (order.side == "BUY") {
            buyOrders[order.price].push_back(order);
        } else {
            sellOrders[order.price].push_back(order);
        }
        matchOrders();
    }

    void matchOrders() {
        std::lock_guard<std::mutex> lock(mtx_);
        while (!buyOrders.empty() && !sellOrders.empty()) {
            auto bestBuy = findBestBuy();
            auto bestSell = findBestSell();
            if (bestBuy.price < bestSell.price) break;

            // Execute trade
            int tradeQty = std::min(bestBuy.quantity, bestSell.quantity);
            std::cout << "Match: " << tradeQty << " @ " << bestBuy.price << std::endl;

            // Update order books
            buyOrders[bestBuy.price].erase(buyOrders[bestBuy.price].begin());
            if (buyOrders[bestBuy.price].empty()) buyOrders.erase(bestBuy.price);

            sellOrders[bestSell.price].erase(sellOrders[bestSell.price].begin());
            if (sellOrders[bestSell.price].empty()) sellOrders.erase(bestSell.price);
        }
    }

private:
    struct PriceLevel {
        double price;
        int quantity;
    };

    PriceLevel findBestBuy() {
        auto it = buyOrders.begin();
        return {it->first, it->second.front().quantity};
    }

    PriceLevel findBestSell() {
        auto it = sellOrders.begin();
        return {it->first, it->second.front().quantity};
    }

    std::mutex mtx_;
    std::unordered_map<double, std::vector<Order>> buyOrders;
    std::unordered_map<double, std::vector<Order>> sellOrders;
};

// Worker thread to process incoming messages
class Worker {
public:
    Worker(OrderBook& book, MessageQueue<Order>& queue) : orderBook_(book), msgQueue_(queue) {
        thread_ = std::thread(&Worker::run, this);
    }

    void run() {
        while (true) {
            Order order = msgQueue_.pop();
            orderBook_.addOrder(order);
        }
    }

    void join() { thread_.join(); }

private:
    OrderBook& orderBook_;
    MessageQueue<Order>& msgQueue_;
    std::thread thread_;
};

int main() {
    OrderBook orderBook;
    MessageQueue<Order> msgQueue;
    const int NUM_WORKERS = 4; // Scale horizontally by increasing workers

    std::vector<std::unique_ptr<Worker>> workers;
    for (int i = 0; i < NUM_WORKERS; ++i) {
        workers.emplace_back(std::make_unique<Worker>(orderBook, msgQueue));
    }

    // Simulate incoming orders
    for (int i = 0; i < 10; ++i) {
        Order buy = {"AAPL", "BUY", 150.0 + i * 0.1, 100, "BUY_" + std::to_string(i)};
        Order sell = {"AAPL", "SELL", 150.0 + i * 0.1, 100, "SELL_" + std::to_string(i)};
        msgQueue.push(buy);
        msgQueue.push(sell);
    }

    // Wait for workers to finish (in real system, use shutdown signal)
    for (auto& worker : workers) {
        worker->join();
    }

    return 0;
}
```

