### **1. Core Execution Engine (C++)**
```cpp
// order_book.cpp
#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>

struct Order {
    int64_t id;
    double price;
    int32_t quantity;
    bool is_buy;
};

class OrderBook {
public:
    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order.is_buy) {
            buy_orders.push(order);
        } else {
            sell_orders.push(order);
        }
        matchOrders();
    }

private:
    std::mutex mtx;
    std::priority_queue<Order, std::vector<Order>, std::greater<>> buy_orders;  // Buy orders (ascending)
    std::priority_queue<Order, std::vector<Order>, std::less<>> sell_orders;    // Sell orders (descending)

    void matchOrders() {
        while (!buy_orders.empty() && !sell_orders.empty()) {
            auto buy = buy_orders.top();
            auto sell = sell_orders.top();
            if (buy.price >= sell.price) {
                int32_t traded = std::min(buy.quantity, sell.quantity);
                std::cout << "Match: " << traded << " shares at " << sell.price << std::endl;
                // Update remaining quantities
