### 1. **Core Order Matching Engine (C++)**
```cpp
// order_book.cpp
#include <iostream>
#include <queue>
#include <unordered_map>
#include <string>
#include <sstream>
#include <thread>
#include <mutex>
#include <asio.hpp>

using asio::ip::tcp;

struct Order {
    std::string id;
    std::string type; // "buy" or "sell"
    double price;
    int quantity;
};

class OrderBook {
public:
    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order.type == "buy") {
            buyOrders.emplace(order.price, order.quantity);
        } else {
            sellOrders.emplace(order.price, order.quantity);
        }
        matchOrders();
    }

    std::string getBookSnapshot() {
        std::lock_guard<std::mutex> lock(mtx);
        std::ostringstream oss;
        oss << "Buys: ";
        while (!buyOrders.empty()) {
            oss << buyOrders.top().price << "@" << buyOrders.top().quantity << " ";
            buyOrders.pop();
        }
        oss << "\nSells: ";
        while (!sellOrders.empty()) {
            oss << sellOrders.top().price << "@" << sellOrders.top().quantity << " ";
            sellOrders.pop();
        }
        return oss.str();
    }

private:
    std::mutex mtx;
    std::priority_queue<std::pair<double, int>> buyOrders; // Max heap
    std::priority_queue<std::pair<double, int>> sellOrders; // Min heap (inverted price)

    void matchOrders() {
        // Simplified matching logic for demo
        while (!buyOrders.empty() && !sellOrders.empty() && buyOrders.top().price >= sellOrders.top().price) {
            auto buy = buyOrders.top();
            auto sell = sellOrders.top();
            int matchedQty = std::min(buy.second, sell.second);
            std::cout << "Match: " << matchedQty << " @ " << sell.price << std::endl;
            buyOrders.pop();
            sellOrders.pop();
            if (buy.second > matchedQty) buyOrders.emplace(buy.price, buy.second - matchedQty);
            if (sell.second > matchedQty) sellOrders.emplace(sell.price, sell.second - matchedQty);
        }
    }
};

int main() {
    OrderBook book;
    tcp::acceptor acceptor(asio::io_context(), {tcp::v4(), 5555});

    while (true) {
        tcp::socket socket(acceptor.get_executor());
        acceptor.accept(socket);

        std::thread([&socket, &book]() {
            try {
                asio::streambuf buffer;
                asio::read_until(socket, buffer, '\n');
                std::string orderStr = asio::buffer_cast<const char*>(buffer.data());
                std::istringstream iss(orderStr);
                Order order;
                iss >> order.id >> order.type >> order.price >> order.quantity;
                book.addOrder(order);
                socket.write_some(asio::buffer("Order processed\n"));
            } catch (std::exception&) {}
        }).detach();
    }

    return 0;
}
```

