// main.go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"net"
)

type Order struct {
	ID     string  `json:"id"`
	Type   string  `json:"type"`   // "buy" or "sell"
	Price  float64 `json:"price"`
	Quantity int    `json:"quantity"`
}

func sendOrderToCore(order Order) error {
	conn, err := net.Dial("tcp", "localhost:5555")
	if err != nil {
		return err
	}
	defer conn.Close()

	_, err = conn.Write([]byte(fmt.Sprintf("%s %s %.2f %d\n", order.ID, order.Type, order.Price, order.Quantity)))
	return err
}

func handleOrder(w http.ResponseWriter, r *http.Request) {
	body, _ := ioutil.ReadAll(r.Body)
	var order Order
	json.Unmarshal(body, &order)

	if err := sendOrderToCore(order); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "order processed"})
}

func main() {
	http.HandleFunc("/order", handleOrder)
	log.Println("Starting Go backend on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
