Here's a **C++ implementation** using Boost.Asio for real-time market data aggregation and streaming. This example includes:

1. A TCP server that processes market data
2. Sliding window price aggregation
3. Subscription management for clients
4. Real-time updates for subscribers

```cpp
#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>
#include <deque>
#include <map>
#include <mutex>
#include <thread>
#include <iostream>
#include <cmath>
#include <sstream>

namespace pt = boost::posix_time;
namespace asio = boost::asio;

// Market data structure
struct MarketData {
    std::string symbol;
    double price;
    pt::ptime timestamp;
};

// Aggregation data structure
struct PriceAggregate {
    double min_price = std::numeric_limits<double>::infinity();
    double max_price = 0.0;
    double sum_price = 0.0;
    size_t count = 0;
    pt::ptime window_start;
};

// Sliding window aggregator
class Aggregator {
public:
    void add_data(const MarketData& data, double window_seconds) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto now = pt::microsec_clock::universal_time();

        // Clean up old data
        while (!data_window_.empty() && 
              (now - data_window_.front().timestamp) > pt::seconds(window_seconds)) {
            const auto& old_data = data_window_.front();
            data_window_.pop_front();

            // Adjust aggregates
            if (old_data.price == aggregates_.min_price || old_data.price == aggregates_.max_price) {
                // Recalculate min/max if extreme values were removed
                aggregates_.min_price = std::numeric_limits<double>::infinity();
                aggregates_.max_price = 0.0;
                for (const auto& d : data_window_) {
                    aggregates_.min_price = std::min(aggregates_.min_price, d.price);
                    aggregates_.max_price = std::max(aggregates_.max_price, d.price);
                }
            }
            aggregates_.sum_price -= old_data.price;
            aggregates_.count--;
        }

        // Add new data
        data_window_.push_back(data);
        aggregates_.sum_price += data.price;
        aggregates_.count++;
        aggregates_.min_price = std::min(aggregates_.min_price, data.price);
        aggregates_.max_price = std::max(aggregates_.max_price, data.price);

        if (data_window_.size() == 1) {
            aggregates_.window_start = data.timestamp;
        }
    }

    PriceAggregate get_aggregates() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return aggregates_;
    }

private:
    mutable std::mutex mutex_;
    std::deque<MarketData> data_window_;
    PriceAggregate aggregates_;
};

// Market data server
class MarketDataServer {
public:
    MarketDataServer(asio::io_context& io, short port)
        : io_context_(io), acceptor_(io, asio::ip::tcp::endpoint(asio::ip::tcp::v4(), port)) {
        start_accept();

        // Start simulated data generator
        data_thread_ = std::thread(&MarketDataServer::generate_data, this);
    }

    void add_subscriber(const std::string& symbol, asio::ip::tcp::socket* socket) {
        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        subscribers_[symbol].push_back(socket);
    }

private:
    void start_accept() {
        asio::ip::tcp::socket* socket = new asio::ip::tcp::socket(io_context_);
        acceptor_.async_accept(*socket,
            boost::bind(&MarketDataServer::handle_accept, this, socket, _1));
    }

    void handle_accept(asio::ip::tcp::socket* socket, const boost::system::error_code& error) {
        if (!error) {
            // Read subscription request
            asio::streambuf buffer;
            asio::async_read_until(*socket, buffer, '\n',
                boost::bind(&MarketDataServer::handle_subscription, this, socket, buffer, _1, _2));
        }
        delete socket;
        start_accept();
    }

    void handle_subscription(asio::ip::tcp::socket* socket, asio::streambuf& buffer,
                             const boost::system::error_code& error, size_t bytes_transferred) {
        if (!error) {
            std::istream is(&buffer);
            std::string symbol;
            std::getline(is, symbol);

            // Add to subscribers
            {
                std::lock_guard<std::mutex> lock(subscribers_mutex_);
                subscribers_[symbol].push_back(socket);
            }

            // Start sending updates
            boost::asio::async_write(*socket, asio::buffer("Ready\n"),
                boost::bind(&MarketDataServer::handle_write, this, socket, _1, _2));
        }
    }

    void handle_write(asio::ip::tcp::socket* socket, const boost::system::error_code& error, size_t bytes_transferred) {
        if (!error) {
            // This would normally be triggered by aggregate updates
            // For simplicity, we'll just close the connection here
            socket->shutdown(asio::ip::tcp::socket::shutdown_both);
            socket->close();
        }
    }

    void generate_data() {
        while (true) {
            pt::ptime now = pt::microsec_clock::universal_time();

            // Simulate market data for different symbols
            for (const auto& symbol : {"AAPL", "GOOGL", "MSFT", "AMZN", "TSLA"}) {
                MarketData data;
                data.symbol = symbol;
                data.price = 100.0 + (std::rand() % 1000) * 0.1;  // $100-$200
                data.timestamp = now;

                aggregators_[symbol].add_data(data, 60.0);  // 60-second window

                // Notify subscribers
                notify_subscribers(symbol);
            }

            std::this_thread::sleep_for(std::chrono::milliseconds(100));  // 10 updates/second
        }
    }

    void notify_subscribers(const std::string& symbol) {
        PriceAggregate aggregates = aggregators_[symbol].get_aggregates();

        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        for (auto* socket : subscribers_[symbol]) {
            std::ostringstream oss;
            oss << "Symbol: " << symbol << "\n"
                << "Avg: " << (aggregates.count ? aggregates.sum_price / aggregates.count : 0.0) << "\n"
                << "Min: " << aggregates.min_price << "\n"
                << "Max: " << aggregates.max_price << "\n"
                << "Count: " << aggregates.count << "\n"
                << "Window: " << (now - aggregates.window_start).total_seconds() << "s\n";

            std::string response = oss.str();
            boost::asio::async_write(*socket, asio::buffer(response),
                boost::bind(&MarketDataServer::handle_write, this, socket, _1, _2));
        }
    }

    asio::io_context& io_context_;
    asio::ip::tcp::acceptor acceptor_;
    std::map<std::string, Aggregator> aggregators_;
    std::map<std::string, std::vector<asio::ip::tcp::socket*>> subscribers_;
    std::mutex subscribers_mutex_;
    std::thread data_thread_;
};

int main() {
    try {
        asio::io_context io;
        MarketDataServer server(io, 8080);
        io.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }
    return 0;
}
```

