### 🧾 Code (C++17+):
```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <map>
#include <vector>
#include <functional>
#include <chrono>
#include <cmath>
#include <atomic>

// Market data structure
struct MarketData {
    std::string symbol;
    double price;
    std::chrono::steady_clock::time_point timestamp;

    MarketData(const std::string& s, double p)
        : symbol(s), price(p), timestamp(std::chrono::steady_clock::now()) {}
};

// Aggregation result
struct AggregationResult {
    std::string symbol;
    double average;
    double min;
    double max;
    std::chrono::steady_clock::time_point window_end;
};

// Thread-safe queue
class MarketDataQueue {
public:
    void enqueue(const MarketData& data) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        data_queue.push(data);
    }

    bool dequeue(MarketData& data) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        if (data_queue.empty()) return false;
        data = data_queue.front();
        data_queue.pop();
        return true;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(queue_mutex);
        return data_queue.empty();
    }

private:
    std::queue<MarketData> data_queue;
    mutable std::mutex queue_mutex;
};

// Market data processor
class MarketProcessor {
public:
    MarketProcessor(int window_seconds = 60)
        : window_duration(window_seconds), running(true) {}

    void start() {
        worker_thread = std::thread(&MarketProcessor::processLoop, this);
    }

    void stop() {
        running = false;
        if (worker_thread.joinable()) worker_thread.join();
    }

    void addData(const MarketData& data) {
        data_queue.enqueue(data);
    }

    void subscribe(const std::function<void(const AggregationResult&)>& callback) {
        std::lock_guard<std::mutex> lock(callback_mutex);
        callbacks.push_back(callback);
    }

private:
    void processLoop() {
        while (running) {
            MarketData data;
            while (data_queue.dequeue(data)) {
                auto now = std::chrono::steady_clock::now();
                auto window_start = now - std::chrono::seconds(window_duration);

                // Update symbol data
                auto& symbol_data = symbol_buffers[data.symbol];
                symbol_data.emplace_back(data.price, data.timestamp);

                // Remove outdated data
                auto& prices = symbol_data;
                prices.erase(
                    std::remove_if(prices.begin(), prices.end(),
                        [&window_start](const auto& entry) {
                            return entry.timestamp < window_start;
                        }),
                    prices.end()
                );

                // Compute and stream aggregates
                computeAndStream(data.symbol);
            }

            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    void computeAndStream(const std::string& symbol) {
        auto now = std::chrono::steady_clock::now();
        auto& prices = symbol_buffers[symbol];

        if (prices.empty()) return;

        double sum = 0.0, min = std::numeric_limits<double>::infinity(),
               max = -std::numeric_limits<double>::infinity();

        for (const auto& entry : prices) {
            sum += entry.price;
            min = std::min(min, entry.price);
            max = std::max(max, entry.price);
        }

        double average = sum / prices.size();

        AggregationResult result{
            symbol, average, min, max, now
        };

        // Notify subscribers
        std::lock_guard<std::mutex> lock(callback_mutex);
        for (const auto& callback : callbacks) {
            callback(result);
        }
    }

    MarketDataQueue data_queue;
    std::map<std::string, std::vector<std::pair<double, std::chrono::steady_clock::time_point>>> symbol_buffers;
    std::atomic<bool> running;
    std::thread worker_thread;
    int window_duration;
    std::vector<std::function<void(const AggregationResult&)>> callbacks;
    mutable std::mutex callback_mutex;
};

// Example subscriber
void printSubscriber(const AggregationResult& result) {
    auto duration = std::chrono::duration_cast<std::chrono::seconds>(result.window_end.time_since_epoch()).count();
    std::cout << "[" << duration << "s] "
              << "Symbol: " << result.symbol << ", "
              << "Avg: " << result.average << ", "
              << "Min: " << result.min << ", "
              << "Max: " << result.max << "\n";
}

// Main program
int main() {
    MarketProcessor processor(60); // 1-minute window
    processor.subscribe(printSubscriber);
    processor.start();

    // Simulate market data input
    for (int i = 0; i < 10; ++i) {
        processor.addData(MarketData("AAPL", 150.0 + i * 0.5));
        processor.addData(MarketData("GOOGL", 2800.0 + i * 2.0));
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    }

    // Stop the processor
    std::this_thread::sleep_for(std::chrono::seconds(2));
    processor.stop();

    return 0;
}
```

