// MarketData represents a price update
type MarketData struct {
	Symbol string
	Price  float64
	Volume float64
}

// Aggregate represents computed metrics
type Aggregate struct {
	Symbol        string
	AveragePrice  float64
	TotalVolume   float64
	Timestamp     time.Time
}

// MarketDataProcessor handles data processing and subscriptions
type MarketDataProcessor struct {
	dataChan      chan MarketData
	subscribers   map[chan Aggregate]bool
	subscriberMux sync.RWMutex
	priceWindow   []float64
	windowSize    int
}

func NewMarketDataProcessor(windowSize int) *MarketDataProcessor {
	return &MarketDataProcessor{
		dataChan:    make(chan MarketData),
		subscribers: make(map[chan Aggregate]bool),
		windowSize:  windowSize,
	}
}

// Start begins processing data
func (p *MarketDataProcessor) Start() {
	go func() {
		for data := range p.dataChan {
			p.priceWindow = append(p.priceWindow, data.Price)
			if len(p.priceWindow) > p.windowSize {
				p.priceWindow = p.priceWindow[1:]
			}

			agg := Aggregate{
				Symbol:      data.Symbol,
				AveragePrice: p.computeAverage(),
				TotalVolume:  data.Volume,
				Timestamp:    time.Now(),
			}

			p.broadcast(agg)
		}
	}()
}

// computeAverage calculates the average of the price window
func (p *MarketDataProcessor) computeAverage() float64 {
	if len(p.priceWindow) == 0 {
		return 0
	}
	sum := 0.0
	for _, price := range p.priceWindow {
		sum += price
	}
	return sum / float64(len(p.priceWindow))
}

// broadcast sends updates to all subscribers
func (p *MarketDataProcessor) broadcast(agg Aggregate) {
	p.subscriberMux.RLock()
	defer p.subscriberMux.RUnlock()

	for sub := range p.subscribers {
		select {
		case sub <- agg:
		default:
			// Drop if subscriber is not reading (backpressure)
		}
	}
}

// Register adds a new subscriber
func (p *MarketDataProcessor) Register() chan Aggregate {
	ch := make(chan Aggregate, 100) // Buffered channel for backpressure
	p.subscriberMux.Lock()
	p.subscribers[ch] = true
	p.subscriberMux.Unlock()
	return ch
}

// Unregister removes a subscriber
func (p *MarketDataProcessor) Unregister(ch chan Aggregate) {
	p.subscriberMux.Lock()
	delete(p.subscribers, ch)
	p.subscriberMux.Unlock()
	close(ch)
}

