Here's a high-performance C++ implementation of a real-time market data processor with a sliding window for price aggregation and in-memory subscriber notifications. This example uses a fixed-size sliding window for simplicity, but can be extended with more sophisticated time-based windows.

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <cmath>
#include <chrono>
#include <atomic>
#include <functional>
#include <deque>

// Market data structure
struct MarketData {
    std::string symbol;
    double price;
    double volume;
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
};

// Aggregated statistics
struct Aggregates {
    double weighted_avg_price = 0.0;
    double total_volume = 0.0;
    std::chrono::time_point<std::chrono::steady_clock> window_end;
};

// Core processing engine
class MarketProcessor {
public:
    MarketProcessor(size_t window_size_seconds = 60) 
        : window_size_seconds_(window_size_seconds) {}

    // Add new market data
    void add_data(const MarketData& data) {
        std::lock_guard<std::mutex> lock(data_mutex_);
        auto now = std::chrono::steady_clock::now();

        // Add to buffer
        data_buffer_.push_back(data);

        // Clean up old data
        auto cutoff = now - std::chrono::seconds(window_size_seconds_);
        data_buffer_.erase(
            std::remove_if(data_buffer_.begin(), data_buffer_.end(),
                [&cutoff](const MarketData& d) {
                    return d.timestamp < cutoff;
                }),
            data_buffer_.end()
        );

        // Compute aggregates
        Aggregates new_agg;
        double total = 0.0;

        for (const auto& d : data_buffer_) {
            new_agg.total_volume += d.volume;
            total += d.price * d.volume;
        }

        new_agg.weighted_avg_price = new_agg.total_volume > 0 
            ? total / new_agg.total_volume 
            : 0.0;
        new_agg.window_end = now;

        // Update state and notify subscribers
        {
            std::lock_guard<std::mutex> agg_lock(agg_mutex_);
            aggregates_ = new_agg;
            has_new_data_ = true;
        }
        cv_.notify_all();
    }

    // Subscribe to updates
    void subscribe(std::function<void(const Aggregates&)> callback) {
        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        subscribers_.push_back(callback);
    }

    // Start streaming updates
    void start_streaming() {
        streaming_thread_ = std::thread([this]() {
            while (!shutdown_) {
                Aggregates current_agg;
                {
                    std::unique_lock<std::mutex> lock(agg_mutex_);
                    cv_.wait(lock, [this] { return has_new_data_ || shutdown_; });

                    if (shutdown_) break;

                    current_agg = aggregates_;
                    has_new_data_ = false;
                }

                // Notify all subscribers
                std::vector<std::function<void(const Aggregates&)>> callbacks;
                {
                    std::lock_guard<std::mutex> lock(subscribers_mutex_);
                    callbacks = subscribers_;
                }

                for (const auto& cb : callbacks) {
                    try {
                        cb(current_agg);
                    } catch (...) {
                        // Handle exceptions from callbacks
                    }
                }

                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            }
        });
    }

    // Stop streaming
    void stop() {
        shutdown_ = true;
        cv_.notify_all();
        if (streaming_thread_.joinable()) {
            streaming_thread_.join();
        }
    }

private:
    size_t window_size_seconds_;
    std::deque<MarketData> data_buffer_;
    Aggregates aggregates_;
    std::atomic<bool> shutdown_{false};
    std::atomic<bool> has_new_data_{false};

    std::mutex data_mutex_;
    std::mutex agg_mutex_;
    std::mutex subscribers_mutex_;

    std::condition_variable cv_;
    std::thread streaming_thread_;
    std::vector<std::function<void(const Aggregates&)>> subscribers_;
};

// Simulated data generator
void generate_data(MarketProcessor& processor) {
    int counter = 0;
    while (!processor.shutdown_) {
        MarketData data;
        data.symbol = "AAPL";
        data.price = 150.0 + sin(counter * 0.1) * 10.0; // Simulated price
        data.volume = 100.0 + (rand() % 1000);          // Random volume
        data.timestamp = std::chrono::steady_clock::now();

        processor.add_data(data);
        counter++;
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

int main() {
    MarketProcessor processor(60); // 60-second window

    // Subscribe to updates
    processor.subscribe([](const Aggregates& agg) {
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - agg.window_end).count();

        std::cout << "Window end: " << elapsed << "ms ago | "
                  << "Avg Price: " << agg.weighted_avg_price << " | "
                  << "Volume: " << agg.total_volume << std::endl;
    });

    // Start streaming and data generation
    processor.start_streaming();
    std::thread data_thread(generate_data, std::ref(processor));

    // Run for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));

    // Clean up
    processor.stop();
    data_thread.join();

    return 0;
}
