package main

import (
	"container/ring"
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// MarketData represents a price update
type MarketData struct {
	Symbol string
	Price  float64
	Volume float64
	Timestamp time.Time
}

// Aggregator maintains a moving window of prices
type Aggregator struct {
	windowSize int
	window     *ring.Ring
	sum        float64
}

// NewAggregator creates a new aggregator with a fixed window size
func NewAggregator(windowSize int) *Aggregator {
	return &Aggregator{
		windowSize: windowSize,
		window:     ring.New(0),
	}
}

// Update adds a new price to the window and returns the current average
func (a *Aggregator) Update(price float64) float64 {
	if a.window.Len() < a.windowSize {
		a.window = a.window.Next()
		a.window.Value = price
		a.sum += price
	} else {
		// Remove oldest price and add new one
		oldest := a.window.Value.(float64)
		a.sum = a.sum - oldest + price
		a.window.Value = price
		a.window = a.window.Next()
	}
	return a.sum / float64(a.window.Len())
}

// SubscriberManager handles client subscriptions
type SubscriberManager struct {
	subscribers map[chan MarketData]struct{}
	mu          sync.RWMutex
}

func NewSubscriberManager() *SubscriberManager {
	return &SubscriberManager{
		subscribers: make(map[chan MarketData]struct{}),
	}
}

func (sm *SubscriberManager) Subscribe() chan MarketData {
	sm.mu.Lock()
	defer sm.mu.Unlock()
	ch := make(chan MarketData, 100) // Buffered channel
	sm.subscribers[ch] = struct{}{}
	return ch
}

func (sm *SubscriberManager) Unsubscribe(ch chan MarketData) {
	sm.mu.Lock()
	defer sm.mu.Unlock()
	delete(sm.subscribers, ch)
	close(ch)
}

func (sm *SubscriberManager) Broadcast(data MarketData) {
	sm.mu.RLock()
	defer sm.mu.RUnlock()
	for ch := range sm.subscribers {
		select {
		case ch <- data:
		default:
			// Handle backpressure if needed
		}
	}
}

// Simulated market data producer
func MarketDataProducer(symbol string, ch chan<- MarketData) {
	rand.Seed(time.Now().UnixNano())
