```go
package main

import (
    "fmt"
    "math"
    "sync"
    "time"
)

// MarketData represents incoming price data
type MarketData struct {
    Symbol string
    Price  float64
    Time   time.Time
}

// Aggregate represents computed price statistics
type Aggregate struct {
    Symbol       string
    AvgPrice     float64
    TotalVolume  float64
    TimeWindow   time.Duration
    LastUpdated  time.Time
}

// Aggregator maintains state for price aggregation
type Aggregator struct {
    windowSize time.Duration
    data       map[string][]MarketData
    mu         sync.RWMutex
    out        chan Aggregate
}

// NewAggregator creates a new aggregator with a sliding time window
func NewAggregator(windowSize time.Duration) *Aggregator {
    return &Aggregator{
        windowSize: windowSize,
        data:       make(map[string][]MarketData),
        out:        make(chan Aggregate, 1000),
    }
}

// ProcessData handles incoming market data and computes aggregates
func (a *Aggregator) ProcessData(dataChan <-chan MarketData) {
    for data := range dataChan {
        a.mu.Lock()
        // Remove old data outside the time window
        now := time.Now()
        a.data[data.Symbol] = filterRecentData(data, now, a.windowSize)
        // Add new data point
        a.data[data.Symbol] = append(a.data[data.Symbol], data)
        a.mu.Unlock()

        // Compute and stream aggregate
        a.computeAggregate(data.Symbol, now)
    }
}

// filterRecentData removes data points older than the window
func filterRecentData(data MarketData, now time.Time, window time.Duration) []MarketData {
    cutoff := now.Add(-window)
    var filtered []MarketData
    for _, d := range a.data[data.Symbol] {
        if d.Time.After(cutoff) {
            filtered = append(filtered, d)
        }
    }
    return filtered
}

// computeAggregate calculates price aggregates for a symbol
func (a *Aggregator) computeAggregate(symbol string, now time.Time) {
    a.mu.RLock()
    prices := a.data[symbol]
    a.mu.RUnlock()

    if len(prices) == 0 {
        return
    }

    total := 0.0
    volume := 0.0
    for _, p := range prices {
        total += p.Price
        volume += 1.0 // Simplified volume calculation
    }

    avg := total / float64(len(prices))
    a.out <- Aggregate{
        Symbol:       symbol,
        AvgPrice:     avg,
        TotalVolume:  volume,
        TimeWindow:   a.windowSize,
        LastUpdated:  now,
    }
}

// Streamer broadcasts aggregates to subscribers
type Streamer struct {
    subs map[string]chan Aggregate
    mu   sync.RWMutex
}

// NewStreamer creates a new streamer
func NewStreamer() *Streamer {
    return &Streamer{
        subs: make(map[string]chan Aggregate),
    }
}

// Subscribe registers a new subscriber
func (s *Streamer) Subscribe(id string) <-chan Aggregate {
    s.mu.Lock()
    ch := make(chan Aggregate, 100)
    s.subs[id] = ch
    s.mu.Unlock()
    return ch
}

// Unsubscribe removes a subscriber
func (s *Streamer) Unsubscribe(id string) {
    s.mu.Lock()
    delete(s.subs, id)
    s.mu.Unlock()
}

// Broadcast sends aggregates to all subscribers
func (s *Streamer) Broadcast(agg Aggregate) {
    s.mu.RLock()
    defer s.mu.RUnlock()

    for _, ch := range s.subs {
        select {
        case ch <- agg:
        default:
            // Handle backpressure (e.g., drop or buffer)
        }
    }
}

func main() {
