    aggregator := NewAggregator(30 * time.Second)
    streamer := NewStreamer()

    // Simulate market data input
    dataChan := make(chan MarketData, 1000)
    go func() {
        symbols := []string{"AAPL", "GOOGL", "MSFT"}
        for i := 0; i < 100; i++ {
