        }
        close(dataChan)
    }()

    // Start processing pipeline
    var wg sync.WaitGroup
    wg.Add(1)
    go func() {
        defer wg.Done()
        aggregator.ProcessData(dataChan)
    }()

    // Subscribe to aggregates
    sub1 := streamer.Subscribe("client1")
    sub2 := streamer.Subscribe("client2")

    // Stream results to subscribers
    go func() {
        for agg := range aggregator.out {
            streamer.Broadcast(agg)
        }
    }()

    // Consume results
