package main

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// MarketData represents a single price update
type MarketData struct {
	Symbol string
	Price  float64
	Time   time.Time
}

// Aggregator maintains a sliding window of prices
type Aggregator struct {
	windowSize time.Duration
	window     []MarketData
	mu         sync.RWMutex
}

// Subscriber channel and ID
type Subscriber struct {
	id   string
	ch   chan MarketDataAggregate
}

// MarketProcessor handles data flow
type MarketProcessor struct {
	dataChan      chan MarketData
	subscribers   map[string]Subscriber
	subMu         sync.RWMutex
	aggregator    *Aggregator
	quit          chan struct{}
}

// MarketDataAggregate represents computed aggregates
type MarketDataAggregate struct {
	Symbol      string
	WindowStart time.Time
	WindowEnd   time.Time
	AvgPrice    float64
	TotalVolume int
}

func main() {
	// Initialize processor with 10-second window
	mp := NewMarketProcessor(10 * time.Second)

	// Start data stream simulation
	go simulateDataStream(mp.dataChan)

	// Subscribe to updates
	sub1 := mp.Subscribe("subscriber1")
	sub2 := mp.Subscribe("subscriber2")

	// Process for 30 seconds
	time.AfterFunc(30*time.Second, func() {
		mp.Unsubscribe(sub1.id)
		mp.Unsubscribe(sub2.id)
		close(mp.quit)
	})

	// Consume updates
	for update := range sub1.ch {
		fmt.Printf("Subscriber1: %s %v - %v | Avg: %.2f\n", 
			update.Symbol, update.WindowStart.Format("15:04:05"), 
			update.WindowEnd.Format("15:04:05"), update.AvgPrice)
	}

	for update := range sub2.ch {
		fmt.Printf("Subscriber2: %s %v - %v | Avg: %.2f\n", 
			update.Symbol, update.WindowStart.Format("15:04:05"), 
			update.WindowEnd.Format("15:04:05"), update.AvgPrice)
	}
}

// NewMarketProcessor creates a new market data processor
func NewMarketProcessor(windowSize time.Duration) *MarketProcessor {
	return &MarketProcessor{
		dataChan:    make(chan MarketData, 1000),
		subscribers: make(map[string]Subscriber),
		aggregator: &Aggregator{
			windowSize: windowSize,
		},
		quit: make(chan struct{}),
	}
}

// Start begins processing
func (mp *MarketProcessor) Start() {
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for {
			select {
			case data := <-mp.dataChan:
				mp.aggregator.AddData(data)
				mp.BroadcastAggregate()
			case <-ticker.C:
				mp.aggregator.CleanupOldData()
			case <-mp.quit:
				return
			}
		}
	}()
}()

// Subscribe adds a new subscriber
func (mp *MarketProcessor) Subscribe(id string) Subscriber {
	mp.subMu.Lock()
	defer mp.subMu.Unlock()

	sub := Subscriber{
		id: id,
		ch: make(chan MarketDataAggregate, 10),
	}
	mp.subscribers[id] = sub
	return sub
}

// Unsubscribe removes a subscriber
func (mp *MarketProcessor) Unsubscribe(id string) {
	mp.subMu.Lock()
	defer mp.subMu.Unlock()
	delete(mp.subscribers, id)
}

// BroadcastAggregate sends current aggregates to all subscribers
func (mp *MarketProcessor) BroadcastAggregate() {
	agg := mp.aggregator.GetAggregate()
	if agg != nil {
		mp.subMu.RLock()
		for _, sub := range mp.subscribers {
			select {
			case sub.ch <- *agg:
			default:
				// Drop if channel is full (backpressure)
			}
		}
		mp.subMu.RUnlock()
	}
}

// AddData adds a new data point to the aggregator
func (a *Aggregator) AddData(data MarketData) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.window = append(a.window, data)
}

// CleanupOldData removes data outside the window
func (a *Aggregator) CleanupOldData() {
	a.mu.Lock()
	defer a.mu.Unlock()

	now := time.Now()
	newWindow := a.window[:0]
	for _, data := range a.window {
		if now.Sub(data.Time) <= a.windowSize {
			newWindow = append(newWindow, data)
		}
	}
	a.window = newWindow
}

// GetAggregate calculates current aggregates
func (a *Aggregator) GetAggregate() *MarketDataAggregate {
	a.mu.RLock()
	defer a.mu.RUnlock()

	if len(a.window) == 0 {
		return nil
	}

	sum := 0.0
	volume := 0
	symbol := a.window[0].Symbol

	for _, data := range a.window {
		sum += data.Price
		volume++
	}

	return &MarketDataAggregate{
		Symbol:      symbol,
		WindowStart: a.window[0].Time,
		WindowEnd:   a.window[len(a.window)-1].Time,
		AvgPrice:    sum / float64(volume),
		TotalVolume: volume,
	}
}

// simulateDataStream generates random market data
func simulateDataStream(ch chan<- MarketData) {
	ticker := time.NewTicker(200 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			ch <- MarketData{
				Symbol: "AAPL",
				Price:  rand.Float64()*100 + 150,
				Time:   time.Now(),
			}
		}
	}
}
