#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <deque>
#include <vector>
#include <functional>
#include <chrono>
#include <atomic>

// Market data structure
struct MarketData {
    std::string symbol;
    double price;
    std::chrono::steady_clock::time_point timestamp;
};

// Aggregation window configuration
const std::chrono::seconds WINDOW_DURATION(10);
const std::chrono::seconds UPDATE_INTERVAL(1);

// Aggregation calculator
class PriceAggregator {
public:
    void addData(const MarketData& data) {
        std::lock_guard<std::mutex> lock(windowMutex);
        dataWindow.push_back(data);
    }

    double getAveragePrice() {
        std::lock_guard<std::mutex> lock(windowMutex);
        purgeOldData();

        if (dataWindow.empty()) return 0.0;

        double sum = 0.0;
        for (const auto& data : dataWindow) {
            sum += data.price;
        }
        return sum / dataWindow.size();
    }

private:
    void purgeOldData() {
        auto now = std::chrono::steady_clock::now();
        while (!dataWindow.empty() && 
              std::chrono::duration_cast<std::chrono::seconds>(now - dataWindow.front().timestamp).count() > WINDOW_DURATION.count()) {
            dataWindow.pop_front();
        }
    }

    std::deque<MarketData> dataWindow;
    std::mutex windowMutex;
};

// Data processor with subscriber support
class MarketDataProcessor {
public:
    MarketDataProcessor() : running(false) {}

    void start() {
        running = true;
        receiverThread = std::thread(&MarketDataProcessor::receiveData, this);
        processorThread = std::thread(&MarketDataProcessor::processData, this);
    }

    void stop() {
        running = false;
        receiverThread.join();
        processorThread.join();
    }

    void addSubscriber(std::function<void(const std::string&, double)> callback) {
        std::lock_guard<std::mutex> lock(subscribersMutex);
        subscribers.push_back(callback);
    }

private:
    void receiveData() {
        while (running) {
            // Simulate incoming market data
            MarketData data;
            data.symbol = "AAPL";
            data.price = 150.0 + (std::rand() % 200) * 0.1; // Random price between 150-170
            data.timestamp = std::chrono::steady_clock::now();

            {
                std::lock_guard<std::mutex> lock(queueMutex);
                dataQueue.push(data);
            }
            cv.notify_one();

            std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Simulate 20Hz data rate
        }
    }

    void processData() {
        while (running) {
            // Wait for data or timeout
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait_for(lock, std::chrono::milliseconds(100), [this] { return !dataQueue.empty(); });

            // Process all available data
            while (!dataQueue.empty()) {
                aggregator.addData(dataQueue.front());
                dataQueue.pop();
            }
            lock.unlock();

            // Periodically compute and publish aggregates
            auto now = std::chrono::steady_clock::now();
            static auto lastUpdate = now;
            if (std::chrono::duration_cast<std::chrono::seconds>(now - lastUpdate).count() >= UPDATE_INTERVAL.count()) {
                double avgPrice = aggregator.getAveragePrice();
                notifySubscribers("AAPL", avgPrice);
                lastUpdate = now;
            }
        }
    }

    void notifySubscribers(const std::string& symbol, double price) {
        std::lock_guard<std::mutex> lock(subscribersMutex);
        for (auto& callback : subscribers) {
            callback(symbol, price);
        }
    }

    PriceAggregator aggregator;
    std::queue<MarketData> dataQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::vector<std::function<void(const std::string&, double)>> subscribers;
    std::mutex subscribersMutex;
    std::thread receiverThread, processorThread;
    std::atomic<bool> running;
};

// Example subscriber
void priceUpdateCallback(const std::string& symbol, double price) {
    std::cout << "New average for " << symbol << ": $" << price << std::setprecision(2) << std::fixed << std::endl;
}

int main() {
    MarketDataProcessor processor;
    processor.addSubscriber(priceUpdateCallback);

    try {
        processor.start();

        // Run for 30 seconds
        std::this_thread::sleep_for(std::chrono::seconds(30));

        processor.stop();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        processor.stop();
    }

    return 0;
}
