// Market data generator (simulated)
async fn generate_market_data(
    tx: broadcast::Sender<MarketData>,
    symbol: String,
) {
    let mut price = 100.0;
    let mut volume = 100.0;

    loop {
        let timestamp = Instant::now().elapsed().as_millis() as u64;
        let data = MarketData {
            symbol: symbol.clone(),
            price: price + rand::random::<f64>() * 2.0 - 1.0,
            volume: volume + rand::random::<f64>() * 10.0,
            timestamp,
        };

        if let Err(e) = tx.send(data) {
            eprintln!("Failed to send market data: {}", e);
        }

        price = data.price;
        volume = data.volume;
        sleep(Duration::from_millis(10)).await;
    }
}

// Aggregation processor
async fn compute_aggregates(
    mut rx: broadcast::Receiver<MarketData>,
    tx: broadcast::Sender<Aggregation>,
    symbol: String,
) {
    let window = Arc::new(Mutex::new(VecDeque::with_capacity(WINDOW_SIZE)));

    loop {
        match rx.recv().await {
            Ok(data) => {
                let mut window = window.lock().unwrap();
                if window.len() == WINDOW_SIZE {
                    window.pop_front();
                }
                window.push_back(data);

                // Calculate aggregates
                let total_volume: f64 = window.iter().map(|d| d.volume).sum();
                let avg_price = window.iter().map(|d| d.price).sum::<f64>() / window.len() as f64;

                let aggregation = Aggregation {
                    symbol: symbol.clone(),
                    avg_price,
                    total_volume,
                    window_size: window.len(),
                    timestamp: Instant::now().elapsed().as_millis() as u64,
                };

                if let Err(e) = tx.send(aggregation) {
                    eprintln!("Failed to send aggregation: {}", e);
                }
            }
            Err(e) => {
                eprintln!("Receiver error: {}", e);
                break;
            }
        }
    }
}

