### 🚀 **Go Implementation**

```go
package main

import (
	"bufio"
	"fmt"
	"math/rand"
	"net/http"
	"time"
)

// Global state
var (
	subscribers = make(map[chan string]bool)
	subscriberMutex chan bool = make(chan bool, 1) // Mutex for safe map access
	marketData    = make(chan float64)             // Channel for incoming price data
	aggregates    = make(chan string)              // Channel for computed aggregates
)

// Simulate market data (random prices every 200ms)
func simulateMarketData() {
	for {
		price := rand.Float64()*100 + 100 // $100-$200
		marketData <- price
		time.Sleep(200 * time.Millisecond)
	}
}

// Compute aggregates (simple moving average over 5 samples)
func computeAggregate() {
	window := []float64{}
	for price := range marketData {
		window = append(window, price)
		if len(window) > 5 {
			window = window[1:] // Maintain 5-element window
		}
		avg := 0.0
		for _, v := range window {
			avg += v
		}
		avg /= float64(len(window))
		aggregates <- fmt.Sprintf("avg=%.2f", avg)
	}
}

// Broadcast aggregates to all subscribers
func broadcast() {
	for msg := range aggregates {
		subscriberMutex <- true // Acquire mutex
		for ch := range subscribers {
			ch <- msg
		}
		<-subscriberMutex // Release mutex
	}
}

// HTTP handler for SSE streaming
func sseHandler(w http.ResponseWriter, r *http.Request) {
	flusher, _ := http.NewResponseWriter(w).(http.Flusher)
	ch := make(chan string)

	// Register subscriber
	subscriberMutex <- true
	subscribers[ch] = true
	<-subscriberMutex

	// Stream results
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")

	scanner := bufio.NewScanner(r.Body)
	for {
		select {
		case msg := <-ch:
			fmt.Fprintf(w, "data: %s\n\n", msg)
			flusher.Flush()
		case <-r.Context().Done():
			// Unregister subscriber
			subscriberMutex <- true
			delete(subscribers, ch)
			<-subscriberMutex
			return
		}
	}
}

func main() {
	// Start data simulation and aggregation
	go simulateMarketData()
	go computeAggregate()
	go broadcast()

	// HTTP server
	http.HandleFunc("/subscribe", sseHandler)
	fmt.Println("Server running at http://localhost:8080")
	http.ListenAndServe(":8080", nil)
}
```

