#include <boost/asio.hpp>
#include <boost/beast/websocket.hpp>
#include <boost/beast.hpp>
#include <iostream>
#include <thread>
#include <unordered_map>
#include <deque>
#include <mutex>
#include <memory>

namespace asio = boost::asio;
namespace beast = boost::beast;
using tcp = asio::ip::tcp;
using websocket = beast::websocket::stream<beast::tcp_stream>;

// Market data structure
struct PriceData {
    double current_price = 0.0;
    std::deque<double> price_window;  // For moving average
    const size_t window_size = 5;
};

// Market data processor
class MarketDataProcessor {
public:
    void add_price(const std::string& symbol, double price) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& data = prices[symbol];
        data.price_window.push_back(price);
        if (data.price_window.size() > data.window_size)
            data.price_window.pop_front();
        data.current_price = price;

        // Notify subscribers
        auto avg = compute_average(data);
        notify_subscribers(symbol, avg, price);
    }

    void subscribe(tcp::socket socket) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers.push_back(std::make_shared<websocket>(std::move(socket)));
    }

private:
    double compute_average(const PriceData& data) {
        if (data.price_window.empty()) return 0.0;
        double sum = 0.0;
        for (double p : data.price_window) sum += p;
        return sum / data.price_window.size();
    }

    void notify_subscribers(const std::string& symbol, double avg, double current) {
        std::string message = symbol + " | Current: " + std::to_string(current) + 
                             " | Avg: " + std::to_string(avg) + "\n";

        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& ws : subscribers) {
            try {
                ws->text(ws->got_text());
                ws->write(asio::buffer(message));
            } catch (...) {
                // Handle errors
            }
        }
    }

    std::unordered_map<std::string, PriceData> prices;
    std::vector<std::shared_ptr<websocket>> subscribers;
    std::mutex mutex_;
};

// WebSocket server
class WebSocketServer {
public:
    WebSocketServer(asio::io_context& io, MarketDataProcessor& processor, short port)
        : io_(io), acceptor_(io, tcp::endpoint(tcp::v4(), port)), processor_(processor) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept([this](boost::system::error_code ec, tcp::socket socket) {
            if (!ec) {
                processor_.subscribe(std::move(socket));
            }
            do_accept();
        });
    }

    asio::io_context& io_;
    tcp::acceptor acceptor_;
    MarketDataProcessor& processor_;
};

// Market data generator (simulated)
void simulate_market_data(MarketDataProcessor& processor) {
    while (true) {
        static int counter = 0;
        std::string symbols[] = {"AAPL", "GOOGL", "MSFT"};
