            double price = base_prices[i] + (rand() % 20 - 10);  // Random ±$10
            processor.add_price(symbols[i], price);
        }

        std::this_thread::sleep_for(std::chrono::seconds(1));
        ++counter;
    }
}

int main() {
    asio::io_context io;
    MarketDataProcessor processor;
    WebSocketServer server(io, processor, 8080);

    std::thread market_data_thread(simulate_market_data, std::ref(processor));

    io.run();

    market_data_thread.join();
    return 0;
}
