### **Code: Real-Time Market Data Processor in Go**
```go
package main

import (
	"fmt"
	"math/rand"
	"net/http"
	"strconv"
	"sync"
	"time"
)

// PriceAggregate holds the computed average and timestamp
type PriceAggregate struct {
	Symbol      string
	Average     float64
	Timestamp   time.Time
	WindowSize  int
}

// MarketDataProcessor handles price aggregation and streaming
type MarketDataProcessor struct {
	mu           sync.Mutex
	subscribers  map[chan PriceAggregate]struct{}
	prices       []float64
	windowSize   int
	priceChan    chan float64
	aggChan      chan PriceAggregate
}

func NewMarketDataProcessor(windowSize int) *MarketDataProcessor {
	return &MarketDataProcessor{
		subscribers:  make(map[chan PriceAggregate]struct{}),
		prices:       []float64{},
		windowSize:   windowSize,
		priceChan:    make(chan float64),
		aggChan:      make(chan PriceAggregate),
	}
}

// Start begins the price aggregation loop
func (p *MarketDataProcessor) Start() {
	go func() {
		for price := range p.priceChan {
			p.mu.Lock()
			p.prices = append(p.prices, price)
			if len(p.prices) > p.windowSize {
				p.prices = p.prices[1:]
			}
			p.mu.Unlock()

			sum := 0.0
			for _, v := range p.prices {
				sum += v
			}
			avg := sum / float64(len(p.prices))

			agg := PriceAggregate{
				Symbol:     "AAPL", // Simulated symbol
				Average:    avg,
				Timestamp:  time.Now(),
				WindowSize: p.windowSize,
			}
			p.aggChan <- agg
		}
	}()
}

// Subscribe returns a channel for receiving aggregates
func (p *MarketDataProcessor) Subscribe() chan PriceAggregate {
	ch := make(chan PriceAggregate, 100)
	p.mu.Lock()
	p.subscribers[ch] = struct{}{}
	p.mu.Unlock()
	return ch
}

// Unsubscribe removes a subscriber
func (p *MarketDataProcessor) Unsubscribe(ch chan PriceAggregate) {
	p.mu.Lock()
	delete(p.subscribers, ch)
	p.mu.Unlock()
}

// SimulateMarketData generates random prices at intervals
func (p *MarketDataProcessor) SimulateMarketData() {
	go func() {
		for {
			price := rand.Float64()*100 + 100 // Random price between $100 and $200
			p.priceChan <- price
			time.Sleep(500 * time.Millisecond)
		}
	}()
}

// HTTP handler for SSE streaming
func (p *MarketDataProcessor) HandleSubscribe(w http.ResponseWriter, r *http.Request) {
	flusher, _ := w.(http.Flusher)
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")

	ch := p.Subscribe()
	defer p.Unsubscribe(ch)

	for {
		select {
		case agg := <-ch:
			msg := fmt.Sprintf("data: {\"symbol\":\"%s\",\"average\":%.2f,\"timestamp\":\"%s\",\"window_size\":%d}\n\n",
				agg.Symbol, agg.Average, agg.Timestamp.Format(time.RFC3339), agg.WindowSize)
			_, _ = w.Write([]byte(msg))
			flusher.Flush()
		case <-r.Context().Done():
			return
		}
	}
}

func main() {
	processor := NewMarketDataProcessor(10) // 10-sample window
	processor.Start()
	processor.SimulateMarketData()

	http.HandleFunc("/subscribe", processor.HandleSubscribe)
	fmt.Println("Server running at http://localhost:8080")
	http.ListenAndServe(":8080", nil)
}
```

---

### **How It Works**
1. **Market Data Simulation**  
   - A goroutine generates random prices every 500ms and sends them to `priceChan`.

2. **Price Aggregation**  
   - The `Start()` method maintains a rolling window of prices and computes the average. Results are sent to `aggChan`.

3. **Subscriber Streaming**  
   - Clients connect to `/subscribe` via HTTP. The server streams updates using Server-Sent Events (SSE), a lightweight alternative to WebSockets.

4. **Concurrency Safety**  
   - `sync.Mutex` protects the subscriber list and price window from race conditions.

