```go
package main

import (
	"fmt"
	"math/rand"
	"time"
)

// MarketData represents a price update
type MarketData struct {
	Symbol string
	Price  float64
	Time   time.Time
}

// Aggregate represents computed price aggregates
type Aggregate struct {
	Symbol      string
	AvgPrice    float64
	UpdateTime  time.Time
	WindowSize  int
}

func main() {
	// Channels for data flow
	priceChan := make(chan MarketData)
	aggChan := make(chan Aggregate)

	// Simulate market data source (random prices)
	go func() {
		for {
			priceChan <- MarketData{
				Symbol: "AAPL",
				Price:  150 + rand.Float64()*10,
				Time:   time.Now(),
			}
			time.Sleep(200 * time.Millisecond)
		}
	}()

	// Price aggregator with moving average
	priceBuffer := []float64{}
	go func() {
		for data := range priceChan {
			priceBuffer = append(priceBuffer, data.Price)
			if len(priceBuffer) > 5 { // 5-sample window
				priceBuffer = priceBuffer[1:]
			}
			if len(priceBuffer) >= 2 { // Ensure at least 2 samples for meaningful average
				sum := 0.0
				for _, p := range priceBuffer {
					sum += p
				}
				aggChan <- Aggregate{
					Symbol:      data.Symbol,
					AvgPrice:    sum / float64(len(priceBuffer)),
					UpdateTime:  data.Time,
					WindowSize:  len(priceBuffer),
				}
			}
		}
	}()

	// Subscriber(s) receiving aggregates
	go func() {
		for agg := range aggChan {
			fmt.Printf("Aggregate: %s | Avg: %.2f | Window: %d | Time: %v\n",
				agg.Symbol, agg.AvgPrice, agg.WindowSize, agg.UpdateTime.Format("15:04:05"))
		}
	}()

	// Keep program running
	<-time.After(10 * time.Second)
}
```

