### **main.rs**
```rust
use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::net::TcpListener;
use tokio_tungstenite::{accept_async, WebSocketStream};
use tungstenite::Message;
use futures::{SinkExt, StreamExt};

// Shared state for subscribers and price data
struct AppState {
    subscribers: Mutex<Vec<Subscriber>>,
    price_window: Mutex<VecDeque<f64>>,
}

type Subscriber = tokio::sync::mpsc::UnboundedSender<Message>;
type SharedState = Arc<Mutex<AppState>>;

#[tokio::main]
async fn main() {
    // Initialize state
    let state = Arc::new(Mutex::new(AppState {
        subscribers: Mutex::new(Vec::new()),
        price_window: Mutex::new(VecDeque::with_capacity(5)), // 5-minute window
    }));

    // Start WebSocket server
    let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
    println!("WebSocket server running on ws://127.0.0.1:8080");

    // Simulate incoming market data (every 1s)
    let state_clone = Arc::clone(&state);
    tokio::spawn(async move {
        loop {
            let price = (rand::random::<f64>() * 100.0) as f64; // Simulated price
            let now = Instant::now();

            // Update price window
            {
                let mut window = state_clone.lock().unwrap().price_window.lock().unwrap();
                if window.len() >= 5 {
                    window.pop_front();
                }
                window.push_back(price);
            }

            // Compute and broadcast aggregate
            let avg = compute_average(&state_clone);
            broadcast(avg, Arc::clone(&state_clone));

            println!("Simulated price: {:.2}, 5s MA: {:.2}", price, avg);
            tokio::time::sleep(Duration::from_secs(1)).await;
        }
    });

    // Handle WebSocket connections
    while let Ok((stream, _)) = listener.accept().await {
        let state_clone = Arc::clone(&state);
        tokio::spawn(handle_connection(stream, state_clone));
    }
}

// Compute 5-minute moving average
fn compute_average(state: &SharedState) -> f64 {
    let window = state.lock().unwrap().price_window.lock().unwrap();
    if window.is_empty() {
        return 0.0;
    }
    let sum: f64 = window.iter().sum();
    sum / window.len() as f64
}

// Broadcast aggregate to all subscribers
fn broadcast(avg: f64, state: SharedState) {
    let mut subscribers = state.lock().unwrap().subscribers.lock().unwrap();
    let msg = Message::Text(format!("{{\"average\":{:.2}}}", avg));
    for subscriber in subscribers.iter() {
        let _ = subscriber.send(msg.clone());
    }
}

// Handle WebSocket connection
async fn handle_connection(stream: tokio::net::TcpStream, state: SharedState) {
    let ws_stream = accept_async(stream).await.unwrap();
    let (mut write, read) = ws_stream.split();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();

    // Add subscriber to state
    {
        let mut subs = state.lock().unwrap().subscribers.lock().unwrap();
        subs.push(tx);
    }

    // Forward messages to client
    tokio::spawn(async move {
        while let Some(msg) = rx.recv() {
            if let Err(e) = write.send(msg).await {
                eprintln!("Error sending message: {}", e);
                break;
            }
        }
    });

    // Handle client disconnection
    read.for_each(|msg| {
        let state_clone = Arc::clone(&state);
        async move {
            if let Err(e) = msg {
                eprintln!("WebSocket error: {}", e);
                return;
            }
            // Remove subscriber on disconnect
            let mut subs = state_clone.lock().unwrap().subscribers.lock().unwrap();
            subs.retain(|s| !s.is_closed());
        }
    })
    .await;
}
```

