namespace asio = boost::asio;
using boost::asio::ip::tcp;

// Message structure
struct Message {
    std::chrono::steady_clock::time_point timestamp;
    std::string payload;
    std::string destination;
};

// Latency metrics
struct LatencyMetrics {
    std::atomic<uint64_t> total_messages{0};
    std::atomic<uint64_t> total_latency{0};  // nanoseconds
    std::atomic<uint64_t> min_latency{UINT64_MAX};
    std::atomic<uint64_t> max_latency{0};
};

// Thread-safe latency queue
class LatencyQueue {
public:
    void push(uint64_t latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(latency);
        cond_.notify_one();
    }

    bool try_pop(uint64_t& latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) return false;
        latency = queue_.front();
        queue_.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    std::queue<uint64_t> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;
};

// Messaging system components
class MessageRouter {
public:
    MessageRouter(asio::io_context& io_context, unsigned short port)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)),
          io_context_(io_context),
          latency_queue_(std::make_shared<LatencyQueue>()) {
        start_accept();
    }

    void start() {
        std::thread([this] { monitor_latency(); }).detach();
    }

private:
    void start_accept() {
        socket_ = std::make_shared<tcp::socket>(io_context_);
        acceptor_.async_accept(*socket_,
            [this](boost::system::error_code ec) {
                if (!ec) {
                    handle_connection();
                }
                start_accept();
            });
    }

    void handle_connection() {
        auto socket = std::move(socket_);
        asio::async_read(*socket, asio::buffer(buffer_),
            [this, socket](boost::system::error_code ec, std::size_t length) {
                if (!ec) {
                    auto message = parse_message(buffer_.data(), length);
                    auto latency = std::chrono::duration_cast<std::chrono::nanoseconds>(
                        std::chrono::steady_clock::now() - message->timestamp).count();

                    update_metrics(latency);
                    route_message(message);

                    // Simulate processing
                    std::this_thread::sleep_for(std::chrono::microseconds(10));

                    // Acknowledgment
                    std::string ack = "ACK";
                    asio::write(*socket, asio::buffer(ack));
                }
                socket->close();
            });
    }

    std::shared_ptr<Message> parse_message(const char* data, size_t length) {
        // Real implementation would use binary parsing
        auto msg = std::make_shared<Message>();
        msg->timestamp = std::chrono::steady_clock::now();
        msg->payload = std::string(data, length);
        msg->destination = "default";  // Would be parsed from message
        return msg;
    }

    void route_message(const std::shared_ptr<Message>& message) {
        // Real implementation would have routing logic
        // This is a simplified example
    }

    void update_metrics(uint64_t latency) {
        latency_metrics_.total_messages++;
        latency_metrics_.total_latency += latency;
        latency_metrics_.min_latency = std::min(latency_metrics_.min_latency.load(), latency);
        latency_metrics_.max_latency = std::max(latency_metrics_.max_latency.load(), latency);

        latency_queue_->push(latency);
    }

    void monitor_latency() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));

            uint64_t messages = latency_metrics_.total_messages.load();
            uint64_t total = latency_metrics_.total_latency.load();
            uint64_t min = latency_metrics_.min_latency.load();
            uint64_t max = latency_metrics_.max_latency.load();

            if (messages > 0) {
                double avg = static_cast<double>(total) / messages;
                std::cout << "Latency (ms): Avg=" << avg/1e6 
                          << " Min=" << min/1e6 
                          << " Max=" << max/1e6 
                          << " Messages=" << messages 
                          << std::endl;
            }

            // Reset metrics
            latency_metrics_ = {};
        }
    }

    tcp::acceptor acceptor_;
    asio::io_context& io_context_;
    std::shared_ptr<LatencyQueue> latency_queue_;
    std::shared_ptr<tcp::socket> socket_;
    std::array<char, 65536> buffer_;
    LatencyMetrics latency_metrics_;
};

int main(int argc, char* argv[]) {
    try {
        asio::io_context io_context;
        MessageRouter router(io_context, 8080);
        router.start();

        // Use multiple threads for high throughput
        std::vector<std::thread> threads;
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads.emplace_back([&io_context] {
                io_context.run();
            });
        }

        for (auto& t : threads) {
            t.join();
        }
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

