// Message represents a message in the system
type Message struct {
	ID      uint64
	Content  string
	Topic    string
	Timestamp time.Time
}

// LatencyBucket holds latency data
type LatencyBucket struct {
	Min, Max, Avg float64
	Count         int64
}

// LatencyMonitor tracks message processing latencies
type LatencyMonitor struct {
	buckets map[string]*LatencyBucket
	mu      sync.RWMutex
}

// NewLatencyMonitor creates a new latency monitor
func NewLatencyMonitor() *LatencyMonitor {
	return &LatencyMonitor{
		buckets: make(map[string]*LatencyBucket),
	}
}

// RecordLatency records the latency for a message
func (lm *LatencyMonitor) RecordLatency(topic string, latency time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	if _, exists := lm.buckets[topic]; !exists {
		lm.buckets[topic] = &LatencyBucket{}
	}

	bucket := lm.buckets[topic]
	latencyMs := float64(latency.Milliseconds())

	atomic.AddInt64(&bucket.Count, 1)

	if bucket.Min == 0 || latencyMs < bucket.Min {
		bucket.Min = latencyMs
	}

	if latencyMs > bucket.Max {
		bucket.Max = latencyMs
	}

	bucket.Avg = (bucket.Avg*(float64(bucket.Count-1)) + latencyMs) / float64(bucket.Count)
}

// PrintReport prints latency metrics
func (lm *LatencyMonitor) PrintReport() {
	lm.mu.RLock()
	defer lm.mu.RUnlock()

	fmt.Println("\n=== Latency Report ===")
	for topic, bucket := range lm.buckets {
		fmt.Printf("Topic: %s\n", topic)
		fmt.Printf("  Min: %.2f ms\n", bucket.Min)
		fmt.Printf("  Max: %.2f ms\n", bucket.Max)
		fmt.Printf("  Avg: %.2f ms\n", bucket.Avg)
		fmt.Printf("  Count: %d\n", bucket.Count)
	}
}

