template <typename T>
class ConcurrentQueue {
public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(std::move(value));
        cond_.notify_one();
    }

    bool try_pop(T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) return false;
        value = std::move(queue_.front());
        queue_.pop();
        return true;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;
};

// Latency statistics collector
class LatencyMonitor {
public:
    void record_latency(std::chrono::steady_clock::duration latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        latencies_.push_back(latency);
    }

    void print_stats() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (latencies_.empty()) return;

        auto total = std::chrono::steady_clock::duration::zero();
        auto min = latencies_[0];
        auto max = latencies_[0];

        for (const auto& l : latencies_) {
            total += l;
            min = std::min(min, l);
            max = std::max(max, l);
        }

        auto avg = total / latencies_.size();

        std::cout << "Latency Stats:\n";
        std::cout << "  Min: " << std::chrono::duration_cast<std::chrono::microseconds>(min).count() << " µs\n";
        std::cout << "  Max: " << std::chrono::duration_cast<std::chrono::microseconds>(max).count() << " µs\n";
        std::cout << "  Avg: " << std::chrono::duration_cast<std::chrono::microseconds>(avg).count() << " µs\n";
        std::cout << "  Count: " << latencies_.size() << "\n";

        latencies_.clear();
    }

private:
    std::vector<std::chrono::steady_clock::duration> latencies_;
    mutable std::mutex mutex_;
};

