        for (size_t i = 0; i < numWorkers_; ++i) {
            workers_.emplace_back(&MessageRouter::workerLoop, this);
        }
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(queueMtx_);
            stop_ = true;
