Here's a high-performance C++ implementation for a high-frequency messaging system with latency monitoring. This example uses Boost.Asio for I/O and std::chrono for latency tracking, focusing on routing and throughput optimization.

```cpp
#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/array.hpp>
#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>
#include <unordered_map>
#include <mutex>
#include <queue>

using boost::asio::ip::tcp;

namespace {
    const size_t MAX_MESSAGE_SIZE = 8192;
    const short PORT = 55555;
    const size_t LATENCY_WINDOW_MS = 1000;
}

// Message routing table (topic -> list of destinations)
using RouteTable = std::unordered_map<std::string, std::vector<tcp::socket*>>;

// Latency metrics
struct LatencyMetrics {
    std::atomic<size_t> message_count{0};
    std::mutex metrics_mutex;
    std::queue<std::chrono::microseconds> latencies;

    void record_latency(std::chrono::microseconds duration) {
        std::lock_guard<std::mutex> lock(metrics_mutex);
        latencies.push(duration);
        message_count++;
    }

    void report() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(LATENCY_WINDOW_MS));

            std::lock_guard<std::mutex> lock(metrics_mutex);
            if (latencies.empty()) continue;

            size_t total = 0;
            size_t max = 0;
            size_t min = std::numeric_limits<size_t>::max();
            std::vector<size_t> all_latencies;

            while (!latencies.empty()) {
                auto dur = latencies.front().count();
                all_latencies.push_back(dur);
                total += dur;
                max = std::max(max, dur);
                min = std::min(min, dur);
                latencies.pop();
            }

            if (!all_latencies.empty()) {
                std::sort(all_latencies.begin(), all_latencies.end());
                size_t p99 = all_latencies[all_latencies.size() * 99 / 100];
                double avg = static_cast<double>(total) / all_latencies.size();

                std::cout << "Metrics (" << LATENCY_WINDOW_MS << "ms window):" << std::endl;
                std::cout << "  Throughput: " << message_count << " messages" << std::endl;
                std::cout << "  Avg latency: " << avg << " µs" << std::endl;
                std::cout << "  P99 latency: " << p99 << " µs" << std::endl;
                std::cout << "  Max latency: " << max << " µs" << std::endl;
                std::cout << "  Min latency: " << min << " µs" << std::endl;
            }
            message_count = 0;
        }
    }
} metrics;

class Session : public std::enable_shared_from_this<Session> {
public:
    Session(tcp::socket socket, RouteTable& routes)
        : socket_(std::move(socket)), routes_(routes) {}

    void start() {
        do_read();
    }

private:
    void do_read() {
        auto self(shared_from_this());
        socket_.async_read_some(boost::asio::buffer(data_),
            [this, self](boost::system::error_code ec, std::size_t length) {
                if (!ec) {
                    auto start_time = std::chrono::high_resolution_clock::now();

                    // Simple routing: first 4 bytes = topic length, next N bytes = topic
                    size_t topic_len = *reinterpret_cast<uint32_t*>(data_.data());
                    std::string topic(data_.data() + 4, topic_len);

                    // Route message to all subscribers
                    auto it = routes_.find(topic);
                    if (it != routes_.end()) {
                        for (auto dest : it->second) {
                            boost::asio::post(socket_.get_executor(),
                                [dest, this, payload = boost::asio::buffer(data_, length)]() {
                                    boost::asio::write(*dest, payload);
                                });
                        }
                    }

                    auto end_time = std::chrono::high_resolution_clock::now();
                    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time);
                    metrics.record_latency(duration);

                    do_read();
                }
            });
    }

    tcp::socket socket_;
    RouteTable& routes_;
    boost::array<char, MAX_MESSAGE_SIZE> data_;
};

class Server {
public:
    Server(boost::asio::io_context& io_context, short port)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
        do_accept();
    }

    void subscribe(const std::string& topic, tcp::socket* socket) {
        std::lock_guard<std::mutex> lock(mutex_);
        routes_[topic].push_back(socket);
    }

private:
    void do_accept() {
        auto session = std::make_shared<Session>(acceptor_.accept(), routes_);
        session->start();

        do_accept();
    }

    tcp::acceptor acceptor_;
    RouteTable routes_;
    std::mutex mutex_;
};

int main(int argc, char* argv[]) {
    try {
        boost::asio::io_context io_context;

        // Start server
        Server server(io_context, PORT);

        // Start metrics reporting
        std::thread metrics_thread([]() { metrics.report(); });
        metrics_thread.detach();

        // Start I/O threads
        const size_t num_threads = std::thread::hardware_concurrency();
        std::vector<std::thread> threads;
        for (size_t i = 0; i < num_threads; ++i) {
            threads.emplace_back([&io_context]() { io_context.run(); });
        }

        for (auto& t : threads) {
            t.join();
        }
    }
    catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

