```go
package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"runtime"
	"sync"
	"sync/atomic"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

// Message represents a routed message
type Message struct {
	ID        string    `json:"id"`
	Type      string    `json:"type"` // "high_priority" or "low_priority"
	Payload   string    `json:"payload"`
	Timestamp time.Time `json:"timestamp"`
}

// Metrics
var (
	msgCount = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "messaging_system_messages_total",
			Help: "Total messages processed by type",
		},
		[]string{"type"},
	)

	msgLatency = prometheus.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "messaging_system_latency_seconds",
			Help:    "Message routing latency distribution",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"type"},
	)
)

// Router handles message routing
type Router struct {
	highPriorityChan  chan Message
	lowPriorityChan   chan Message
	latencyRecorder   *LatencyRecorder
	workers           int
	workerWaitGroup   sync.WaitGroup
	shutdown          atomic.Bool
}

// LatencyRecorder tracks message processing times
type LatencyRecorder struct {
	startTimes map[string]time.Time
	mu         sync.RWMutex
}

func init() {
	prometheus.MustRegister(msgCount, msgLatency)
}

func main() {
	// Initialize metrics server
	go func() {
		http.Handle("/metrics", promhttp.Handler())
		log.Println("Starting metrics server on :8080")
		if err := http.ListenAndServe(":8080", nil); err != nil {
			log.Fatal(err)
		}
	}()

	// Configure router with appropriate channel sizes
	router := NewRouter(1000000, 1000000, 16)

	// Start benchmark test
	log.Println("Starting benchmark test...")
	runBenchmark(router, 1000000)
}

// NewRouter creates a new message router
func NewRouter(highCapacity, lowCapacity, workers int) *Router {
	r := &Router{
		highPriorityChan:  make(chan Message, highCapacity),
		lowPriorityChan:   make(chan Message, lowCapacity),
		workers:           workers,
		latencyRecorder:   &LatencyRecorder{startTimes: make(map[string]time.Time)},
	}

	// Start worker goroutines
	r.workerWaitGroup.Add(r.workers * 2)
	for i := 0; i < r.workers; i++ {
		go r.processHighPriority(i)
		go r.processLowPriority(i)
	}

	return r
}

// RouteMessage adds a message to the appropriate channel
func (r *Router) RouteMessage(msg Message) {
	r.latencyRecorder.RecordStart(msg.ID)

	switch msg.Type {
	case "high_priority":
		r.highPriorityChan <- msg
	case "low_priority":
		r.lowPriorityChan <- msg
	default:
		log.Printf("Unknown message type: %s", msg.Type)
	}
}

// processHighPriority handles high priority messages
func (r *Router) processHighPriority(workerID int) {
	defer r.workerWaitGroup.Done()

	for msg := range r.highPriorityChan {
		// Simulate processing (real system would have actual routing logic)
		time.Sleep(10 * time.Microsecond) // Simulated processing time

		latency := r.latencyRecorder.RecordEnd(msg.ID)
		msgCount.WithLabelValues("high_priority").Inc()
		msgLatency.WithLabelValues("high_priority").Observe(latency.Seconds())
	}
}

// processLowPriority handles low priority messages
func (r *Router) processLowPriority(workerID int) {
	defer r.workerWaitGroup.Done()

	for msg := range r.lowPriorityChan {
		// Simulate processing (real system would have actual routing logic)
		time.Sleep(50 * time.Microsecond) // Simulated processing time

		latency := r.latencyRecorder.RecordEnd(msg.ID)
		msgCount.WithLabelValues("low_priority").Inc()
		msgLatency.WithLabelValues("low_priority").Observe(latency.Seconds())
	}
}

// LatencyRecorder methods
func (lr *LatencyRecorder) RecordStart(id string) {
	lr.mu.Lock()
	lr.startTimes[id] = time.Now()
	lr.mu.Unlock()
}

func (lr *LatencyRecorder) RecordEnd(id string) time.Duration {
	lr.mu.RLock()
	start, exists := lr.startTimes[id]
	lr.mu.RUnlock()

	if !exists {
		return 0
	}

	delete(lr.startTimes, id)
	return time.Since(start)
}

// runBenchmark simulates high message throughput
func runBenchmark(router *Router, totalMessages int) {
	var wg sync.WaitGroup
	batchSize := 10000

	// Calculate number of batches
	batches := totalMessages / batchSize
	if totalMessages%batchSize != 0 {
		batches++
	}

	for i := 0; i < batches; i++ {
		wg.Add(1)
		go func(batch int) {
			defer wg.Done()
			for j := 0; j < batchSize; j++ {
				msg := Message{
					ID:        generateID(),
					Type:      randomType(),
					Payload:   "test_payload",
					Timestamp: time.Now(),
				}
				router.RouteMessage(msg)
			}
		}(i)
	}

	wg.Wait()
	router.Shutdown()
}

// generateID creates a simple unique ID
func generateID() string {
	// In production, use a proper ID generation strategy
	return time.Now().Format("20060102150405.999999999")
}

// randomType returns a random message type
func randomType() string {
	// In production, use actual routing logic
	if time.Now().UnixNano()%2 == 0 {
		return "high_priority"
	}
	return "low_priority"
}

// Shutdown gracefully stops the router
func (r *Router) Shutdown() {
	if r.shutdown.CompareAndSwap(false, true) {
		close(r.highPriorityChan)
		close(r.lowPriorityChan)
		r.workerWaitGroup.Wait()
		log.Println("Router shutdown complete")
	}
}
