### **Code Implementation**

```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <atomic>
#include <chrono>
#include <unordered_map>
#include <functional>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <cmath>

// Message structure with timestamp for latency tracking
struct Message {
    uint64_t id;
    std::string type;
    std::string payload;
    std::chrono::steady_clock::time_point enqueue_time;

    Message(uint64_t id, const std::string& type, const std::string& payload)
        : id(id), type(type), payload(payload), enqueue_time(std::chrono::steady_clock::now()) {}
};

// Thread-safe queue with lock-free principles
class ThreadSafeQueue {
    std::deque<std::shared_ptr<Message>> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;

public:
    void enqueue(std::shared_ptr<Message> msg) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push_back(msg);
        cond_.notify_one();
    }

    std::shared_ptr<Message> dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_.wait(lock, [this] { return !queue_.empty(); });
        auto msg = queue_.front();
        queue_.pop_front();
        return msg;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }
};

// Latency histogram with buckets (e.g., 0-100us, 100-200us, etc.)
class LatencyMonitor {
    std::vector<std::atomic<uint64_t>> buckets_;
    const uint64_t max_bucket_;
    const uint64_t bucket_size_;

public:
    LatencyMonitor(uint64_t max_bucket_us, uint64_t bucket_size_us)
        : max_bucket_(max_bucket_us), bucket_size_(bucket_size_us) {
        buckets_.resize((max_bucket_ / bucket_size_) + 2, 0); // +1 for overflow
    }

    void record_latency(uint64_t latency_us) {
        if (latency_us < max_bucket_) {
            buckets_[latency_us / bucket_size_] += 1;
        } else {
            buckets_.back() += 1;
        }
    }

    void print_stats() const {
        std::cout << "Latency Histogram (us):\n";
        for (size_t i = 0; i < buckets_.size(); ++i) {
            auto count = buckets_[i].load();
            if (count > 0) {
                if (i == buckets_.size() - 1) {
                    std::cout << "> " << max_bucket_ << "us: " << count << "\n";
                } else {
                    std::cout << i * bucket_size_ << "-" << (i + 1) * bucket_size_ << "us: " << count << "\n";
                }
            }
        }
    }
};

// High-frequency messaging router
class MessageRouter {
    ThreadSafeQueue message_queue_;
    std::unordered_map<std::string, std::function<void(const Message&)>> handlers_;
    std::vector<std::thread> workers_;
    LatencyMonitor latency_monitor_;
    std::atomic<bool> running_{false};

public:
    MessageRouter(size_t num_workers, uint64_t max_latency_bucket_us = 10000, uint64_t bucket_size_us = 100)
        : latency_monitor_(max_latency_bucket_us, bucket_size_us) {
        for (size_t i = 0; i < num_workers; ++i) {
            workers_.emplace_back([this]() {
                while (running_) {
                    auto msg = message_queue_.dequeue();
                    auto process_start = std::chrono::steady_clock::now();
                    auto enqueue_time = msg->enqueue_time;
                    auto latency = std::chrono::duration_cast<std::chrono::microseconds>(process_start - enqueue_time).count();

                    auto it = handlers_.find(msg->type);
                    if (it != handlers_.end()) {
                        it->second(*msg);
                    }

                    latency_monitor_.record_latency(latency);
                }
            });
        }
    }

    ~MessageRouter() {
        running_ = false;
        for (auto& t : workers_) {
            if (t.joinable()) t.join();
        }
    }

    void enqueue_message(const std::string& type, const std::string& payload, uint64_t id) {
        message_queue_.enqueue(std::make_shared<Message>(id, type, payload));
    }

    void register_handler(const std::string& type, std::function<void(const Message&)> handler) {
        handlers_[type] = handler;
    }

    void print_latency_stats() {
        latency_monitor_.print_stats();
    }
};

// Example usage
int main() {
    const size_t NUM_WORKERS = std::thread::hardware_concurrency();
    const size_t MAX_LATENCY_BUCKET_US = 10000; // 10ms
    const size_t BUCKET_SIZE_US = 100;

    MessageRouter router(NUM_WORKERS, MAX_LATENCY_BUCKET_US, BUCKET_SIZE_US);

    // Register message handlers
    router.register_handler("order", [](const Message& msg) {
        // Simulate message processing
        std::this_thread::sleep_for(std::chrono::microseconds(50));
    });

    router.register_handler("trade", [](const Message& msg) {
        // Simulate message processing
        std::this_thread::sleep_for(std::chrono::microseconds(150));
    });

    // Start routing
    router.running_ = true;

    // Simulate high-frequency message generation
    std::thread producer([&]() {
        uint64_t msg_id = 0;
        while (true) {
            router.enqueue_message("order", "BUY 100 AAPL", msg_id++);
            router.enqueue_message("trade", "TRADE 500 GOOG", msg_id++);
            std::this_thread::sleep_for(std::chrono::microseconds(10)); // ~100k messages/sec
        }
    });

    // Periodically print latency stats
    std::thread monitor([&]() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            router.print_latency_stats();
        }
    });

    producer.join();
    monitor.join();
    return 0;
}
```

