```go
package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

// Message represents a routed message
type Message struct {
	ID        int64
	Timestamp time.Time
}

// LatencyMonitor tracks message processing latency
type LatencyMonitor struct {
	mu      sync.Mutex
	total   time.Duration
	count   int64
	max     time.Duration
	min     time.Duration
}

func (lm *LatencyMonitor) Record(latency time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()
	lm.total += latency
	lm.count++
	if latency > lm.max {
		lm.max = latency
	}
	if lm.min == 0 || latency < lm.min {
		lm.min = latency
	}
}

func (lm *LatencyMonitor) Summary() {
	lm.mu.Lock()
	defer lm.mu.Unlock()
	if lm.count == 0 {
		return
	}
	avg := lm.total / time.Duration(lm.count)
	fmt.Printf("Latency Summary:\n")
	fmt.Printf("  Min: %v\n", lm.min)
	fmt.Printf("  Max: %v\n", lm.max)
	fmt.Printf("  Avg: %v\n", avg)
}

// Router handles message routing
func Router(msgChan <-chan Message, consumer func(Message), wg *sync.WaitGroup) {
	for msg := range msgChan {
		consumer(msg)
		wg.Done()
	}
}

// Consumer processes messages and records latency
func Consumer(msg Message, monitor *LatencyMonitor) {
	latency := time.Since(msg.Timestamp)
	monitor.Record(latency)
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU()) // Optimize for CPU usage

	const msgCount = 1_000_000      // Simulate 1 million messages
	const workers = 16              // Use 16 consumer goroutines
	msgChan := make(chan Message, 1_000_000) // Buffered channel

	var wg sync.WaitGroup
	monitor := &LatencyMonitor{min: time.Duration(0)}

	// Start consumer workers
	for i := 0; i < workers; i++ {
		go Router(msgChan, func(msg Message) {
			Consumer(msg, monitor)
		}, &wg)
	}

	// Producer: Generate and send messages
	start := time.Now()
	for i := 0; i < msgCount; i++ {
		wg.Add(1)
		msgChan <- Message{
			ID:        int64(i),
			Timestamp: time.Now(),
		}
	}
	close(msgChan)
	wg.Wait()

	// Print results
	monitor.Summary()
	fmt.Printf("Total messages processed: %d\n", msgCount)
	fmt.Printf("Total time: %v\n", time.Since(start))
	fmt.Printf("Throughput: %.2f msg/s\n", float64(msgCount)/time.Since(start).Seconds())
}
```

