#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>
#include <cstdint>
#include <limits>

struct Message {
    uint64_t id;
    std::chrono::high_resolution_clock::time_point enqueue_time;
};

class MessageQueue {
public:
    void enqueue(Message msg) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (shutdown_) throw std::runtime_error("Queue shutdown");
        queue_.push(msg);
        cond_.notify_one();
    }

    Message dequeue() {
        std::unique_lock<std::mutex> lock(mtx_);
        cond_.wait(lock, [this] { return !queue_.empty() || shutdown_; });
        if (shutdown_ && queue_.empty()) {
            throw std::runtime_error("Queue is shutdown and empty");
        }
        Message msg = queue_.front();
        queue_.pop();
        return msg;
    }

    void shutdown() {
        std::lock_guard<std::mutex> lock(mtx_);
        shutdown_ = true;
        cond_.notify_all();
    }

private:
    std::queue<Message> queue_;
    std::mutex mtx_;
    std::condition_variable cond_;
    bool shutdown_ = false;
};

struct LatencyStats {
    std::atomic<uint64_t> count{0};
    std::atomic<double> total_latency{0.0};
    std::atomic<double> min_latency{std::numeric_limits<double>::max()};
    std::atomic<double> max_latency{0.0};

    void record(double latency_us) {
        count++;
        total_latency += latency_us;
        if (latency_us < min_latency) min_latency = latency_us;
        if (latency_us > max_latency) max_latency = latency_us;
    }

    void print() const {
        std::cout << "=== Latency Stats ===\n";
        std::cout << "Total messages: " << count << "\n";
        std::cout << "Average latency: " << (total_latency / count) << " us\n";
        std::cout << "Min latency: " << min_latency << " us\n";
        std::cout << "Max latency: " << max_latency << " us\n";
    }
};

void producer(MessageQueue& queue, uint64_t num_messages) {
    for (uint64_t i = 0; i < num_messages; ++i) {
        Message msg;
        msg.id = i;
        msg.enqueue_time = std::chrono::high_resolution_clock::now();
        queue.enqueue(msg);
    }
}

void consumer(MessageQueue& queue, LatencyStats& stats, int thread_id) {
    try {
        while (true) {
            Message msg = queue.dequeue();
            auto dequeue_time = std::chrono::high_resolution_clock::now();
            auto latency_us = std::chrono::duration_cast<std::chrono::microseconds>(
                dequeue_time - msg.enqueue_time).count();
            stats.record(latency_us);

            // Simulate message processing (routing)
            // In a real system, this would involve routing logic
            // For example: route_to_destination(msg.id % 10);
        }
    } catch (const std::exception& e) {
        // Exit on shutdown
    }
}

int main() {
    const size_t num_consumers = 4;
    const uint64_t num_messages = 1000000;

    MessageQueue queue;
    LatencyStats stats;

    std::vector<std::thread> consumers;
    for (size_t i = 0; i < num_consumers; ++i) {
        consumers.emplace_back(consumer, std::ref(queue), std::ref(stats), i);
    }

    // Producer thread
    producer(queue, num_messages);

    // Signal shutdown after all messages are enqueued
    queue.shutdown();

    // Wait for all consumers to finish
    for (auto& t : consumers) {
        t.join();
    }

    stats.print();
    return 0;
}
