    std::string payload;
};

class Router {
public:
    Router(size_t capacity) : queue_(capacity) {}

    void send(Message msg) {
        auto start = high_resolution_clock::now();
        while (!queue_.push(msg)) {} // Block until space is available
        auto end = high_resolution_clock::now();
        latency_.fetch_add(duration_cast<microseconds>(end - start).count());
    }

    void route() {
        Message msg;
        while (true) {
            if (queue_.pop(msg)) {
                // Simulate routing logic (e.g., topic-based routing)
                std::this_thread::yield(); // Simulate minimal processing
            }
        }
    }

    double get_average_latency() {
        return latency_.load() / (double)message_count_.load();
    }

private:
    boost::lockfree::queue<Message> queue_;
    std::atomic<uint64_t> latency_{0};
    std::atomic<uint64_t> message_count_{0};
};

int main() {
    Router router(1024 * 1024); // 1M capacity

    // Start routing thread
    std::thread router_thread([&] { router.route(); });

