use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};
use crossbeam::queue::SegQueue;
use tokio::time::{sleep, Duration as TokioDuration};

struct Message {
    id: u64,
    payload: String,
}

struct Router {
    queue: SegQueue<Message>,
    latency: AtomicU64,
    message_count: AtomicU64,
}

impl Router {
    fn new() -> Self {
        Router {
            queue: SegQueue::new(),
            latency: AtomicU64::new(0),
            message_count: AtomicU64::new(0),
        }
    }

    fn send(&self, msg: Message) {
        let start = Instant::now();
        self.queue.push(msg);
        let elapsed = start.elapsed();
        self.latency.fetch_add(elapsed.as_micros() as u64, Ordering::Relaxed);
        self.message_count.fetch_add(1, Ordering::Relaxed);
    }

    async fn route(&self) {
        loop {
            if let Some(msg) = self.queue.pop() {
                // Simulate routing logic
                std::thread::yield_now(); // Simulate minimal processing
            }
        }
    }

    fn average_latency(&self) -> f64 {
        self.latency.load(Ordering::Relaxed) as f64 / self.message_count.load(Ordering::Relaxed) as f64
    }
}

#[tokio::main]
async fn main() {
    let router = Router::new();

    // Start routing task
    tokio::spawn(router.route());

    // Producer task
    tokio::spawn(async move {
        for i in 0..1_000_000 {
            let msg = Message {
                id: i,
                payload: "test".to_string(),
            };
            router.send(msg);
        }
    });

    // Wait for completion (simplified)
    sleep(TokioDuration::from_secs(1)).await;
    println!("Average latency: {} µs", router.average_latency());
}
