        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& [bucket, count] : buckets_) {
            std::cout << bucket << "µs: " << count << " messages\n";
        }
    }

private:
    std::mutex mutex_;
    std::unordered_map<int64_t, int64_t> buckets_;
};

// Message routing system
class MessageRouter {
public:
    MessageRouter(int num_workers) : workers_(num_workers), stop_(false) {
        for (int i = 0; i < num_workers; ++i) {
            workers_.emplace_back([this] { this->worker_thread(); });
        }
    }

    ~MessageRouter() {
        stop_ = true;
        for (auto& worker : workers_) {
            if (worker.joinable()) worker.join();
        }
    }

    void send_message(const Message& msg) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        message_queue_.push(msg);
    }

private:
    void worker_thread() {
        while (!stop_) {
            Message msg;
            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                if (!message_queue_.empty()) {
                    msg = message_queue_.front();
                    message_queue_.pop();
                    lock.unlock();

                    // Simulate routing logic
                    process_message(msg);
                }
            }
        }
    }

    void process_message(const Message& msg) {
        auto end_time = std::chrono::steady_clock::now();
        auto latency = end_time - msg.timestamp;
        monitor_.record_latency(latency);
    }

    std::vector<std::thread> workers_;
    std::queue<Message> message_queue_;
    std::mutex queue_mutex_;
    std::atomic<bool> stop_;
    LatencyMonitor monitor_;
};

