```rust
use tokio::sync::mpsc;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;
use chrono::Utc;

#[derive(Clone)]
struct Metrics {
    total_messages: AtomicU64,
    total_latency_ns: AtomicU64,
    min_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Metrics {
            total_messages: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            min_latency_ns: AtomicU64::new(u64::MAX),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.total_messages.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let current_min = self.min_latency_ns.load(Ordering::Relaxed);
        if latency_ns < current_min {
            self.min_latency_ns.store(latency_ns, Ordering::Relaxed);
        }

        let current_max = self.max_latency_ns.load(Ordering::Relaxed);
        if latency_ns > current_max {
            self.max_latency_ns.store(latency_ns, Ordering::Relaxed);
        }
    }

    fn print_stats(&self) {
        let total = self.total_messages.load(Ordering::Relaxed);
        let total_latency = self.total_latency_ns.load(Ordering::Relaxed);
        let avg = total_latency as f64 / total as f64;
        let min = self.min_latency_ns.load(Ordering::Relaxed);
        let max = self.max_latency_ns.load(Ordering::Relaxed);

        println!(
            "[{}] Processed {} messages | Avg Latency: {:.2} ns | Min: {} ns | Max: {} ns",
            Utc::now().to_rfc3339(),
            total,
            avg,
            min,
            max
        );
    }
}

#[derive(Clone)]
struct Message {
    payload: String,
    send_time: Instant,
}

async fn message_router(mut rx: mpsc::Receiver<Message>, metrics: Arc<Metrics>) {
    while let Some(msg) = rx.recv().await {
        let process_time = Instant::now();
        // Simulate message routing (e.g., to a downstream system)
        tokio::task::spawn(async move {
            // Dummy processing (replace with actual routing logic)
            let latency = process_time.duration_since(msg.send_time).as_nanos() as u64;
            metrics.record_latency(latency);
        });
    }
}

#[tokio::main]
async fn main() {
    let metrics = Arc::new(Metrics::new());
    let (tx, rx) = mpsc::channel(100_000); // Bounded channel for backpressure

    // Spawn 4 worker routers
    for _ in 0..4 {
        let rx_clone = rx.clone();
        let metrics_clone = Arc::clone(&metrics);
        tokio::spawn(message_router(rx_clone, metrics_clone));
    }

    // Simulate message sender
    tokio::spawn(async move {
