                send_time: Instant::now(),
            };
            tx.send(msg).await.unwrap();
        }
    });

    // Print latency stats every second
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
        metrics.print_stats();
    }
}
