Here's an example implementation in **C** using the **DPDK** (Data Plane Development Kit), optimized for ultra-low-latency packet filtering and forwarding. This code assumes a basic understanding of DPDK and Linux kernel bypass techniques.

---

### **Key Features**
- **Zero-copy packet processing**
- **Hardware-accelerated filtering**
- **Minimal CPU context switches**
- **Sub-microsecond latency (with proper hardware)**

---

### **Code Example**
```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_cycles.h>
#include <rte_lcore.h>
#include <rte_ip.h>
#include <rte_ether.h>

#define RX_RING_SIZE 4096
#define TX_RING_SIZE 4096
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Simple packet filter: forward only IPv4 packets from a specific source IP
int filter_packet(struct rte_mbuf *pkt) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);
    if (rte_be_to_cpu_16(eth_hdr->ether_type) != RTE_ETHER_TYPE_IPV4)
        return 0; // Drop non-IPv4 packets

    struct rte_ipv4_hdr *ip_hdr = (struct rte_ipv4_hdr *)((uint8_t *)eth_hdr + sizeof(struct rte_ether_hdr));
    if (rte_be_to_cpu_32(ip_hdr->src_addr) != 0x01020304) // Replace with target source IP (e.g., 1.2.3.4)
        return 0; // Drop packets not from 1.2.3.4

    return 1; // Accept packet
}

int main(int argc, char *argv[]) {
    // Initialize the Environment Abstraction Layer (EAL)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    uint16_t port_id = 0; // Use first available port
    uint16_t queue_id = 0;

    // Configure the Ethernet device
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Could not configure device: err=%d\n", ret);

    // Allocate and set up RX/TX queues
    ret = rte_eth_rx_queue_setup(port_id, queue_id, RX_RING_SIZE, RTE_ETH_DEV_SOCKET_ID_ANY, NULL, rte_eth_dev_allocated_mbuf_pool(port_id));
    ret |= rte_eth_tx_queue_setup(port_id, queue_id, TX_RING_SIZE, RTE_ETH_DEV_SOCKET_ID_ANY, NULL);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Could not set up RX/TX queues: err=%d\n", ret);

    // Start the Ethernet port
    ret = rte_eth_dev_start(port_id);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Could not start device: err=%d\n", ret);

    // Main packet processing loop
    struct rte_mbuf *pkts_burst[RTE_MBUF_DEFAULT_BUF_SIZE];
    while (1) {
        // Receive packets (burst of 32 packets)
        uint16_t nb_rx = rte_eth_rx_burst(port_id, queue_id, pkts_burst, 32);

        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *pkt = pkts_burst[i];
            if (filter_packet(pkt)) {
                // Forward accepted packets (e.g., to another port)
                uint16_t nb_tx = rte_eth_tx_burst(port_id, queue_id, &pkt, 1);
                if (nb_tx < 1)
                    rte_pktmbuf_free(pkt);
            } else {
                rte_pktmbuf_free(pkt); // Drop filtered packets
            }
        }
    }

    return 0;
}
```

---

### **Compilation and Execution**
1. **Install DPDK** (e.g., `apt install libdpdk-dev` or build from source).
2. **Compile** with DPDK flags:
   ```bash
   gcc -O3 -march=native -o lowlatency_service lowlatency_service.c -lrte_eal -lrte_ethdev -lrte_mbuf -lrte_ip -lrte_ether
   ```
3. **Run** with DPDK EAL parameters (e.g., bind a NIC to DPDK and specify hugepages):
   ```bash
   ./lowlatency_service -l 0-3 -n 4 -- -p 0x1
   ```

