#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <net/if.h>
#include <sys/ioctl.h>

#define BUFFER_SIZE 65535

int main() {
    int sockfd;
    struct ifreq ifr;
    struct sockaddr_ll src_addr, dest_addr;
    char buffer[BUFFER_SIZE];
    struct ether_header *eth_hdr;
    struct ip *ip_hdr;
    struct tcphdr *tcp_hdr;
    socklen_t addr_len = sizeof(src_addr);

    // Create raw socket
    if ((sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL))) < 0) {
        perror("Socket creation error");
        return 1;
    }

    // Set interface to promiscuous mode (e.g., eth0)
    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ);
    if (ioctl(sockfd, SIOCGIFFLAGS, &ifr) < 0) {
        perror("ioctl(SIOCGIFFLAGS)");
        close(sockfd);
        return 1;
    }
    ifr.ifr_flags |= IFF_PROMISC;
    if (ioctl(sockfd, SIOCSIFFLAGS, &ifr) < 0) {
        perror("ioctl(SIOCSIFFLAGS)");
        close(sockfd);
        return 1;
    }

    while (1) {
        // Receive packet
        int packet_len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&src_addr, &addr_len);
        if (packet_len < 0) {
            perror("Recvfrom error");
            continue;
        }

        eth_hdr = (struct ether_header *)buffer;
        if (ntohs(eth_hdr->ether_type) != ETHERTYPE_IP) continue;

        ip_hdr = (struct ip *)(buffer + sizeof(struct ether_header));
        if (ip_hdr->ip_p != IPPROTO_TCP) continue;

        tcp_hdr = (struct tcphdr *)((char *)ip_hdr + (ip_hdr->ip_hl * 4));
        if (ntohs(tcp_hdr->th_dport) != 80) continue; // Filter HTTP traffic

        // Forward the packet (example: send to another interface)
        // Pre-configure `dest_addr` with destination MAC and interface index
        // For simplicity, assume we forward to the same interface
        sendto(sockfd, buffer, packet_len, 0, (struct sockaddr *)&src_addr, sizeof(src_addr));
    }

    close(sockfd);
    return 0;
}
```

