init_port(uint16_t port) {
    struct rte_eth_conf port_conf = {
        .rxmode = {
            .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
        },
    };
    rte_eth_dev_configure(port, 1, 1, &port_conf);
