    rte_eth_tx_queue_setup(port, 0, TX_RING_SIZE, RTE_ETH_DEV_QUEUE_OFFSET(0), NULL);
    rte_eth_dev_start(port);
    rte_eth_promiscuous_enable(port);
}

static void
process_packets(uint16_t rx_port, uint16_t tx_port) {
    struct rte_mbuf *pkts_burst[RTE_MBUF_DEFAULT_BUF_SIZE];
    uint16_t nb_rx;

    while (1) {
        nb_rx = rte_eth_rx_burst(rx_port, 0, pkts_burst, RX_RING_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
