            // Filter: Drop non-IPv4 packets
            if (eth_hdr->ether_type != htons(RTE_ETHER_TYPE_IPV4)) {
                rte_pktmbuf_free(pkt);
                continue;
            }

            // Forward packet to output port
            uint16_t nb_tx = rte_eth_tx_burst(tx_port, 0, &pkt, 1);
            if (nb_tx < 1)
                rte_pktmbuf_free(pkt);
        }
    }
}

int
main(int argc, char *argv[]) {
    uint16_t nb_ports;
    uint16_t rx_port = 0, tx_port = 1;

    rte_eal_init(argc, argv);

    pkt_pool = rte_pktmbuf_pool_create("pkt_pool", NUM_MBUFS, MBUF_CACHE_SIZE, 0,
                                       RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (!pkt_pool)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    nb_ports = rte_eth_dev_count();
    if (nb_ports < 2)
