    int raw_socket;
    struct sockaddr_ll forward_addr;
    u_char buffer[BUFFER_SIZE];
    socklen_t addr_len = sizeof(forward_addr);

    // Create raw socket
    if ((raw_socket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL))) < 0) {
        perror("Socket creation failed");
        return 1;
    }

    // Set up forward interface
    memset(&forward_addr, 0, sizeof(forward_addr));
    forward_addr.sll_family = AF_PACKET;
    forward_addr.sll_protocol = htons(ETH_P_ALL);
