    strncpy(ifr.ifr_name, FORWARD_INTERFACE, IFNAMSIZ);
    if (ioctl(raw_socket, SIOCGIFINDEX, &ifr) < 0) {
        perror("Interface index retrieval failed");
        close(raw_socket);
        return 1;
    }
    forward_addr.sll_ifindex = ifr.ifr_ifindex;

    while (1) {
        int packet_len = recvfrom(raw_socket, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (packet_len < 0) {
