Here's a minimal, high-performance implementation in **C** using **DPDK** (Data Plane Development Kit) for ultra-low-latency packet filtering and forwarding. This example assumes DPDK is installed and configured for your system.

---

### <language>C</language> Implementation (DPDK-based)

```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_ether.h>
#include <stdio.h>
#include <stdint.h>

#define RX_QUEUE 0
#define TX_QUEUE 0
#define BURST_SIZE 32
#define PORT 0
#define DEST_MAC "00:11:22:33:44:55"

// Simple packet filter: forward only IPv4 packets from a specific source IP
static inline int is_allowed_packet(struct rte_mbuf *pkt) {
    struct ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct ether_hdr *);
    struct ipv4_hdr *ip_hdr = (struct ipv4_hdr *)((uint8_t *)eth_hdr + sizeof(struct ether_hdr));

    // Check Ethernet type is IPv4
    if (eth_hdr->ether_type != htons(ETHER_TYPE_IPV4)) return 0;

    // Example filter: allow packets from 192.168.1.100
    if (ip_hdr->src_addr == htonl(0xC0A80164)) return 1;

    return 0;
}

void lcore_main(void) {
    uint16_t port = PORT;
    struct rte_mbuf *pkts[BURST_SIZE];
    struct ether_hdr *eth_hdr;
    uint16_t nb_rx, nb_tx;

    while (1) {
        // Poll for packets (zero-copy, no interrupts)
        nb_rx = rte_eth_rx_burst(port, RX_QUEUE, pkts, BURST_SIZE);

        for (uint16_t i = 0; i < nb_rx; i++) {
            if (!is_allowed_packet(pkts[i])) {
                rte_pktmbuf_free(pkts[i]); // Drop packet
                continue;
            }

            // Modify destination MAC (forwarding example)
            eth_hdr = rte_pktmbuf_mtod(pkts[i], struct ether_hdr *);
            ether_addr_copy((struct ether_addr *)DEST_MAC, &eth_hdr->d_addr);

            // Forward packet
        }

        // Transmit packets (batched for efficiency)
        nb_tx = rte_eth_tx_burst(port, TX_QUEUE, pkts, nb_rx);
        for (uint16_t j = 0; j < (nb_rx - nb_tx); j++)
            rte_pktmbuf_free(pkts[j]);
    }
}

int main(int argc, char *argv[]) {
    // Initialize DPDK environment
    if (rte_eal_init(argc, argv) < 0) {
        printf("Error with EAL initialization\n");
        return -1;
    }

    // Configure Ethernet device (port 0)
    uint16_t port = PORT;
    struct rte_eth_conf port_conf = {
        .rxmode = {
            .mq_mode = ETH_MQ_RX_RSS,
            .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
            .split_hdr_size = 0,
            .header_split = 0,
            .hw_ip_checksum = 0,
            .hw_vlan_filter = 0,
            .jumbo_frame = 0,
            .hw_strip_crc = 0,
        },
        .txmode = {
            .mq_mode = ETH_MQ_TX_NONE,
        },
    };

    if (rte_eth_dev_configure(port, 1, 1, &port_conf) < 0) {
        printf("Error configuring port\n");
        return -1;
    }

    // Allocate and set up RX/TX queues
    uint16_t rx_rings = 1, tx_rings = 1;
    if (rte_eth_rx_queue_setup(port, RX_QUEUE, BURST_SIZE, RTE_ETH_DEV_ANY_RX_QUEUE, NULL, NULL) < 0 ||
        rte_eth_tx_queue_setup(port, TX_QUEUE, BURST_SIZE, RTE_ETH_DEV_ANY_TX_QUEUE, NULL) < 0) {
        printf("Error setting up queues\n");
        return -1;
    }

    // Start the port
    if (rte_eth_dev_start(port) < 0) {
        printf("Error starting port\n");
        return -1;
    }

    // Launch the packet processing loop on the main lcore
    rte_eal_remote_launch(lcore_main, NULL, 0);

    // Wait for termination (simplified for example)
    while (1) rte_eal_wait_lcore(0);

    return 0;
}
