### 📦 **Code: `low_latency_forwarder.c`**
```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_mempool.h>
#include <rte_cycles.h>
#include <rte_lcore.h>
#include <netinet/ether.h>
#include <netinet/ip.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8192
#define MBUF_CACHE_SIZE 256
#define BURST_SIZE 32

// Simple filter: forward only packets from a specific source IP
#define TARGET_SRC_IP 0xC0A80101 // 192.168.1.1

// Memory pool for packet buffers
static struct rte_mempool *mbuf_pool;

// Port configuration
static const struct rte_eth_conf port_conf_default = {
    .rxmode = {
        .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
        .split_hdr_size = 0,
        .header_split   = 0,
        .hw_ip_checksum = 1,
        .hw_vlan_filter = 0,
        .jumbo_frame    = 0,
        .hw_strip_crc   = 1,
    },
};

// Packet filtering logic
static inline int should_forward(struct rte_mbuf *pkt) {
    struct ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct ether_hdr *);
    if (eth_hdr->ether_type != htons(ETHER_TYPE_IPv4)) return 0;

    struct ipv4_hdr *ip_hdr = (struct ipv4_hdr *)((uint8_t *)eth_hdr + sizeof(struct ether_hdr));
    if (ip_hdr->src_addr == TARGET_SRC_IP) {
        return 1; // Forward
    }
    return 0; // Drop
}

// Main packet processing loop
static void lcore_main(uint16_t port_id) {
    uint16_t rx_port = port_id;
    uint16_t tx_port = (port_id + 1) % RTE_MAX_ETHPORTS; // Example: forward to adjacent port

    struct rte_mbuf *pkts[BURST_SIZE];
    uint16_t nb_rx, nb_tx;

    while (1) {
        nb_rx = rte_eth_rx_burst(rx_port, 0, pkts, BURST_SIZE);

        for (uint16_t i = 0; i < nb_rx; i++) {
            if (!should_forward(pkts[i])) {
                rte_pktmbuf_free(pkts[i]); // Drop packet
            } else {
                // Prepend VLAN tag or modify headers if needed (optional)
                // ...
            }
        }

        nb_tx = rte_eth_tx_burst(tx_port, 0, pkts, nb_rx);
        for (uint16_t i = nb_tx; i < nb_rx; i++) {
            rte_pktmbuf_free(pkts[i]); // Free untransmitted packets
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize DPDK EAL
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error initializing EAL\n");

    // Create memory pool
    mbuf_pool = rte_mempool_create("MBUF_POOL", NUM_MBUFS, RTE_MBUF_DEFAULT_BUF_SIZE,
                                   MBUF_CACHE_SIZE, 0, NULL, NULL, NULL, NULL, 0, RTE_MEMPOOL_F_SP_PUT | RTE_MEMPOOL_F_SC_GET);
    if (!mbuf_pool) rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Configure ports
    uint16_t port_id;
    for (port_id = 0; port_id < RTE_MAX_ETHPORTS; port_id++) {
        if (rte_eth_dev_is_valid_port(port_id)) {
            struct rte_eth_dev_info dev_info;
            rte_eth_dev_info_get(port_id, &dev_info);
            rte_eth_conf port_conf = port_conf_default;

            if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) != 0)
                rte_exit(EXIT_FAILURE, "Failed to configure port %u\n", port_id);

            rte_eth_txconf tx_conf = dev_info.default_txconf;
            rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), &tx_conf);
            rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, mbuf_pool);

            rte_eth_dev_start(port_id);
            rte_eth_promiscuous_enable(port_id);
        }
    }

    // Launch per-lcore processing
    RTE_LCORE_FOREACH_SLAVE(port_id) {
        rte_eal_remote_launch((void (*)(void *))lcore_main, (void *)(uintptr_t)port_id, port_id);
    }

    lcore_main(0); // Main lcore
    return 0;
}
```

