#include <rte_tcp.h>
#include <rte_udp.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Simple filter: forward only TCP packets on port 80
static inline int is_allowed_packet(struct rte_mbuf *pkt) {
    struct ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct ether_hdr *);
    if (eth_hdr->ether_type != htons(ETHER_TYPE_IPv4))
        return 0;

    struct ipv4_hdr *ip_hdr = (struct ipv4_hdr *)((char *)eth_hdr + sizeof(struct ether_hdr));
    if (ip_hdr->next_proto_id != IPPROTO_TCP)
        return 0;

    struct tcp_hdr *tcp_hdr = (struct tcp_hdr *)((char *)ip_hdr + (ip_hdr->version_ihl & 0x0F) * 4);
    if (ntohs(tcp_hdr->dest_port) != 80)
        return 0;

    return 1;
}

static void lcore_main(uint16_t port) {
    struct rte_mbuf *pkts[BURST_SIZE];
    struct rte_mempool *mbuf_pool = rte_mempool_lookup("MBUF_POOL");
    if (!mbuf_pool) rte_exit(EXIT_FAILURE, "Mbuf pool not found\n");

    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port, 0, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            if (is_allowed_packet(pkts[i])) {
                // Forward packet (simple mirror to same port for demo)
                rte_eth_tx_burst(port, 0, &pkts[i], 1);
            } else {
                rte_pktmbuf_free(pkts[i]);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    uint16_t port = 0; // Use first available port
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };

    // Initialize port
    ret = rte_eth_dev_configure(port, 1, 1, &port_conf);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Port configuration failed\n");

    // Configure RX/TX queues
    rte_eth_rx_queue_setup(port, 0, RX_RING_SIZE, 0, NULL, rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id()));
    rte_eth_tx_queue_setup(port, 0, TX_RING_SIZE, 0, NULL);

    // Start port
    rte_eth_dev_start(port);
    rte_eth_promiscuous_enable(port);

    // Launch per-lcore function
    rte_eal_mp_remote_launch((void *)lcore_main, (void *)port, CALL_MASTER);

    // Wait for completion (simplified for demo)
    while (1) rte_eal_wait_lcore(0);

    return 0;
}
