#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Filter configuration (e.g., allow packets with this destination MAC)
static struct ether_addr allowed_mac = {{0x00, 0x11, 0x22, 0x33, 0x44, 0x55}};

// Initialize Ethernet device
static inline int setup_port(uint16_t port) {
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    if (rte_eth_dev_configure(port, 1, 1, &port_conf) != 0) {
        rte_exit(EXIT_FAILURE, "Port %u configuration failed\n", port);
    }

    struct rte_eth_rxconf rx_conf = { .rx_drop_en = 1 };
    struct rte_eth_rxq_conf rxq_conf = { .rx_drop_en = 1 };
    if (rte_eth_rx_queue_setup(port, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port), &rxq_conf, NULL) != 0) {
        rte_exit(EXIT_FAILURE, "Port %u RX queue setup failed\n", port);
    }

    struct rte_eth_txconf tx_conf = { .txq_flags = 0 };
    if (rte_eth_tx_queue_setup(port, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port), &tx_conf) != 0) {
        rte_exit(EXIT_FAILURE, "Port %u TX queue setup failed\n", port);
    }

    if (rte_eth_dev_start(port) != 0) {
        rte_exit(EXIT_FAILURE, "Port %u start failed\n", port);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize DPDK environment
    if (rte_eal_init(argc, argv) < 0) {
        rte_exit(EXIT_FAILURE, "rte_eal_init failed\n");
    }

    uint16_t port = 0; // Assume a single port for simplicity
    if (rte_eth_dev_count_avail() < 1) {
        rte_exit(EXIT_FAILURE, "No Ethernet ports available\n");
    }

    // Setup port
    if (setup_port(port) != 0) {
        rte_exit(EXIT_FAILURE, "Port setup failed\n");
    }

    // Allocate memory for packets
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (mbuf_pool == NULL) {
        rte_exit(EXIT_FAILURE, "Mbuf pool creation failed\n");
    }

    // Main packet processing loop
    struct rte_mbuf *pkts[BURST_SIZE];
    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port, 0, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkts[i], struct rte_ether_hdr *);
            if (memcmp(&eth_hdr->d_addr, &allowed_mac, sizeof(allowed_mac)) == 0) {
                // Forward packet (e.g., to another port or mirror)
                uint16_t nb_tx = rte_eth_tx_burst(port, 0, &pkts[i], 1);
                if (nb_tx < 1) {
                    rte_pktmbuf_free(pkts[i]); // Drop packet if TX queue is full
                }
            } else {
                rte_pktmbuf_free(pkts[i]); // Drop packet if MAC doesn't match
            }
        }
    }

    return 0;
}
