#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <stdio.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Filter: Drop packets from this source IP
#define DROP_SOURCE_IP 0xC0A80101 // 192.168.1.1

static inline void process_packet(struct rte_mbuf *pkt) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);
    struct rte_ipv4_hdr *ip_hdr = (struct rte_ipv4_hdr *)((uint8_t *)eth_hdr + sizeof(struct rte_ether_hdr));

    // Skip non-IPv4 packets
    if (eth_hdr->ether_type != htons(RTE_ETHER_TYPE_IPV4)) return;

    // Filter: Drop packets from DROP_SOURCE_IP
    if (ip_hdr->src_addr == DROP_SOURCE_IP) {
        rte_pktmbuf_free(pkt);
        return;
    }

    // Forward packet (simplified: same port)
    // In a real system, you'd use TX queues and hardware offloads
    printf("[FORWARD] Packet from %d.%d.%d.%d\n",
           (ip_hdr->src_addr >> 24) & 0xFF,
           (ip_hdr->src_addr >> 16) & 0xFF,
           (ip_hdr->src_addr >> 8) & 0xFF,
           ip_hdr->src_addr & 0xFF);
}

int main(int argc, char *argv[]) {
    // Initialize the Environment Abstraction Layer (EAL)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        printf("Error with EAL initialization\n");
        return -1;
    }

    // Assume one Ethernet port (port 0)
    uint16_t port_id = 0;
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };

    // Configure the Ethernet device
    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0) {
        printf("Failed to configure port %u\n", port_id);
        return -1;
    }

    // Allocate and set up RX/TX queues
    rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, RTE_ETH_DEV_RX_OFFLOAD_NONE, NULL, NULL);
    rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, RTE_ETH_DEV_TX_OFFLOAD_NONE, NULL);

    // Start the Ethernet port
    rte_eth_dev_start(port_id);

    // Packet processing loop
    struct rte_mbuf *pkts_burst[32];
    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, pkts_burst, 32);
        for (uint16_t i = 0; i < nb_rx; i++) {
            process_packet(pkts_burst[i]);
        }
    }

    return 0;
}
