```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <sys/socket.h>

#define TARGET_SRC_IP "192.168.1.100"  // Filter packets from this IP
#define DST_INTERFACE "eth0"            // Interface to forward packets

// Forward a packet to a raw socket
void forward_packet(const u_char *packet, int len, int sock_fd, const char *dst_iface) {
    struct sockaddr_ll sa = {0};
    sa.sll_family = AF_PACKET;
    sa.sll_protocol = htons(ETH_P_IP);
    sa.sll_ifindex = if_nametoindex(dst_iface);

    if (sendto(sock_fd, packet, len, 0, (struct sockaddr *)&sa, sizeof(sa)) < 0) {
        perror("sendto");
    }
}

// Packet handler for libpcap
void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *packet) {
    static int sock_fd = -1;
    if (sock_fd == -1) {
        sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sock_fd < 0) {
            perror("socket");
            exit(EXIT_FAILURE);
        }
    }

    struct iphdr *ip = (struct iphdr *)(packet + 14); // Skip Ethernet header
    if (ip->version != 4) return;

    char src_ip[16];
    inet_ntop(AF_INET, &(ip->saddr), src_ip, sizeof(src_ip));

    if (strcmp(src_ip, TARGET_SRC_IP) == 0) {
        printf("[FORWARD] IP: %s -> %s\n", src_ip, DST_INTERFACE);
        forward_packet(packet, h->len, sock_fd, DST_INTERFACE);
    }
}

int main() {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open live capture on the default interface
    handle = pcap_open_live(DST_INTERFACE, BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
        return 1;
    }

    // Compile and apply a BPF filter (optional, adjust as needed)
    struct bpf_program fp;
    char filter_exp[] = "ip"; // Capture all IP packets
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        perror("pcap_compile");
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        perror("pcap_setfilter");
        return 1;
    }

    // Start packet capture
    printf("Listening for packets from %s on interface %s...\n", TARGET_SRC_IP, DST_INTERFACE);
    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
```

