### **C + DPDK Example**
```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <stdio.h>

#define RX_PORT 0
#define TX_PORT 1
#define BURST_SIZE 32

// Simple filter: drop packets from a specific source IP
static inline int
is_packet_allowed(struct rte_mbuf *mbuf) {
    struct ether_hdr *eth_hdr = rte_pktmbuf_mtod(mbuf, struct ether_hdr *);
    if (eth_hdr->ether_type != htons(ETHER_TYPE_IPV4))
        return 1; // Non-IP packets allowed

    struct ipv4_hdr *ip_hdr = (struct ipv4_hdr *)((uint8_t *)eth_hdr + sizeof(struct ether_hdr));
    if (ip_hdr->src_addr == 0x01020304) { // Example: drop packets from 1.2.3.4
        rte_pktmbuf_free(mbuf);
        return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    // Initialize DPDK EAL (Environment Abstraction Layer)
    if (rte_eal_init(argc, argv) < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    // Configure RX/TX ports
    uint16_t port_mask = (1 << RX_PORT) | (1 << TX_PORT);
    if (rte_eth_dev_configure(RX_PORT, 1, 1, &(struct rte_eth_conf){}) < 0)
        rte_exit(EXIT_FAILURE, "Port %u config failed\n", RX_PORT);

    // Set up RX/TX queues
    for (uint16_t port = 0; port < RTE_MAX_ETHPORTS; port++) {
        if (port_mask & (1 << port)) {
            struct rte_eth_rxconf rx_conf = {0};
            struct rte_eth_txconf tx_conf = {0};
            rte_eth_rx_queue_setup(port, 0, BURST_SIZE, rte_eth_dev_socket_id(port), &rx_conf, NULL);
            rte_eth_tx_queue_setup(port, 0, BURST_SIZE, rte_eth_dev_socket_id(port), &tx_conf);
            rte_eth_dev_start(port);
        }
    }

    // Main packet processing loop
    struct rte_mbuf *pkts[BURST_SIZE];
    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(RX_PORT, 0, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            if (is_packet_allowed(pkts[i])) {
                // Forward packet to TX_PORT
                uint16_t nb_tx = rte_eth_tx_burst(TX_PORT, 0, &pkts[i], 1);
                if (nb_tx < 1)
                    rte_pktmbuf_free(pkts[i]);
            }
        }
    }

    return 0;
}
```

