### <language>C</language> Example: Ultra-Low-Latency Packet Filter/Forwarder

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/types.h>

#define INPUT_INTERFACE "eth0"
#define OUTPUT_INTERFACE "eth1"
#define BUFFER_SIZE 65536

int main() {
    int sock_in, sock_out;
    struct ifreq ifr_in, ifr_out;
    struct sockaddr_ll sll_in, sll_out;
    char buffer[BUFFER_SIZE];
    struct ether_header *eth_hdr;
    ssize_t packet_len;

    // Create input socket for capturing packets
    sock_in = socket(PF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_in < 0) {
        perror("socket_in");
        exit(EXIT_FAILURE);
    }

    // Get input interface index
    strncpy(ifr_in.ifr_name, INPUT_INTERFACE, IFNAMSIZ);
    if (ioctl(sock_in, SIOCGIFINDEX, &ifr_in) < 0) {
        perror("ioctl_in");
        close(sock_in);
        exit(EXIT_FAILURE);
    }

    // Bind to input interface
    memset(&sll_in, 0, sizeof(sll_in));
    sll_in.sll_family = AF_PACKET;
    sll_in.sll_protocol = htons(ETH_P_ALL);
    sll_in.sll_ifindex = ifr_in.ifr_ifindex;
    if (bind(sock_in, (struct sockaddr *)&sll_in, sizeof(sll_in)) < 0) {
        perror("bind_in");
        close(sock_in);
        exit(EXIT_FAILURE);
    }

    // Create output socket for forwarding packets
    sock_out = socket(PF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_out < 0) {
        perror("socket_out");
        close(sock_in);
        exit(EXIT_FAILURE);
    }

    // Get output interface index
    strncpy(ifr_out.ifr_name, OUTPUT_INTERFACE, IFNAMSIZ);
    if (ioctl(sock_out, SIOCGIFINDEX, &ifr_out) < 0) {
        perror("ioctl_out");
        close(sock_in);
        close(sock_out);
        exit(EXIT_FAILURE);
    }

    // Set output socket to send packets via the specified interface
    memset(&sll_out, 0, sizeof(sll_out));
    sll_out.sll_family = AF_PACKET;
    sll_out.sll_protocol = htons(ETH_P_ALL);
    sll_out.sll_ifindex = ifr_out.ifr_ifindex;

    printf("Listening on %s, forwarding to %s. Filtering IPv4 (0x0800) packets.\n", INPUT_INTERFACE, OUTPUT_INTERFACE);

    while (1) {
        packet_len = recvfrom(sock_in, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (packet_len < 0) {
            perror("recvfrom");
            continue;
        }

        eth_hdr = (struct ether_header *)buffer;

        // Filter by Ethernet type (IPv4)
        if (ntohs(eth_hdr->ether_type) == ETH_P_IP) {
            if (sendto(sock_out, buffer, packet_len, 0,
                       (struct sockaddr *)&sll_out, sizeof(sll_out)) < 0) {
                perror("sendto");
            }
        }
    }

    close(sock_in);
    close(sock_out);
    return 0;
}
```

---

### Key Features:
1. **Raw Sockets**: Direct access to Ethernet frames with minimal OS overhead.
2. **Packet Filtering**: Only forwards IPv4 packets (`ether_type == ETH_P_IP`).
3. **Low-Latency Design**:
   - No unnecessary abstractions.
   - Minimal memory copying (direct buffer reuse).
   - No garbage collection or runtime overhead.

