### <language>C++</language> Example: Packet Filtering & Forwarding
```cpp
#include <iostream>
#include <cstring>
#include <cstdlib>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>

#define INTERFACE "eth0"       // Replace with your network interface
#define FILTER_IP "192.168.1.100"  // IP to filter

int main() {
    // Create raw socket
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("Socket creation failed");
        return 1;
    }

    // Bind to interface
    struct ifreq ifr;
    strcpy(ifr.ifr_name, INTERFACE);
    if (setsockopt(sock, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0) {
        perror("Binding to device failed");
        close(sock);
        return 1;
    }

    uint32_t filter_ip = inet_addr(FILTER_IP);
    char buffer[65536];  // Max Ethernet frame size

    while (true) {
        struct sockaddr_ll sll;
        socklen_t sll_len = sizeof(sll);
        ssize_t len = recvfrom(sock, buffer, sizeof(buffer), 0, (struct sockaddr*)&sll, &sll_len);
        if (len < 0) {
            perror("recvfrom failed");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr* eth = (struct ethhdr*)buffer;
        if (ntohs(eth->h_proto) != ETH_P_IP) continue;  // Skip non-IP packets

        // Parse IP header
        struct iphdr* ip = (struct iphdr*)(buffer + sizeof(struct ethhdr));
        if (ip->protocol != IPPROTO_TCP) continue;  // Skip non-TCP packets

        // Filter by source IP
        if (ip->saddr == filter_ip) {
            std::cout << "Filtered packet from " << inet_ntoa(*reinterpret_cast<in_addr*>(&ip->saddr)) << std::endl;

            // Forward packet (example: send it back)
            sendto(sock, buffer, len, 0, (struct sockaddr*)&sll, sll_len);
        }
    }

    close(sock);
    return 0;
}
```

---

### Key Features:
1. **Raw Sockets**: Direct access to network packets with minimal OS overhead.
2. **Packet Filtering**: Filters TCP packets by source IP address.
3. **Forwarding**: Resends matching packets (e.g., for mirroring or redirection).

