    // Example: Count words in line (replace with your business logic)
    std::size_t word_count = std::count(line.begin(), line.end(), ',') + 1;
    std::cout << "Line length: " << line.size() << ", Words: " << word_count << "\n";
}

class StreamingParser {
public:
    StreamingParser(const std::string& filename) : file_(filename, std::ios::binary) {
        if (!file_.is_open()) {
            throw std::runtime_error("Failed to open file");
        }
        file_.rdbuf()->pubsetbuf(buffer_.data(), buffer_.size()); // Optimize I/O buffer
    }

    void parse() {
        std::string remaining_line;

        while (file_.read(buffer_.data(), buffer_.size()) || file_.gcount() > 0) {
            std::size_t bytes_read = file_.gcount();

            // Combine remaining data from previous buffer with new data
            if (!remaining_line.empty()) {
                remaining_line.append(buffer_.data(), bytes_read);
                std::swap(remaining_line, buffer_.data());
                bytes_read += remaining_line.size();
            }

            // Process lines in current buffer
            std::size_t start = 0;
            for (std::size_t i = 0; i < bytes_read; ++i) {
                if (buffer_[i] == '\n') {
                    process_line(std::string_view(buffer_.data() + start, i - start));
                    start = i + 1;
                }
            }

            // Save any remaining data that didn't end with a newline
            if (start < bytes_read) {
                std::memcpy(buffer_.data(), buffer_.data() + start, bytes_read - start);
                remaining_line.assign(buffer_.data(), bytes_read - start);
            }
        }

        // Process any remaining data after EOF
        if (!remaining_line.empty()) {
            process_line(std::string_view(remaining_line));
        }
    }

private:
    std::ifstream file_;
    std::vector<char> buffer_ = std::vector<char>(BUFFER_SIZE + 1); // +1 for null-termination
};
