    // Memory-efficient buffer and state tracking
    std::vector<char> buffer(BUFFER_SIZE);
    std::vector<char> line_buffer(MAX_LINE_SIZE); // Reusable line buffer
    size_t buffer_pos = 0; // Start of unprocessed data
    size_t buffer_end = 0; // End of valid data in buffer

    // Pre-allocate for partial line at end of file
    std::vector<char> partial_line;

    // Read file in a streaming loop
    while (true) {
        // Refill buffer if needed
        if (buffer_pos >= buffer_end) {
            file.read(buffer.data(), buffer.size());
            if (!file) break; // End of file or error
            buffer_end = file.gcount();
            buffer_pos = 0;
        }

        // Search for newline in current buffer segment
        const char* newline = std::search(
            buffer.data() + buffer_pos,
            buffer.data() + buffer_end,
            "\n", "\n" + 1
        );

        if (newline != buffer.data() + buffer_end) {
            // Line found: copy to line buffer and process
            size_t line_length = newline - (buffer.data() + buffer_pos);
            if (line_length >= MAX_LINE_SIZE) {
                std::cerr << "Line too long, increase MAX_LINE_SIZE\n";
                return 1;
