            std::memcpy(line_buffer.data(), buffer.data() + buffer_pos, line_length);
            process_line(line_buffer.data(), line_length);
            buffer_pos += line_length + 1; // Skip newline
        } else {
            // No newline: shift unprocessed data to front and continue
            if (buffer_pos > 0) {
                std::memmove(buffer.data(), buffer.data() + buffer_pos, buffer_end - buffer_pos);
                buffer_end -= buffer_pos;
                buffer_pos = 0;
            } else {
                // No progress: move to next chunk
                buffer_pos = buffer_end;
            }
        }
    }

    // Handle any remaining partial line at EOF
    if (buffer_pos < buffer_end) {
        size_t remaining = buffer_end - buffer_pos;
        partial_line.resize(remaining);
        std::memcpy(partial_line.data(), buffer.data() + buffer_pos, remaining);
        process_line(partial_line.data(), remaining);
    }

    return 0;
}
