        std::cerr << "Usage: " << argv[0] << " <file>\n";
        return 1;
    }

    std::ifstream file(argv[1], std::ios::binary);
    if (!file) {
        std::cerr << "Error opening file\n";
        return 1;
    }

    std::vector<char> buffer(BUFFER_SIZE);
    size_t current_pos = 0; // Start of unprocessed data
    size_t end_pos = 0;     // End of processed data

    while (true) {
        // If there's no more data in the buffer, read more
        if (current_pos >= end_pos) {
            file.read(buffer.data(), buffer.size());
            if (file.gcount() == 0) break; // End of file
            end_pos = current_pos + file.gcount();
        }

        // Search for newline in the buffer from current_pos to end_pos
        char* newline_pos = reinterpret_cast<char*>(memchr(&buffer[current_pos], '\n', end_pos - current_pos));
        if (newline_pos != nullptr) {
            size_t line_end = newline_pos - &buffer[0];
            process_line(&buffer[current_pos], line_end - current_pos);
            current_pos = line_end + 1; // Move past the newline
        } else {
            // No newline found, shift remaining data to the start of the buffer
            if (current_pos > 0) {
                std::memmove(buffer.data(), &buffer[current_pos], end_pos - current_pos);
                end_pos -= current_pos;
                current_pos = 0;
            }
            // If still no newline, and buffer is full, then we need to handle partial line
            // But since we can't read more, this is the end of the file
            break;
        }
    }

    // Handle any remaining data in the buffer (last line without newline)
    if (current_pos < end_pos) {
        process_line(&buffer[current_pos], end_pos - current_pos);
    }

    return 0;
}

