### **Code: C++ Streaming Data Parser (Minimal Memory Overhead)**
```cpp
#include <fstream>
#include <iostream>
#include <vector>
#include <string>

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <filename>" << std::endl;
        return 1;
    }

    const std::string filename = argv[1];
    std::ifstream file(filename, std::ios::binary | std::ios::ate);
    if (!file) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return 1;
    }

    const size_t buffer_size = 1024 * 1024; // 1 MB chunk size
    std::vector<char> buffer(buffer_size);
    size_t total_lines = 0;
    std::ios::pos_type file_size = file.tellg();
    file.seekg(0, std::ios::beg);

    // Process file in chunks
    while (file.tellg() < file_size) {
        file.read(buffer.data(), buffer_size);
        size_t bytes_read = file.gcount();

        // Count lines in current buffer
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                ++total_lines;
            }
        }
    }

    std::cout << "Total lines processed: " << total_lines << std::endl;
    return 0;
}
```

---

