Here's a memory-efficient C implementation of a log rotation daemon with strict memory limits. The code avoids dynamic memory allocation (except for necessary file paths) and uses minimal system resources:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

#define LOG_FILE "/var/log/myapp.log"
#define MAX_LOG_SIZE (1024 * 1024)  // 1MB
#define MAX_BACKUPS 5
#define EVENT_SIZE  (sizeof(struct inotify_event))
#define BUF_LEN     (1024 * (EVENT_SIZE + 16))

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
    }
}

void rotate_logs() {
    struct stat st;
    if (stat(LOG_FILE, &st) < 0) return;

    // Create backup names in reverse order to avoid overwriting
    for (int i = MAX_BACKUPS; i > 0; i--) {
        char *src = NULL;
        char *dst = NULL;

        if (asprintf(&src, "%s", LOG_FILE) == -1) return;
        if (asprintf(&dst, "%s.%d", LOG_FILE, i) == -1) {
            free(src);
            return;
        }

        if (access(dst, F_OK) == 0) {
            if (rename(dst, dst + 1) < 0 && errno != ENOENT) {
                perror("Failed to rotate backup");
            }
        }

        if (rename(LOG_FILE, dst) < 0 && errno != ENOENT) {
            perror("Failed to rotate log");
        }

        free(src);
        free(dst);
    }

    // Truncate original log file
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd >= 0) close(fd);
}

int main() {
    // Daemonize
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);
    chdir("/");

    // Redirect stdin/stdout/stderr
    int devnull = open("/dev/null", O_RDWR);
    for (int i = 0; i < 3; i++) {
        if (i != devnull) {
            dup2(devnull, i);
        }
    }
    if (devnull > 2) close(devnull);

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initial rotation check
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > MAX_LOG_SIZE) {
        rotate_logs();
    }

    // Watch for log file changes
    int fd = inotify_init();
    if (fd < 0) {
        perror("Failed to initialize inotify");
        exit(EXIT_FAILURE);
    }

    int wd = inotify_add_watch(fd, LOG_FILE, IN_MODIFY | IN_ATTRIB);
    if (wd < 0) {
        perror("Failed to add inotify watch");
        close(fd);
        exit(EXIT_FAILURE);
    }

    char buffer[BUF_LEN];
    while (running) {
        ssize_t len = read(fd, buffer, BUF_LEN);
        if (len < 0 && errno != EAGAIN) continue;

        struct inotify_event *event;
        for (char *ptr = buffer; ptr < buffer + len; ptr += EVENT_SIZE + event->len) {
            event = (struct inotify_event *)ptr;
            if (event->mask & (IN_MODIFY | IN_ATTRIB)) {
                if (stat(LOG_FILE, &st) == 0 && st.st_size > MAX_LOG_SIZE) {
                    rotate_logs();
                }
            }
        }

        // Fallback check every 60 seconds
        sleep(60);
    }

    inotify_rm_watch(fd, wd);
    close(fd);
    return 0;
}
```

