#include <errno.h>
#include <time.h>

#define LOG_PATH "/var/log/myapp.log"
#define MAX_LOG_SIZE (1024 * 1024)  // 1 MiB
#define MAX_BACKUPS 5
#define CHECK_INTERVAL 60  // seconds

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        running = 0;
    }
}

void rotate_logs() {
    char oldpath[256], newpath[256];
    struct stat st;

    if (stat(LOG_PATH, &st) < 0) return;

    if (st.st_size < MAX_LOG_SIZE) return;

    // Shift existing backups
    for (int i = MAX_BACKUPS - 1; i >= 0; i--) {
        snprintf(oldpath, sizeof(oldpath), "%s.%d", LOG_PATH, i);
        if (access(oldpath, F_OK) < 0) continue;

        snprintf(newpath, sizeof(newpath), "%s.%d", LOG_PATH, i + 1);
        rename(oldpath, newpath);
    }

    // Rename current log
    rename(LOG_PATH, LOG_PATH ".0");

    // Truncate new log
    int fd = open(LOG_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd >= 0) close(fd);
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    umask(0);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main() {
    daemonize();

    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    while (running) {
        rotate_logs();
        sleep(CHECK_INTERVAL);
    }

    return 0;
}
