#define MAX_BUFFER 4096

volatile sig_atomic_t rotate_flag = 0;

void handle_signal(int sig) {
    if (sig == SIGHUP) {
        rotate_flag = 1;
    }
}

void rotate_log() {
    if (rename(LOG_PATH, ROTATED_LOG_PATH) == -1) {
        perror("Failed to rotate log");
    }
}

void check_log_size() {
    struct stat st;
    if (stat(LOG_PATH, &st) == -1) {
        return; // File doesn't exist or error
    }
    if (st.st_size > MAX_LOG_SIZE) {
        rotate_log();
    }
}

int main() {
    // Fork and daemonize
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGHUP, &sa, NULL);

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Main loop
    while (1) {
        if (rotate_flag || access(LOG_PATH, F_OK) != -1) {
            check_log_size();
            rotate_flag = 0;
        }
        sleep(CHECK_INTERVAL);
    }

    return 0;
