#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>

#define LOG_PATH "/var/log/myapp.log"
#define MAX_SIZE (1024 * 1024)  // 1MB
#define MAX_BACKUPS 5
#define CHECK_INTERVAL 5  // seconds

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    umask(0);

    for (int x = sysconf(_SC_OPEN_MAX); x > 0; x--)
        close(x);
}

void rotate_logs() {
    struct stat st;
    if (stat(LOG_PATH, &st) != 0) return;

    if (st.st_size > MAX_SIZE) {
        char oldpath[256], newpath[256];

        for (int i = MAX_BACKUPS; i > 0; i--) {
            snprintf(oldpath, sizeof(oldpath), "%s.%d", LOG_PATH, i);
            snprintf(newpath, sizeof(newpath), "%s.%d", LOG_PATH, i+1);

            if (access(oldpath, F_OK) == 0) {
                rename(oldpath, newpath);
            }
        }

        rename(LOG_PATH, LOG_PATH ".1");

        // Truncate new log file
        int fd = open(LOG_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd >= 0) close(fd);
    }
}

void handle_signal(int sig) {
    if (sig == SIGTERM) {
        exit(EXIT_SUCCESS);
    }
}

int main() {
    daemonize();

    signal(SIGTERM, handle_signal);

    while (1) {
        rotate_logs();
        sleep(CHECK_INTERVAL);
    }

    return 0;
}
