    pid = getpid();
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

// Log message to file
void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t now = time(NULL);
        fprintf(fp, "[%s] %s\n", ctime(&now), msg);
        fclose(fp);
    }
}

// Get CPU usage percentage
double get_cpu_usage() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1;

    unsigned long user, nice, system, idle, iowait, irq, softirq;
    fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq);
    fclose(fp);

    unsigned long total = user + nice + system + idle + iowait + irq + softirq;
    unsigned long prev_total = total;
    sleep(1);
    fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq);
    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq;
    unsigned long total_diff = total - prev_total;
    unsigned long idle_diff = (idle + iowait) - ((idle + iowait) - (total - prev_total));

    return 100.0 * (total_diff - idle_diff) / total_diff;
}

// Get memory usage percentage
double get_memory_usage() {
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) < 0) return -1;
    return 100.0 * (mem_info.totalram - mem_info.freeram) / mem_info.totalram;
}

// Get disk usage (root partition)
double get_disk_usage() {
    struct statvfs fs;
    if (statvfs("/", &fs) < 0) return -1;
    return 100.0 * (fs.f_blocks - fs.f_bfree) / fs.f_blocks;
}

// Get network usage (RX/TX in KB)
void get_network_usage(unsigned long *rx, unsigned long *tx) {
    FILE *fp = fopen("/proc/net/dev", "r");
    if (!fp) return;

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%*s: %lu %*d %*d %*d %*d %*d %*d %*d %lu", rx, tx) == 2) break;
    }
    fclose(fp);
}

// Placeholder for resource management actions
void manage_resources() {
    double mem_usage = get_memory_usage();
    if (mem_usage > MEM_THRESHOLD) {
        log_message("Memory usage above threshold. Initiating cleanup.");
        // Example: Kill processes with high memory usage (requires root privileges)
        // system("kill -9 $(ps -eo pid,%%mem --sort -%%mem | awk 'NR==2{print $1}')");
    }

    double cpu_usage = get_cpu_usage();
    if (cpu_usage > CPU_THRESHOLD) {
        log_message("CPU usage above threshold. Initiating throttling.");
        // Example: Throttle CPU-intensive processes
        // system("cpulimit -p <PID> -l 80");
    }
}

// Signal handler
void handle_signal(int sig) {
    if (sig == SIGHUP) {
        log_message("Received SIGHUP. Reloading configuration.");
    } else {
        log_message("Shutting down daemon.");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    daemonize();

    signal(SIGHUP, handle_signal);
    signal(SIGTERM, handle_signal);

    log_message("Daemon started.");

    while (1) {
        manage_resources();

        char log_entry[512];
        double cpu = get_cpu_usage();
        double mem = get_memory_usage();
        double disk = get_disk_usage();
        unsigned long rx, tx;
        get_network_usage(&rx, &tx);

        snprintf(log_entry, sizeof(log_entry),
                 "CPU: %.2f%% | MEM: %.2f%% | DISK: %.2f%% | RX: %lu KB | TX: %lu KB",
                 cpu, mem, disk, rx, tx);
        log_message(log_entry);

        sleep(INTERVAL);
    }

    return 0;
}
