use std::time::{Duration, Instant};
use std::sync::mpsc;
use sysinfo::{System, SystemExt, CpuExt, DiskExt, NetworkExt};
use tokio::time::sleep;
use signal_hook::consts::signal::*;
use signal_hook_tokio::handle_signal;
use log::{info, error, warn};
use env_logger;

// Configuration thresholds
const CPU_THRESHOLD: f32 = 90.0; // Percent
const MEMORY_THRESHOLD: f32 = 80.0; // Percent
const DISK_THRESHOLD: f32 = 90.0; // Percent

#[tokio::main]
async fn main() {
    env_logger::init();
    info!("System Resource Daemon started");

    let (tx, rx) = mpsc::channel();

    // Handle termination signals
    let signal_task = tokio::spawn(async move {
        let mut sigterm = handle_signal(SIGTERM);
        let mut sigint = handle_signal(SIGINT);
        loop {
            tokio::select! {
                _ = sigterm.recv() => {
                    info!("Received SIGTERM, shutting down...");
                    tx.send(()).unwrap();
                    break;
                },
                _ = sigint.recv() => {
                    info!("Received SIGINT, shutting down...");
                    tx.send(()).unwrap();
                    break;
                },
            }
        }
    });

    // Main monitoring loop
    let monitor_task = tokio::spawn(async move {
        let mut sys = System::new_all();
        let mut last_update = Instant::now();

        loop {
            sys.refresh_all();

            // CPU Monitoring
            let total_cpu_usage = sys.global_cpu_info().cpu_usage();
            if total_cpu_usage > CPU_THRESHOLD {
                warn!("CPU usage exceeds threshold: {:.1}%", total_cpu_usage);
                // Example action: throttle CPU-intensive processes
                throttle_cpu_processes();
            }

            // Memory Monitoring
            let used_memory = sys.used_memory() as f64 / 1024.0 / 1024.0 / 1024.0; // GB
            let total_memory = sys.total_memory() as f64 / 1024.0 / 1024.0 / 1024.0; // GB
            let memory_usage = (used_memory / total_memory) * 100.0;
            if memory_usage > MEMORY_THRESHOLD {
                warn!("Memory usage exceeds threshold: {:.1}%", memory_usage);
                // Example action: free memory
                free_memory();
            }

            // Disk Monitoring
            for disk in sys.disks() {
                let disk_usage = (disk.available_space() as f64 / disk.total_space() as f64) * 100.0;
                if disk_usage < DISK_THRESHOLD {
                    warn!("Disk usage exceeds threshold on {}: {:.1}%", disk.name().display(), disk_usage);
                    // Example action: clean up disk
                    clean_disk(disk.name());
                }
            }

            // Network Monitoring (example)
            let network = sys.networks();
            if let Some((interface, stats)) = network.iter().find(|(_, s)| s.total_received() > 100_000_000) {
                info!("High network activity on {}: {:.2} MB/s", interface, stats.total_received() as f64 / 1_000_000.0);
            }

            // Log summary every 30 seconds
            if last_update.elapsed() >= Duration::from_secs(30) {
                info!(
                    "CPU: {:.1}%, Memory: {:.1}%, Disk: {:.1}%",
                    total_cpu_usage,
                    memory_usage,
                    disk_usage
                );
                last_update = Instant::now();
            }

            // Check for shutdown signal
            if rx.try_recv().is_ok() {
                break;
            }

            // Sleep for 1 second between checks
            sleep(Duration::from_secs(1)).await;
        }
    });

    // Wait for tasks to complete
    let _ = tokio::join!(monitor_task, signal_task);
    info!("System Resource Daemon stopped");
}

