#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <dirent.h>
#include <errno.h>
#include <time.h>
#include <sys/sysinfo.h>

#define CPU_THRESHOLD 90    // % CPU usage threshold
#define MEM_THRESHOLD 90    // % Memory usage threshold
#define CHECK_INTERVAL 5    // seconds

volatile sig_atomic_t running = 1;

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGHUP) {
        running = 0;
        printf("Daemon shutting down...\n");
    }
}

// Read CPU usage from /proc/stat
double get_cpu_usage() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return 0.0;

    unsigned long user, nice, system, idle, iowait, irq, softirq, steal;
    fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
    fclose(fp);

    unsigned long total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long prev_total = 0, prev_idle = 0;

    // Wait for next sample
    usleep(100000); // 100ms

    // Read again for delta
    fp = fopen("/proc/stat", "r");
    if (!fp) return 0.0;

    fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long totald = total - prev_total;
    unsigned long idled = idle - prev_idle;
    prev_total = total;
    prev_idle = idle;

    return (1.0 - ((double)idled / (double)totald)) * 100.0;
}

// Read memory usage from /proc/meminfo
double get_memory_usage() {
    FILE *fp = fopen("/proc/meminfo", "r");
    if (!fp) return 0.0;

    unsigned long long mem_total, mem_free, buffers, cached;
    fscanf(fp, "MemTotal: %llu kB\n", &mem_total);
    fscanf(fp, "MemFree: %llu kB\n", &mem_free);
    fscanf(fp, "Buffers: %llu kB\n", &buffers);
    fscanf(fp, "Cached: %llu kB\n", &cached);
    fclose(fp);

    unsigned long long used = mem_total - (mem_free + buffers + cached);
    return (double)(used * 100.0 / mem_total);
}

// Kill processes exceeding thresholds
void manage_resources() {
    double cpu_usage = get_cpu_usage();
    double mem_usage = get_memory_usage();

    if (cpu_usage > CPU_THRESHOLD) {
        printf("High CPU usage: %.2f%%\n", cpu_usage);
    }
    if (mem_usage > MEM_THRESHOLD) {
        printf("High Memory usage: %.2f%%\n", mem_usage);
    }

    // Example: Kill processes using > 90% CPU (simplified)
    DIR *dir = opendir("/proc");
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_DIR) {
            long pid = strtol(entry->d_name, NULL, 10);
            if (pid > 0) {
                char path[256];
                snprintf(path, sizeof(path), "/proc/%ld/stat", pid);
                FILE *fp = fopen(path, "r");
                if (fp) {
                    char comm[256];
                    unsigned long utime, stime;
                    fscanf(fp, "%*d %s %*c %*d %*d %*d %*d %*d %*u %*u %*u %*u %*u %lu %lu", comm, &utime, &stime);
                    fclose(fp);

                    unsigned long total_time = utime + stime;
                    // Simplified check (real-world would use delta)
                    if (total_time > 1000000) { // Arbitrary threshold
                        kill(pid, SIGKILL);
                        printf("Killed process %ld (%s)\n", pid, comm);
                    }
                }
            }
        }
    }
    closedir(dir);
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    umask(0);
    chdir("/");

    // Close file descriptors
    int x;
    for (x = sysconf(_SC_OPEN_MAX); x >= 0; x--) {
        close(x);
    }

    // Redirect stdin/stdout/stderr
    open("/dev/null", O_RDONLY);
    open("/dev/null", O_RDWR);
    open("/dev/null", O_RDWR);
}

int main() {
    daemonize();

    signal(SIGTERM, handle_signal);
    signal(SIGHUP, handle_signal);

    while (running) {
        manage_resources();
        sleep(CHECK_INTERVAL);
    }

    return 0;
}
