#define CPU_THRESHOLD 90

void log_message(const std::string& message) {
    std::ofstream log(LOG_FILE, std::ios_base::app);
    if (log.is_open()) {
        time_t now = time(nullptr);
        log << "[" << ctime(&now) << "] " << message << "\n";
        log.close();
    }
}

