    struct sysinfo info;
    if (sysinfo(&info) != 0) return;

    // Memory usage
    double mem_usage = (double)info.freeram / info.totalram * 100;
    if (mem_usage > MEMORY_THRESHOLD) {
        log_message("High memory usage. Terminating non-critical processes.");
        DIR *dir = opendir("/proc");
        if (dir) {
            struct dirent *entry;
            while ((entry = readdir(dir)) != NULL) {
                long pid = strtol(entry->d_name, NULL, 10);
                if (pid > 1000) {
                    kill(pid, SIGKILL);
                }
            }
            closedir(dir);
        }
    }

    // CPU usage
    double cpu_usage = (double)info.loads[0] * 100 / (double)sysconf(_SC_CLK_TCK);
    if (cpu_usage > CPU_THRESHOLD) {
        log_message("High CPU usage. No automated action in this example.");
    }
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(0);
    setsid();

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

void signal_handler(int sig) {
    if (sig == SIGTERM) {
        log_message("Daemon terminated.");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    daemonize();
    signal(SIGTERM, signal_handler);

    while (true) {
        manage_resources();
        sleep(10);
    }

    return 0;
}
