use std::time::{Duration, Instant};
use std::sync::atomic::{AtomicBool, Ordering};
use std::path::PathBuf;
use sysinfo::{System, SystemExt, ProcessExt, CpuExt, DiskExt, NetworkExt};
use log::{info, warn, error};
use daemonize::Daemonize;
use nix::unistd::{Pid, fork, ForkResult};
use nix::sys::signal::Signal;
use nix::sys::wait::wait;
use nix::unistd::kill;
use ctrlc::set_handler;
use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize, Serialize)]
struct Config {
    cpu_threshold: f32,           // % CPU usage threshold
    memory_threshold: u64,        // Memory usage in MB
    disk_threshold: u64,          // Disk usage in MB
    check_interval: u64,          // Seconds between checks
}

impl Default for Config {
    fn default() -> Self {
        Config {
            cpu_threshold: 90.0,
            memory_threshold: 9000,
            disk_threshold: 90000,
            check_interval: 5,
        }
    }
}

fn load_config() -> Config {
    let config_path = PathBuf::from("config.yaml");
    if config_path.exists() {
        let config_str = std::fs::read_to_string(config_path).expect("Failed to read config");
        serde_yaml::from_str(&config_str).expect("Invalid config format")
    } else {
        Config::default()
    }
}

fn check_system_resources(config: &Config) {
    let mut sys = System::new_all();
    sys.refresh_all();

    // CPU Usage Check
    let total_cpu_usage: f32 = sys.cpus().iter().map(|cpu| cpu.cpu_usage()).sum::<f32>() / sys.cpus().len() as f32;
    if total_cpu_usage > config.cpu_threshold {
        warn!("CPU usage exceeds threshold: {:.2}%", total_cpu_usage);
        manage_high_cpu_usage(&sys);
    }

    // Memory Usage Check
    let memory_usage = sys.total_memory() - sys.free_memory();
    if memory_usage > config.memory_threshold * 1024 * 1024 {
        warn!("Memory usage exceeds threshold: {:.2} MB", memory_usage as f32 / 1024.0 / 1024.0);
        manage_high_memory_usage(&sys);
    }

    // Disk Usage Check
    for disk in sys.disks() {
        let disk_usage = disk.total_space() - disk.available_space();
        if disk_usage > config.disk_threshold * 1024 * 1024 {
            warn!("Disk usage on {} exceeds threshold: {:.2} MB", disk.name().to_string_lossy(), disk_usage as f32 / 1024.0 / 1024.0);
            // Add disk-specific management logic here
        }
    }

    // Network Usage Check (basic)
    let mut net = System::new();
    net.refresh_networks();
    for (interface, data) in net.networks() {
        if data.total_received() > 100_000_000 || data.total_transmitted() > 100_000_000 {
            warn!("High network activity on interface {}: {:.2} KB received, {:.2} KB transmitted", 
                interface, data.total_received() as f32 / 1024.0, data.total_transmitted() as f32 / 1024.0);
        }
    }
}

fn manage_high_cpu_usage(sys: &System) {
    let mut high_cpu_pids = sys.processes()
        .iter()
        .filter(|(_, p)| p.cpu_usage() > 90.0)
        .map(|(pid, _)| *pid)
        .collect::<Vec<_>>();
    if !high_cpu_pids.is_empty() {
        info!("Killing high-CPU processes: {:?}", high_cpu_pids);
        for pid in high_cpu_pids {
            if let Err(e) = kill(Pid::from_raw(pid as i32), Signal::SIGKILL) {
                error!("Failed to kill PID {}: {}", pid, e);
            }
        }
    }
}

fn manage_high_memory_usage(sys: &System) {
    let mut high_memory_pids = sys.processes()
        .iter()
        .filter(|(_, p)| p.memory() > 100_000_000) // 100 MB
        .map(|(pid, _)| *pid)
        .collect::<Vec<_>>();
    if !high_memory_pids.is_empty() {
        info!("Killing high-memory processes: {:?}", high_memory_pids);
        for pid in high_memory_pids {
            if let Err(e) = kill(Pid::from_raw(pid as i32), Signal::SIGKILL) {
                error!("Failed to kill PID {}: {}", pid, e);
            }
        }
    }
}

fn daemonize() {
    let stdout = PathBuf::from("/var/log/os_monitor_daemon.log");
    let stderr = PathBuf::from("/var/log/os_monitor_daemon_error.log");
    let daemonize = Daemonize::new()
        .pid_file("/var/run/os_monitor_daemon.pid")
        .stdout(stdout)
        .stderr(stderr);
    match daemonize.start() {
        Ok(_) => info!("Daemonized successfully"),
        Err(e) => error!("Failed to daemonize: {}", e),
    }
}

fn setup_signal_handler(should_exit: &Arc<AtomicBool>) {
    set_handler(move || {
        should_exit.store(true, Ordering::SeqCst);
    }).expect("Error setting up signal handler");
}

fn main() {
    env_logger::init();

    let config = load_config();
    let should_exit = Arc::new(AtomicBool::new(false));
    setup_signal_handler(should_exit.clone());

    // Daemonize the process (comment out for testing)
