    info!("Starting OS Monitor Daemon v0.1.0");
    info!("Config: {:?}", config);

    loop {
        if should_exit.load(Ordering::SeqCst) {
            info!("Shutting down daemon...");
            break;
        }

        check_system_resources(&config);
        std::thread::sleep(Duration::from_secs(config.check_interval));
    }
}
