```rust
use sysinfo::{System, SystemExt, DiskExt, ProcessorExt};
use std::time::{Duration, Instant};
use std::sync::Arc;
use std::path::Path;
use std::fs;
use std::process::Command;
use signal_hook_async_std::Signals;
use tokio::time::interval;
use log::{info, warn, error};
use serde::{Deserialize, Serialize};
use toml;

#[derive(Debug, Deserialize, Serialize)]
struct Config {
    cpu_threshold: u8,         // % CPU usage
    memory_threshold: u8,      // % Memory usage
    disk_threshold: u8,        // % Disk usage
    check_interval: u64,       // Seconds
    log_file: String,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            cpu_threshold: 90,
            memory_threshold: 80,
            disk_threshold: 90,
            check_interval: 10,
            log_file: "os_daemon.log".to_string(),
        }
    }
}

async fn monitor_system(config: Arc<Config>) {
    let mut sys = System::new_all();
    let mut interval = interval(Duration::from_secs(config.check_interval));

    loop {
        interval.tick().await;
        sys.refresh_all();

        // CPU Monitoring
        let total_cpu_usage = sys.global_cpu_info().cpu_usage();
        if total_cpu_usage > config.cpu_threshold as f32 {
            warn!("High CPU usage: {:.2}%", total_cpu_usage);
            execute_action("CPU_OVERLOAD", config.log_file.clone());
        }

        // Memory Monitoring
        let used_memory = sys.used_memory() / 1024 / 1024; // Convert to MB
        let total_memory = sys.total_memory() / 1024 / 1024;
        let memory_usage = (used_memory as f64 / total_memory as f64) * 100.0;
        if memory_usage > config.memory_threshold as f64 {
            warn!("High memory usage: {:.2}%", memory_usage);
            execute_action("MEMORY_OVERLOAD", config.log_file.clone());
        }

        // Disk Monitoring
        for disk in sys.disks() {
            let disk_usage = disk.used() * 100 / disk.total();
            if disk_usage > config.disk_threshold {
                warn!(
                    "High disk usage on {}: {}%",
                    disk.name().to_str().unwrap(),
                    disk_usage
                );
                execute_action("DISK_OVERLOAD", config.log_file.clone());
            }
        }
    }
}

fn execute_action(action: &str, log_file: String) {
    match action {
        "CPU_OVERLOAD" => {
            // Example: Kill non-critical processes (platform-specific)
            #[cfg(target_os = "linux")]
            Command::new("kill")
                .arg("-9")
                .arg("1234") // Example PID
                .output()
                .expect("Failed to execute command");
        }
        "MEMORY_OVERLOAD" => {
            // Example: Clear cache (Linux-specific)
            #[cfg(target_os = "linux")]
            Command::new("sync")
                .output()
                .expect("Failed to execute command");
        }
        "DISK_OVERLOAD" => {
            // Example: Delete temporary files
            if let Err(e) = fs::remove_dir_all("/tmp/cache") {
                error!("Failed to clear cache: {}", e);
            }
        }
        _ => {}
    }

    // Log action
    let log_entry = format!("[{}] Action triggered: {}\n", chrono::Local::now(), action);
    if let Err(e) = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_file)
        .and_then(|mut f| f.write_all(log_entry.as_bytes()))
    {
        error!("Failed to write to log file: {}", e);
    }
}

#[tokio::main]
async fn main() {
    // Initialize logging
    env_logger::init();

    // Load config
    let config_path = "config.toml";
    let config: Config = if Path::new(config_path).exists() {
        toml::from_str(&fs::read_to_string(config_path).expect("Failed to read config")).unwrap()
    } else {
        Config::default()
    };

    info!("Starting OS Daemon with config: {:?}", config);

    // Signal handling for graceful shutdown
    let signals = Signals::new(&[signal_hook::consts::SIGINT, signal_hook::consts::SIGTERM])
        .expect("Failed to register signals");
    let signals_clone = signals.clone();
    tokio::spawn(async move {
        signals_clone.forever().await;
        info!("Received shutdown signal, exiting...");
        std::process::exit(0);
    });

    // Start monitoring
    monitor_system(Arc::new(config)).await;
}
