### **High-Performance System Daemon in C**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/sysinfo.h>
#include <sys/statvfs.h>
#include <string.h>
#include <fcntl.h>
#include <syslog.h>
#include <errno.h>

// Configuration
#define CHECK_INTERVAL 5      // Seconds
#define CPU_THRESHOLD 90.0    // Percentage
#define MEM_THRESHOLD 90.0    // Percentage
#define DISK_THRESHOLD 90.0   // Percentage
#define MONITORED_DISK "/"    // Disk to monitor

// Global flag for graceful exit
volatile sig_atomic_t running = 1;

// Signal handler
void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
    }
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits

    if (setsid() < 0) exit(EXIT_FAILURE); // Create new session

    umask(0); // Clear file mode creation mask
    chdir("/"); // Change to root directory

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

// Get CPU usage percentage (0.0 to 100.0)
double get_cpu_usage() {
    static unsigned long long prev_total = 0, prev_idle = 0;
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1.0;

    unsigned long long user, nice, system, idle, iowait, irq, softirq, total;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu", &user, &nice, &system, &idle, &iowait, &irq, &softirq) != 7) {
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    total = user + nice + system + iowait + irq + softirq;
    unsigned long long diff_total = total - prev_total;
    unsigned long long diff_idle = idle - prev_idle;

    prev_total = total;
    prev_idle = idle;

    return 100.0 * (diff_total - diff_idle) / diff_total;
}

// Get memory usage percentage (0.0 to 100.0)
double get_memory_usage() {
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) != 0) return -1.0;

    long total = mem_info.totalram - mem_info.sharedram;
    long free = mem_info.freeram + mem_info.bufferram;
    return 100.0 * (total - free) / total;
}

// Get disk usage percentage (0.0 to 100.0)
double get_disk_usage(const char *path) {
    struct statvfs vfs;
    if (statvfs(path, &vfs) != 0) return -1.0;

    uint64_t total = (uint64_t)vfs.f_blocks * vfs.f_bsize;
    uint64_t free = (uint64_t)vfs.f_bfree * vfs.f_bsize;
    return 100.0 * (total - free) / total;
}

// Log alert
void log_alert(const char *resource, double value, double threshold) {
    openlog("system_daemon", LOG_PID | LOG_CONS, LOG_DAEMON);
    syslog(LOG_ALERT, "%s usage (%.2f%%) exceeded threshold (%.2f%%)", resource, value, threshold);
    closelog();
}

int main() {
    daemonize();

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    syslog(LOG_NOTICE, "System daemon started");

    while (running) {
        double cpu_usage = get_cpu_usage();
        double mem_usage = get_memory_usage();
        double disk_usage = get_disk_usage(MONITORED_DISK);

        if (cpu_usage > CPU_THRESHOLD) log_alert("CPU", cpu_usage, CPU_THRESHOLD);
        if (mem_usage > MEM_THRESHOLD) log_alert("Memory", mem_usage, MEM_THRESHOLD);
        if (disk_usage > DISK_THRESHOLD) log_alert("Disk", disk_usage, DISK_THRESHOLD);

        sleep(CHECK_INTERVAL);
    }

    syslog(LOG_NOTICE, "System daemon stopped");
    closelog();
    return 0;
}
