            sscanf(line, "%*[^:]:%*d %lu", &metrics.network_bytes);
            break;
        }
    }
    fclose(net_file);

    return metrics;
}

// Log rotation
void rotate_log() {
    int fd = open(LOG_FILE, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd == -1) return;

    struct stat st;
    fstat(fd, &st);
    if (st.st_size > MAX_LOG_SIZE) {
        close(fd);
        rename(LOG_FILE, "/var/log/sysmonitor.log.1");
        open(LOG_FILE, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    }
    close(fd);
}

// Main daemon loop
int main() {
    // Daemonize
    if (fork() != 0) exit(0);
    setsid();
    chdir("/");
    umask(0);

    // Setup signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

