#include <dirent.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/sysinfo.h>

#define CPU_THRESHOLD 90.0  // CPU usage threshold (%)
#define MEM_THRESHOLD 80.0  // Memory usage threshold (%)
#define LOG_INTERVAL 5      // Logging interval (seconds)

volatile sig_atomic_t stop = 0;

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    stop = 1;
    printf("Received signal %d. Shutting down...\n", sig);
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);
    umask(0);
    chdir("/");

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

// Read CPU usage from /proc/stat
double get_cpu_usage() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1.0;

    unsigned long user, nice, system, idle, iowait, irq, softirq;
    fscanf(fp, "cpu %lu %lu %lu %lu %lu %lu %lu", &user, &nice, &system, &idle, &iowait, &irq, &softirq);
    fclose(fp);

    unsigned long total = user + nice + system + idle + iowait + irq + softirq;
    unsigned long prev_total = total;
    unsigned long prev_idle = idle;

    sleep(1); // Wait for next sample

    fp = fopen("/proc/stat", "r");
    if (!fp) return -1.0;

    fscanf(fp, "cpu %lu %lu %lu %lu %lu %lu %lu", &user, &nice, &system, &idle, &iowait, &irq, &softirq);
    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq;
    unsigned long totald = total - prev_total;
    unsigned long idled = idle - prev_idle;

    return (double)(totald - idled) / totald * 100.0;
}

// Read memory usage from /proc/meminfo
double get_memory_usage() {
    FILE *fp = fopen("/proc/meminfo", "r");
    if (!fp) return -1.0;

    unsigned long long mem_total, mem_free;
    fscanf(fp, "MemTotal: %llu kB\n", &mem_total);
    fscanf(fp, "MemFree: %llu kB\n", &mem_free);
    fclose(fp);

    return (double)(mem_total - mem_free) / mem_total * 100.0;
}

// Read disk I/O from /proc/diskstats
void get_disk_usage() {
    FILE *fp = fopen("/proc/diskstats", "r");
    if (!fp) return;

    char dev[32];
    unsigned long long reads, writes;
    while (fscanf(fp, "%s %*s %*s %llu %*s %*s %*s %*s %*s %*s %llu", dev, &reads, &writes) == 3) {
        if (strncmp(dev, "sd", 2) == 0 || strncmp(dev, "hd", 2) == 0) {
            printf("Disk %s: Reads=%llu, Writes=%llu\n", dev, reads, writes);
        }
    }
    fclose(fp);
}

// Kill processes exceeding memory threshold
void manage_resources() {
    struct sysinfo sys_info;
    sysinfo(&sys_info);
    double mem_usage = get_memory_usage();
    if (mem_usage > MEM_THRESHOLD) {
        printf("Memory usage %f%% exceeds threshold %f%%. Managing...\n", mem_usage, MEM_THRESHOLD);

        DIR *dir = opendir("/proc");
        if (!dir) return;

        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_DIR && isdigit(entry->d_name[0])) {
                char path[256];
                snprintf(path, sizeof(path), "/proc/%s/status", entry->d_name);

                FILE *fp = fopen(path, "r");
                if (!fp) continue;

                char line[256];
                int pid = atoi(entry->d_name);
                unsigned long vmsize = 0;

                while (fgets(line, sizeof(line), fp)) {
                    if (strncmp(line, "VmRSS:", 6) == 0) {
                        sscanf(line, "VmRSS:%llu", &vmsize);
                        break;
                    }
                }
                fclose(fp);

                if (vmsize > 0) {
                    double percent = (double)vmsize / sys_info.totalram * 100.0;
                    if (percent > MEM_THRESHOLD) {
                        printf("Killing process %s (PID %d) using %f%% memory\n", entry->d_name, pid, percent);
                        kill(pid, SIGKILL);
                    }
                }
            }
        }
        closedir(dir);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    daemonize();

    while (!stop) {
        double cpu_usage = get_cpu_usage();
        double mem_usage = get_memory_usage();

        printf("CPU Usage: %f%%\n", cpu_usage);
        printf("Memory Usage: %f%%\n", mem_usage);
        get_disk_usage();

        if (cpu_usage > CPU_THRESHOLD) {
            printf("CPU usage %f%% exceeds threshold %f%%. Throttling...\n", cpu_usage, CPU_THRESHOLD);
            // Add CPU throttling logic (e.g., nice(), cgroups)
        }

        manage_resources();

        sleep(LOG_INTERVAL);
    }

    printf("Daemon stopped.\n");
    return 0;
}
