    if (sysinfo(&sys_info) == 0) {
        snprintf(buffer, sizeof(buffer), "%.2f%% Memory Used: %luMB/%luMB",
                 (double)(sys_info.totalram - sys_info.freeram) / sys_info.totalram * 100,
