        }
        fclose(cpu_file);
    } else {
        snprintf(buffer, sizeof(buffer), "CPU Info Error");
    }
    log_message(buffer);

    // Get disk usage (root partition)
    if (statvfs("/", &disk_stat) == 0) {
        unsigned long free_blocks = (unsigned long)disk_stat.f_bfree * disk_stat.f_bsize;
        unsigned long total_blocks = (unsigned long)disk_stat.f_blocks * disk_stat.f_bsize;
        snprintf(buffer, sizeof(buffer), "%.2f%% Disk Free: %luMB/%luMB",
                 (double)free_blocks / total_blocks * 100,
                 free_blocks / (1024 * 1024), total_blocks / (1024 * 1024));
    } else {
        snprintf(buffer, sizeof(buffer), "Disk Info Error");
    }
    log_message(buffer);
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits

    if (setsid() < 0) exit(EXIT_FAILURE); // Create new session

    chdir("/"); // Change working directory

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main() {
    daemonize();

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGHUP, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        monitor_resources();
        sleep(CHECK_INTERVAL);
    }

    log_message("Daemon shutting down...");
    return 0;
