use nix::unistd::{fork, setsid, umask, ForkResult};
use nix::sys::signal::Signal::SIGTERM;
use nix::sys::log::{syslog, LOG_DAEMON, LOG_INFO};
use libc::{sysinfo, sysinfo as Sysinfo};
use std::time::Duration;
use std::thread;

fn daemonize() {
    match unsafe { fork() } {
        Ok(ForkResult::Parent { .. }) => std::process::exit(0),
        Ok(ForkResult::Child) => {
            unsafe {
                setsid().expect("Failed to setsid");
                umask(0).expect("Failed to set umask");
            }
        },
        Err(_) => std::process::exit(1),
    }
}

fn main() {
    daemonize();
    unsafe { libc::openlog(b"resmon\0".as_ptr() as *const _, 0, LOG_DAEMON as i32); }

    let mut info = Sysinfo {
        ..Default::default()
    };

    loop {
        unsafe {
            if sysinfo(&mut info as *mut _ as *mut _) == 0 {
                let mem_used = (info.totalram - info.freeram) as f64 / info.totalram as f64 * 100.0;
                syslog(LOG_INFO as i32, b"Memory usage: %.2f%%\n", mem_used as f64);
            }
        }
        thread::sleep(Duration::from_secs(5));
    }
}
