```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>

// Function to log messages to /var/log/daemon.log
void log_message(const char *msg) {
    int log_fd = open("/var/log/daemon.log", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) return;

    time_t now = time(0);
    char *dt = ctime(&now);
    dt[strlen(dt) - 1] = '\0'; // Remove trailing newline

    char buffer[256];
    snprintf(buffer, sizeof(buffer), "[%s] %s\n", dt, msg);
    write(log_fd, buffer, strlen(buffer));
    close(log_fd);
}

// Function to parse and log CPU & memory usage
void monitor_resources() {
    FILE *fp;
    char line[128];

    // Parse CPU stats (Linux-specific /proc/stat)
    double user = 0, nice = 0, system = 0, idle = 0;
    fp = fopen("/proc/stat", "r");
    if (fp) {
        while (fgets(line, sizeof(line), fp)) {
            if (strncmp(line, "cpu ", 4) == 0) {
                sscanf(line, "cpu %lf %lf %lf %lf", &user, &nice, &system, &idle);
                break;
            }
        }
        fclose(fp);
    }

    // Parse memory stats (Linux-specific /proc/meminfo)
    unsigned long mem_total = 0, mem_free = 0;
    fp = fopen("/proc/meminfo", "r");
    if (fp) {
        while (fgets(line, sizeof(line), fp)) {
            if (strncmp(line, "MemTotal:", 9) == 0) {
                sscanf(line, "MemTotal: %lu", &mem_total);
            } else if (strncmp(line, "MemFree:", 8) == 0) {
                sscanf(line, "MemFree: %lu", &mem_free);
            }
        }
        fclose(fp);
    }

    char msg[256];
    snprintf(msg, sizeof(msg), "CPU: user=%.0f, nice=%.0f, system=%.0f, idle=%.0f | Mem: total=%lu KB, free=%lu KB", 
             user, nice, system, idle, mem_total, mem_free);
    log_message(msg);
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits

    if (setsid() < 0) exit(EXIT_FAILURE); // Create new session
    if (chdir("/") < 0) exit(EXIT_FAILURE); // Change to root

    // Redirect stdin, stdout, stderr to /dev/null
    int devnull = open("/dev/null", O_RDWR);
    dup2(devnull, STDIN_FILENO);
    dup2(devnull, STDOUT_FILENO);
    dup2(devnull, STDERR_FILENO);
    close(devnull);
}

int main() {
    daemonize();

    // Monitor every 5 seconds
    while (1) {
        monitor_resources();
        sleep(5);
    }

    return 0;
}
```

