        log.Fatal("Fork failed")
    }
    if pid > 0 {
        os.Exit(0)
    }
    syscall.Setsid()
    os.Chdir("/")
    syscall.Close(0)
    syscall.Close(1)
    syscall.Close(2)
}

func main() {
