Here's a minimal working example in **Go** for a system daemon that monitors CPU, memory, and disk usage. This version is designed for Linux and uses concurrency for efficient resource tracking:

```go
package main

import (
	"fmt"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
	"io/ioutil"
	"regexp"
)

func main() {
	// Daemonize (optional, for foreground testing)
	runtime.GOMAXPROCS(1) // Limit to single core for minimal resource usage

	// Start monitoring goroutines
	go monitorCPU()
	go monitorMemory()
	go monitorDisk("/")

	// Handle termination signals
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	<-sigChan
	fmt.Println("Shutting down system monitor daemon...")
}

func monitorCPU() {
	lastTotal, lastIdle uint64 = 0, 0
	for {
		cpuUsage, err := getCPUUsage(lastTotal, lastIdle)
		if err == nil {
			fmt.Printf("CPU Usage: %.2f%%\n", cpuUsage)
		}
		time.Sleep(1 * time.Second)
	}
}

func getCPUUsage(lastTotal, lastIdle uint64) (float64, error) {
	data, err := ioutil.ReadFile("/proc/stat")
	if err != nil {
		return 0, err
	}

	var user, nice, system, idle, iowait, irq, softirq uint64
	_, err = fmt.Sscanf(string(data), "cpu  %d %d %d %d %d %d %d", &user, &nice, &system, &idle, &iowait, &irq, &softirq)
	if err != nil {
		return 0, err
	}

	total := user + nice + system + idle + iowait + irq + softirq
	idleTotal := idle + iowait

	if lastTotal > 0 {
		totalDelta := total - lastTotal
		idleDelta := idleTotal - lastIdle
		if totalDelta > 0 {
			return float64(totalDelta-idleDelta) / float64(totalDelta) * 100.0, nil
		}
	}

	lastTotal, lastIdle = total, idleTotal
	return 0, nil
}

func monitorMemory() {
	for {
		memInfo, err := getMemoryInfo()
		if err == nil {
			fmt.Printf("Memory: %d%% used (%dMB/%dMB)\n", 
				(100*(memInfo.total-memInfo.free))/memInfo.total, 
				(memInfo.total-memInfo.free)/1024, 
				memInfo.total/1024)
		}
		time.Sleep(1 * time.Second)
	}
}

func getMemoryInfo() (struct{ total, free uint64 }, error) {
	data, err := ioutil.ReadFile("/proc/meminfo")
	if err != nil {
		return struct{ total, free uint64 }{}, err
	}

	var memTotal, memFree uint64
	re := regexp.MustCompile(`(MemTotal|MemFree):\s+(\d+)\s+kB`)
	matches := re.FindAllStringSubmatch(string(data), 2)
	if len(matches) < 2 {
		return struct{ total, free uint64 }{}, fmt.Errorf("invalid meminfo format")
	}

	fmt.Sscanf(matches[0][2], "%d", &memTotal)
	fmt.Sscanf(matches[1][2], "%d", &memFree)

	return struct{ total, free uint64 }{memTotal, memFree}, nil
}

func monitorDisk(path string) {
	for {
		fsStat := syscall.Statfs_t{}
		if err := syscall.Statfs(path, &fsStat); err != nil {
			fmt.Printf("Disk error: %v\n", err)
		} else {
			total := fsStat.Blocks * uint64(fsStat.Bsize)
			free := fsStat.Bfree * uint64(fsStat.Bsize)
			used := total - free
			fmt.Printf("Disk (%s): %d%% used (%dGB/%dGB)\n", 
				path, (used*100)/total, used/(1024*1024*1024), total/(1024*1024*1024))
		}
		time.Sleep(5 * time.Second)
	}
}
```

### Key Features:
