### <language>Rust</language>  
```rust
use std::time::Duration;
use sysinfo::{System, SystemExt};
use tokio::signal;
use tokio::time::interval;

#[tokio::main]
async fn main() {
    println!("Starting system monitor daemon...");
    let mut sys = System::new_all();

    // Daemonize the process (platform-specific)
    #[cfg(target_os = "linux")]
    {
        use daemonize::Daemonize;
        let daemonize = Daemonize::new()
            .pid_file("/tmp/sysmonitor.pid")
            .chdir("/tmp");
        daemonize.start().expect("Failed to daemonize");
    }

    let mut interval = interval(Duration::from_secs(5));
    loop {
        interval.tick().await;
        sys.refresh_all();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let memory = sys.total_memory() - sys.free_memory();
        let disk = sys.get_disks().iter().map(|d| d.total_space() - d.available_space()).sum::<u64>();

        println!(
            "CPU: {:.2}% | Memory: {} MB | Disk: {} MB",
            cpu_usage,
            memory / 1024 / 1024,
            disk / 1024 / 1024
        );

        // Graceful shutdown on SIGINT/SIGTERM
        tokio::spawn(async {
            if let Ok(signal) = signal::ctrl_c().await {
                if signal {
                    std::process::exit(0);
                }
            }
        });
    }
}
```

