    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    umask(0);
    chdir("/tmp");

    struct rlimit rl = {0};
    getrlimit(RLIMIT_NOFILE, &rl);
    for (int i = 0; i < (int)rl.rlim_max; ++i) close(i);
}

void log_metrics() {
    std::ofstream log("/tmp/sysmonitor.log", std::ios_base::app);
    if (!log) return;

    // Read /proc/meminfo
    std::ifstream meminfo("/proc/meminfo");
    std::string line;
    long total_mem = 0, free_mem = 0;
    while (std::getline(meminfo, line)) {
        if (line.find("MemTotal") != std::string::npos)
            total_mem = std::stol(line.substr(13, 5)) * 1024;
        if (line.find("MemFree") != std::string::npos)
            free_mem = std::stol(line.substr(12, 5)) * 1024;
    }

    // Read /proc/diskstats (simplified)
