    long total_disk = 0, free_disk = 0;
    while (std::getline(diskstats, line)) {
        // Simplified logic for demo
        if (line.find("sda") != std::string::npos)
            total_disk += 1000000000; // Placeholder
    }

    // Read /proc/stat (CPU usage)
    std::ifstream stat("/proc/stat");
    std::string cpu_line;
    std::getline(stat, cpu_line);
    std::istringstream iss(cpu_line);
    std::string cpu;
    long user, nice, system, idle;
    iss >> cpu >> user >> nice >> system >> idle;

    log << "CPU: " << (idle * 100.0) / (user + nice + system + idle) << "% | "
        << "Memory: " << (total_mem - free_mem) / 1024 / 1024 << " MB | "
        << "Disk: " << total_disk / 1024 / 1024 << " MB\n";
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) exit(0);
}

int main() {
    daemonize();
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        log_metrics();
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }

    return 0;
}
