Here's a high-performance network flow analyzer in **C** using `libpcap` for packet capture and `uthash` for efficient flow tracking. This example prioritizes low latency and throughput for gigabit-scale traffic:

```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>
#include "uthash.h"

#define MAX_PACKET_SIZE 65536
#define FLOW_TIMEOUT 30  // seconds

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
    UT_hash_handle hh;
} Flow;

Flow *flow_table = NULL;
pthread_mutex_t flow_mutex = PTHREAD_MUTEX_INITIALIZER;

void update_flow(uint32_t src_ip, uint32_t dst_ip, 
                uint16_t src_port, uint16_t dst_port, 
                uint8_t protocol, uint16_t payload_len) {
    Flow *f;
    uint32_t hash_key = (src_ip << 32) | (dst_ip << 16) | (protocol << 8) | src_port | (dst_port << 16);

    pthread_mutex_lock(&flow_mutex);
    HASH_FIND(hh, flow_table, &hash_key, sizeof(hash_key), f);

    if (!f) {
        f = (Flow *)malloc(sizeof(Flow));
        f->src_ip = src_ip;
        f->dst_ip = dst_ip;
        f->src_port = src_port;
        f->dst_port = dst_port;
        f->protocol = protocol;
        f->packets = 1;
        f->bytes = payload_len;
        f->last_seen = time(NULL);
        HASH_ADD(hh, flow_table, hash_key, sizeof(hash_key), f);
    } else {
        f->packets++;
        f->bytes += payload_len;
        f->last_seen = time(NULL);
    }
    pthread_mutex_unlock(&flow_mutex);
}

void cleanup_flows() {
    Flow *current, *tmp;
    time_t now = time(NULL);

    pthread_mutex_lock(&flow_mutex);
    HASH_ITER(hh, flow_table, current, tmp) {
        if (now - current->last_seen > FLOW_TIMEOUT) {
            HASH_DEL(flow_table, current);
            free(current);
        }
    }
    pthread_mutex_unlock(&flow_mutex);
}

void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, 
                   const u_char *packet) {
    struct ether_header *eth_header;
    struct ip *ip_header;
    struct tcphdr *tcp_header;
    struct udphdr *udp_header;
    uint32_t src_ip, dst_ip;
    uint16_t src_port, dst_port;
    uint8_t protocol;
    uint16_t payload_len;

    eth_header = (struct ether_header *)packet;

    // Check for IPv4
    if (ntohs(eth_header->ether_type) == ETHERTYPE_IP) {
        ip_header = (struct ip *)(packet + sizeof(struct ether_header));
        src_ip = ip_header->ip_src.s_addr;
        dst_ip = ip_header->ip_dst.s_addr;
        protocol = ip_header->ip_p;

        // Calculate payload length (IP total length - IP header length)
        payload_len = ntohs(ip_header->ip_len) - (ip_header->ip_hl * 4);

        if (protocol == IPPROTO_TCP) {
            tcp_header = (struct tcphdr *)((u_char *)ip_header + (ip_header->ip_hl * 4));
            src_port = ntohs(tcp_header->th_sport);
            dst_port = ntohs(tcp_header->th_dport);
        } else if (protocol == IPPROTO_UDP) {
            udp_header = (struct udphdr *)((u_char *)ip_header + (ip_header->ip_hl * 4));
            src_port = ntohs(udp_header->uh_sport);
            dst_port = ntohs(udp_header->uh_dport);
        } else {
            // Skip non-TCP/UDP traffic
            return;
        }

        update_flow(src_ip, dst_ip, src_port, dst_port, protocol, payload_len);
    }
}

void *flow_monitor(void *arg) {
    while (1) {
        cleanup_flows();
        sleep(1);
    }
}

int main(int argc, char *argv[]) {
    pcap_t *handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    struct bpf_program fp;
    char filter_exp[] = "tcp or udp";
    bpf_u_int32 mask;
    bpf_u_int32 net;
    pthread_t monitor_thread;

    if (argc != 2) {
        printf("Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    handle = pcap_open_live(argv[1], MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", argv[1], errbuf);
        return 2;
    }

    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 3;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 4;
    }

    pthread_create(&monitor_thread, NULL, flow_monitor, NULL);

    printf("Capturing packets... Press Ctrl+C to stop.\n");
    pcap_loop(handle, 0, packet_handler, NULL);

    pthread_join(monitor_thread, NULL);
    pcap_close(handle);
    return 0;
}
