        // Initialize pcap
        if (!PcapLiveDevice::getAllLiveDevices().empty()) {
            devPtr = PcapLiveDeviceList::getInstance().getPcapLiveDeviceByIp(
                PcapLiveDeviceList::getInstance().getIPv4Address(device)
            );
            if (devPtr != nullptr) {
                devPtr->open();
                devPtr->setFilter("ip");
            } else {
                throw runtime_error("Device not found");
            }
        } else {
            throw runtime_error("No devices found");
        }

        // Start statistics thread
        statsThread = thread(&FlowAnalyzer::printStats, this);
    }

    ~FlowAnalyzer() {
        isRunning = false;
        if (statsThread.joinable()) statsThread.join();
        if (devPtr != nullptr) devPtr->close();
    }

    void start() {
        while (isRunning) {
            RawPacketVec packets;
            if (devPtr->getNextPackets(packets, 100, 100)) {
                for (auto& packet : packets) {
                    processPacket(packet);
                }
            }
        }
    }

private:
    void processPacket(const RawPacket& rawPacket) {
        unique_ptr<Packet> packet(new Packet(&rawPacket, true));
        if (!packet->isParsedCorrectly()) return;

        // Extract Ethernet layer
        EthLayer* ethLayer = packet->getLayerOfType<EthLayer>();
        if (ethLayer == nullptr) return;

        // Extract IP layer
        IPv4Layer* ipLayer = packet->getLayerOfType<IPv4Layer>();
        if (ipLayer == nullptr) return;

        // Extract transport layer
        TcpLayer* tcpLayer = packet->getLayerOfType<TcpLayer>();
        UdpLayer* udpLayer = packet->getLayerOfType<UdpLayer>();

        // Build flow key
        FlowKey key;
        key.srcIP = ipLayer->getSrcIPAddress().toInt();
        key.dstIP = ipLayer->getDstIPAddress().toInt();
        key.protocol = ipLayer->getProtocol();

        if (tcpLayer) {
            key.srcPort = ntohs(tcpLayer->getSrcPort());
            key.dstPort = ntohs(tcpLayer->getDstPort());
        } else if (udpLayer) {
            key.srcPort = ntohs(udpLayer->getSrcPort());
            key.dstPort = ntohs(udpLayer->getDstPort());
        } else {
            return; // Skip other transport layers
        }

        // Update flow data
        lock_guard<mutex> lock(flowMutex);
        auto& flow = flowMap[key];
        flow.packetCount++;
        flow.byteCount += rawPacket.getTotalSize();
        flow.lastSeen = time(nullptr);
    }

    void printStats() {
        while (isRunning) {
            this_thread::sleep_for(chrono::seconds(5));

            lock_guard<mutex> lock(flowMutex);
            cout << "\n--- Flow Statistics ---\n";
            for (const auto& [key, flow] : flowMap) {
                cout << "Flow: " << inet_ntoa(*reinterpret_cast<in_addr*>(&key.srcIP)) << ":"
                     << key.srcPort << " -> " 
                     << inet_ntoa(*reinterpret_cast<in_addr*>(&key.dstIP)) << ":"
                     << key.dstPort << " (Proto: " << (int)key.protocol << ")\n"
                     << "  Packets: " << flow.packetCount << "\n"
                     << "  Bytes: " << flow.byteCount << "\n"
                     << "  Duration: " << difftime(time(nullptr), flow.firstSeen) << "s\n";
            }
            cout << "-----------------------\n";
        }
    }

    PcapLiveDevice* devPtr;
    string device;
    atomic<bool> isRunning;
    thread statsThread;
    unordered_map<FlowKey, FlowData> flowMap;
    mutex flowMutex;
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    try {
        FlowAnalyzer analyzer(argv[1]);
        analyzer.start();
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}
