### **C Implementation (libpcap-based)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <pcap.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <string.h>
#include <time.h>
#include <uthash.h>  // Hash table library

// Flow key (5-tuple)
typedef struct {
    u_int32_t src_ip;
    u_int32_t dst_ip;
    u_int16_t src_port;
    u_int16_t dst_port;
    u_int8_t protocol;
} FlowKey;

// Flow entry
typedef struct {
    FlowKey key;
    u_int64_t bytes;
    u_int64_t packets;
    time_t first_seen;
    time_t last_seen;
    UT_hash_handle hh; // For uthash
} FlowEntry;

// Global hash table
FlowEntry *flows = NULL;

// Packet handler
void process_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *packet) {
    struct ip *ip_hdr = (struct ip*)(packet + 14); // Skip Ethernet header
    struct tcphdr *tcp_hdr;
    struct udphdr *udp_hdr;
    FlowKey key = {0};
    FlowEntry *entry;

    // Extract IP and protocol
    key.src_ip = ip_hdr->ip_src.s_addr;
    key.dst_ip = ip_hdr->ip_dst.s_addr;
    key.protocol = ip_hdr->ip_p;

    // Extract ports (TCP/UDP only)
    if (key.protocol == IPPROTO_TCP) {
        tcp_hdr = (struct tcphdr*)((u_char*)ip_hdr + (ip_hdr->ip_hl * 4));
        key.src_port = ntohs(tcp_hdr->th_sport);
        key.dst_port = ntohs(tcp_hdr->th_dport);
    } else if (key.protocol == IPPROTO_UDP) {
        udp_hdr = (struct udphdr*)((u_char*)ip_hdr + (ip_hdr->ip_hl * 4));
        key.src_port = ntohs(udp_hdr->uh_sport);
        key.dst_port = ntohs(udp_hdr->uh_dport);
    } else {
        return; // Skip non-TCP/UDP
    }

    // Update flow entry
    HASH_FIND(hh, flows, &key, sizeof(FlowKey), entry);
    if (!entry) {
        entry = (FlowEntry*)malloc(sizeof(FlowEntry));
        memcpy(&entry->key, &key, sizeof(FlowKey));
        entry->bytes = h->len;
        entry->packets = 1;
        entry->first_seen = time(NULL);
        entry->last_seen = entry->first_seen;
        HASH_ADD(hh, flows, key, sizeof(FlowKey), entry);
    } else {
        entry->bytes += h->len;
        entry->packets++;
        entry->last_seen = time(NULL);
    }
}

int main(int argc, char *argv[]) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[] = "ip"; // Filter only IPv4
    bpf_u_int32 net;

    if (argc < 2) {
        printf("Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    // Open device
    handle = pcap_open_live(argv[1], BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device: %s\n", errbuf);
        return 2;
    }

    // Compile filter
    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 2;
    }

    // Apply filter
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 2;
    }

    // Capture packets
    pcap_loop(handle, 0, process_packet, NULL);

    // Print flows (example: top 10)
    printf("Top flows:\n");
    FlowEntry *s, *tmp;
    int count = 0;
    HASH_SORT(flows, bytes); // Sort by bytes (descending)
    for (s = flows; s && count < 10; s = s->hh.next) {
        printf("Flow: %u.%u.%u.%u:%u -> %u.%u.%u.%u:%u, %llu bytes, %u packets\n",
            (s->key.src_ip >> 24) & 0xFF, (s->key.src_ip >> 16) & 0xFF,
            (s->key.src_ip >> 8) & 0xFF, s->key.src_ip & 0xFF, ntohs(s->key.src_port),
            (s->key.dst_ip >> 24) & 0xFF, (s->key.dst_ip >> 16) & 0xFF,
            (s->key.dst_ip >> 8) & 0xFF, s->key.dst_ip & 0xFF, ntohs(s->key.dst_port),
            s->bytes, s->packets);
        count++;
    }

    // Cleanup
    HASH_ITER(hh, flows, s, tmp) {
        free(s);
    }
    pcap_close(handle);
    return 0;
}
