### Code (C++ with DPDK):
```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_hash.h>
#include <rte_jhash.h>
#include <rte_lcore.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <fstream>
#include <atomic>
#include <cstring>

#define MAX_PKT_BURST 32
#define FLOW_KEY_LEN 16  // 4 (src IP) + 4 (dst IP) + 2 (src port) + 2 (dst port) + 2 (protocol) + 2 (0)
#define FLOW_TABLE_SIZE (1 << 20)

struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t proto;
    uint16_t pad; // Padding for alignment
};

struct flow_data {
    uint64_t bytes;
    uint32_t packets;
    uint64_t first_seen;
    uint64_t last_seen;
};

std::atomic<bool> stop_flag{false};

// DPDK hash table for flows
struct rte_hash *flow_table = nullptr;

// File for output
std::ofstream output_file;

// Helper: Parse IPv4 packet
bool parse_ip(const struct rte_mbuf *pkt, struct flow_key *key) {
    const struct ether_hdr *eth = rte_pktmbuf_mtod(pkt, struct ether_hdr *);
    if (eth->ether_type != htons(ETHER_TYPE_IP)) return false;

    const struct ipv4_hdr *ip = reinterpret_cast<const ipv4_hdr*>(rte_pktmbuf_mtod_offset(pkt, const void*, sizeof(struct ether_hdr)));
    key->src_ip = ip->src_addr;
    key->dst_ip = ip->dst_addr;
    key->proto = ntohs(ip->next_proto_id);

    if (ip->next_proto_id == IPPROTO_TCP || ip->next_proto_id == IPPROTO_UDP) {
        const struct tcp_hdr *tcp = reinterpret_cast<const tcp_hdr*>(rte_pktmbuf_mtod_offset(pkt, const void*, sizeof(ether_hdr) + sizeof(ipv4_hdr)));
        const struct udp_hdr *udp = reinterpret_cast<const udp_hdr*>(tcp);
        if (ip->next_proto_id == IPPROTO_TCP) {
            key->src_port = ntohs(tcp->src_port);
            key->dst_port = ntohs(tcp->dst_port);
        } else {
            key->src_port = ntohs(udp->src_port);
            key->dst_port = ntohs(udp->dst_port);
        }
        return true;
    }
    return false;
}

// Worker function for each core
void process_packets(uint16_t port) {
    struct rte_mbuf *pkts_burst[MAX_PKT_BURST];
    while (!stop_flag) {
        const uint16_t nb_rx = rte_eth_rx_burst(port, 0, pkts_burst, MAX_PKT_BURST);
        for (uint16_t i = 0; i < nb_rx; ++i) {
            struct flow_key key = {0};
            if (!parse_ip(pkts_burst[i], &key)) {
                rte_pktmbuf_free(pkts_burst[i]);
                continue;
            }

            struct flow_data *data;
            void *lookup_key = &key;
            data = reinterpret_cast<flow_data*>(rte_hash_lookup_data(flow_table, lookup_key));
            if (!data) {
                data = new flow_data{0, 0, rte_rdtsc(), rte_rdtsc()};
                rte_hash_add_key_data(flow_table, lookup_key, data);
            }

            data->bytes += rte_pktmbuf_data_len(pkts_burst[i]);
            data->packets++;
            data->last_seen = rte_rdtsc();

            rte_pktmbuf_free(pkts_burst[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize DPDK
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) return -1;

    // Setup ports (example: port 0)
    const uint16_t port = 0;
    if (rte_eth_dev_count_avail() < 1) {
        std::cerr << "No Ethernet ports found!" << std::endl;
        return -1;
    }

    // Configure port
    struct rte_eth_conf port_conf = {};
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rx_adv_conf.rss_conf.rss_hf = ETH_RSS_IP;

    ret = rte_eth_dev_configure(port, 1, 1, &port_conf);
    if (ret < 0) return ret;

    // Setup RX queue
    uint16_t rx_rings = 1;
    ret = rte_eth_rx_queue_setup(port, 0, 1024, rte_eth_dev_socket_id(port), nullptr, nullptr);
    if (ret < 0) return ret;

    // Start port
    ret = rte_eth_dev_start(port);
    if (ret < 0) return ret;

    // Create flow hash table
    struct rte_hash_parameters hash_params = {
        .name = "flow_table",
        .entries = FLOW_TABLE_SIZE,
        .key_len = FLOW_KEY_LEN,
        .hash_func = rte_jhash,
        .hash_func_init_val = 0,
        .socket_id = rte_socket_id()
    };
    flow_table = rte_hash_create(&hash_params);
    if (!flow_table) return -1;

    // Launch worker threads
    rte_eal_mp_remote_launch(process_packets, reinterpret_cast<void*>(port), SKIP_MASTER);

    // Wait for user to exit
    std::cout << "Press Enter to stop..." << std::endl;
    std::cin.get();
    stop_flag = true;

    // Clean up and output flows
    output_file.open("flows.csv");
    output_file << "src_ip,dst_ip,src_port,dst_port,proto,bytes,packets\n";

    void *key;
    struct flow_data *data;
    while (rte_hash_iterate(flow_table, &key, reinterpret_cast<void**>(&data), nullptr) >= 0) {
        struct flow_key *k = reinterpret_cast<flow_key*>(key);
        output_file << k->src_ip << "," << k->dst_ip << "," << k->src_port << "," << k->dst_port << "," << k->proto << "," << data->bytes << "," << data->packets << "\n";
    }

    output_file.close();
    rte_eal_cleanup();
    return 0;
}
