### **C++ Code with DPDK**
```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_tcp.h>
#include <rte_udp.h>
#include <unordered_map>
#include <mutex>
#include <chrono>

// Flow key structure
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
struct FlowKeyHash {
    size_t operator()(const FlowKey& key) const {
        return ((size_t)key.src_ip << 32) ^ key.dst_ip ^
               ((size_t)key.src_port << 48) ^ ((size_t)key.dst_port << 16) ^
               ((size_t)key.protocol << 56);
    }
};

// Flow statistics
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t start_time = 0;
    uint64_t end_time = 0;
};

// Global flow table
std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flow_table;
std::mutex flow_mutex;

// Parse packet and extract flow key
FlowKey parse_flow(rte_mbuf* mbuf) {
    FlowKey key = {0};

    // Extract Ethernet header
    struct rte_ether_hdr* eth_hdr = rte_pktmbuf_mtod(mbuf, struct rte_ether_hdr*);

    // Skip VLAN if present
    if (RTE_ETH_IS_VLAN(eth_hdr->ether_type)) {
        struct rte_vlan_hdr* vlan_hdr = (struct rte_vlan_hdr*)((char*)eth_hdr + sizeof(struct rte_ether_hdr));
        struct rte_ipv4_hdr* ip_hdr = (struct rte_ipv4_hdr*)((char*)vlan_hdr + sizeof(struct rte_vlan_hdr));
        key.protocol = ip_hdr->next_proto_id;
    } else {
        struct rte_ipv4_hdr* ip_hdr = (struct rte_ipv4_hdr*)((char*)eth_hdr + sizeof(struct rte_ether_hdr));
        key.protocol = ip_hdr->next_proto_id;
    }

    // Extract IP addresses
    struct rte_ipv4_hdr* ip_hdr = (struct rte_ipv4_hdr*)((char*)eth_hdr + sizeof(struct rte_ether_hdr));
    key.src_ip = ip_hdr->src_addr;
    key.dst_ip = ip_hdr->dst_addr;

    // Extract TCP/UDP ports
    if (key.protocol == IPPROTO_TCP) {
        struct rte_tcp_hdr* tcp_hdr = (struct rte_tcp_hdr*)((char*)ip_hdr + (ip_hdr->version_ihl << 2));
        key.src_port = tcp_hdr->src_port;
        key.dst_port = tcp_hdr->dst_port;
    } else if (key.protocol == IPPROTO_UDP) {
        struct rte_udp_hdr* udp_hdr = (struct rte_udp_hdr*)((char*)ip_hdr + (ip_hdr->version_ihl << 2));
        key.src_port = udp_hdr->src_port;
        key.dst_port = udp_hdr->dst_port;
    }

    return key;
}

// Worker thread for packet processing
void process_packets(uint16_t port_id) {
    uint16_t nb_rx;
    struct rte_mbuf* pkts_burst[RTE_PKT_BURST_MAX_SIZE];

    while (1) {
        nb_rx = rte_eth_rx_burst(port_id, 0, pkts_burst, RTE_PKT_BURST_MAX_SIZE);

        for (uint16_t i = 0; i < nb_rx; i++) {
            FlowKey key = parse_flow(pkts_burst[i]);
            auto now = std::chrono::steady_clock::now().time_since_epoch().count();

            std::lock_guard<std::mutex> lock(flow_mutex);
            auto& stats = flow_table[key];
            stats.packets++;
            stats.bytes += rte_pktmbuf_pkt_len(pkts_burst[i]);
            stats.end_time = now;
            if (stats.start_time == 0) {
                stats.start_time = now;
            }
        }

        // Free packets
        rte_eth_tx_burst(port_id, 0, pkts_burst, nb_rx);
    }
}

int main(int argc, char* argv[]) {
    // Initialize DPDK
    if (rte_eal_init(argc, argv) < 0) {
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");
    }

    // Setup port
    uint16_t port_id = 0;
    struct rte_eth_conf port_conf = {0};
    rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(port_id, 0, 128, rte_eth_dev_socket_id(port_id), NULL, NULL);
    rte_eth_tx_queue_setup(port_id, 0, 128, rte_eth_dev_socket_id(port_id), NULL);
    rte_eth_dev_start(port_id);

    // Start worker thread
    process_packets(port_id);

    return 0;
}
