#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_cycles.h>
#include <unordered_map>
#include <mutex>
#include <tuple>
#include <cstring>
#include <arpa/inet.h>

// Flow key (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return std::tie(src_ip, dst_ip, src_port, dst_port, protocol) ==
               std::tie(other.src_ip, other.dst_ip, other.src_port, other.dst_port, other.protocol);
    }
};

// Flow data
struct Flow {
    uint64_t bytes;
    uint64_t packets;
    uint64_t first_seen;
    uint64_t last_seen;
};

// Hash specialization for FlowKey
struct FlowKeyHash {
    size_t operator()(const FlowKey& key) const {
        return (key.src_ip * 31 + key.dst_ip) * 31 +
               (key.src_port * 31 + key.dst_port) * 31 + key.protocol;
    }
};

// Global flow table
std::unordered_map<FlowKey, Flow, FlowKeyHash> flow_table;
std::mutex flow_mutex;

// DPDK port and queue configuration
#define RX_QUEUE 0
#define BURST_SIZE 32

// Packet parsing utility
void parse_packet(struct rte_mbuf* mbuf, FlowKey& key) {
    auto eth_hdr = rte_pktmbuf_mtod(mbuf, struct rte_ether_hdr*);
    auto ip_hdr = reinterpret_cast<void*>(eth_hdr + 1);
    auto ip4_hdr = reinterpret_cast<struct rte_ipv4_hdr*>(ip_hdr);
    auto ip6_hdr = reinterpret_cast<struct rte_ipv6_hdr*>(ip_hdr);
    auto tcp_udp_hdr = reinterpret_cast<void*>(ip_hdr + (ip4_hdr->version_ihl & 0x0F) * 4);

    // Ethernet type check
    if (eth_hdr->ether_type != htons(RTE_ETHER_TYPE_IPV4) &&
        eth_hdr->ether_type != htons(RTE_ETHER_TYPE_IPV6)) {
        return;
    }

    // IPv4/IPv6 parsing
    if (eth_hdr->ether_type == htons(RTE_ETHER_TYPE_IPV4)) {
        key.src_ip = ip4_hdr->src_addr;
        key.dst_ip = ip4_hdr->dst_addr;
        key.protocol = ip4_hdr->next_proto_id;
    } else {
        // IPv6 is omitted for brevity
        return;
    }

    // TCP/UDP parsing
    if (key.protocol != IPPROTO_TCP && key.protocol != IPPROTO_UDP) return;
    auto udp_hdr = reinterpret_cast<struct rte_udp_hdr*>(tcp_udp_hdr);
    key.src_port = ntohs(udp_hdr->src_port);
    key.dst_port = ntohs(udp_hdr->dst_port);
}

// Packet processing function (per lcore)
void lcore_main(uint16_t port_id) {
    struct rte_mbuf* pkts[BURST_SIZE];
    while (1) {
        uint16_t nb_pkts = rte_eth_rx_burst(port_id, RX_QUEUE, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_pkts; ++i) {
            FlowKey key{};
            parse_packet(pkts[i], key);

            std::lock_guard<std::mutex> lock(flow_mutex);
            auto& flow = flow_table[key];
            flow.bytes += rte_pktmbuf_data_len(pkts[i]);
            flow.packets++;
            flow.last_seen = rte_rdtsc();
        }
    }
}

int main(int argc, char* argv[]) {
    // DPDK initialization
    if (rte_eal_init(argc, argv) < 0) {
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");
    }

    uint16_t port_id = 0;
    if (rte_eth_dev_count_avail() < 1) {
        rte_exit(EXIT_FAILURE, "No available ports\n");
    }

    // Port configuration
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) < 0) {
        rte_exit(EXIT_FAILURE, "Port configuration failed\n");
    }

    // Start RX queue
    struct rte_mempool* mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", RTE_PKTMBUF_POOL_SIZE, 0, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (!mbuf_pool) {
        rte_exit(EXIT_FAILURE, "Mempool creation failed\n");
    }

    if (rte_eth_rx_queue_setup(port_id, RX_QUEUE, 1024, rte_eth_dev_socket_id(port_id), NULL, mbuf_pool) < 0) {
        rte_exit(EXIT_FAILURE, "RX queue setup failed\n");
    }

    if (rte_eth_dev_start(port_id) < 0) {
        rte_exit(EXIT_FAILURE, "Port start failed\n");
    }

    // Launch lcore function
    rte_eal_mp_remote_launch(lcore_main, (void*)port_id, CALL_MASTER);
    rte_eal_mp_wait_lcore();

    return 0;
}
