```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_tcp.h>
#include <rte_udp.h>
#include <unordered_map>
#include <mutex>
#include <atomic>
#include <thread>
#include <chrono>
#include <iomanip>
#include <iostream>

// Flow key (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               proto == other.proto;
    }
};

// Flow data
struct FlowData {
    uint64_t packet_count = 0;
    uint64_t byte_count = 0;
    std::chrono::steady_clock::time_point first_seen;
    std::chrono::steady_clock::time_point last_seen;
};

// Hash for FlowKey
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& k) const {
            return ((std::hash<uint32_t>()(k.src_ip) ^ 
                     (std::hash<uint32_t>()(k.dst_ip) << 1)) >> 1) ^
                   std::hash<uint16_t>()(k.src_port) ^
                   std::hash<uint16_t>()(k.dst_port) ^
                   std::hash<uint8_t>()(k.proto);
        }
    };
}

// Global flow map
std::unordered_map<FlowKey, FlowData> flow_map;
std::mutex flow_mutex;

// Packet parsing utility
void parse_packet(struct rte_mbuf* mbuf, FlowKey* key) {
    uint8_t* data = rte_pktmbuf_mtod(mbuf, uint8_t*);
    struct ether_hdr* eth = (struct ether_hdr*)data;

    // Skip non-IP packets
    if (eth->ether_type != htons(ETHER_TYPE_IPv4)) return;

    struct ipv4_hdr* ip = (struct ipv4_hdr*)(data + sizeof(struct ether_hdr));
    key->src_ip = ip->src_addr;
    key->dst_ip = ip->dst_addr;
    key->proto = ip->next_proto_id;

    // Skip non-TCP/UDP
    if (key->proto != IPPROTO_TCP && key->proto != IPPROTO_UDP) return;

    // Parse TCP/UDP
    uint16_t ip_header_len = ip->version_ihl & 0x0F;
    ip_header_len *= 4;
    struct tcp_hdr* tcp = (struct tcp_hdr*)(data + sizeof(struct ether_hdr) + ip_header_len);
    struct udp_hdr* udp = (struct udp_hdr*)(data + sizeof(struct ether_hdr) + ip_header_len);

    if (key->proto == IPPROTO_TCP) {
        key->src_port = tcp->src_port;
        key->dst_port = tcp->dst_port;
    } else if (key->proto == IPPROTO_UDP) {
        key->src_port = udp->src_port;
        key->dst_port = udp->dst_port;
    }
}

// Worker thread for packet processing
void packet_processor(uint16_t port_id) {
    const uint16_t nb_rx = 32; // Batch size
    struct rte_mbuf* pkts[nb_rx];

    while (!rte_eal_stop_request()) {
        uint16_t nb_recvd = rte_eth_rx_burst(port_id, 0, pkts, nb_rx);
        for (uint16_t i = 0; i < nb_recvd; ++i) {
            FlowKey key{};
            parse_packet(pkts[i], &key);

            if (key.proto != 0) { // Valid flow key
                auto now = std::chrono::steady_clock::now();
                std::lock_guard<std::mutex> lock(flow_mutex);
                auto& flow = flow_map[key];
                flow.packet_count++;
                flow.byte_count += rte_pktmbuf_pkt_len(pkts[i]);
                flow.last_seen = now;
                if (flow.first_seen == std::chrono::steady_clock::time_point{}) {
                    flow.first_seen = now;
                }
            }
            rte_pktmbuf_free(pkts[i]);
        }
    }
}

// Periodic flow dump
void flow_dumper() {
    while (!rte_eal_stop_request()) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        std::lock_guard<std::mutex> lock(flow_mutex);
        std::cout << "Active flows (" << flow_map.size() << "):" << std::endl;
        for (const auto& [key, data] : flow_map) {
            auto duration = std::chrono::duration_cast<std::chrono::seconds>(data.last_seen - data.first_seen).count();
            std::cout << std::hex << key.src_ip << ":" << std::dec << ntohs(key.src_port) << " -> "
                      << std::hex << key.dst_ip << ":" << std::dec << ntohs(key.dst_port) << " ("
                      << data.packet_count << " pkts, " << data.byte_count << " bytes, "
                      << duration << "s)" << std::endl;
        }
    }
}

int main(int argc, char* argv[]) {
    // Initialize DPDK
    if (rte_eal_init(argc, argv) < 0) {
        std::cerr << "Error initializing EAL" << std::endl;
        return -1;
    }

    // Configure port
    uint16_t port_id = 0;
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(port_id, 0, 1024, rte_eth_dev_socket_id(port_id), nullptr, nullptr);
    rte_eth_dev_start(port_id);

    // Launch packet processor
    rte_eal_remote_launch((rte_launch_t*)packet_processor, (void*)port_id, 0);

    // Launch flow dumper
    std::thread dumper(flow_dumper);
    dumper.detach();

    // Wait for termination
    while (!rte_eal_stop_request()) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    rte_eth_dev_stop(port_id);
    return 0;
}
