                auto udp = reinterpret_cast<struct udp_hdr*>(l4);
                src_port = udp->src_port;
                dst_port = udp->dst_port;
            } else {
                rte_pktmbuf_free(m);
                continue;
            }

            // Build flow key
            FlowKey key = {src_ip, dst_ip, src_port, dst_port, protocol};

            // Update flow statistics
            auto now = rte_get_tsc_cycles();
            auto& stats = flow_map[key];
            stats.packet_count++;
            stats.byte_count += rte_pktmbuf_data_len(m);
            stats.last_seen = now;
            if (stats.first_seen == 0) stats.first_seen = now;

            rte_pktmbuf_free(m);
        }
    }
}

int main(int argc, char* argv[]) {
    // Initialize DPDK
    if (rte_eal_init(argc, argv) < 0) {
        std::cerr << "Error initializing EAL" << std::endl;
        return -1;
    }

    uint16_t port_id = 0;
    if (rte_eth_dev_count_avail() < 1) {
        std::cerr << "No available ports" << std::endl;
        return -1;
    }

    // Configure port
    struct rte_eth_conf port_conf = {0};
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = ETHER_MAX_LEN;

    if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) < 0) {
        std::cerr << "Error configuring port" << std::endl;
        return -1;
    }

    // Start packet processing threads (one per lcore)
    std::thread workers[RTE_MAX_LCORE];
    for (int lcore = 0; lcore < RTE_MAX_LCORE; lcore++) {
        if (rte_lcore_is_enabled(lcore)) {
            workers[lcore] = std::thread(lcore_main, port_id);
        }
    }

    // Periodically merge and output flow data (simplified)
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(10));
        // Merge thread-local flow maps (simplified for example)
        static std::mutex global_mutex;
        static std::unordered_map<FlowKey, FlowStats, FlowKeyHash> global_map;
        std::lock_guard<std::mutex> lock(global_mutex);
        for (auto& [key, stats] : flow_map) {
            auto& global_stats = global_map[key];
            global_stats.packet_count += stats.packet_count;
            global_stats.byte_count += stats.byte_count;
            if (stats.first_seen < global_stats.first_seen || global_stats.first_seen == 0)
                global_stats.first_seen = stats.first_seen;
            if (stats.last_seen > global_stats.last_seen)
                global_stats.last_seen = stats.last_seen;
        }
        flow_map.clear(); // Reset thread-local map

        // Output top flows (simplified)
        std::cout << "Top flows (example output):" << std::endl;
        for (auto& [key, stats] : global_map) {
            std::cout << "Flow: " << key.src_ip << ":" << key.src_port << " -> "
                      << key.dst_ip << ":" << key.dst_port << " | "
                      << stats.packet_count << " packets, " << stats.byte_count << " bytes" << std::endl;
        }
    }

    return 0;
}
