    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

// Flow statistics
#[derive(Debug, Default)]
struct FlowStats {
    start_time: Instant,
    last_seen: Instant,
    bytes: u64,
    packets: u64,
}

// Main analyzer state
struct FlowAnalyzer {
    flows: HashMap<FlowKey, FlowStats>,
    interface: NetworkInterface,
}

impl FlowAnalyzer {
    fn new(interface: NetworkInterface) -> Self {
        FlowAnalyzer {
            flows: HashMap::new(),
            interface,
        }
    }

    fn update_flow(&mut self, key: FlowKey) {
        let now = Instant::now();
        let stats = self.flows.entry(key).or_insert_with(|| FlowStats {
            start_time: now,
            last_seen: now,
            bytes: 0,
            packets: 0,
        });

        stats.last_seen = now;
        stats.bytes += 1; // Simplified for example (actual packet size would be better)
        stats.packets += 1;
    }

    async fn flush_flows(&self) {
        // Periodic cleanup and reporting
        for (flow, stats) in &self.flows {
            println!(
                "Flow: {:?}, Duration: {:?}, Packets: {}, Bytes: {}",
                flow,
                stats.last_seen.duration_since(stats.start_time),
                stats.packets,
                stats.bytes
            );
        }
    }
}

// Packet processing pipeline
async fn process_packet(packet: &[u8], analyzer: Arc<RwLock<FlowAnalyzer>>) {
    if let Some(ethernet) = EthernetPacket::new(packet) {
        match ethernet.get_ethertype() {
            pnet::packet::ethernet::EtherType(b"IPv4") => {
                if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                    let src_ip = IpAddr::V4(ipv4.get_source());
                    let dst_ip = IpAddr::V4(ipv4.get_destination());
                    let protocol = ipv4.get_next_level_protocol() as u8;

                    match protocol {
                        6 => { // TCP
                            if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                let key = FlowKey {
                                    src_ip,
                                    dst_ip,
                                    src_port: tcp.get_source(),
                                    dst_port: tcp.get_destination(),
                                    protocol,
                                };
                                let mut analyzer = analyzer.write().await;
                                analyzer.update_flow(key);
                            }
                        }
                        17 => { // UDP
                            if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                let key = FlowKey {
                                    src_ip,
                                    dst_ip,
                                    src_port: udp.get_source(),
                                    dst_port: udp.get_destination(),
                                    protocol,
                                };
                                let mut analyzer = analyzer.write().await;
                                analyzer.update_flow(key);
                            }
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
}

#[async_std::main]
