        .find(|iface| !iface.is_loopback())
        .expect("No suitable interface found");

    let analyzer = Arc::new(RwLock::new(FlowAnalyzer::new(interface.clone())));
    let analyzer_clone = Arc::clone(&analyzer);

    // Start periodic flow flush
    task::spawn(async move {
        loop {
            task::sleep(Duration::from_secs(10)).await;
            let analyzer = analyzer_clone.read().await;
            analyzer.flush_flows().await;
        }
    });

    // Start packet capture
    let (mut tx, _) = datalink::channel(
        &interface,
        datalink::Channel::Ethernet,
    )
    .expect("Error creating datalink channel");

    loop {
        match datalink::Frame::read(&mut tx) {
            Ok(packet) => {
                let analyzer_clone = Arc::clone(&analyzer);
                task::spawn(process_packet(packet, analyzer_clone));
            }
            Err(e) => eprintln!("Error reading packet: {}", e),
        }
    }
}
