#define RX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Flow key structure (5-tuple)
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

// Simple in-memory flow table (for demo purposes)
#define FLOW_TABLE_SIZE 100000
flow_key_t flow_table[FLOW_TABLE_SIZE];
uint32_t flow_count = 0;

// Helper: Parse IPv4/TCP/UDP headers
static inline void parse_flow(const struct rte_mbuf *mbuf, flow_key_t *key) {
    struct ether_hdr *eth = rte_pktmbuf_mtod(mbuf, struct ether_hdr *);
    struct ipv4_hdr *ip = (struct ipv4_hdr *)((uint8_t *)eth + sizeof(struct ether_hdr));
    key->src_ip = ip->src_addr;
    key->dst_ip = ip->dst_addr;
    key->proto = ip->next_proto_id;

    if (key->proto == IPPROTO_TCP || key->proto == IPPROTO_UDP) {
        struct tcp_hdr *tcp = (struct tcp_hdr *)((uint8_t *)ip + sizeof(struct ipv4_hdr));
        key->src_port = tcp->src_port;
        key->dst_port = tcp->dst_port;
    } else {
        key->src_port = 0;
        key->dst_port = 0;
    }
}

// Main packet processing loop
static void lcore_main(uint16_t port_id) {
    uint16_t rx_queue = 0;
    struct rte_mbuf *bufs[BURST_SIZE];

    printf("Starting packet processing on port %u...\n", port_id);

    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port_id, rx_queue, bufs, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            flow_key_t key = {0};
            parse_flow(bufs[i], &key);

            // Simple flow tracking (for demo; real use would use a hash table)
            if (flow_count < FLOW_TABLE_SIZE) {
                memcpy(&flow_table[flow_count++], &key, sizeof(flow_key_t));
            }

            rte_pktmbuf_free(bufs[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    int ret;
    uint16_t port_id = 0;

    // Initialize DPDK
    ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "rte_eal_init failed\n");
    }

    // Configure Ethernet device
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "rte_eth_dev_configure failed\n");
    }

    // Allocate RX queue
    ret = rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, RTE_ETH_DEV_DEFAULT_OFFLOADS, NULL, rte_pktmbuf_pool_create("mbuf_pool", NUM_MBUFS, MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id()));
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "rte_eth_rx_queue_setup failed\n");
    }

    // Start port
    ret = rte_eth_dev_start(port_id);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "rte_eth_dev_start failed\n");
    }

    // Launch packet processing on this core
    lcore_main(port_id);

    return 0;
}
