### **Minimal C Flow Analyzer (libpcap-based)**
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define FLOW_TABLE_SIZE 1000003  // Prime for hashing

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} FlowKey;

typedef struct {
    FlowKey key;
    uint64_t packet_count;
    uint64_t byte_count;
} FlowEntry;

FlowEntry* flow_table[FLOW_TABLE_SIZE] = {0};

// Simple hash function
unsigned int hash_flow(const FlowKey* key) {
    return (key->src_ip ^ key->dst_ip ^ ntohs(key->src_port) ^ ntohs(key->dst_port) ^ key->proto) % FLOW_TABLE_SIZE;
}

void process_packet(u_char* user_data, const struct pcap_pkthdr* header, const u_char* packet) {
    const struct ether_header* eth = (struct ether_header*)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const struct ip* ip = (struct ip*)(packet + sizeof(struct ether_header));
    if (ip->ip_p != IPPROTO_TCP && ip->ip_p != IPPROTO_UDP) return;

    const uint32_t src_ip = ip->ip_src.s_addr;
    const uint32_t dst_ip = ip->ip_dst.s_addr;
    const uint8_t proto = ip->ip_p;

    const uint16_t src_port = 0, dst_port = 0; // Fallback for non-TCP/UDP
    if (proto == IPPROTO_TCP) {
        const struct tcphdr* tcp = (struct tcphdr*)(packet + sizeof(struct ether_header) + (ip->ip_hl << 2));
        src_port = tcp->th_sport;
        dst_port = tcp->th_dport;
    } else if (proto == IPPROTO_UDP) {
        const struct udphdr* udp = (struct udphdr*)(packet + sizeof(struct ether_header) + (ip->ip_hl << 2));
        src_port = udp->uh_sport;
        dst_port = udp->uh_dport;
    }

    FlowKey key = {src_ip, dst_ip, src_port, dst_port, proto};
    unsigned int idx = hash_flow(&key);

    FlowEntry* entry = flow_table[idx];
    if (entry && entry->key.src_ip == key.src_ip && entry->key.dst_ip == key.dst_ip &&
        entry->key.src_port == key.src_port && entry->key.dst_port == key.dst_port &&
        entry->key.proto == key.proto) {
        entry->packet_count++;
        entry->byte_count += header->len;
    } else {
        entry = (FlowEntry*)malloc(sizeof(FlowEntry));
        *entry = (FlowEntry){key, 1, header->len};
        flow_table[idx] = entry;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live(argv[1], BUFSIZ, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    printf("Capturing packets... (Ctrl+C to stop)\n");
    pcap_loop(handle, 0, process_packet, NULL);

    // Print flows (simplified for demo)
    for (int i = 0; i < FLOW_TABLE_SIZE; i++) {
        if (flow_table[i]) {
            FlowEntry* e = flow_table[i];
            char src_ip_str[INET_ADDRSTRLEN], dst_ip_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &e->key.src_ip, src_ip_str, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &e->key.dst_ip, dst_ip_str, INET_ADDRSTRLEN);
            printf("Flow: %s:%d -> %s:%d (proto %d) | Packets: %llu | Bytes: %llu\n",
                   src_ip_str, ntohs(e->key.src_port),
                   dst_ip_str, ntohs(e->key.dst_port),
                   e->key.proto, e->packet_count, e->byte_count);
            free(e);
        }
    }

    pcap_close(handle);
    return 0;
}
