        const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; i++) {
            process_packet(pkts[i]);
            rte_pktmbuf_free(pkts[i]); // Free buffer after processing
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize the Environment Abstraction Layer (EAL)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        fprintf(stderr, "Error with EAL initialization\n");
        return -1;
    }

    // Configure the Ethernet device
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    rte_eth_dev_configure(port_id, 1, 1, &port_conf);

    // Allocate and set up RX/TX queues
    rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, rte_pktmbuf_pool_create("mbuf_pool", NUM_MBUFS, MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id()));
    rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL);

    // Start the Ethernet port
    rte_eth_dev_start(port_id);
    rte_eth_promiscuous_enable(port_id);

    // Launch the packet processing thread
    rte_eal_remote_launch(lcore_main, NULL, 1);
    lcore_main(NULL); // Run on main thread for simplicity

    return 0;
}
