### **C++ Minimal Network Flow Analyzer (DPDK-based)**

```cpp
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_tcp.h>
#include <unordered_map>
#include <mutex>

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port;
    }
};

struct FlowStats {
    uint64_t packet_count = 0;
    uint64_t byte_count = 0;
};

namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& key) const {
            return (std::hash<uint32_t>()(key.src_ip) ^
                    (std::hash<uint32_t>()(key.dst_ip) << 1) ^
                    (std::hash<uint16_t>()(key.src_port) << 2) ^
                    (std::hash<uint16_t>()(key.dst_port) << 3));
        }
    };
}

std::unordered_map<FlowKey, FlowStats> flow_map;
std::mutex flow_mutex;

void process_packet(struct rte_mbuf* mbuf) {
    auto* ipv4 = rte_pktmbuf_mtod_offset(mbuf, struct rte_ipv4_hdr*, sizeof(struct rte_ether_hdr));
    if (ipv4->version_ihl != RTE_IPV4_VHL_DEF) return;

    auto* tcp = (struct rte_tcp_hdr*)((uint8_t*)ipv4 + (ipv4->hdr_len << 2));
    if (rte_be_to_cpu_16(ipv4->next_proto_id) != IPPROTO_TCP) return;

    FlowKey key = {
        .src_ip = ipv4->src_addr,
        .dst_ip = ipv4->dst_addr,
        .src_port = rte_be_to_cpu_16(tcp->src_port),
        .dst_port = rte_be_to_cpu_16(tcp->dst_port)
    };

    std::lock_guard<std::mutex> lock(flow_mutex);
    flow_map[key].packet_count++;
    flow_map[key].byte_count += rte_pktmbuf_data_len(mbuf);
}

void lcore_main() {
    uint16_t port = 0;
    uint16_t nb_rx = 0;
    struct rte_mbuf* pkts[BURST_SIZE];

    while (1) {
        nb_rx = rte_eth_rx_burst(port, 0, pkts, BURST_SIZE);
        for (uint16_t i = 0; i < nb_rx; ++i) {
            process_packet(pkts[i]);
            rte_pktmbuf_free(pkts[i]); // Free buffer after processing
        }
    }
}

int main(int argc, char* argv[]) {
    // Initialize DPDK
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "rte_eal_init failed\n");

    // Configure port
    uint16_t port = 0;
    struct rte_eth_conf port_conf = { .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN } };
    if (rte_eth_dev_configure(port, 1, 1, &port_conf) != 0) {
        rte_exit(EXIT_FAILURE, "Port %u configuration failed\n", port);
    }

    // Start the packet processing loop
    rte_eal_mp_remote_launch(lcore_main, NULL, CALL_MASTER);
    while (1) {
        // Periodically print flow stats (simplified)
        // In practice, use a separate thread or timer
        for (const auto& [key, stats] : flow_map) {
            printf("Flow %x:%d -> %x:%d | Pkts: %lu | Bytes: %lu\n",
                   key.src_ip, key.src_port, key.dst_ip, key.dst_port,
                   stats.packet_count, stats.byte_count);
        }
        sleep(5);
    }

    return 0;
}
```

