### ✅ Minimal C++ Network Flow Analyzer (libpcap-based)
```cpp
#include <iostream>
#include <pcap.h>
#include <map>
#include <thread>
#include <chrono>
#include <cstring>
#include <arpa/inet.h>  // For ntohs/ntohl

// Define a 5-tuple flow key
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash specialization for FlowKey (required for std::unordered_map)
struct FlowKeyHash {
    std::size_t operator()(const FlowKey& k) const {
        return (std::hash<uint32_t>()(k.src_ip) ^ 
                std::hash<uint32_t>()(k.dst_ip) << 1) ^ 
               std::hash<uint16_t>()(k.src_port) ^ 
               std::hash<uint16_t>()(k.dst_port) ^ 
               std::hash<uint8_t>()(k.protocol);
    }
};

// Flow statistics
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    std::chrono::steady_clock::time_point first_seen;
    std::chrono::steady_clock::time_point last_seen;
};

// Global flow map (use lock-free structures in production)
std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flow_map;
std::mutex flow_map_mutex;

// Packet handler
void packet_handler(u_char* user_data, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Parse Ethernet header
    struct ether_header* eth = (struct ether_header*)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;  // Skip non-IPv4

    // Parse IPv4 header
    struct ip* ip = (struct ip*)(packet + sizeof(struct ether_header));
    if (ip->ip_v != 4) return;  // Skip non-IPv4

    // Parse TCP/UDP port (if applicable)
    uint16_t src_port = 0, dst_port = 0;
    const u_char* transport_header = packet + sizeof(struct ether_header) + (ip->ip_hl * 4);
    if (ip->ip_p == IPPROTO_TCP) {
        struct tcphdr* tcp = (struct tcphdr*)transport_header;
        src_port = ntohs(tcp->th_sport);
        dst_port = ntohs(tcp->th_dport);
    } else if (ip->ip_p == IPPROTO_UDP) {
        struct udphdr* udp = (struct udphdr*)transport_header;
        src_port = ntohs(udp->uh_sport);
        dst_port = ntohs(udp->uh_dport);
    } else {
        return;  // Skip non-TCP/UDP
    }

    // Build flow key
    FlowKey key{
        .src_ip = ip->ip_src.s_addr,
        .dst_ip = ip->ip_dst.s_addr,
        .src_port = src_port,
        .dst_port = dst_port,
        .protocol = ip->ip_p
    };

    // Update flow stats
    std::lock_guard<std::mutex> lock(flow_map_mutex);
    auto& stats = flow_map[key];
    stats.packets++;
    stats.bytes += pkthdr->len;
    stats.last_seen = std::chrono::steady_clock::now();
    if (stats.first_seen == std::chrono::steady_clock::time_point{}) {
        stats.first_seen = stats.last_seen;
    }
}

// Periodic flow printer
void print_flows() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(10));
        std::lock_guard<std::mutex> lock(flow_map_mutex);
        std::cout << "\n--- Flow Statistics ---\n";
        for (const auto& [key, stats] : flow_map) {
            char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &key.src_ip, src_ip, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &key.dst_ip, dst_ip, INET_ADDRSTRLEN);
            auto duration = std::chrono::duration_cast<std::chrono::seconds>(stats.last_seen - stats.first_seen).count();
            std::cout << src_ip << ":" << key.src_port << " -> "
                      << dst_ip << ":" << key.dst_port << " ("
                      << (key.protocol == IPPROTO_TCP ? "TCP" : "UDP") << ")\n"
                      << "  Packets: " << stats.packets << ", Bytes: " << stats.bytes
                      << ", Duration: " << duration << "s\n";
        }
    }
}

int main(int argc, char* argv[]) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live("eth0", BUFSIZ, 1, 1000, errbuf);  // Replace with your interface
    if (!handle) {
        std::cerr << "Error opening device: " << errbuf << std::endl;
        return 1;
    }

    // Start periodic flow printer in a separate thread
    std::thread printer_thread(print_flows);

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, nullptr);

    printer_thread.join();
    pcap_close(handle);
    return 0;
}
```

