### **Example: Sensor Data Acquisition and Filtering**
```c
#include <stdint.h>
#include <stdio.h>
#include "mcu_peripherals.h"  // MCU-specific headers (e.g., ADC, UART)

// Constants
#define ADC_RESOLUTION 4096    // 12-bit ADC
#define SENSOR_PIN ADC0_CH1    // Example ADC channel
#define SAMPLE_BUFFER_SIZE 10  // Moving average window size

// Global variables
volatile uint16_t adc_raw_value = 0;
volatile float sensor_voltage = 0.0f;
volatile float filtered_value = 0.0f;
uint16_t sample_buffer[SAMPLE_BUFFER_SIZE] = {0};

// Initialize peripherals
void initialize_system() {
    // Initialize ADC
    ADC_Init(ADC_RESOLUTION, SENSOR_PIN);

    // Initialize UART for serial output
    UART_Init(115200);  // 115200 baud rate

    // Initialize buffer
    for (int i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
        sample_buffer[i] = 0;
    }
}

// Read raw ADC value from sensor
uint16_t read_sensor() {
    return ADC_Read(SENSOR_PIN);
}

// Convert ADC value to voltage (assuming 3.3V reference)
float process_sensor_data(uint16_t raw_value) {
    float voltage = (raw_value * 3.3f) / (ADC_RESOLUTION - 1);
    return voltage;
}

// Simple moving average filter
float apply_filter(float new_value) {
    static uint8_t buffer_index = 0;

    // Replace oldest sample with new value
    sample_buffer[buffer_index++] = (uint16_t)(new_value * 1000);  // Store as millivolts
    if (buffer_index >= SAMPLE_BUFFER_SIZE) buffer_index = 0;

    // Calculate average
    uint32_t sum = 0;
    for (int i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
        sum += sample_buffer[i];
    }
    return (float)sum / SAMPLE_BUFFER_SIZE / 1000.0f;  // Convert back to volts
}

// Main loop
int main(void) {
    initialize_system();

    while (1) {
        // Step 1: Read raw sensor data
        adc_raw_value = read_sensor();

        // Step 2: Convert to voltage
        sensor_voltage = process_sensor_data(adc_raw_value);

        // Step 3: Apply filter
        filtered_value = apply_filter(sensor_voltage);

        // Step 4: Output result via UART (for debugging/monitoring)
        char buffer[32];
        sprintf(buffer, "Raw: %d | Filtered: %.3f V\r\n", adc_raw_value, filtered_value);
        UART_Send(buffer, strlen(buffer));

        // Delay for sampling rate control (adjust as needed)
        for (volatile int i = 0; i < 100000; i++);  // Simple delay
    }
}
```

