};

// Simplified Kalman filter for 1D position and velocity
class KalmanFilter {
private:
    double x;     // Estimated position
    double v;     // Estimated velocity
    double P[2][2]; // Covariance matrix
    double Q;     // Process noise covariance
    double R;     // Measurement noise covariance

public:
    KalmanFilter(double initial_position, double initial_velocity) {
        x = initial_position;
        v = initial_velocity;
        P[0][0] = 1.0; P[0][1] = 0.0;
        P[1][0] = 0.0; P[1][1] = 1.0;
        Q = 0.01; // Process noise (adjust based on system dynamics)
        R = 0.1;  // Measurement noise (adjust based on sensor accuracy)
    }

    // Predict step (based on time delta dt)
    void predict(double dt) {
        double F[2][2] = {{1.0, dt}, {0.0, 1.0}}; // State transition matrix
        double new_x = F[0][0] * x + F[0][1] * v;
        double new_v = F[1][0] * x + F[1][1] * v;

        // Update covariance
        double P_pred[2][2] = {
            {P[0][0] * F[0][0] + P[0][1] * F[1][0], P[0][0] * F[0][1] + P[0][1] * F[1][1]},
            {P[1][0] * F[0][0] + P[1][1] * F[1][0], P[1][0] * F[0][1] + P[1][1] * F[1][1]}
        };
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                P[i][j] = P_pred[i][j] + Q * ((i == j) ? 1.0 : 0.0);

        x = new_x;
        v = new_v;
    }

    // Update step (with new measurement z)
    void update(double z) {
        double H[2] = {1.0, 0.0}; // Measurement matrix
        double y = z - (H[0] * x + H[1] * v);
        double S = H[0] * P[0][0] * H[0] + H[1] * P[1][1] * H[1] + R;
        double K[2];
        K[0] = P[0][0] * H[0] / S;
        K[1] = P[1][1] * H[1] / S;

        x += K[0] * y;
        v += K[1] * y;

        // Update covariance
        P[0][0] = (1.0 - K[0] * H[0]) * P[0][0];
        P[0][1] = (1.0 - K[0] * H[0]) * P[0][1];
        P[1][0] = (1.0 - K[1] * H[1]) * P[1][0];
        P[1][1] = (1.0 - K[1] * H[1]) * P[1][1];
    }

    double get_position() const { return x; }
};

// PID controller for motor output
class PIDController {
private:
    double Kp, Ki, Kd;
    double integral, previous_error;
    double dt;

public:
    PIDController(double Kp, double Ki, double Kd, double loop_dt) 
        : Kp(Kp), Ki(Ki), Kd(Kd), dt(loop_dt), integral(0.0), previous_error(0.0) {}

    double compute(double setpoint, double measured_value) {
        double error = setpoint - measured_value;
        integral += error * dt;
        double derivative = (error - previous_error) / dt;
        previous_error = error;

        return Kp * error + Ki * integral + Kd * derivative;
    }
};

