    std::pair<double, double> update(double measurement, double dt) {
        // Prediction step
        F(0, 1) = dt;
        x = F * x;
        P = F * P * F.transpose() + Q;

        // Update step
        Eigen::MatrixXd y = measurement - H * x;
        Eigen::MatrixXd S = H * P * H.transpose() + R;
        Eigen::MatrixXd K = P * H.transpose() * S.inverse();

        x = x + K * y;
        P = (Eigen::MatrixXd::Identity(2, 2) - K * H) * P;

        return {x(0), x(1)}; // [position, velocity]
    }
};

