// PID controller class
class PIDController {
public:
    PIDController(double Kp, double Ki, double Kd, double dt)
        : Kp_(Kp), Ki_(Ki), Kd_(Kd), dt_(dt) {}

    double compute(double setpoint, double measured) {
        error_ = setpoint - measured;
        integral_ += error_ * dt_;
        derivative_ = (error_ - prev_error_) / dt_;
        prev_error_ = error_;
        return Kp_ * error_ + Ki_ * integral_ + Kd_ * derivative_;
    }

private:
    double Kp_, Ki_, Kd_, dt_;
    double error_ = 0.0, integral_ = 0.0, derivative_ = 0.0, prev_error_ = 0.0;
};

// Sensor fusion using complementary filter
Eigen::Vector3d sensorFusion(const SensorData& data) {
    static const double ALPHA = 0.98;  // Filter coefficient
    static Eigen::Vector3d angle_estimate = Eigen::Vector3d::Zero();

    // Accelerometer-based angle estimation (low-frequency)
    Eigen::Vector3d accel_angle;
    if (std::abs(data.imu_accel.z()) > 0.1) {  // Avoid division by near-zero
        double tilt = std::atan2(data.imu_accel.y(), data.imu_accel.z());
        double roll = std::atan2(-data.imu_accel.x(), std::sqrt(data.imu_accel.y()*data.imu_accel.y() + data.imu_accel.z()*data.imu_accel.z()));
        accel_angle << roll, tilt, 0.0;
    }

    // Gyro-based angle estimation (high-frequency)
    Eigen::Vector3d gyro_angle = angle_estimate + data.imu_gyro * dt_;

    // Complementary filter
    angle_estimate = ALPHA * gyro_angle + (1.0 - ALPHA) * accel_angle;
    return angle_estimate;
}

// Main control loop
void controlLoop() {
    const double dt = 0.01;  // 100Hz control loop
    std::atomic<bool> running(true);

    // Initialize PID controllers for 4 motors
    PIDController pid_roll(1.2, 0.05, 0.2, dt);
    PIDController pid_pitch(1.2, 0.05, 0.2, dt);
    PIDController pid_yaw(0.8, 0.03, 0.15, dt);
