        double motor_yaw = pid_yaw.compute(setpoint_yaw, orientation.z());

        // Combine motor commands
        MotorCommand cmd;
        cmd.pwm_outputs << 
            motor_thrust + motor_roll + motor_pitch + motor_yaw,
            motor_thrust + motor_roll - motor_pitch - motor_yaw,
