// Simplified Kalman filter for sensor fusion
class KalmanFilter {
public:
    KalmanFilter(double initial_value, double process_noise, double measurement_noise, double initial_error)
        : value_(initial_value), error_(initial_error), process_noise_(process_noise), measurement_noise_(measurement_noise) {}

    double update(double measurement) {
        // Prediction step
        error_ += process_noise_;

        // Update step
        double kalman_gain = error_ / (error_ + measurement_noise_);
        value_ += kalman_gain * (measurement - value_);
        error_ = (1 - kalman_gain) * error_;

        return value_;
    }

private:
    double value_;
    double error_;
    double process_noise_;
    double measurement_noise_;
};

// Mock sensor interface
class SensorInterface {
public:
    double readIMU() {
