public:
    void setMotorPower(double power) {
        // Clamp power between -1.0 and 1.0
        power = std::max(-1.0, std::min(1.0, power));
        std::cout << "Motor power set to: " << power << std::endl;
    }
};

// Control system with real-time constraints
class RoboticsControlSystem {
public:
    RoboticsControlSystem()
        : running_(false),
          sensor_(),
          imu_filter_(0.0, 0.1, 0.5, 1.0),
          encoder_filter_(0.0, 0.05, 0.2, 1.0),
          motor_(0.0),
          target_angle_(0.0),
          target_position_(0.0),
          last_time_(std::chrono::steady_clock::now()) {}

    void start(double control_frequency) {
        running_ = true;
        control_thread_ = std::thread(&RoboticsControlSystem::controlLoop, this, control_frequency);
    }

    void stop() {
        running_ = false;
        if (control_thread_.joinable()) {
            control_thread_.join();
        }
    }

private:
    void controlLoop(double target_frequency) {
        auto control_period = std::chrono::duration<double>(1.0 / target_frequency);

        while (running_) {
            auto current_time = std::chrono::steady_clock::now();
            auto elapsed = current_time - last_time_;
            last_time_ = current_time;

            // Read raw sensor data
            double raw_imu = sensor_.readIMU();
            double raw_encoder = sensor_.readEncoder();

            // Sensor fusion with Kalman filters
            double fused_angle = imu_filter_.update(raw_imu);
            double fused_position = encoder_filter_.update(raw_encoder);

            // Calculate control outputs
            double angle_error = target_angle_ - fused_angle;
            double position_error = target_position_ - fused_position;

            // Simple proportional control for demonstration
            double motor_power = 0.5 * angle_error + 0.3 * position_error;

            // Apply motor control
            motor_.setMotorPower(motor_power);

            // Wait for next control cycle
            std::this_thread::sleep_until(current_time + control_period);
        }
    }

    std::atomic<bool> running_;
    std::thread control_thread_;
    SensorInterface sensor_;
    KalmanFilter imu_filter_;
    KalmanFilter encoder_filter_;
    MotorController motor_;
    double target_angle_;
    double target_position_;
    std::chrono::time_point<std::chrono::steady_clock> last_time_;
};

int main() {
    RoboticsControlSystem control_system;
    control_system.start(100.0); // 100 Hz control loop

    // Run for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));

    control_system.stop();
    return 0;
}
