// Kalman Filter (Simplified for demonstration)
class KalmanFilter {
private:
    double Q = 0.001; // Process noise covariance
    double R = 0.03;  // Measurement noise covariance
    double P = 1.0;   // Estimate uncertainty
    double K = 0.0;   // Kalman gain
    double x = 0.0;   // Filtered estimate

public:
    double update(double measurement) {
        P = P + Q;                            // Predict uncertainty
        K = P / (P + R);                      // Compute Kalman gain
        x = x + K * (measurement - x);        // Update estimate
        P = (1 - K) * P;                      // Update uncertainty
        return x;
    }
};

// PID Controller
class PIDController {
private:
    double Kp = 1.0;   // Proportional gain
    double Ki = 0.01;  // Integral gain
    double Kd = 0.1;   // Derivative gain
    double integral = 0.0;
    double previousError = 0.0;

public:
    double compute(double setpoint, double processVariable, double dt) {
        double error = setpoint - processVariable;
        integral += error * dt;
        double derivative = (error - previousError) / dt;
        double output = Kp * error + Ki * integral + Kd * derivative;
        previousError = error;
        return output;
    }
};

