class ComplementaryFilter {
private:
    double alpha = 0.98;  // Weighting factor (gyro vs accelerometer)
    double angleEstimate = 0.0;
    double lastTimestamp = 0.0;

public:
    double update(const SensorData& data) {
        if (lastTimestamp == 0.0) {
            lastTimestamp = data.timestamp;
            return data.accel_angle;
        }

        double dt = data.timestamp - lastTimestamp;
        lastTimestamp = data.timestamp;

        // Complementary filter: gyro for short-term accuracy, accelerometer for drift correction
        angleEstimate = alpha * (angleEstimate + data.gyro_rate * dt) + 
                        (1.0 - alpha) * data.accel_angle;
        return angleEstimate;
    }
};

// PID controller for motor control
class PIDController {
private:
    double Kp = 2.0;   // Proportional gain
    double Ki = 0.01;  // Integral gain
    double Kd = 0.5;   // Derivative gain

    double integral = 0.0;
    double previousError = 0.0;
    double lastTimestamp = 0.0;

public:
    double compute(double setpoint, double measured, double timestamp) {
        if (lastTimestamp == 0.0) {
            lastTimestamp = timestamp;
            return 0.0;
        }

        double dt = timestamp - lastTimestamp;
        lastTimestamp = timestamp;

        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - previousError) / dt;
        previousError = error;

        return Kp * error + Ki * integral + Kd * derivative;
    }
};

