```cpp
#include <cmath>
#include <array>
#include <vector>
#include <iostream>

// Configuration
const int SAMPLE_RATE = 100;           // Hz
const int WINDOW_SIZE = 100;           // 1-second window
const float ANOMALY_THRESHOLD = 3.0f;  // 3σ threshold
const int MOVING_AVERAGE_WINDOW = 5;   // Smoothing filter

// Sensor data structure
struct AccelerometerData {
    float x, y, z;
    uint32_t timestamp;
};

// Pipeline class
class SensorPipeline {
public:
    SensorPipeline() : bufferIndex(0), isBufferFull(false) {}

    void processSample(const AccelerometerData& data) {
        // 1. Data preprocessing
        float magnitude = calculateMagnitude(data);
        float smoothed = applyMovingAverage(magnitude);

        // 2. Anomaly detection
        if (isBufferFull) {
            float mean = calculateMean();
            float stdDev = calculateStandardDeviation(mean);

            if (std::abs(smoothed - mean) > ANOMALY_THRESHOLD * stdDev) {
                triggerAnomalyAlert(smoothed);
            }
        }

        // 3. Buffer management
        samples[bufferIndex] = smoothed;
        bufferIndex = (bufferIndex + 1) % WINDOW_SIZE;
        isBufferFull = (bufferIndex == 0);  // Mark buffer as full on wrap
    }

private:
    std::array<float, WINDOW_SIZE> samples;
    std::array<float, MOVING_AVERAGE_WINDOW> smoothBuffer;
    int bufferIndex;
    bool isBufferFull;

    float calculateMagnitude(const AccelerometerData& data) {
        return std::sqrt(data.x*data.x + data.y*data.y + data.z*data.z);
    }

    float applyMovingAverage(float value) {
        float sum = 0.0f;
        int count = 0;

        // Shift buffer
        for (int i = MOVING_AVERAGE_WINDOW - 1; i > 0; --i) {
            smoothBuffer[i] = smoothBuffer[i-1];
        }
        smoothBuffer[0] = value;

        // Calculate average
        for (int i = 0; i < MOVING_AVERAGE_WINDOW; ++i) {
            if (smoothBuffer[i] != 0.0f) {
                sum += smoothBuffer[i];
                count++;
            }
        }
        return (count > 0) ? sum / count : value;
    }

    float calculateMean() {
        float sum = 0.0f;
        for (int i = 0; i < WINDOW_SIZE; ++i) {
            sum += samples[i];
        }
        return sum / WINDOW_SIZE;
    }

    float calculateStandardDeviation(float mean) {
        float variance = 0.0f;
        for (int i = 0; i < WINDOW_SIZE; ++i) {
            variance += std::pow(samples[i] - mean, 2);
        }
        return std::sqrt(variance / WINDOW_SIZE);
    }

    void triggerAnomalyAlert(float value) {
        // In embedded systems, this would trigger:
        // - LED indicator
        // - UART message
        // - Watchdog reset
        std::cout << "Anomaly detected! Value: " << value << std::endl;
    }
};

// Simulated sensor interface
