    static uint32_t timestamp = 0;
    static bool anomalyDetected = false;

    // Simulate normal data with occasional anomaly
    float normalValue = 9.8f + (rand() % 100 - 50) * 0.01f;  // 9.8 m/s² ± 0.5
    float anomalyValue = 20.0f + (rand() % 100 - 50) * 0.01f; // 20 m/s² ± 0.5

    timestamp += 1000/SAMPLE_RATE;  // 10ms increments
    anomalyDetected = (rand() % 1000) == 0;  // 0.1% anomaly rate

    return {
        .x = 0.0f,
        .y = 0.0f,
        .z = anomalyDetected ? anomalyValue : normalValue,
        .timestamp = timestamp
    };
}

int main() {
    SensorPipeline pipeline;

