#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Configuration
#define SAMPLE_RATE 100       // Hz
#define BUFFER_SIZE 10        // Moving average window
#define ANOMALY_THRESHOLD 2.5 // g (gravity units)

// Simulated raw accelerometer data (x, y, z in g)
float raw_data[] = {
    0.1, 0.2, 9.8,  // Normal
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    10.0, 10.0, 10.0, // Anomaly
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    0.1, 0.2, 9.8,
    10.0, 10.0, 10.0, // Anomaly
};

// Circular buffer for moving average
typedef struct {
    float buffer[BUFFER_SIZE];
    int index;
    int count;
} MovingAverage;

void init_moving_average(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
}

float add_sample(MovingAverage *ma, float sample) {
    ma->buffer[ma->index] = sample;
    ma->index = (ma->index + 1) % BUFFER_SIZE;
    if (ma->count < BUFFER_SIZE) ma->count++;
    float sum = 0.0;
    for (int i = 0; i < ma->count; i++) {
        sum += ma->buffer[i];
    }
    return sum / ma->count;
}

// Compute magnitude of acceleration
float compute_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Anomaly detection
int is_anomaly(float magnitude) {
    return magnitude > ANOMALY_THRESHOLD;
}

int main() {
    MovingAverage x_ma, y_ma, z_ma;
    init_moving_average(&x_ma);
    init_moving_average(&y_ma);
    init_moving_average(&z_ma);

    int data_len = sizeof(raw_data) / sizeof(float);
    int sample_index = 0;

    while (sample_index < data_len) {
        // Simulate reading 3-axis data
        float x = raw_data[sample_index++];
        float y = raw_data[sample_index++];
        float z = raw_data[sample_index++];

        // Preprocessing: Apply moving average
        x = add_sample(&x_ma, x);
        y = add_sample(&y_ma, y);
        z = add_sample(&z_ma, z);

