#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define SAMPLES 100
#define WINDOW_SIZE 5
#define ANOMALY_THRESHOLD 2.0

// Simulate accelerometer data with occasional anomalies
double get_accelerometer_data(int step) {
    // Normal data with noise (mean 1.0, noise +/-0.2)
    double normal_data = 1.0 + ((double)rand() / RAND_MAX - 0.5) * 0.4;
    // Introduce anomalies every 20 steps
    if (step % 20 == 0) {
        return 5.0 + ((double)rand() / RAND_MAX - 0.5) * 1.0; // Anomaly
    }
    return normal_data;
}

// Simple moving average filter
double moving_average_filter(double new_sample) {
    static double buffer[WINDOW_SIZE] = {0};
    static int index = 0;
    static int filled = 0;

    buffer[index] = new_sample;
    index = (index + 1) % WINDOW_SIZE;
    if (filled < WINDOW_SIZE) filled++;

    double sum = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / (filled < WINDOW_SIZE ? filled : WINDOW_SIZE);
}

// Detect anomalies based on threshold
int is_anomaly(double filtered_value) {
    return fabs(filtered_value) > ANOMALY_THRESHOLD;
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < SAMPLES; i++) {
        double raw = get_accelerometer_data(i);
        double filtered = moving_average_filter(raw);
        int anomaly = is_anomaly(filtered);

        printf("Sample %02d: Raw=%.2f | Filtered=%.2f | Anomaly=%d\n", i, raw, filtered, anomaly);
    }

    return 0;
}
