```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>2D Platformer Demo</title>
  <script src="https://cdn.jsdelivr.net/npm/phaser@3.55.2/dist/phaser.js"></script>
</head>
<body>
  <script>
    // Game configuration
    const config = {
      type: Phaser.AUTO,
      width: 800,
      height: 600,
      physics: {
        default: 'arcade',
        arcade: {
          gravity: { y: 1200 },
          debug: false
        }
      },
      scene: {
        preload: preload,
        create: create,
        update: update
      }
    };

    const game = new Phaser.Game(config);
    let player;
    let cursors;
    let platforms;

    function preload() {
      // Load placeholder assets (replace with your own)
      this.load.image('ground', 'https://i.imgur.com/3JZQ8yA.png'); // Platform
      this.load.image('sky', 'https://i.imgur.com/0jFqjJG.png');    // Background
      this.load.spritesheet('dude', 'https://i.imgur.com/3JZQ8yA.png', {
        frameWidth: 32,
        frameHeight: 48
      });
    }

    function create() {
      // Background
      this.add.image(400, 300, 'sky');

      // Platforms
      platforms = this.physics.add.staticGroup();
      platforms.create(400, 568, 'ground').setScale(2).refreshBody();
      platforms.create(600, 400, 'ground');
      platforms.create(50, 250, 'ground');

      // Player
      player = this.physics.add.sprite(100, 450, 'dude');
      player.setBounce(0.2);
      player.setCollideWorldBounds(true);

      // Physics collisions
      this.physics.add.collider(player, platforms);

      // Input
      cursors = this.input.keyboard.createCursorKeys();

      // Animations
      this.anims.create({
        key: 'left',
        frames: this.anims.generateFrameNumbers('dude', { start: 0, end: 3 }),
        frameRate: 10,
        repeat: -1
      });

      this.anims.create({
        key: 'turn',
        frames: [{ key: 'dude', frame: 4 }],
        frameRate: 20
      });

      this.anims.create({
        key: 'right',
        frames: this.anims.generateFrameNumbers('dude', { start: 5, end: 8 }),
        frameRate: 10,
        repeat: -1
      });
    }

    function update() {
      if (cursors.left.isDown) {
        player.setVelocityX(-160);
        player.anims.play('left', true);
      } else if (cursors.right.isDown) {
        player.setVelocityX(160);
        player.anims.play('right', true);
      } else {
        player.setVelocityX(0);
        player.anims.play('turn');
      }

      if (cursors.up.isDown && player.body.touching.down) {
        player.setVelocityY(-330);
      }
    }
  </script>
</body>
</html>
```

