  <script src="https://cdn.jsdelivr.net/npm/three@0.155.0/examples/js/controls/OrbitControls.js"></script>
  <script>
    // === Scene Setup ===
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // === Lighting ===
    const light = new THREE.PointLight(0xffffff, 1.5, 100);
    light.position.set(5, 5, 5);
    scene.add(light);

    const ambientLight = new THREE.AmbientLight(0x404040);
    scene.add(ambientLight);

    // === Custom Shader Material ===
    const vertexShader = `
      varying vec3 vNormal;
      varying vec3 vViewPosition;
      void main() {
        vNormal = normal;
        vViewPosition = cameraPosition - position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const fragmentShader = `
      uniform vec3 uLightPosition;
      uniform vec3 uLightColor;
      uniform vec3 uAmbientColor;
      uniform vec3 uMaterialColor;
      varying vec3 vNormal;
      varying vec3 vViewPosition;

      void main() {
        vec3 normal = normalize(vNormal);
        vec3 lightDirection = normalize(uLightPosition - vViewPosition);
        vec3 viewDirection = normalize(vViewPosition);
        vec3 reflectDirection = reflect(-lightDirection, normal);

        float diff = max(dot(normal, lightDirection), 0.0);
        float spec = pow(max(dot(viewDirection, reflectDirection), 0.0), 32.0);

        vec3 diffuse = diff * uLightColor * uMaterialColor;
        vec3 specular = spec * uLightColor * 0.5;
        vec3 ambient = uAmbientColor * uMaterialColor;

        gl_FragColor = vec4(ambient + diffuse + specular, 1.0);
      }
    `;

    const material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        uLightPosition: { value: light.position.clone() },
        uLightColor: { value: light.color.clone().convertLinearToSRGB().toArray() },
        uAmbientColor: { value: new THREE.Color(0x202020).convertLinearToSRGB().toArray() },
        uMaterialColor: { value: new THREE.Color(0x77aaff).convertLinearToSRGB().toArray() }
      }
    });

    // === 3D Object ===
    const geometry = new THREE.SphereGeometry(1, 64, 64);
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

