    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Dynamic lighting
    const light = new THREE.PointLight(0xffffff, 1);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Custom shader material with dynamic lighting effect
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uLightPosition: { value: light.position.clone() },
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;
        void main() {
          vNormal = normalize(normalMatrix * normal);
          vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uLightPosition;
        varying vec3 vNormal;
        varying vec3 vPosition;
        void main() {
          // Basic lighting
          vec3 lightDir = normalize(uLightPosition - vPosition);
          float diffuse = max(dot(vNormal, lightDir), 0.0);
          vec3 baseColor = vec3(0.5, 0.8, 1.0);

          // Dynamic shader effect (e.g., glowing with time)
          float glow = 0.5 + 0.5 * sin(uTime + diffuse * 5.0);
          vec3 finalColor = baseColor * diffuse + vec3(glow);

          gl_FragColor = vec4(finalColor, 1.0);
        }
      `,
    });

    // 3D object (sphere)
    const geometry = new THREE.SphereGeometry(1, 64, 64);
    const mesh = new THREE.Mesh(geometry, shaderMaterial);
    scene.add(mesh);

    camera.position.z = 5;

    // Animation loop
    let clock = new THREE.Clock();
    function animate() {
      requestAnimationFrame(animate);
      const time = clock.getElapsedTime();

      // Rotate object
      mesh.rotation.y += 0.01;

      // Move light dynamically
      light.position.x = 5 * Math.sin(time);
      light.position.z = 5 * Math.cos(time);
      shaderMaterial.uniforms.uLightPosition.value.copy(light.position);

      // Update time uniform
      shaderMaterial.uniforms.uTime.value = time;

      renderer.render(scene, camera);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth/window.innerHeight;
      camera.updateProjectionMatrix();
