#### **2. Shader (GLSL-style in Unity ShaderLab)**
Create a new `Shader` file (e.g., `DynamicLighting.shader`):

```c
Shader "Custom/DynamicLighting"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Ambient ("Ambient Color", Color) = (0.1, 0.1, 0.1, 1)
        _LightColor ("Light Color", Color) = (1,1,1,1)
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float3 normal : NORMAL;
            };

            struct v2f
            {
                float4 pos : SV_POSITION;
                float3 worldNormal : TEXCOORD0;
                float3 worldPos : TEXCOORD1;
            };

            sampler2D _MainTex;
            float3 _Ambient;
            float3 _LightColor;

            v2f vert (appdata v)
            {
                v2f o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.worldNormal = UnityObjectToWorldNormal(v.normal);
                o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Normalize vectors
                float3 normalDir = normalize(i.worldNormal);
                float3 lightDir = normalize(_WorldSpaceLightPos0.xyz); // Dynamic light direction
                float3 viewDir = normalize(_WorldSpaceCameraPos - i.worldPos);

                // Diffuse
                float diff = max(dot(normalDir, lightDir), 0.0);
                float3 diffuse = diff * _LightColor;

                // Specular (Phong)
                float3 reflectDir = reflect(-lightDir, normalDir);
                float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32);
                float3 specular = spec * _LightColor;

                // Final color
                float3 color = _Ambient + diffuse + specular;
                return fixed4(color, 1.0);
            }
            ENDCG
        }
    }
}
```

