Here's a minimal working example using **JavaScript + Three.js** (with WebGL) to create a real-time 3D scene viewer with dynamic lighting and shader effects. This example includes a rotating 3D cube with dynamic lighting and a custom shader effect.

---

### ✅ Key Features:
- **Dynamic lighting**: A directional light that orbits the scene.
- **Shader effect**: A glowing rim light effect using a custom fragment shader.
- **Interactivity**: Mouse controls for camera rotation/zoom.

---

### 📄 Code (Save as `index.html` and open in a browser):

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>3D Scene Viewer</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <!-- Include Three.js and OrbitControls -->
  <script src="https://cdn.jsdelivr.net/npm/three@0.158.0/build/three.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/three@0.158.0/examples/js/controls/OrbitControls.min.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Add OrbitControls
    const controls = new THREE.OrbitControls(camera, renderer.domElement);
    camera.position.set(5, 5, 5);
    controls.update();

    // Add light (dynamic)
    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Custom shader material (glow effect)
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        time: { value: 0 },
        lightPos: { value: light.position.clone() }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vViewPosition;
        void main() {
          vNormal = normal;
          vViewPosition = - (modelViewMatrix * vec4(position, 1.0)).xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float time;
        uniform vec3 lightPos;
        varying vec3 vNormal;
        varying vec3 vViewPosition;
        void main() {
          vec3 lightDir = normalize(lightPos - vViewPosition);
          float rimDot = 1.0 - max(0.0, dot(normalize(vViewPosition), vNormal));
          vec3 rimColor = vec3(0.7, 0.2, 1.0) * rimDot * 0.5 + 0.5;
          vec3 baseColor = vec3(0.2, 0.6, 1.0) * max(0.0, dot(vNormal, lightDir));
          gl_FragColor = vec4(baseColor + rimColor, 1.0);
        }
      `,
      side: THREE.DoubleSide
    });

    // Create a cube with the custom shader
    const geometry = new THREE.BoxGeometry(1, 1, 1);
    const cube = new THREE.Mesh(geometry, shaderMaterial);
    scene.add(cube);

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);
      const time = Date.now() * 0.001;

      // Rotate the cube
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.01;

      // Move the light dynamically
      light.position.x = 5 * Math.cos(time);
      light.position.z = 5 * Math.sin(time);
      light.position.y = 5 * Math.sin(time * 0.5);
      shaderMaterial.uniforms.lightPos.value.copy(light.position);
      shaderMaterial.uniforms.time.value = time;

      renderer.render(scene, camera);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth/window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
