// Example implementation of a basic physics engine
class BasicPhysicsEngine : public PhysicsPlugin {
public:
    struct RigidBody {
        std::string id;
        Math::Vector3 position;
        Math::Vector3 velocity;
        Math::Vector3 acceleration;
        float mass;
        float radius; // For simple sphere collision
    };

    void Initialize() override {
        gravity = Math::Vector3(0.0f, -9.81f, 0.0f);
    }

    void Update(float deltaTime) override {
        for (auto& body : bodies) {
            body.velocity += body.acceleration * deltaTime;
            body.position += body.velocity * deltaTime;
            body.acceleration = gravity; // Reset acceleration for next frame
        }
    }

    void ApplyForce(Math::Vector3 force, const std::string& bodyID) override {
        for (auto& body : bodies) {
            if (body.id == bodyID) {
                body.acceleration += force / body.mass;
            }
        }
    }

    void DetectCollisions() override {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                auto& a = bodies[i];
                auto& b = bodies[j];
                float distance = std::sqrt(
                    (a.position.x - b.position.x) * (a.position.x - b.position.x) +
                    (a.position.y - b.position.y) * (a.position.y - b.position.y) +
                    (a.position.z - b.position.z) * (a.position.z - b.position.z)
                );
                if (distance < (a.radius + b.radius)) {
                    ResolveCollision(a, b);
                }
            }
        }
    }

    // Add a rigid body to the simulation
    void AddRigidBody(const RigidBody& body) {
        bodies.push_back(body);
    }

private:
    std::vector<RigidBody> bodies;
    Math::Vector3 gravity;

    void ResolveCollision(RigidBody& a, RigidBody& b) {
        // Simple elastic collision resolution
        Math::Vector3 direction = (b.position - a.position).normalized();
        float overlap = a.radius + b.radius - direction.length();
        // Move bodies apart
        a.position -= direction * (overlap / 2.0f) * (a.mass / (a.mass + b.mass));
        b.position += direction * (overlap / 2.0f) * (b.mass / (a.mass + b.mass));
    }
};

