    Vector3 getMaxBounds() const { return {position.x + 0.5f, position.y + 0.5f, position.z + 0.5f}; }
};

// Physics engine singleton
class PhysicsEngine {
public:
    static PhysicsEngine& getInstance() {
        static PhysicsEngine instance;
        return instance;
    }

    void addRigidBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void update(float deltaTime) {
        // Apply gravity (example force)
        for (RigidBody* body : bodies) {
            body->addForce({0.0f, -9.81f, 0.0f});
        }

        // Integrate motion
        for (RigidBody* body : bodies) {
            body->integrate(deltaTime);
        }

        // Resolve collisions
        resolveCollisions();
    }

private:
    std::vector<RigidBody*> bodies;

    void resolveCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                if (checkCollision(bodies[i], bodies[j])) {
                    resolveCollision(bodies[i], bodies[j]);
                }
            }
        }
    }

    bool checkCollision(RigidBody* a, RigidBody* b) {
        Vector3 aMin = a->getMinBounds();
        Vector3 aMax = a->getMaxBounds();
        Vector3 bMin = b->getMinBounds();
        Vector3 bMax = b->getMaxBounds();

        // AABB overlap test
        return aMin.x < bMax.x && aMax.x > bMin.x &&
               aMin.y < bMax.y && aMax.y > bMin.y &&
               aMin.z < bMax.z && aMax.z > bMin.z;
    }

    void resolveCollision(RigidBody* a, RigidBody* b) {
        Vector3 aMin = a->getMinBounds();
        Vector3 aMax = a->getMaxBounds();
        Vector3 bMin = b->getMinBounds();
        Vector3 bMax = b->getMaxBounds();

        // Calculate overlap along each axis
        float xOverlap = std::min(aMax.x - bMin.x, bMax.x - aMin.x);
        float yOverlap = std::min(aMax.y - bMin.y, bMax.y - aMin.y);
        float zOverlap = std::min(aMax.z - bMin.z, bMax.z - aMin.z);

        float minOverlap = std::min(xOverlap, std::min(yOverlap, zOverlap));

        // Resolve by moving along the axis with least overlap
        if (xOverlap == minOverlap) {
            float penetration = (aMax.x - bMin.x);
            a->position.x -= penetration * 0.5f;
            b->position.x += penetration * 0.5f;
        } else if (yOverlap == minOverlap) {
            float penetration = (aMax.y - bMin.y);
            a->position.y -= penetration * 0.5f;
            b->position.y += penetration * 0.5f;
        } else {
            float penetration = (aMax.z - bMin.z);
            a->position.z -= penetration * 0.5f;
            b->position.z += penetration * 0.5f;
        }
    }
};
