#include "PhysicsSystem.h"
#include <algorithm>

void PhysicsSystem::RegisterBody(std::shared_ptr<PhysicsBody> body) {
    bodies.push_back(body);
}

void PhysicsSystem::Simulate(float deltaTime) {
    // Integrate motion
    for (auto& body : bodies) {
        if (!body->isStatic) {
            body->position += body->velocity * deltaTime;
        }
    }

    // Broad-phase collision detection (naive O(n²), replace with spatial partitioning in real systems)
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            glm::vec3 contactPoint;
            if (CheckCollision(*bodies[i], *bodies[j], contactPoint)) {
                ResolveCollision(*bodies[i], *bodies[j], contactPoint);
            }
        }
    }
}

bool PhysicsSystem::CheckCollision(const PhysicsBody& a, const PhysicsBody& b, glm::vec3& contactPoint) {
    // AABB collision detection
    bool overlapX = std::abs(a.position.x - b.position.x) < (a.halfExtents.x + b.halfExtents.x);
    bool overlapY = std::abs(a.position.y - b.position.y) < (a.halfExtents.y + b.halfExtents.y);
    bool overlapZ = std::abs(a.position.z - b.position.z) < (a.halfExtents.z + b.halfExtents.z);

    if (overlapX && overlapY && overlapZ) {
        // Compute midpoint as contact point
        contactPoint = (a.position + b.position) * 0.5f;
        return true;
    }
    return false;
}

void PhysicsSystem::ResolveCollision(PhysicsBody& a, PhysicsBody& b, const glm::vec3& contactPoint) {
    // Simple impulse-based resolution (simplified for example)
    if (a.isStatic && b.isStatic) return;

    glm::vec3 normal = a.position - b.position;
    if (glm::length(normal) == 0.0f) normal = glm::vec3(1.0f, 0.0f, 0.0f);
    normal = glm::normalize(normal);

    float relativeVelocity = glm::dot(b.velocity - a.velocity, normal);
    if (relativeVelocity > 0.0f) return; // No collision response if moving apart

    float totalInverseMass = (a.isStatic ? 0.0f : 1.0f / a.mass) + (b.isStatic ? 0.0f : 1.0f / b.mass);
    if (totalInverseMass <= 0.0f) return;

    float impulse = -(1 + a.restitution) * relativeVelocity;
    impulse /= totalInverseMass;

    if (!a.isStatic) a.velocity -= (impulse / a.mass) * normal;
    if (!b.isStatic) b.velocity += (impulse / b.mass) * normal;
}
