    if (!otherBody) return false;

    // AABB collision detection
    bool xOverlap = (bounds.min.x < otherBody->bounds.max.x) && (bounds.max.x > otherBody->bounds.min.x);
    bool yOverlap = (bounds.min.y < otherBody->bounds.max.y) && (bounds.max.y > otherBody->bounds.min.y);
    bool zOverlap = (bounds.min.z < otherBody->bounds.max.z) && (bounds.max.z > otherBody->bounds.min.z);

