    float position[3];    // Position (x, y, z)
    float velocity[3];    // Velocity (m/s)
    float force[3];       // Accumulated force
    float radius;         // Collision radius (for sphere-based collision)
    bool isKinematic;     // Whether physics is applied

    PhysicsObject(float m, float x, float y, float z, float r)
        : mass(m), radius(r), isKinematic(false) {
        position[0] = x; position[1] = y; position[2] = z;
        velocity[0] = 0.0f; velocity[1] = 0.0f; velocity[2] = 0.0f;
        force[0] = 0.0f; force[1] = 0.0f; force[2] = 0.0f;
    }

    void ClearForces() {
        force[0] = 0.0f; force[1] = 0.0f; force[2] = 0.0f;
    }
};

// Physics plugin class
class CustomPhysicsPlugin {
public:
    // Engine integration: Called once to register the plugin
    static void Initialize() {
        EngineAPI::registerPhysicsPlugin(updatePhysics);
    }

    // Add a physics object to the simulation
    static void AddObject(std::shared_ptr<PhysicsObject> obj) {
        objects.push_back(obj);
    }

    // Core physics update logic (called by the engine every frame)
    static void updatePhysics(float deltaTime) {
        // Apply gravity (9.81 m/s²)
        for (auto& obj : objects) {
            if (obj->isKinematic) continue;
            obj->force[1] += 9.81f * obj->mass; // Gravity in Y-axis
        }

        // Integrate forces into velocity and position
        for (auto& obj : objects) {
            if (obj->isKinematic) continue;

            // Acceleration = F/m
            float acceleration[3] = {
                obj->force[0] / obj->mass,
                obj->force[1] / obj->mass,
                obj->force[2] / obj->mass
            };

            // Update velocity and position
            for (int i = 0; i < 3; ++i) {
                obj->velocity[i] += acceleration[i] * deltaTime;
                obj->position[i] += obj->velocity[i] * deltaTime;
            }

            obj->ClearForces(); // Reset forces for next frame
        }

        // Simple collision detection (sphere-sphere)
        for (size_t i = 0; i < objects.size(); ++i) {
            for (size_t j = i + 1; j < objects.size(); ++j) {
                auto& a = objects[i];
                auto& b = objects[j];

                if (a->isKinematic && b->isKinematic) continue;

                // Calculate distance between centers
                float dx = a->position[0] - b->position[0];
                float dy = a->position[1] - b->position[1];
                float dz = a->position[2] - b->position[2];
                float distanceSq = dx * dx + dy * dy + dz * dz;
                float minDistance = a->radius + b->radius;

                if (distanceSq < minDistance * minDistance) {
                    // Simple collision resolution: move objects apart
                    float distance = std::sqrt(distanceSq);
                    if (distance > 0.0f) {
                        float overlap = minDistance - distance;
                        float nx = dx / distance;
                        float ny = dy / distance;
                        float nz = dz / distance;

                        // Move objects apart proportionally to mass
                        float invMassSum = 1.0f / (a->mass + b->mass);
                        if (!a->isKinematic) {
                            a->position[0] += nx * overlap * (b->mass * invMassSum);
                            a->position[1] += ny * overlap * (b->mass * invMassSum);
                            a->position[2] += nz * overlap * (b->mass * invMassSum);
                        }
                        if (!b->isKinematic) {
                            b->position[0] -= nx * overlap * (a->mass * invMassSum);
                            b->position[1] -= ny * overlap * (a->mass * invMassSum);
                            b->position[2] -= nz * overlap * (a->mass * invMassSum);
                        }
                    }
                }
            }
        }
    }

private:
    static std::vector<std::shared_ptr<PhysicsObject>> objects;
};

