#include <cmath>    // For sqrt, fmax
#include <iostream> // For debugging (remove in production)

// Minimal math types (engine-specific types would replace these in practice)
struct Vector3 {
    float x, y, z;
    Vector3 operator+(const Vector3& other) const {
        return {x + other.x, y + other.y, z + other.z};
    }
    Vector3 operator-(const Vector3& other) const {
        return {x - other.x, y - other.y, z - other.z};
    }
    Vector3 operator*(float scalar) const {
        return {x * scalar, y * scalar, z * scalar};
    }
    float Length() const {
        return std::sqrt(x*x + y*y + z*z);
    }
};

struct Quaternion {
    float x, y, z, w;
};

// Physics object interface
class PhysicsObject {
public:
    virtual ~PhysicsObject() = default;
    virtual void ApplyForce(const Vector3& force) = 0;
    virtual void Update(float deltaTime) = 0;
    virtual Vector3 GetPosition() const = 0;
    virtual void SetPosition(const Vector3& position) = 0;
};

// Simple rigid body implementation
class RigidBody : public PhysicsObject {
public:
    RigidBody(const Vector3& position, float mass, float radius)
        : position(position), velocity({0, 0, 0}), mass(mass), radius(radius) {}

    void ApplyForce(const Vector3& force) override {
        acceleration += force / mass;
    }

    void Update(float deltaTime) override {
        // Integrate physics
        velocity += acceleration * deltaTime;
        position = position + velocity * deltaTime;

        // Reset acceleration after integration
        acceleration = {0, 0, 0};
    }

    Vector3 GetPosition() const override {
        return position;
    }

    void SetPosition(const Vector3& newPosition) override {
        position = newPosition;
    }

    // Simple sphere-sphere collision detection
    bool CheckCollision(const RigidBody& other) const {
        Vector3 delta = position - other.position;
        float distance = delta.Length();
        return distance < (radius + other.radius);
    }

private:
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;
    float radius;
};

// Example usage in a game engine's update loop
void PhysicsSimulationStep(float deltaTime) {
    // Create two physics objects (e.g., a ball and a ground plane)
    RigidBody ball({0, 10, 0}, 1.0f, 1.0f);
    RigidBody ground({0, 0, 0}, 1000.0f, 5.0f); // Static ground

    // Apply gravity
    ball.ApplyForce({0, -9.81f, 0});

    // Simulate physics
    ball.Update(deltaTime);

    // Collision resolution (simplified)
    if (ball.CheckCollision(ground)) {
        Vector3 delta = ball.GetPosition() - ground.GetPosition();
        float penetration = (ball.radius + ground.radius) - delta.Length();
        Vector3 correction = delta * (penetration / delta.Length());
        ball.SetPosition(ball.GetPosition() + correction);
        ball.velocity.y = 0; // Stop bouncing
    }

    // Output debug info
    std::cout << "Ball Position: (" << ball.GetPosition().x << ", "
              << ball.GetPosition().y << ", " << ball.GetPosition().z << ")\n";
}

// Entry point for engine integration (e.g., called by the game engine's update loop)
extern "C" {
    void UpdatePhysics(float deltaTime) {
        PhysicsSimulationStep(deltaTime);
    }
}
