### **Code (C++)**
```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <GLFW/glfw3.h>
#include <glad/gl.h>

// Rigid body class
struct RigidBody {
    glm::vec3 position = {0.0f, 5.0f, 0.0f}; // Initial position
    glm::vec3 velocity = {0.0f, 0.0f, 0.0f};
    float mass = 1.0f;
    float radius = 1.0f; // For simple sphere collision
};

// Simulation parameters
const float GRAVITY = -9.81f;
const float FIXED_TIME_STEP = 1.0f / 60.0f; // 60 Hz
const float PHYSICS_EPSILON = 0.0001f;

// Collision with ground (y = 0)
void resolveCollision(RigidBody& body) {
    if (body.position.y - body.radius < 0.0f) {
        body.position.y = body.radius; // Snap to ground
        body.velocity.y *= -0.5f;     // Bounce with damping
    }
}

// Physics update (fixed time step)
void updatePhysics(std::vector<RigidBody>& bodies, float dt) {
    for (auto& body : bodies) {
        // Apply gravity
        body.velocity += glm::vec3(0.0f, GRAVITY, 0.0f) * dt;
        body.position += body.velocity * dt;
        resolveCollision(body);
    }
}

// Rendering
void render(const std::vector<RigidBody>& bodies) {
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glLoadIdentity();

    for (const auto& body : bodies) {
        glPushMatrix();
        glTranslatef(body.position.x, body.position.y, body.position.z);
        glColor3f(0.0f, 0.0f, 1.0f);
        glutSolidSphere(body.radius, 16, 16); // Simple sphere
        glPopMatrix();
    }
}

int main() {
    // Initialize GLFW and OpenGL
    if (!glfwInit()) {
        std::cerr << "Failed to initialize GLFW\n";
        return -1;
    }
    GLFWwindow* window = glfwCreateWindow(800, 600, "Real-Time Physics Simulation", NULL, NULL);
    if (!window) {
        std::cerr << "Failed to create GLFW window\n";
        glfwTerminate();
        return -1;
    }
    glfwMakeContextCurrent(window);

    // Initialize GLAD
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
        std::cerr << "Failed to initialize GLAD\n";
        return -1;
    }

    // Create a single rigid body
    std::vector<RigidBody> bodies = { RigidBody() };

    // Time variables
    auto previousTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (!glfwWindowShouldClose(window)) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(currentTime - previousTime).count();
        previousTime = currentTime;

        // Cap delta time to prevent spiral of death
        if (deltaTime > 0.25f) deltaTime = 0.25f;

        // Update physics at fixed rate
        accumulator += deltaTime;
        while (accumulator >= FIXED_TIME_STEP) {
            updatePhysics(bodies, FIXED_TIME_STEP);
            accumulator -= FIXED_TIME_STEP;
        }

        // Render
        render(bodies);
        glfwSwapBuffers(window);
        glfwPollEvents();
    }

    glfwDestroyWindow(window);
    glfwTerminate();
    return 0;
}
