### 🚀 **Code Example**

```cpp
#include <iostream>
#include <btBulletDynamicsCommon.h>
#include <chrono>
#include <thread>

// Constants for simulation
const float TIME_STEP = 1.0f / 60.0f; // 60 FPS target
const int MAX_SUBSTEPS = 4;          // Max substeps per frame
const float SIMULATION_SPEED = 1.0f; // Simulation speed multiplier

// Simple rendering placeholder (replace with OpenGL/DirectX)
void renderScene(btDiscreteDynamicsWorld* world) {
    std::cout << "Rendering frame..." << std::endl;
    for (int i = 0; i < world->getNumCollisionObjects(); i++) {
        btCollisionObject* obj = world->getCollisionObjectArray()[i];
        btRigidBody* body = btRigidBody::upcast(obj);
        if (body && body->getMotionState()) {
            btTransform trans;
            body->getMotionState()->getWorldTransform(trans);
            std::cout << "Object " << i << " position: " << trans.getOrigin() << std::endl;
        }
    }
}

int main() {
    // Initialize Bullet Physics
    btDefaultCollisionConfiguration* collisionConfig = new btDefaultCollisionConfiguration();
    btCollisionDispatcher* dispatcher = new btCollisionDispatcher(collisionConfig);
    btBroadphaseInterface* broadphase = new btDbvtBroadphase();
    btSequentialImpulseConstraintSolver* solver = new btSequentialImpulseConstraintSolver();
    btDiscreteDynamicsWorld* dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, broadphase, solver, collisionConfig);
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity

    // Create ground plane (static rigid body)
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 1);
    btDefaultMotionState* groundMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0)));
    btRigidBody::btRigidBodyConstructionInfo groundRigidBodyCI(0, groundMotionState, groundShape, btVector3(0, 0, 0));
    btRigidBody* groundRigidBody = new btRigidBody(groundRigidBodyCI);
    dynamicsWorld->addRigidBody(groundRigidBody);

    // Create a falling box (dynamic rigid body)
    btCollisionShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
    btTransform boxStartTransform;
    boxStartTransform.setIdentity();
    boxStartTransform.setOrigin(btVector3(0, 10, 0)); // Start above ground
    btDefaultMotionState* boxMotionState = new btDefaultMotionState(boxStartTransform);
    btScalar mass = 1.0f;
    btVector3 inertia(0, 0, 0);
    boxShape->calculateLocalInertia(mass, inertia);
    btRigidBody::btRigidBodyConstructionInfo boxRigidBodyCI(mass, boxMotionState, boxShape, inertia);
    btRigidBody* boxRigidBody = new btRigidBody(boxRigidBodyCI);
    dynamicsWorld->addRigidBody(boxRigidBody);

    // Main loop with frame-rate control
    std::chrono::steady_clock::time_point startTime = std::chrono::steady_clock::now();
    while (true) {
        // Simulate physics
        dynamicsWorld->stepSimulation(TIME_STEP * SIMULATION_SPEED, MAX_SUBSTEPS, TIME_STEP);

        // Render scene
        renderScene(dynamicsWorld);

        // Frame-rate control
        auto currentTime = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration<float>(currentTime - startTime).count();
        if (elapsed < TIME_STEP) {
            std::this_thread::sleep_for(std::chrono::duration<float>(TIME_STEP - elapsed));
        }
        startTime = currentTime;
    }

    // Cleanup
    dynamicsWorld->removeRigidBody(groundRigidBody);
    dynamicsWorld->removeRigidBody(boxRigidBody);
    delete groundRigidBody;
    delete boxRigidBody;
    delete groundShape;
    delete boxShape;
    delete groundMotionState;
    delete boxMotionState;
    delete dynamicsWorld;
    delete solver;
    delete broadphase;
    delete dispatcher;
    delete collisionConfig;

    return 0;
}
```

