// Basic rigid body class
struct RigidBody {
    double position[2] = {0.0, 0.0}; // x, y
    double velocity[2] = {0.0, 0.0};
    double mass = 1.0;
    double acceleration[2] = {0.0, 0.0};

    void applyForce(double fx, double fy) {
        acceleration[0] += fx / mass;
        acceleration[1] += fy / mass;
    }

    void integrate(double dt) {
        velocity[0] += acceleration[0] * dt;
        velocity[1] += acceleration[1] * dt;

        position[0] += velocity[0] * dt;
        position[1] += velocity[1] * dt;

        // Reset acceleration for next step
        acceleration[0] = 0.0;
        acceleration[1] = 0.0;
    }
};

// Simple collision detection with boundaries
void checkCollisions(RigidBody& body) {
    if (body.position[0] < 0 || body.position[0] > 800) {
        body.velocity[0] *= -0.9; // Dampen velocity
        body.position[0] = std::clamp(body.position[0], 0.0, 800.0);
    }
    if (body.position[1] < 0 || body.position[1] > 600) {
        body.velocity[1] *= -0.9;
        body.position[1] = std::clamp(body.position[1], 0.0, 600.0);
    }
}

int main() {
    const int PHYSICS_FPS = 60;      // Target physics update rate
    const int RENDER_FPS = 60;       // Target rendering rate
    const double PHYSICS_DT = 1.0 / PHYSICS_FPS;
    const double PHYSICS_TIME = 1.0 / PHYSICS_FPS;

    RigidBody ball;
    ball.position[0] = 400.0;
    ball.position[1] = 300.0;
    ball.velocity[0] = 200.0; // px/s
    ball.velocity[1] = 150.0;
    ball.mass = 1.0;

    auto lastPhysicsTime = std::chrono::high_resolution_clock::now();
    auto lastRenderTime = std::chrono::high_resolution_clock::now();

    while (true) {
        // Physics update loop (fixed time step)
        auto now = std::chrono::high_resolution_clock::now();
        auto elapsedPhysics = std::chrono::duration<double>(now - lastPhysicsTime).count();

        if (elapsedPhysics >= PHYSICS_DT) {
            // Apply gravity (simple force)
            ball.applyForce(0.0, 9.81 * ball.mass); // Simulated gravity

            // Integrate physics
            ball.integrate(PHYSICS_DT);

            // Check collisions
            checkCollisions(ball);

            // Reset timer
            lastPhysicsTime = now;
        }

