#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>

// Forward declarations
struct RigidBody;
class PhysicsEngine;

// Rigid Body Class
struct RigidBody {
    double mass;                // Mass (kg)
    double invMass;             // Inverse mass (1/mass)
    double linearDamping;       // Linear velocity damping
    double angularDamping;      // Angular velocity damping
    double* inertiaTensor;      // 3x3 inertia tensor (local space)
    double* invInertiaTensor;   // 3x3 inverse inertia tensor (local space)
    double position[3];         // Position (x, y, z)
    double velocity[3];         // Linear velocity
    double orientation[4];      // Orientation (quaternion: w, x, y, z)
    double angularVelocity[3];  // Angular velocity
    double force[3];            // Accumulated force
    double torque[3];           // Accumulated torque

    RigidBody(double mass, const double* inertiaTensor, const double position[3]) {
        this->mass = mass;
        invMass = (mass > 0) ? 1.0 / mass : 0.0;
        linearDamping = 0.99;
        angularDamping = 0.99;
        this->inertiaTensor = new double[9];
        this->invInertiaTensor = new double[9];
        for (int i = 0; i < 9; ++i) {
            this->inertiaTensor[i] = inertiaTensor[i];
            invInertiaTensor[i] = (inertiaTensor[i] != 0) ? 1.0 / inertiaTensor[i] : 0.0;
        }
        std::copy(position, position + 3, this->position);
        std::copy(position, position + 3, this->velocity);
        orientation[0] = 1.0; orientation[1] = 0.0; orientation[2] = 0.0; orientation[3] = 0.0;
        std::fill(angularVelocity, angularVelocity + 3, 0.0);
        std::fill(force, force + 3, 0.0);
        std::fill(torque, torque + 3, 0.0);
    }

    ~RigidBody() {
        delete[] inertiaTensor;
        delete[] invInertiaTensor;
    }

    void applyForce(const double force[3]) {
        for (int i = 0; i < 3; ++i) {
            this->force[i] += force[i];
        }
    }

    void integrate(double dt) {
        // Linear motion
        for (int i = 0; i < 3; ++i) {
            velocity[i] += (force[i] * invMass) * dt;
            velocity[i] *= linearDamping;
            position[i] += velocity[i] * dt;
        }

        // Angular motion
        double angularAcceleration[3] = {0.0};
        for (int i = 0; i < 3; ++i) {
            angularAcceleration[i] = torque[i] * invInertiaTensor[i];
            angularVelocity[i] += angularAcceleration[i] * dt;
            angularVelocity[i] *= angularDamping;
        }

        // Update orientation using angular velocity (simplified)
        double qDot[4] = {0.0}; // Derivative of quaternion
        qDot[0] = -0.5 * (angularVelocity[0] * orientation[1] + angularVelocity[1] * orientation[2] + angularVelocity[2] * orientation[3]);
        qDot[1] = 0.5 * (angularVelocity[0] * orientation[0] + angularVelocity[2] * orientation[3] - angularVelocity[1] * orientation[3]);
        qDot[2] = 0.5 * (angularVelocity[1] * orientation[0] - angularVelocity[2] * orientation[2] + angularVelocity[0] * orientation[3]);
        qDot[3] = 0.5 * (angularVelocity[2] * orientation[0] + angularVelocity[1] * orientation[1] - angularVelocity[0] * orientation[2]);

        for (int i = 0; i < 4; ++i) {
            orientation[i] += qDot[i] * dt;
        }

        // Normalize quaternion
        double norm = sqrt(orientation[0] * orientation[0] + orientation[1] * orientation[1] +
                           orientation[2] * orientation[2] + orientation[3] * orientation[3]);
        for (int i = 0; i < 4; ++i) {
            orientation[i] /= norm;
        }

        // Clear forces and torques for next step
        std::fill(force, force + 3, 0.0);
        std::fill(torque, torque + 3, 0.0);
    }
};

// Physics Engine Class
class PhysicsEngine {
private:
    std::vector<RigidBody*> bodies;
    double gravity[3] = {0.0, -9.81, 0.0}; // m/s²
    double fixedTimeStep = 1.0 / 60.0;      // 60 Hz
    double timeAccumulator = 0.0;

public:
    void addBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void update() {
        // Apply gravity
        for (RigidBody* body : bodies) {
            if (body->mass > 0) {
                body->applyForce({0.0, gravity[1] * body->mass, 0.0});
            }
        }

        // Integrate motion
        for (RigidBody* body : bodies) {
            body->integrate(fixedTimeStep);
        }

        // Collision detection and resolution
        resolveCollisions();
    }

private:
    void resolveCollisions() {
        // Placeholder: Simple sphere-sphere collision
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody* a = bodies[i];
                RigidBody* b = bodies[j];
                double dx = a->position[0] - b->position[0];
                double dy = a->position[1] - b->position[1];
                double dz = a->position[2] - b->position[2];
                double distanceSq = dx * dx + dy * dy + dz * dz;
                if (distanceSq < 1.0) { // Collision radius = 1.0
                    resolveCollision(a, b);
                }
            }
        }
    }

    void resolveCollision(RigidBody* a, RigidBody* b) {
        // Simplified impulse-based resolution
        double dx = a->position[0] - b->position[0];
        double dy = a->position[1] - b->position[1];
        double dz = a->position[2] - b->position[2];
        double distance = sqrt(dx * dx + dy * dy + dz * dz);
        if (distance == 0.0) return;

        double normal[3] = {dx / distance, dy / distance, dz / distance};
        double relativeVelocity[3] = {
            a->velocity[0] - b->velocity[0],
            a->velocity[1] - b->velocity[1],
            a->velocity[2] - b->velocity[2]
        };

        double velocityDot = relativeVelocity[0] * normal[0] + relativeVelocity[1] * normal[1] + relativeVelocity[2] * normal[2];
        if (velocityDot > 0.0) return; // Only resolve if moving toward each other

        double restitution = 0.5; // Coefficient of restitution
        double impulse = -(1 + restitution) * velocityDot;
        impulse /= (a->invMass + b->invMass);

        double impulseVector[3] = {impulse * normal[0], impulse * normal[1], impulse * normal[2]};
        for (int i = 0; i < 3; ++i) {
            a->velocity[i] += impulseVector[i] * a->invMass;
            b->velocity[i] -= impulseVector[i] * b->invMass;
        }
    }
};

// Main Simulation Loop
