        std::cout << "Body2 Position: (" << body2->position[0] << ", " << body2->position[1] << ", " << body2->position[2] << ")\n";
        std::cout << "----------------------------------------\n";

        // Sleep to simulate real-time (optional)
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    // Cleanup
    delete body1;
    delete body2;
    return 0;
}
