#include <SFML/Graphics.hpp>
#include <Box2D/Box2D.h>
#include <iostream>

const int SCALE = 30; // 1 meter = 30 pixels
const float TIME_STEP = 1.0f / 60.0f; // 60 Hz physics
const int VELOCITY_ITERATIONS = 6;
const int POSITION_ITERATIONS = 2;

struct BodyData {
    sf::RectangleShape shape;
    b2Body* body;
};

int main() {
    // SFML setup
    sf::RenderWindow window(sf::VideoMode(800, 600), "Rigid Body Simulation");
    window.setFramerateLimit(60); // Cap to 60 FPS

    // Box2D world with gravity
    b2Vec2 gravity(0.0f, -9.8f); // Inverted Y for SFML coordinate system
    b2World world(gravity);

    // Ground body
    {
        b2BodyDef groundBodyDef;
        groundBodyDef.position.Set(0.0f, 0.0f);
        b2Body* groundBody = world.CreateBody(&groundBodyDef);

        b2PolygonShape groundBox;
        groundBox.SetAsBox(40.0f, 1.0f); // 40m wide, 2m high
        groundBody->CreateFixture(&groundBox, 0.0f);
    }

    // Dynamic body (falling box)
    BodyData box;
    {
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(0.0f, 10.0f); // Start 10m above ground
        box.body = world.CreateBody(&bodyDef);

        b2PolygonShape dynamicBox;
        dynamicBox.SetAsBox(1.0f, 1.0f); // 2m x 2m box
        box.body->CreateFixture(&dynamicBox, 1.0f); // Density = 1

        // SFML visual
        box.shape.setSize(sf::Vector2f(2.0f * SCALE, 2.0f * SCALE));
        box.shape.setFillColor(sf::Color::Green);
    }

    sf::Clock clock;
    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        // Physics step
        world.Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);

        // Update SFML shape position
        b2Vec2 position = box.body->GetPosition();
        float angle = box.body->GetAngle();
        box.shape.setPosition(position.x * SCALE, window.getSize().y - position.y * SCALE);
        box.shape.setRotation(angle * 180.0f / b2_pi);

        // Render
        window.clear();
        window.draw(box.shape);
        window.display();
    }

    return 0;
}
