#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>

// Simple rigid body class
struct RigidBody {
    double x, y;       // Position
    double vx, vy;     // Velocity
    double mass;       // Mass
    double radius;     // Collision radius

    RigidBody(double x, double y, double mass, double radius)
        : x(x), y(y), vx(0), vy(0), mass(mass), radius(radius) {}

    // Apply gravity
    void applyGravity(double gravity, double dt) {
        vy += gravity * dt;
    }

    // Update position
    void update(double dt) {
        x += vx * dt;
        y += vy * dt;
    }

    // Simple collision detection between two bodies
    void resolveCollision(RigidBody& other) {
        double dx = other.x - x;
        double dy = other.y - y;
        double distSq = dx*dx + dy*dy;
        double minDist = radius + other.radius;

        if (distSq < minDist*minDist) {
            double dist = std::sqrt(distSq);
            double overlap = minDist - dist;
            double nx = dx / dist;
            double ny = dy / dist;

            // Separate bodies
            x -= nx * overlap * 0.5;
            y -= ny * 0.5;
            other.x += nx * overlap * 0.5;
            other.y += ny * 0.5;

            // Simple velocity swap (perfectly elastic collision)
            std::swap(vx, other.vx);
            std::swap(vy, other.vy);
        }
    }
};

int main() {
    const double gravity = -9.81;  // m/s² (negative for downward direction)
    const double fixedDeltaTime = 1.0 / 60.0;  // 60 Hz
    const double simulationTime = 10.0;  // Run for 10 seconds

    RigidBody ball1(0.0, 10.0, 1.0, 1.0);
    RigidBody ball2(0.0, 20.0, 1.0, 1.0);

    auto startTime = std::chrono::high_resolution_clock::now();
    auto currentTime = startTime;
    auto accumulator = 0.0;

    while (std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - startTime).count() < simulationTime) {
        auto newTime = std::chrono::high_resolution_clock::now();
        auto frameTime = std::chrono::duration<double>(newTime - currentTime).count();
        currentTime = newTime;
        accumulator += frameTime;

        // Physics update
        while (accumulator >= fixedDeltaTime) {
            ball1.applyGravity(gravity, fixedDeltaTime);
            ball2.applyGravity(gravity, fixedDeltaTime);

            ball1.update(fixedDeltaTime);
            ball2.update(fixedDeltaTime);

            ball1.resolveCollision(ball2);

            accumulator -= fixedDeltaTime;
        }

        // Render/Output (simplified)
        if (std::chrono::duration<double>(currentTime - startTime).count() % 1.0 < fixedDeltaTime) {
            std::cout << "Ball1: (" << ball1.x << ", " << ball1.y << ") | "
                      << "Ball2: (" << ball2.x << ", " << ball2.y << ")\n";
        }

        // Frame rate limiting
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    return 0;
}
