        auto deltaTime = std::chrono::duration<double>(now - lastTime).count();
        lastTime = now;

        accumulatedTime += deltaTime;

        // Simulate physics at fixed time step
        while (accumulatedTime >= fixedTimeStep) {
            body.update(fixedTimeStep);
            accumulatedTime -= fixedTimeStep;
        }

        // Optional: Apply user input (e.g., jump)
        static bool jumping = false;
        if (!jumping) {
            std::cin.ignore(1); // Simulate key press (e.g., spacebar)
            body.applyForce(10.0, fixedTimeStep); // Jump impulse
            jumping = true;
        } else if (body.velocity <= 0.1) {
            jumping = false;
        }

        // Render (console output for minimalism)
        std::cout << "Position: " << body.position << " | Velocity: " << body.velocity << "\r";
        std::cout.flush();

        // Frame rate control (sleep to avoid CPU overload)
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
