#### 4. **Payment Service (Core Logic)**
```java
public class PaymentService {
    private final Map<String, PaymentGateway> gateways;
    private final Logger logger = LoggerFactory.getLogger(PaymentService.class);

    public PaymentService() {
        gateways = new HashMap<>();
        gateways.put("CREDIT_CARD", new CreditCardGateway());
        gateways.put("ACH", new ACHGateway());
    }

    public synchronized PaymentResponse processPayment(PaymentRequest request) {
        try {
            PaymentGateway gateway = gateways.get(request.getPaymentMethod());
            if (gateway == null) {
                throw new PaymentException("Unsupported payment method: " + request.getPaymentMethod());
            }

            PaymentResponse response = gateway.processPayment(request);
            logger.info("Processed payment: {} | Status: {}", request.getTransactionId(), response.getStatus());
            return response;
        } catch (PaymentException e) {
            logger.error("Payment failed: {}", e.getMessage(), e);
            return new PaymentResponse()
                    .setTransactionId(request.getTransactionId())
                    .setStatus("FAILED")
                    .setErrorMessage(e.getMessage())
                    .setTimestamp(LocalDateTime.now().toString());
        }
    }

    // Thread-safe retry mechanism (simplified)
    public PaymentResponse retryPayment(PaymentRequest request, int maxRetries) {
        for (int i = 0; i < maxRetries; i++) {
            try {
                Thread.sleep(1000); // Simulate retry delay
                return processPayment(request);
            } catch (Exception e) {
                logger.warn("Retry {} failed for transaction {}", i + 1, request.getTransactionId());
            }
        }
        return new PaymentResponse()
                .setTransactionId(request.getTransactionId())
                .setStatus("FAILED")
                .setErrorMessage("Max retries exceeded")
                .setTimestamp(LocalDateTime.now().toString());
    }
}
```

