```java
// PaymentService.java
@Service
public class PaymentService {
    @Autowired
    private UserRepository userRepository;

    @Autowired
    private PaymentRepository paymentRepository;

    @Transactional
    public Payment processPayment(Long senderId, Long receiverId, BigDecimal amount) {
        // Validate inputs
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }

        // Fetch users
        User sender = userRepository.findById(senderId)
                .orElseThrow(() -> new RuntimeException("Sender not found"));
        User receiver = userRepository.findById(receiverId)
                .orElseThrow(() -> new RuntimeException("Receiver not found"));

        // Check sender's balance
        if (sender.getBalance().compareTo(amount) < 0) {
            throw new RuntimeException("Insufficient balance");
        }

        // Deduct and add funds
        sender.setBalance(sender.getBalance().subtract(amount));
        receiver.setBalance(receiver.getBalance().add(amount));

        // Save updates
        userRepository.save(sender);
        userRepository.save(receiver);

        // Create payment record
        Payment payment = new Payment();
        payment.setSenderId(senderId);
        payment.setReceiverId(receiverId);
        payment.setAmount(amount);
        payment.setStatus("COMPLETED");
        payment.setTimestamp(new Date());

        return paymentRepository.save(payment);
    }

    public List<Payment> getPaymentHistory(Long userId) {
        return paymentRepository.findBySenderId(userId);
    }
}
