// PaymentService.java
@Service
public class PaymentService {

    private final FraudDetectionService fraudService;
    private final ExternalPaymentProcessor paymentProcessor;
    private final PaymentRepository paymentRepository;
    private final Logger logger = LoggerFactory.getLogger(PaymentService.class);

    public PaymentService(
        FraudDetectionService fraudService,
        ExternalPaymentProcessor paymentProcessor,
        PaymentRepository paymentRepository) {
        this.fraudService = fraudService;
        this.paymentProcessor = paymentProcessor;
        this.paymentRepository = paymentRepository;
    }

    public PaymentResponse processPayment(PaymentRequest request) throws PaymentProcessingException {
        // Step 1: Validate input
        validatePaymentRequest(request);

        // Step 2: Check for fraud
        if (fraudService.isFraudulent(request)) {
            logger.warn("Fraud detected for payment: {}", request.getTransactionId());
            throw new FraudDetectedException("Payment flagged as fraudulent");
        }

        // Step 3: Authorize payment via external processor
        ExternalAuthorizationResponse authResponse = paymentProcessor.authorizePayment(request);

        // Step 4: Persist payment record
        PaymentRecord paymentRecord = new PaymentRecord(
            request.getTransactionId(),
            request.getAmount(),
            authResponse.getStatus(),
            LocalDateTime.now()
        );
        paymentRepository.save(paymentRecord);

        // Step 5: Return response
        return new PaymentResponse(
            request.getTransactionId(),
            authResponse.getStatus(),
            authResponse.getMessage()
        );
    }

    private void validatePaymentRequest(PaymentRequest request) throws PaymentProcessingException {
        if (request.getAmount() <= 0) {
            throw new PaymentProcessingException("Payment amount must be positive");
        }
        if (request.getCardNumber().length() != 16) {
            throw new PaymentProcessingException("Invalid card number");
        }
    }
}
```

