// service/PaymentService.java
@Service
public class PaymentService {
    @Autowired private AccountRepository accountRepository;
    @Autowired private FraudDetectionService fraudService;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        if (fraudService.isFraudulentTransaction(request)) {
            throw new FraudException("Transaction flagged as fraudulent");
        }

        Optional<Account> fromAccountOpt = accountRepository.findByAccountId(request.getFromAccountId());
        Optional<Account> toAccountOpt = accountRepository.findByAccountId(request.getToAccountId());

        if (fromAccountOpt.isEmpty() || toAccountOpt.isEmpty()) {
            throw new AccountNotFoundException("Invalid account ID");
        }

        Account fromAccount = fromAccountOpt.get();
        Account toAccount = toAccountOpt.get();

        if (fromAccount.getBalance().compareTo(request.getAmount()) < 0) {
            throw new InsufficientFundsException("Insufficient balance");
        }

        fromAccount.setBalance(fromAccount.getBalance().subtract(request.getAmount()));
        toAccount.setBalance(toAccount.getBalance().add(request.getAmount()));
        accountRepository.save(fromAccount);
        accountRepository.save(toAccount);

        return new PaymentResponse("SUCCESS", "Payment processed");
    }
}
```

