package com.enterprise.order.service;

import com.enterprise.order.repository.OrderEntity;
import com.enterprise.order.repository.OrderRepository;
import com.enterprise.order.controller.OrderRequest;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;
import java.time.Instant;

@Service
public class OrderServiceImpl implements OrderService {
    private final OrderRepository repository;
    private final ExternalSystemClient externalClient;

    public OrderServiceImpl(OrderRepository repository, ExternalSystemClient externalClient) {
        this.repository = repository;
        this.externalClient = externalClient;
    }

    @Override
    public Mono<OrderEntity> createOrder(OrderRequest request) {
        return externalClient.validateCustomer(request.customerId())
                .flatMap(valid -> {
                    if (valid) {
                        OrderEntity order = new OrderEntity();
                        order.setOrderNumber("ORDER-" + System.currentTimeMillis());
                        order.setAmount(request.amount());
                        order.setStatus(OrderEntity.OrderStatus.PENDING);
                        order.setCreatedAt(Instant.now());
                        return Mono.just(repository.save(order));
                    }
                    return Mono.error(new IllegalArgumentException("Invalid customer"));
                });
    }

    @Override
    public Mono<OrderEntity> approveOrder(String orderNumber) {
        return repository.findByOrderNumber(orderNumber)
                .map(order -> {
                    order.setStatus(OrderEntity.OrderStatus.APPROVED);
                    return repository.save(order);
                })
                .flatMap(Mono::just)
                .switchIfEmpty(Mono.error(new ResourceNotFoundException("Order not found")));
    }
}
