package com.example.microservice.service;

import com.example.microservice.model.CorporateOrder;
import com.example.microservice.model.CorporateOrder.OrderStatus;
import com.example.microservice.repository.OrderRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private LegacySystemIntegration legacySystemIntegration;

    @Transactional
    public CorporateOrder processOrder(CorporateOrder order) {
        // Validate and persist
        order.setStatus(OrderStatus.PROCESSING);
        CorporateOrder savedOrder = orderRepository.save(order);

        // Integrate with legacy system (e.g., ERP, mainframe)
        try {
            legacySystemIntegration.sendToLegacySystem(order.getLegacySystemId());
            savedOrder.setStatus(OrderStatus.COMPLETED);
        } catch (LegacySystemException e) {
            savedOrder.setStatus(OrderStatus.FAILED);
        }

        return orderRepository.save(savedOrder);
    }
}
