// User entity with JPA annotations and type safety
@Entity
@Data
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true)
    private String email;

    @Column(nullable = false)
    private String fullName;

    @Enumerated(EnumType.STRING)
    private UserStatus status;

    @Temporal(TemporalType.TIMESTAMP)
    private Date createdAt;
}

// Type-safe enum
public enum UserStatus {
    ACTIVE("active"),
    INACTIVE("inactive"),
    PENDING("pending");

    private final String value;

    UserStatus(String value) {
        this.value = value;
    }

    public String getValue() {
        return value;
    }
}

// Repository interface with type-safe operations
public interface UserRepository extends JpaRepository<User, Long> {
    Optional<User> findByEmail(String email);
}

// Service layer with business logic
@Service
@RequiredArgsConstructor
public class UserService {
    private final UserRepository userRepository;
    private final LegacySystemService legacySystemService;

    @Transactional
    public User createUser(UserRequest request) {
        if (userRepository.existsByEmail(request.getEmail())) {
            throw new ResourceConflictException("Email already exists");
        }

        User user = new User();
        user.setEmail(request.getEmail());
        user.setFullName(request.getFullName());
        user.setStatus(UserStatus.PENDING);
        user.setCreatedAt(new Date());

        // Integration with legacy system
        legacySystemService.validateUserAgainstLegacySystem(user.getEmail());

        return userRepository.save(user);
    }
}

// Legacy system integration component
@Component
@RequiredArgsConstructor
public class LegacySystemService {
    private final JdbcTemplate legacyJdbcTemplate;

    public void validateUserAgainstLegacySystem(String email) {
        String legacyEmail = legacyJdbcTemplate.queryForObject(
            "SELECT email FROM legacy_users WHERE email = ?", 
            String.class, 
            email
        );

        if (legacyEmail != null) {
            throw new IntegrationException("User exists in legacy system");
        }
    }
}

// REST controller with type-safe endpoints
@RestController
@RequestMapping("/api/users")
@RequiredArgsConstructor
public class UserController {
    private final UserService userService;

    @PostMapping
    public ResponseEntity<UserResponse> createUser(@Valid @RequestBody UserRequest request) {
        User user = userService.createUser(request);
        return ResponseEntity.status(HttpStatus.CREATED)
            .body(UserResponse.fromUser(user));
    }

    @GetMapping("/{id}")
    public ResponseEntity<UserResponse> getUser(@PathVariable Long id) {
        return userService.findById(id)
            .map(user -> ResponseEntity.ok(UserResponse.fromUser(user)))
            .orElse(ResponseEntity.notFound().build());
    }
}

// Type-safe request/response DTOs
@Data
public class UserRequest {
    @Email(message = "Invalid email format")
    private String email;

    @NotBlank(message = "Full name is required")
    private String fullName;
}

@Data
public class UserResponse {
    private Long id;
    private String email;
    private String fullName;
    private String status;
    private Date createdAt;

    public static UserResponse fromUser(User user) {
        UserResponse response = new UserResponse();
        response.setId(user.getId());
        response.setEmail(user.getEmail());
        response.setFullName(user.getFullName());
        response.setStatus(user.getStatus().getValue());
        response.setCreatedAt(user.getCreatedAt());
        return response;
    }
}

// Custom exceptions with type-safe error handling
public class ResourceConflictException extends RuntimeException {
    public ResourceConflictException(String message) {
        super(message);
    }
}

public class IntegrationException extends RuntimeException {
    public IntegrationException(String message) {
        super(message);
    }
}

// Global exception handler
@ControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(ResourceConflictException.class)
    public ResponseEntity<ErrorResponse> handleResourceConflict(ResourceConflictException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
            .body(new ErrorResponse(HttpStatus.CONFLICT.value(), ex.getMessage()));
    }

    @ExceptionHandler(IntegrationException.class)
    public ResponseEntity<ErrorResponse> handleIntegrationError(IntegrationException ex) {
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
            .body(new ErrorResponse(HttpStatus.SERVICE_UNAVAILABLE.value(), ex.getMessage()));
    }
}

@Data
public class ErrorResponse {
    private final int code;
    private final String message;
}
