package com.enterprise.usermanagement.service;

import com.enterprise.usermanagement.dto.UserRequest;
import com.enterprise.usermanagement.dto.UserResponse;
import com.enterprise.usermanagement.model.User;
import com.enterprise.usermanagement.repository.UserRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class UserService {
    private final UserRepository userRepository;
    private final LegacySystemIntegration legacySystem;

    public UserService(UserRepository userRepository, LegacySystemIntegration legacySystem) {
        this.userRepository = userRepository;
        this.legacySystem = legacySystem;
    }

    @Transactional
    public UserResponse createUser(UserRequest request) {
        User user = new User();
        user.setUsername(request.username());
        user.setPassword(legacySystem.hashPassword(request.password())); // Legacy system integration

        User savedUser = userRepository.save(user);
        legacySystem.syncUserToLegacySystem(savedUser); // Synchronize with legacy systems

        return new UserResponse(savedUser.getId(), savedUser.getUsername());
    }

    public UserResponse getUser(UUID id) {
        User user = userRepository.findById(id)
            .orElseThrow(() -> new RuntimeException("User not found"));
        return new UserResponse(user.getId(), user.getUsername());
    }
}
