// src/main/java/com/example/service/service/OrderService.java
@Service
public class OrderService {
    private final OrderRepository repository;
    private final LegacySystemService legacyService;

    public OrderService(OrderRepository repository, LegacySystemService legacyService) {
        this.repository = repository;
        this.legacyService = legacyService;
    }

    public Mono<Order> createOrder(OrderRequest request) {
        return Mono.just(request)
            .handle((req, sink) -> {
                if (req.amount().compareTo(BigDecimal.ZERO) <= 0) {
                    sink.error(new IllegalArgumentException("Amount must be positive"));
                } else {
                    sink.next(repository.save(new Order(req.customerId(), req.amount(), req.method())));
                }
            });
    }
}
```

