### <language>Java</language> Example (Spring Boot)
```java
// User.java - Type-safe entity with JPA annotations
@Entity
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String name;
    private String email;

    // Getters/setters with JavaBeans naming
    public Long getId() { return id; }
    public String getName() { return name; }
    public String getEmail() { return email; }

    // Constructor for type-safe initialization
    public User(String name, String email) {
        this.name = Objects.requireNonNull(name);
        this.email = Objects.requireNonNull(email);
    }
}

// UserRepository.java - Type-safe repository
public interface UserRepository extends JpaRepository<User, Long> {
    Optional<User> findByEmail(String email);
}

// UserService.java - Business logic with legacy system integration
@Service
public class UserService {
    @Autowired private UserRepository userRepository;
    @Autowired private JmsTemplate jmsTemplate;

    public User createUser(String name, String email) {
        User user = new User(name, email);
        User saved = userRepository.save(user);

        // Integrate with legacy system via JMS
        jmsTemplate.convertAndSend("user.created", saved);
        return saved;
    }

    public Optional<User> getUser(Long id) {
        return userRepository.findById(id);
    }
}

// UserController.java - REST API with type-safe DTOs
@RestController
@RequestMapping("/api/users")
public class UserController {
    @Autowired private UserService userService;

    @PostMapping
    public ResponseEntity<User> createUser(
        @RequestBody @Valid UserRequest request) {

        User user = userService.createUser(request.getName(), request.getEmail());
        return ResponseEntity.ok(user);
    }

    @GetMapping("/{id}")
    public ResponseEntity<User> getUser(@PathVariable Long id) {
        return userService.getUser(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }
}

// UserRequest.java - Type-safe DTO with validation
public class UserRequest {
    @NotBlank(message = "Name is required")
    private String name;

    @Email(message = "Valid email required")
    private String email;

    // Getters/setters
    public String getName() { return name; }
    public String getEmail() { return email; }
}
```

