### **4. `Services/CosmosDbService.cs`**
```csharp
using Microsoft.Azure.Cosmos;
using Microsoft.Extensions.Configuration;

public class CosmosDbService : ICosmosDbService
{
    private readonly Container _container;

    public CosmosDbService(IConfiguration configuration)
    {
        var client = new CosmosClient(configuration["CosmosDb:Endpoint"], new DefaultAzureCredential());
        _container = client.GetContainer(configuration["CosmosDb:DatabaseId"], configuration["CosmosDb:ContainerId"]);
    }

    public async Task<ItemResponse<WeatherData>> CreateWeatherDataAsync(WeatherData data)
    {
        return await _container.CreateItemAsync<WeatherData>(data, new PartitionKey(data.City));
    }

    public async Task<FeedResponse<WeatherData>> GetWeatherDataAsync(string city)
    {
        var query = _container.GetItemQueryIterator<WeatherData>(
            new QueryDefinition($"SELECT * FROM c WHERE c.city = @city")
                .WithParameter("@city", city));
        return await query.ReadNextAsync();
    }
}
```

