// Enterprise.Core/Services/ICustomerService.cs
public interface ICustomerService
{
    Task<IEnumerable<CustomerDto>> GetAllAsync();
    Task<CustomerDto> CreateAsync(CustomerDto dto);
}

// Enterprise.Api/Services/CustomerService.cs
public class CustomerService : ICustomerService
{
    private readonly IRepository<Customer> _repository;
    private readonly IMapper _mapper;

    public CustomerService(IRepository<Customer> repository, IMapper mapper)
    {
        _repository = repository;
        _mapper = mapper;
    }

    public async Task<IEnumerable<CustomerDto>> GetAllAsync()
    {
        var entities = await _repository.GetAllAsync();
        return _mapper.Map<IEnumerable<CustomerDto>>(entities);
    }

    public async Task<CustomerDto> CreateAsync(CustomerDto dto)
    {
        var entity = _mapper.Map<Customer>(dto);
        await _repository.AddAsync(entity);
        return _mapper.Map<CustomerDto>(entity);
    }
}
