### 3. **Services/CosmosDbService.cs**
```csharp
using Microsoft.Azure.Cosmos;
using System.Threading.Tasks;

public interface ICosmosDbService
{
    Task AddUserAsync(User user);
    Task<User?> GetUserAsync(string id);
}

public class CosmosDbService : ICosmosDbService
{
    private readonly Container _container;

    public CosmosDbService(string account, string key, string database)
    {
        var client = new CosmosClient(account, key);
        _container = client.GetContainer(database, "Users");
    }

    public async Task AddUserAsync(User user)
    {
        await _container.CreateItemAsync(user, new PartitionKey(user.Email));
    }

    public async Task<User?> GetUserAsync(string id)
    {
        try
        {
            var response = await _container.ReadItemAsync<User>(id, new PartitionKey(id));
            return response.Resource;
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }
}
```

