### <language>C++</language> (Boost.Asio + Thread Pool)
```cpp
// CMakeLists.txt
cmake_minimum_required(VERSION 3.14)
project(HttpServer)
find_package(Boost REQUIRED COMPONENTS system)
add_executable(server main.cpp)
target_link_libraries(server Boost::system)

// main.cpp
#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <thread>

namespace asio = boost::asio;
namespace beast = boost::beast;
using tcp = asio::ip::tcp;

void handle_request(tcp::socket socket) {
    try {
        beast::flat_buffer buffer;
        beast::http::request<beast::http::string_body> req;
        beast::http::read(socket, buffer, req);

        beast::http::response<beast::http::string_body> res{
            beast::http::status::ok, req.version()};
        res.set(beast::http::field::content_type, "text/plain");
        res.keep_alive(false);
        res.body() = "High-performance C++ server!";
        res.prepare_payload();
        beast::http::write(socket, res);
    } catch (...) {
        socket.close();
    }
}

int main() {
    asio::io_context io_context;
    tcp::acceptor acceptor(io_context, {tcp::v4(), 8080});

    const int num_threads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads;
    for (auto i = 0; i < num_threads; ++i) {
        threads.emplace_back([&io_context] { io_context.run(); });
    }

    for (;;) {
        tcp::socket socket(io_context);
        acceptor.accept(socket);
        std::thread(handle_request, std::move(socket)).detach();
    }

    for (auto& t : threads) {
        t.join();
    }
    return 0;
}
```
**Run**: `cmake . && make && ./server`  
**Why**: Boost.Asio provides low-level control with non-blocking I/O and thread pooling.

